begin;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Èjìogbè se presenta como un signo de luz, apertura, equilibrio y crecimiento. Los textos lo relacionan con paz, bienestar, prosperidad, larga vida, descendencia y despertar espiritual. Su frase clave es: «Ogbè crea un camino abierto». La apertura va acompañada de una exigencia reiterada: actuar con honestidad, buen carácter y atención a las decisiones."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere empezar un proyecto o hacer crecer un negocio que no ha despegado; está buscando otra forma de trabajar o de vender.", "Busca paz y estabilidad, además de dinero. Ve oportunidades, pero alguien o algo le estorba el paso.", "Desea tener hijos o agrandar la familia (relato de la familia de Àgbọnnìrègún).", "Se acerca un viaje o un cambio de lugar que puede endulzarle la vida si se prepara antes (relato de Odunkun, el camote).", "Hay chismes o calumnias en la casa, el trabajo o la calle, pero puede salir adelante (relato de Òrúnmìlà acusado).", "Recibió un bien y no lo está valorando (relato del agricultor y el plátano).", "Se le abre un camino y debe decidir cómo aprovecharlo sin volverse soberbio."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Se anuncian posibilidades de abundancia, progreso laboral, nuevos negocios, victoria frente a obstáculos, reconocimiento, relaciones favorables, hijos, paz mental y larga vida. Algunos versos hablan de avanzar gradualmente; otros, de una vida «dulce» o de recibir beneficios después de una etapa estancada. Las bendiciones se vinculan en los relatos con la conducta de la persona y con el consejo específico dado en cada uno."}, {"titulo": "Ibi y advertencias", "texto": "La manifestación desfavorable se asocia con arrogancia, ingratitud, decisiones precipitadas, celos obsesivos, calumnias, conflictos de pareja y apartarse de un camino que antes parecía favorable. La historia del agricultor y el plátano trata el daño causado por no apreciar un bien recibido. Los textos también recuerdan que descuidar la salud o actuar sin reflexión puede impedir que una oportunidad prospere."}, {"titulo": "Enseñanza principal", "texto": "Un verso dedicado a la verdad sostiene que la honestidad es fundamental para la vida humana y pide que aumenten las personas sinceras. Otros relacionan el buen carácter con vivir en armonía con el destino. Así, la «victoria» de Èjìogbè no se limita a vencer a un enemigo: también consiste en conservar la rectitud cuando llegan el éxito y las oportunidades."}, {"titulo": "Relatos reunidos", "texto": "Eleremojú aparece en versos de prosperidad y atención al Ifá de su hijo. Otros relatos tratan el deseo de descendencia de la familia de Àgbọnnìrègún. Odunkun, el camote, emprende un viaje y se convierte en imagen de una vida más dulce. Un relato presenta calumnias dentro y fuera de casa; otro contrapone los beneficios que da el plátano con la ingratitud del agricultor. También aparecen historias sobre matrimonio, reputación, descanso y avance paulatino. Son versiones distintas que conviene conservar por separado debajo de la síntesis."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los textos enumeran ofrendas distintas para prosperidad, descendencia, viaje o superación de adversarios. Dos relatos, por ejemplo, dan listas diferentes dirigidas a Ọbàtálá y Ògún; los versos sobre Eleremojú contienen otras indicaciones. Hay asimismo preparaciones tradicionales y encantaciones para reconocimiento o protección. Ninguna de esas listas debe convertirse en un «ẹbọ único de Èjìogbè»: cada una pertenece a su situación y verso."}, {"titulo": "Relaciones espirituales", "texto": "Orí y Ọbàtálá figuran como asociaciones expresas del signo en uno de los textos. Ògún aparece como destinatario de ofrendas concretas; Òrúnmìlà y Èṣù intervienen en relatos. Conviene mantener visibles esas funciones diferentes en la lectura."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen el camote, el plátano, la palma, el maíz, la miel y la sal. También se nombran egbee, yẹnmẹyẹnmẹ, àgbọnyin e irugba/ogiri en preparaciones o relatos."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus contiene versos sobre verdad, hijos, prosperidad y los relatos anteriores; cantos vinculados con Odunkun y la calumnia; y rezos atribuidos a Baba Èjìogbè. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=1;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Méjì trata el cierre de los ciclos, la relación con los ancestros y la posibilidad de comenzar de otra manera. Otra lectura resume su movimiento con la frase «Ọ̀yẹ̀kú crea y termina un ciclo». Algunos testimonios lo asocian con oscuridad, enfermedad o pérdida; otros presentan riqueza, larga vida y protección. Por eso no equivale a anunciar una muerte: el sentido depende del iré o el ibi y del relato que responda a la consulta."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que una etapa se cierra antes de dar fruto: tristeza, obstáculos o incertidumbre.", "Le preocupa la salud o la vida de un hijo o de alguien de la familia (relato de Onibijé).", "Busca prosperidad en su trabajo y no ve el valor de algo que tiene enfrente (relato de Òyè y el amanecer).", "La casa y el trabajo van cada uno por su lado; cuando se unen, llega la alegría (relato de Onikabidun).", "Hay celos o relaciones que le frenan; le conviene escuchar a los mayores.", "Necesita resistir sin quebrarse ante un viento fuerte (relato de la palma).", "Debe distinguir qué ciclo le toca cerrar y cuál le toca proteger."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Los testimonios anuncian soporte ancestral, riqueza, una etapa nueva, alegría en la casa y el trabajo, descendencia y larga vida. El testimonio de Ọ̀yẹ̀kú habla de prosperidad procedente del trabajo y de un bien inicialmente subestimado. El relato de Onikabidun reúne alegría en el hogar y en la granja. En estos textos, el beneficio aparece ligado a atender el consejo del relato concreto."}, {"titulo": "Ibi y advertencias", "texto": "En la manifestación desfavorable aparecen obstáculos persistentes, tristeza, temor por la enfermedad o la muerte, y finales prematuros que impiden madurar un proyecto. También se mencionan celos y relaciones que desordenan la vida familiar. Otra lectura distingue expresamente el final natural de un ciclo de su interrupción antes de tiempo; no debe convertir toda mención de oscuridad en un pronóstico fatal. El pasaje de Ikú y Ayùnrẹ̀ representa el miedo a la muerte en forma de fábula y no pronostica una muerte individual."}, {"titulo": "Enseñanza principal", "texto": "Terminar una etapa puede abrir otra. Otra lectura explica el nacimiento, la madurez y la llegada al ámbito ancestral como cambios de ciclo, y advierte contra interrumpirlos prematuramente. Los otros testimonios añaden el respeto a los mayores, la atención a Orí y a los ancestros, y la necesidad de reconocer el valor de lo que ya se tiene. En la fábula de Ayùnrẹ̀, pedir consejo antes de enfrentarse a una amenaza importa más que tomar sus elementos míticos literalmente."}, {"titulo": "Relatos reunidos", "texto": "Un relato sobre Òyè, comparado con el amanecer, convierte la duda sobre la riqueza en un horizonte de prosperidad. Onibijé aparece en un verso de protección frente a la muerte y la enfermedad. La palma resiste el viento en otro relato; un pasaje sobre los hijos de Ọlọ́fin afirma que una dificultad no impide necesariamente su porvenir. En otra lectura, Onikabidun recibe alegría cuando se conectan su casa y su granja. Cada historia conserva su situación propia y no debe mezclarse con las demás. Otro relato personifica a Ikú y a Ayùnrẹ̀: este último busca consejo para sobrevivir cuando Ikú amenaza a los seres del bosque. La historia usa alimentos prohibidos para Ikú como recurso mítico; incluye una generalización ofensiva sobre las mujeres que no se acepta como enseñanza del signo."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los versos nombran ofrendas diferentes según el caso. El pasaje de Onibijé menciona tela negra, una chiva y partes de una planta llamada bijé; el de Onikabidun habla de azadas preparadas. También hay prácticas dirigidas a Orí y a los ancestros. Estas indicaciones pertenecen a relatos particulares: la Estera no debe deducir un único ẹbọ para Ọ̀yẹ̀kú Méjì ni marcarlo automáticamente."}, {"titulo": "Relaciones espirituales", "texto": "Los ancestros son una asociación central de la lectura favorable. Orí figura en los consejos sobre el cuidado de la cabeza. Òrúnmìlà interviene en los relatos de consulta, y Èṣù aparece en el canto de Onikabidun. Sus funciones deben mantenerse diferenciadas de las ofrendas dirigidas a una entidad concreta."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La palma aparece en un relato de resistencia al viento; las azadas representan el trabajo compartido entre casa y granja. Los versos también nombran bijé y otros materiales rituales."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus incluye versos sobre protección, descendencia, resistencia y prosperidad, además de un canto de alegría atribuido a Onikabidun. El canto de Ayùnrẹ̀ e Ikú es otro verso de Ọ̀yẹ̀kú Méjì. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=2;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Méjì habla de transformación, percepción y revisión del propio camino. Los textos lo relacionan con sueños o visiones, con la capacidad de mirar una situación desde otra perspectiva y con la pasión necesaria para cambiar. Otra lectura lo resume: «Ìwòrì crea transformación». Ese impulso puede abrir oportunidades o convertirse en conflicto si solo busca imponer una posición."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está repensando su vida y siente que debe cambiar de rumbo, pero no sabe qué conservar.", "Perdió algo o una oportunidad y quiere recuperarla; lo que se veía lejos empieza a acercarse.", "Busca un ascenso o estabilidad en el trabajo y tiene detractores; un éxito rápido no es lo mismo que uno que dura.", "Piensa viajar o entrar en un ambiente desconocido (relato de Olu, que viaja y vuelve con abundancia).", "Le preocupa enfermarse él o alguien cercano (relato de Opakẹrẹ).", "Se siente solo, desea pareja o hijos (relatos de Òde Gbànňsàsà y de Ìwòrì Méjì).", "Tiene un enemigo del que necesita librarse (relato de Òde y Awasa)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Los testimonios mencionan larga vida, abundancia, pareja, hijos, recuperación de algo perdido y posibilidad de promoción. Un testimonio dice que las cosas buenas antes inaccesibles están cerca; el relato de Olu muestra prosperidad después de un viaje. La transformación favorable incluye estabilidad, no solo un triunfo momentáneo."}, {"titulo": "Ibi y advertencias", "texto": "La pasión puede derivar en confrontación sin propósito, terquedad o necesidad de salvar las apariencias. Un relato describe a Òde venciendo a un adversario, pero otro muestra que, al descuidar lo que daría permanencia a sus bienes y relaciones, recibe alegrías breves. También se advierte de oposición en el trabajo y de viajar sin prepararse. Las menciones a enfermedad pertenecen a pasajes concretos y no predicen por sí solas un padecimiento."}, {"titulo": "Enseñanza principal", "texto": "Cambiar exige reconocer qué conducta ya no sirve y actuar con perspectiva. Vencer un problema inmediato no garantiza que la prosperidad, el trabajo o las relaciones perduren. Los textos invitan a mirar más allá de la victoria del momento y a cuidar aquello que sostiene el avance."}, {"titulo": "Relatos reunidos", "texto": "Opakẹrẹ consulta por el temor a enfermarse. Òde enfrenta a Awasa y logra deshacerse de su enemigo, pero otro relato suyo trata la pérdida de compañía y de estabilidad. Ìwòrì Méjì se casa en un verso sobre descendencia. Òde Gbànňsàsà lamenta estar solo y recibe la posibilidad de compañía. En otra lectura, Olu viaja a las casas de Olókun y Olosa, juega ayò y obtiene abundancia. Son escenas diferentes; ninguna reemplaza a las otras."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las listas varían según el verso: Opakẹrẹ recibe una indicación con anzuelos, palomas y una preparación para lavar Orí e Ifá; el relato de Òde menciona ñames y un garrote; el de descendencia, una gallina; otro habla de una piedra de amolar y una estera para dar permanencia a la alegría. El viaje de Olu tiene su propia indicación. No hay un ẹbọ único de Ìwòrì Méjì que deba marcarse automáticamente en la Estera. El tratado de akose registra otras preparaciones atribuidas al signo, que deben mantenerse separadas de los ẹbọ narrativos y verificarse antes de reproducirlas."}, {"titulo": "Relaciones espirituales", "texto": "Otra lectura asocia el signo con Ṣàngó y Aganjú. Orí e Ifá aparecen en el pasaje de Opakẹrẹ; Olókun y Olosa son anfitriones en el viaje de Olu. Èṣù interviene en relatos de bendiciones y canto. La asociación del signo, la intervención narrativa y el destinatario de una ofrenda no son la misma función."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los relatos nombran ñames, nueces de palma o ikin, una estera, una piedra de amolar, anzuelos y palomas. Una preparación atribuida al signo menciona odundun, tete y gbegbe. La palma aparece en un verso de descendencia y los ikin en una explicación de la práctica de Ifá. Ninguno de estos elementos se asigna automáticamente a toda consulta."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan versos sobre protección, adversarios, matrimonio, compañía y la estabilidad de los bienes, además de un canto del viaje de Olu. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=3;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìdí Méjì reúne nacimiento, protección y reconstrucción. Otra lectura expresa su movimiento con «Òdí crea el renacimiento»: una etapa o una estructura que ya no sirve puede dar paso a otra. La interpretación favorable habla de crecimiento firme, familia y reconocimiento; la desfavorable, de aferrarse al pasado o vivir bajo presión y temor."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está presionado por problemas de dinero y emocionales, teme a enemigos ocultos o tiene pesadillas.", "No logra establecerse: cambia de casa o de lugar buscando dónde echar raíces.", "Está por alcanzar una posición importante y teme perderla después; el crecimiento puede ser lento pero seguro (relato de Àkèsán y el mercado).", "Desea formar familia o tener hijos (relato de Odidimadẹ).", "Se acerca un viaje con riesgos que se pueden superar (relato de Òrúnmìlà en el camino).", "Siente que la buena suerte ya llegó una vez y se le escapó, y espera que vuelva (relato de Onibode).", "Quiere ver hechas realidad sus ideas (relato de Itẹrẹ)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Se describen paz mental, larga vida, descendencia, estabilidad y reconocimiento. El testimonio de Òdí cuenta que esfuerzos pequeños y constantes llegan a convertirse en algo grande; la historia de Àkèsán muestra un mercado que atrae gente y prospera. Otro relato presenta bendiciones que vuelven a una persona que creía haberlas dejado pasar."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable habla de resistencia a cambiar estructuras agotadas, miedo, oposición oculta y peligro de perder una posición después de mucho trabajo. Los versos también narran amenazas colectivas y consecuencias de desoír indicaciones concretas. Esos relatos no autorizan a afirmar una muerte, una enfermedad o una condición de un hijo para la persona consultante sin el contexto de su lectura."}, {"titulo": "Enseñanza principal", "texto": "Renacer requiere dejar atrás lo que ya no sostiene la vida y, al mismo tiempo, construir protección y continuidad. El relato de la muralla enseña el valor de resguardar a la comunidad; el de Àkèsán, que la grandeza puede crecer paso a paso. Otra lectura advierte que aferrarse al pasado puede impedir la transformación. La reunión de cabeza, brazo y pierna añade una enseñanza sobre actuar de manera coordinada."}, {"titulo": "Relatos reunidos", "texto": "Itẹrẹ consulta por ideas que desea ver realizadas. En Ilé-Ifẹ̀, una cadena aparece en un relato de protección comunitaria. Odidimadẹ protagoniza una advertencia ligada a su descendencia; la muralla protege un poblado en tiempo de hostilidades. Onibode espera que la buena fortuna lo visite de nuevo. Òrúnmìlà atraviesa un viaje difícil y Àkèsán llega a ser un mercado importante. Son testimonios separados, con problemas y soluciones distintos. Un verso distinto personifica la cabeza, el brazo y la pierna que se reúnen antes de venir a la tierra, como imagen de cooperación entre las partes del cuerpo."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las ofrendas varían mucho: clavos, chivos y gallos en el relato de Itẹrẹ; una cadena y un carnero en el de la ciudad; cocos y caracoles en otro verso; ropas en la historia de la muralla. Otra lectura añade listas particulares para Onibode y el viaje de Òrúnmìlà. Su mención en un relato no crea un ẹbọ universal de Ìdí Méjì: la Estera debe registrar solo el confirmado para la consulta. No deben mezclarse con las listas de estos relatos."}, {"titulo": "Relaciones espirituales", "texto": "Otra lectura asocia Òdí con Yemọja. Orí o Ẹlẹ́dá aparece en el consejo sobre estabilidad personal; Ògún, en indicaciones para un viaje; Ọ̀rúnmìlà, en relatos sobre familia y protección. Èṣù interviene en ofrendas y en la llegada de bendiciones. Cada mención tiene una función diferente y no todas son destinatarios de la misma obra. Orí protagoniza el verso de las partes del cuerpo, en una escena separada de la muralla y el viaje."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los pasajes mencionan maíz preparado como ẹ̀kọ, aceite de palma, ñame, cocos, caracoles y materiales como clavos, cadena, ropa y plato blanco. Un tratado de akose atribuye al signo preparaciones con nombres de plantas como egele, mobo y owo. Los materiales pertenecen a pasajes distintos y no se convierten automáticamente en prohibiciones o ingredientes de toda consulta."}, {"titulo": "Rezos, versos y cantos", "texto": "Hay versos sobre ideas que se realizan, protección colectiva, descendencia y la muralla; otro testimonio conserva el canto de Àkèsán y otra lectura relata alabanza después de un viaje. El canto de las partes del cuerpo repite «Kêrêkêrê» en la traducción. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=4;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìrosùn Méjì habla del potencial que se recibe y se desarrolla con paciencia. Otra lectura lo relaciona con el linaje ancestral y resume su movimiento como «Ìrosùn crea satisfacción del potencial». Los relatos no prometen un avance inmediato: muestran que la constancia, el cuidado de Orí y el vínculo con la familia ayudan a que una posibilidad llegue a madurar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que su vida o su negocio está estancado y que avanzar le cuesta el doble.", "Hay un cargo, una herencia o un puesto en juego dentro de la familia, y no todos se prepararon igual para recibirlo (relato de Iná, Eyin e Iko).", "Le recomendaron una ofrenda o una precaución y todavía no la ha hecho (Iko fue el único que cumplió).", "Espera un hijo, o le preocupa el futuro de sus hijos y que tengan con qué salir adelante (verso de Ìrosù).", "Le afectan los chismes o las críticas de otros (relato de Apeni).", "Necesita paciencia: le toca esperar su turno sin desesperarse."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Los textos anuncian reconocimiento, paz, prosperidad que crece gradualmente y posibilidad de descendencia. El testimonio de Ìrosùn presenta a Òní recibiendo hijos y otras bendiciones; el relato de Iko muestra que esperar y proteger lo alcanzado puede dar permanencia a un cargo. La buena fortuna se describe como desarrollo de una capacidad latente, no solo como un resultado repentino."}, {"titulo": "Ibi y advertencias", "texto": "La manifestación desfavorable incluye desánimo, resistencia a desarrollar las propias capacidades, problemas financieros y dejar que un período difícil parezca definitivo. Algunos relatos advierten de perjuicios causados por palabras ajenas o por desoír un consejo dirigido a los hijos. El pasaje comercial critica incumplir una compra a crédito. Ninguno de esos versos convierte una dificultad concreta en destino inevitable para quien consulta."}, {"titulo": "Enseñanza principal", "texto": "La paciencia no es pasividad: consiste en preparar, proteger y continuar una tarea hasta que dé fruto. Iko conserva un cargo porque actuó y esperó su momento; otros personajes sufren por abandonar una indicación particular. Un texto adicional recuerda que las quejas sobre el propio camino deben dirigirse primero a Orí. El signo invita a cultivar el potencial heredado y a responder por las decisiones presentes."}, {"titulo": "Relatos reunidos", "texto": "Iná, Eyin e Iko compiten por suceder a su padre; Iko, la rafia, soporta la lluvia y conserva el título. Ìrosùn consulta por el futuro de un hijo en un verso distinto. El gallo decide conservar su cresta y Ataparí recibe un gorro que funciona como imagen de la corona. Apeni busca protección frente a las palabras de otros. Òní desea descendencia; Okansansusu Ìrosùn imagina compartir comida con sus hijos. Son relatos independientes y sus indicaciones no deben combinarse."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las ofrendas citadas responden a asuntos diferentes: una estera y ropa amarilla para Iko; caracoles en un verso de descendencia; una indicación particular para el gallo; y ofrendas a Orí y Egúngún en el relato de Apeni. El testimonio de Òní contiene otra lista. Un tratado de akose registra preparaciones adicionales con fines propios. No existe aquí un ẹbọ único que la Estera deba marcar de forma automática."}, {"titulo": "Relaciones espirituales", "texto": "Orí aparece en el cuidado personal y en un verso sobre revisar el propio destino. Otra lectura destaca el vínculo con Egúngún o los ancestros; otro relato dirige ofrendas a ambos. Osù figura en un consejo particular y Èṣù interviene en canciones y en la llegada de bendiciones. Las asociaciones no implican que todos reciban la misma obra."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los relatos nombran rafia, fruto de palma, ñame, sopa, frijoles y aceite de palma. El testimonio menciona ìṣín e ìlà en pasajes de ofrenda. La estera y la ropa amarilla pertenecen al relato de Iko. No se deduce un uso universal de estas plantas o materiales."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan versos sobre sucesión, descendencia, la voz de los adversarios, comercio y atención a Orí; otra lectura transmite cantos de Apeni y de Okansansusu Ìrosùn. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=5;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Méjì trata los cambios inesperados y la capacidad de responder a ellos con claridad. Otra lectura dice: «Ọ̀wọ́nrín crea cambios inesperados». Los otros textos insisten en la moderación, el buen juicio y la ayuda compartida. El cambio puede abrir comercio, trabajo y responsabilidades nuevas, o desordenar una base que no estaba preparada."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está por tomar una decisión con prisa y debe pensarla bien antes de actuar.", "Vende y se esfuerza, pero no gana (relato de Sièjidé en el mercado).", "Le falta dinero y también pareja, y espera que ambas cosas mejoren.", "Un trabajo ligado a la tierra o al campo puede darle prosperidad (relato de Okewu).", "Va a viajar o teme un lugar hostil, y puede regresar bien si se prepara (relato del gato Ologbo).", "Le ofrecen un cargo o una responsabilidad y debe recordar ayudar a los suyos (relato de Owon).", "Desea tener hijos (relato de Opẹkẹtẹ)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Los textos anuncian posibles ganancias en el comercio, prosperidad agrícola, pareja, descendencia, viajes favorables y reconocimiento como líder. El relato de Sièjidé une el éxito comercial con el apoyo mutuo; otro recuerda que la abundancia recibida también debe beneficiar a otras personas. La oportunidad aparece cuando la persona puede adaptarse y sostener decisiones claras."}, {"titulo": "Ibi y advertencias", "texto": "La manifestación desfavorable es la perturbación que rompe una base débil, la confusión ante cambios rápidos o actuar sin moderación. Los viajes del gato se contraponen a los de otros animales que, en el relato, no siguieron la indicación recibida. Esto no significa que toda consulta anuncie hechicería o peligro: esos elementos pertenecen a versos concretos. También se advierte contra pensar solo en la propia ganancia y olvidar las necesidades de los demás."}, {"titulo": "Enseñanza principal", "texto": "El cambio exige perspectiva y solidaridad. Un texto aconseja que una ofrenda también alimente a personas, además de las entidades invocadas. La historia de Sièjidé repite la idea de apoyarse unos a otros. La claridad de pensamiento, la moderación y el cuidado de la familia hacen que una bendición inesperada pueda convertirse en progreso estable."}, {"titulo": "Relatos reunidos", "texto": "Ologbo, el gato, viaja a un lugar hostil y regresa; otro verso cuenta que fue el único animal que volvió. Opẹkẹtẹ consulta por hijos. En otra lectura, Owon recibe un cargo relacionado con el mar y Ologbo Jigolo supera un viaje difícil. Sièjidé, hija del rey de Òyó, busca ganancias en el mercado; Okewu prospera mediante la agricultura. Son historias distintas y sus listas rituales no deben mezclarse."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los versos del gato mencionan, según el caso, una carnera y palomas o una tela negra. El pasaje de Opẹkẹtẹ tiene otra lista; otra lectura atribuye al relato de Owon una ofrenda dirigida a Ọbàtálá y Èṣù. Hay indicaciones diferentes para comercio, viaje y descendencia. Ninguna puede usarse como ẹbọ único del signo ni marcarse automáticamente en la consulta."}, {"titulo": "Relaciones espirituales", "texto": "Otra lectura asocia el signo con Èṣù. Ọbàtálá figura como destinatario junto a Èṣù en una ofrenda del relato de Owon. Orí y Ẹlẹ́dá aparecen en consejos sobre bienestar y larga vida; los ancestros, en el respeto a los mayores. Òrúnmìlà interviene en la consulta de Sièjidé. Conviene conservar esas funciones diferenciadas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La agricultura y las cosechas son imágenes centrales en un verso sobre Okewu. Los relatos mencionan una tela negra, palomas, peces y otros alimentos de ofrendas específicas. En una nota aparece werejéje. Ningún elemento se transforma en una instrucción para todas las lecturas."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus conserva versos sobre comercio, agricultura, viaje, liderazgo y descendencia; los relatos de Owon y Ologbo incluyen cantos, y el de Sièjidé habla de apoyo mutuo. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=6;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Méjì habla de la fuerza que necesita dirección. Otra lectura resume su movimiento como «transformación interna»: la firmeza puede sostener decisiones y nuevos proyectos, mientras el impulso de imponer la propia voluntad causa tropiezos. Los relatos destacan la atención a Orí, la cooperación y la humildad ante otras personas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está bajo presión, con incertidumbre o problemas de dinero, y le cuesta decidir con calma; quizá se arrepiente de una reacción impulsiva.", "Su negocio necesita clientes o mejores condiciones.", "Siente oposición a su alrededor; antes de culpar a alguien debe ver la causa real.", "Quiere empezar un proyecto, mudarse o iniciar una relación (relato del árbol Odán).", "Busca prosperidad o hijos (relatos de Awòn y de Ifákáyòdé).", "Necesita apoyo mutuo: una mano lava a la otra (relato de Awùn y Ondero).", "No siguió un consejo y ahora paga las consecuencias (relato de Èji-Ọ̀bàrà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Se describen prosperidad, clientela, amistades, mejoría económica, proyectos que arraigan, vínculos favorables y descendencia. Awùn recibe un buen Orí; Odán logra establecerse y dar sombra. En el testimonio de Awòn, Òṣun interviene en una historia específica de riqueza e hijos. La fuerza favorable del signo se expresa al combinar iniciativa con ayuda mutua y consideración por los demás."}, {"titulo": "Ibi y advertencias", "texto": "La cara difícil es la indecisión seguida de un acto impulsivo, el egoísmo o intentar forzar la voluntad ajena. Un relato presenta una enfermedad que alcanza a Èji-Ọ̀bàrà tras desatender una ofrenda; esa historia no permite afirmar que todas las personas del signo padecerán lo mismo. Otro texto habla de dificultades financieras y adversarios, que conviene tratar como posibilidades de la consulta, no como hechos comprobados sobre terceros."}, {"titulo": "Enseñanza principal", "texto": "«Una mano lava la otra»: Awùn y Ondero muestran que la prosperidad necesita reciprocidad. Otra lectura relaciona el buen carácter con templar la fuerza mediante la humildad. Reconocer límites y escuchar a otros ayuda a transformar una energía que, sin dirección, puede volverse contra la propia persona."}, {"titulo": "Relatos reunidos", "texto": "Awùn participa en el lavado de Orí de Ondero y ambos relatos presentan ofrendas propias. Odán vuelve a establecerse y ofrece sombra, imagen de un proyecto que puede crecer. Awòn lava su Orí de riqueza en el río y recibe la protección de Òṣun en esa historia. El testimonio de Ifákáyòdé trata la descendencia y la continuidad de la vida. Èji-Ọ̀bàrà enferma después de no seguir el consejo recibido; Atapẹrẹ, hija de Ọ̀wá-Ọlọ́fin, aparece en otro verso relacionado con hijos. Son relatos separados."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los versos de Awùn y Ondero presentan ofrendas distintas para la atención de Orí: uno menciona carnera, paloma y cuentas de coral; el otro, tela blanca y paloma. Otra lectura da listas diferentes para Awùn y Odán dirigidas a Èṣù. El testimonio de Awòn aconseja una ofrenda a Òṣun en su situación particular. Atapẹrẹ recibe indicaciones vinculadas a la descendencia. No hay una sola lista de ẹbọ aplicable a todo Ọ̀bàrà Méjì; cada indicación pertenece a su relato y debe interpretarse dentro de una consulta tradicional."}, {"titulo": "Relaciones espirituales", "texto": "Orí ocupa un lugar central en las historias de Awùn, Ondero y Awòn. Òṣun protege a Awòn y a sus hijos en un testimonio concreto. Èṣù aparece como destinatario de ofrendas en dos relatos; Ọ̀rúnmìlà se menciona en el consejo sobre negocios. Otra lectura asocia el signo con Ṣàngó. Estas funciones no deben fusionarse en una lista indiferenciada de destinatarios."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen los árboles awùn y Odán, la tela blanca, las cuentas de coral, el algodón, la manteca de cacao, el aceite de palma, el ñame y preparaciones de maíz. Un comentario nombra biyenmẹ e irugba en una preparación. Las ofrendas animales pertenecen a versos diferentes."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus reúne los versos de la mano derecha y la izquierda que se lavan mutuamente, el canto de Awùn por un buen Orí, el canto de Odán al establecerse, el testimonio de Awòn ante Òṣun y el verso de Ifákáyòdé. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=7;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀kànràn Méjì presenta una dificultad que puede abrir otra dirección. Otra lectura lo expresa como «nuevas direcciones y nuevas posibilidades» y relaciona el cambio con el equilibrio entre pensamiento y emoción. El consejo del texto principal pide conciliar y resolver conflictos antes de que crezcan. Sus versos reúnen búsquedas de fortuna, viajes, cambios de posición y descendencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Atraviesa una disputa o contrariedades y necesita negociar o cerrar un asunto pendiente.", "Busca dinero o hijos que no llegan y se pregunta si podrá lograrlo con sus propias manos (relato de Jìngbìnní).", "Va a viajar esperando reconocimiento o recursos (relato de Ṣàkótó en Ọwá).", "Un cambio de casa o de entorno le cambia los planes de regreso (relato de Ilé Ètilè).", "Compite con otro por algo y solo uno se preparó (relato de Olú-igbó y Olú-òdan).", "Tiene un solo hijo y desea otro (relato de Oló).", "Debe elegir entre reaccionar con el enojo o dar un paso pensado."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Se anuncian la resolución de dificultades, la fortuna que Jìngbìnní consigue, un viaje que beneficia a Ṣàkótó y al pueblo de Ọwá, y una nueva oportunidad de descendencia en el verso de Oló. La transformación favorable comienza al atender la situación real, asumir una decisión y actuar con juicio. No se presenta como una promesa automática para todas las consultas."}, {"titulo": "Ibi y advertencias", "texto": "Los textos advierten sobre conflictos que se prolongan, reacción emocional sin reflexión, aislamiento ante una oportunidad de cambio y escasez que desgasta. El relato del bosque, la sabana, Ewu e Iná contrapone la preparación de Olú-igbó con la negativa de Olú-òdan a seguir el consejo recibido. Las alusiones a enfermedad o adversarios en el texto principal son advertencias tradicionales, no diagnósticos médicos ni prueba de que una persona concreta sea enemiga."}, {"titulo": "Enseñanza principal", "texto": "Cambiar de camino exige unir corazón y cabeza. Otra lectura llama a ese equilibrio orí tútù y dice que rechazar el primer paso puede cerrar posibilidades. Jìngbìnní muestra constancia en la búsqueda de fortuna; Ṣàkótó encuentra un bien propio al responder también a la necesidad de un pueblo. La conciliación puede ser una forma de avanzar, no una renuncia a la firmeza."}, {"titulo": "Relatos reunidos", "texto": "Jìngbìnní pregunta si sus manos alcanzarán la fortuna y termina celebrando su llegada. Ṣàkótó viaja a Ọwá, donde la lluvia cambia su destino y el de la comunidad; las versiones conservadas difieren en cómo se relaciona con Èṣù durante el trayecto. El pueblo de Ọwá consulta por el nombramiento de un extranjero. En otro relato, Olú-igbó y Olú-òdan compiten por Ewu, la vestidura vegetal antes ligada a Iná. Oló consulta por su hijo único. Un testimonio de Èjì Ọ̀kànràn describe la llegada a Ilé Ètilè. Cada relato debe mantenerse separado."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Jìngbìnní recibe un consejo de sacrificio, sin una lista precisa de ingredientes. El viaje de Ṣàkótó sí trae una lista de paloma, carnera y tres tortas de frijol en una versión, mientras las instrucciones sobre las tortas difieren entre relatos. Olú-igbó recibe otra indicación, con escobas, gallina y tela negra; Oló, una lista vinculada con descendencia. El texto principal menciona a Ṣàngó y Èṣù para superar dificultades. Ninguna indicación constituye un ẹbọ universal de Ọ̀kànràn Méjì."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà e Ifá aparecen en el consejo general del signo. Èṣù interviene en el viaje de Ṣàkótó y figura, junto con Ṣàngó, en una indicación del texto principal. Otra lectura asocia el signo con Ọ̀ṣọ́ọ̀sì, pero esa asociación no sustituye la función particular de los otros relatos. Orí tútù expresa el equilibrio interior mencionado en la caracterización de otra lectura."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los relatos mencionan las tortas de frijol del viaje de Ṣàkótó, lluvia, pequeñas calabazas en una versión, escobas, tela negra y la vegetación que forma el ropaje del bosque. Cada elemento queda unido a su historia."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan versos sobre Jìngbìnní y la fortuna obtenida con sus manos, la llegada de Ṣàkótó a Ọwá, la disputa por Ewu, el hijo de Oló y el viaje a Ilé Ètilè. Un canto atribuido a Ṣàkótó aparece en otra lectura. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=8;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ògúndá Méjì trata de abrir camino mediante trabajo, coraje y una fuerza bien dirigida. Otra lectura resume su movimiento como «eliminación de obstáculos», pero pide identificar primero si el impedimento es externo o nace de una reacción propia. Los versos sobre Ògún muestran que la fuerza creadora también necesita paciencia y responsabilidad para no convertirse en conflicto."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Carga demasiado trabajo y también los problemas de otros; debe ver qué le toca a él.", "Hay tensiones o desconfianza; conviene guardar confidencias y ver los hechos antes de acusar.", "Trabaja, pero no logra conservar lo que gana (relato del tigre).", "Necesita abrir camino en el trabajo, para sí y para otros (relato de Ògún y el machete).", "Espera una mejoría que parece cerca pero no termina de llegar (relato de Idena-Magbon).", "Pregunta por hijos o por el crecimiento de la familia (verso de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Los relatos hablan de abrir oportunidades, superar obstáculos, conservar las ganancias del esfuerzo, favorecer al conjunto de una comunidad y ampliar la familia. Ògún aparece como figura de trabajo creador y de camino abierto. En el cuento del tigre, el beneficio llega cuando puede disfrutar lo que obtuvo; en Idena-Magbon, el bien alcanza al pueblo. La prosperidad se vincula con esfuerzo organizado y consejo adecuado."}, {"titulo": "Ibi y advertencias", "texto": "La manifestación desfavorable reúne peleas, desconfianza, carga excesiva, ira ante un obstáculo y destrucción que no se pretendía. Los relatos advierten que un esfuerzo puede perderse por falta de preparación o de atención a sus causas. La ficha menciona adversarios como posibilidad de consulta, sin que ello autorice a identificar a terceros como traidores. Los pasajes sobre enfermedad o muerte prematura son motivos narrativos, no pronósticos clínicos."}, {"titulo": "Enseñanza principal", "texto": "No basta con tener fuerza: hay que saber dónde aplicarla. Otra lectura enseña a distinguir los obstáculos internos de los externos; un problema mal identificado provoca enojo y conflicto innecesarios. En un verso, Ògún pide paciencia a dos personas que pelean por un pescado. Abrir camino también puede consistir en detener una disputa y repartir con justicia."}, {"titulo": "Relatos reunidos", "texto": "Ògún recibe un machete asociado a su éxito y media ante una pelea por un pescado. Otro verso cuenta su misión de abrir el camino de la vida. Un tercero lo presenta como figura a la que otros piden ayuda para arreglar sus dificultades, mientras nadie resuelve las suyas. El tigre aprende a conservar la presa de su caza. Las personas de Idena-Magbon buscan buena fortuna. Un verso de Ọ̀rúnmìlà relata la llegada de muchos hijos y menciona a Alarẹ. Cada episodio conserva su consejo propio."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los pasajes dan indicaciones diferentes: el primer relato de Ògún menciona machete, gallo y ñame asado; el encargo de abrir camino, carnero y un eslabón de cadena. El tigre recibe una ofrenda vinculada al fruto del trabajo; Idena-Magbon, otra con campanas. La ficha general relaciona la atención a Ògún y a Orí con dificultades económicas. Las listas pertenecen a sus situaciones originales y no forman un único ẹbọ del signo."}, {"titulo": "Relaciones espirituales", "texto": "Ògún es la figura central de varios versos y la asociación expresa de otra lectura. Orí aparece en el consejo del texto principal para buscar estabilidad y prosperidad. Ifá participa en la consulta del tigre y de Idena-Magbon; Ọ̀rúnmìlà protagoniza el relato de descendencia. Se muestran sus papeles por separado, sin convertir cada aparición en una instrucción ritual general."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen el hierro y el machete de Ògún, el eslabón de cadena, el ñame asado, el pescado disputado, las hojas secas de palma que espantan al tigre, aceite de palma y campanas de metal. Son elementos ligados a relatos concretos: el machete representa una herramienta que abre camino; la palma marca el tropiezo del cazador."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus incluye versos sobre el machete y el trabajo de Ògún, su misión hacia el mundo, el tigre, la fortuna de Idena-Magbon y los hijos de Ọ̀rúnmìlà. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=9;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òsá Méjì trata el cambio brusco de circunstancias y la manera de responder a él. Otra lectura lo resume como «cambio radical» que puede desordenar la vida o abrir una oportunidad. Los testimonios A y B del signo apuntan a bienes diferentes: uno habla de prevalecer frente a oposición y otro de alcanzar riqueza. La ficha reúne ambos sin convertirlos en un único anuncio."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le llega un cambio repentino en el trabajo o en una relación y lo rechaza por miedo a perder estabilidad.", "Enfrenta oposición o una pelea y necesita prevalecer (relato de Òlúkòso y Ṣàngó).", "Busca prosperidad material (relato de Òwú, hijo de Ògòdò).", "Va a viajar o trabajar con desconocidos que podrían querer perjudicarlo (relato de Ọ̀rúnmìlà).", "Un susto o un imprevisto puede frenar su proyecto (relato de los dos Òsá).", "Busca pareja, hijos o reconocimiento (relatos del matrimonio de Ọ̀rúnmìlà y de Ejipabileseigi).", "Está cansado o descuida una necesidad propia (relato de Ajá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "El testimonio B anuncia riqueza para Òwú. Otros pasajes hablan de viajes seguros, alivio de la oposición, pareja, descendencia, reconocimiento y conservación de lo logrado. Otra lectura plantea que un cambio externo puede aprovecharse para generar abundancia. En el testimonio A, la posibilidad favorable es prevalecer; en el B, obtener prosperidad. Ambas versiones quedan visibles por separado."}, {"titulo": "Ibi y advertencias", "texto": "La cara difícil del signo es huir de responsabilidades, quedar paralizado ante un cambio o actuar desde el miedo. Los dos Òsá de un verso abandonan su proyecto cuando surge una lucha. El relato de Ajá presenta el costo de desatender una necesidad. Los pasajes sobre adversarios y pesadillas son advertencias tradicionales; no se convierten en afirmaciones médicas ni en acusaciones sobre personas reales."}, {"titulo": "Enseñanza principal", "texto": "Un cambio inesperado no determina por sí solo el resultado. Los relatos contrastan huir, prepararse y responder con firmeza. El viaje de Ọ̀rúnmìlà muestra una oposición que puede transformarse; el testimonio de Òwú presenta una ganancia después del consejo recibido. La enseñanza es reconocer qué ha cambiado y elegir una respuesta proporcionada."}, {"titulo": "Relatos reunidos", "texto": "Òsá Méjì A presenta a Òlúkòso y una victoria ligada a Ṣàngó. Òsá Méjì B relata la buena fortuna de Òwú, hijo de Ògòdò. Los dos Òsá viajan a Ifẹ y huyen de un conflicto inesperado. Otro verso describe a un Òsá que busca pareja; otro, el matrimonio de Ọ̀rúnmìlà con Olúyemi. Ajá desoye un consejo relacionado con su sed. Otra lectura conserva un viaje de Ọ̀rúnmìlà y un relato de Ejipabileseigi sobre reconocimiento. Son episodios distintos."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El testimonio A manda una ofrenda para prevalecer y menciona a Ṣàngó, sin lista de ingredientes. El B dice que Òwú realizó sacrificio, también sin lista precisa. Los versos de los dos Òsá, la búsqueda de pareja y el matrimonio de Ọ̀rúnmìlà sí presentan ofrendas diferentes. Otra lectura da una lista particular para el viaje de Ọ̀rúnmìlà."}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó figura en el testimonio A como entidad vinculada con prevalecer. Otra lectura asocia el signo con Ọya y menciona a Ìyámi en una ofrenda del relato de viaje. Ọ̀rúnmìlà protagoniza ese viaje y otro verso sobre matrimonio. Estas apariciones tienen funciones diferentes y no deben presentarse como una misma instrucción para toda consulta."}, {"titulo": "Plantas, alimentos y elementos", "texto": "En las historias aparecen Òwú, relacionado con el cultivo y la ganancia del granjero, así como maíz, aceite de palma y bebidas en el relato de viaje. Un verso menciona la piedra de rayo; otros, palomas y caracoles de babosa. Los elementos pertenecen a episodios separados."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los testimonios A y B de Òsá Méjì, los versos de los dos Òsá, la búsqueda de pareja, el matrimonio de Ọ̀rúnmìlà, Ajá y los cantos de los otros relatos. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=10;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìká Méjì reúne preocupación, necesidad de moderación y el poder de la palabra. Otra lectura dice que Ìká desarrolla ese poder: puede proteger, afirmar y unir recursos, o convertirse en chisme y daño injusto. Los relatos añaden la atención a Orí, el fruto de lo sembrado, la búsqueda de hijos y la protección frente a pérdidas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Junta preocupaciones de dinero, familia o salud y necesita decidir sin prisa.", "Desea un embarazo o hijos (relato de Bara Àgbọnnìrègún y el maíz).", "Teme que la envidia o los celos de otros le quiten una oportunidad.", "Hay un viaje o un trabajo con extranjeros que puede traer abundancia (relato de Erelu del Océano).", "Debe cuidar lo que dice y cómo habla de los demás: la palabra construye o destruye.", "Se confía demasiado en su posición y desoye un aviso (relato de Eyin), o actúa con fuerza sin prepararse (relato de Ògún).", "Hay una disputa de pareja (relato de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Los testimonios A y B hablan de protección y continuidad de la vida, cada uno en su propio relato. Erelu del Océano recibe abundancia; Bara Àgbọnnìrègún busca descendencia y atiende Orí. El texto principal relaciona prosperidad con decisiones acertadas y con recoger el fruto de lo sembrado. La manifestación favorable del poder de la palabra es crear acuerdos, afirmar una intención y cuidar a otros."}, {"titulo": "Ibi y advertencias", "texto": "La cara difícil incluye angustia, habladurías, denigración, decisiones arrogantes y obstáculos que se agravan cuando se ignora un consejo. Eyin rechaza una indicación porque confía en su corona; Ògún gana una batalla pero sufre después en el relato del ñame. Los pasajes sobre enemigos, enfermedad o muerte no son diagnósticos ni pruebas de una amenaza concreta."}, {"titulo": "Enseñanza principal", "texto": "La palabra tiene consecuencias y debe ir acompañada de buen juicio. Otra lectura contrapone la afirmación que protege con el rumor que hiere. El texto principal recuerda que cada persona cosecha lo que siembra; el verso del maíz lleva esa enseñanza al cuidado de Orí. La moderación y la preparación importan tanto como la fuerza."}, {"titulo": "Relatos reunidos", "texto": "Eyin se siente seguro por su corona y desoye una advertencia. Bara Àgbọnnìrègún planta maíz y lo usa después para atender Orí en una historia de nacimientos. Ọ̀rúnmìlà consulta por una disputa de pareja; Ògún combate sin seguir la indicación recibida y luego pierde el habla en el cuento. Erelu del Océano viaja y consigue abundancia. Los testimonios A y B presentan, por separado, a Oníkàámògún y Òràmolè como imágenes de protección y larga vida."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Eyin menciona un gallo y lo que determine el adivino; el de Bara Àgbọnnìrègún, maíz y gallinas para una situación de descendencia y atención a Orí. Los relatos de Ọ̀rúnmìlà, Ògún y Erelu del Océano tienen listas distintas. El testimonio A pide agregar aaka a su ofrenda sin aclarar aquí una identificación segura de ese elemento; el B insiste en completar el sacrificio, sin una lista precisa. No se reúnen estas indicaciones en un ẹbọ único."}, {"titulo": "Relaciones espirituales", "texto": "Orí aparece en el verso del maíz y en el consejo del texto principal. Otra lectura asocia Ìká Méjì con Orí y Òrò y vincula el signo con el poder de la palabra. Ifá y Èṣù intervienen en el viaje de Erelu del Océano; Ògún y Ọ̀rúnmìlà protagonizan otros versos. Son funciones narrativas distintas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El maíz sembrado y cosechado en el verso de Bara Àgbọnnìrègún, el ñame asado de la historia de Ògún, el aceite de palma, el plátano y el pequeño bote de madera de Erelu del Océano aparecen ligados a episodios concretos. El testimonio A nombra aaka."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de Eyin, Bara Àgbọnnìrègún, Ọ̀rúnmìlà y Ògún, el canto de Erelu del Océano y los testimonios A y B de Oníkàámògún y Òràmolè. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=11;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Méjì reúne resistencia, prudencia y cuidado de la vida familiar. El texto principal destaca maternidad, parto, hijos y la fuerza para soportar dificultades. Otra lectura lo relaciona con el mantenimiento de la salud, pero sus explicaciones tradicionales sobre enfermedad no deben tomarse como hechos médicos. Los relatos enseñan a orientar la tenacidad y a escuchar consejo antes de actuar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pregunta por hijos, un embarazo o el bienestar de su familia.", "Es firme y resistente, pero puede volverse terco si no escucha a los mayores.", "Se va a casar o quiere saber el futuro de una unión (relato de Ọlọ́fin y Pupayẹmi).", "Busca una casa estable o va a cambiarse de vivienda (relato de Yaya y Yayá).", "Le preocupa la salud de un niño o su propia vulnerabilidad (relato de Ikusigbade).", "Llegó a un lugar nuevo y quiere hacerse un sitio (relato de los dos Ogẹ).", "Su valentía puede ponerlo en peligro (relato de Odo, el mortero)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Se anuncian estabilidad familiar, hijos, éxito de los dos Ogẹ en Ifẹ, una vivienda duradera para Yayá y larga vida en el relato de Ikusigbade. La perseverancia favorable se combina con prudencia y guía. Un verso destaca que dos hijos, aunque pocos, pueden llegar a ser importantes; evita medir la bendición solo por cantidad."}, {"titulo": "Ibi y advertencias", "texto": "La manifestación difícil es la obstinación que ignora consejo, la audacia sin cuidado y la fragilidad de un proyecto mal preparado, como la casa de Yaya. Los relatos usan enfermedad y muerte temprana como motivos religiosos; no permiten diagnosticar infecciones, pronosticar un embarazo ni garantizar supervivencia. Si hay síntomas o preocupación por una gestación, corresponde atención médica."}, {"titulo": "Enseñanza principal", "texto": "Resistir no significa insistir a ciegas. La fortaleza de Òtúrúpọ̀n se aprovecha cuando escucha experiencias ajenas, evalúa riesgos y cuida lo que está construyendo. La pareja de casas de Yaya y Yayá deja una imagen clara: dos personas pueden perseguir la misma meta, pero la preparación determina si el resultado perdura."}, {"titulo": "Relatos reunidos", "texto": "Los dos Ogẹ reciben un consejo antes de descender a Ifẹ. Ọlọ́fin consulta por su matrimonio con Pupayẹmi y el futuro de sus dos hijos. Odo, el mortero, recibe una advertencia para que su valentía no se vuelva peligro. Otro Ogẹ rehúsa una indicación ligada a la prudencia. Otra lectura conserva la historia de Ikusigbade y la de Yaya y Yayá, que buscan construir una casa. Son situaciones independientes. Un verso adicional sobre Awèrèmẹ́gọ̀ presenta la muerte como paso a la condición ancestral de Egúngún; es cosmología tradicional y no una noticia de muerte para quien consulta."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los versos de los dos Ogẹ, Ọlọ́fin, Odo y el Ogẹ que rehúsa el consejo contienen listas y propósitos diferentes. Otra lectura describe una ofrenda para Ikusigbade dirigida a Ìbejì y otra para el caso de la vivienda relacionada con Egúngún e Ìbejì. El texto principal menciona Egúngún, Òrìṣànlá, Orí e Ifá en contextos específicos de familia y orientación. No se convierten en un único ẹbọ del signo ni sustituyen cuidados médicos."}, {"titulo": "Relaciones espirituales", "texto": "Egúngún aparece en el relato de la vivienda y como referencia a los ancestros; Ìbejì figura en ofrendas de otra lectura. El texto principal menciona Òrìṣànlá, Orí e Ifá en relación con hijos y decisiones. Otra lectura asocia el signo con Onílẹ̀ y Nàná Bùrùkú. Egúngún aparece en el verso cosmológico de Awèrèmẹ́gọ̀ como condición ancestral posterior a la muerte."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan la fronda de palma del relato de Ikusigbade, aceite de palma, pimienta de caimán en el verso de Odo, piedras de rayo, caracoles y tortugas en el relato de los dos Ogẹ. La casa de Yaya y Yayá funciona como elemento narrativo de estabilidad. Las listas concretas deben permanecer junto a sus versos."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus contiene los versos de los dos Ogẹ, de Ọlọ́fin y Pupayẹmi, de Odo, del Ogẹ que desoye el consejo, y los relatos de Ikusigbade y Yaya/Yayá. Se añade el verso de Awèrèmẹ́gọ̀ sobre Egúngún. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=12;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òtúrá Méjì vincula paz interior, propósito y una visión clara para actuar. Otra lectura llama a esa orientación «visión mística», pero advierte contra confundir el deseo personal con un mandato divino. El texto principal habla de oportunidades en comercio y relaciones. Sus versos ponen esa promesa junto a descanso, justicia y responsabilidad en el uso del éxito."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene una oportunidad de comprar, vender o empezar una relación, pero necesita organizarse para sostenerla.", "Trabaja sin descanso y está a punto de agotarse.", "Tendrá que viajar o estar lejos más tiempo del planeado (relato de Òtú en Ifẹ).", "Quiere vender algo y busca el mejor lugar para hacerlo (relato de Òtú y las tortugas).", "Le toca fundar, dirigir o poner orden en un grupo, con justicia (relatos de Ọ̀rúnmìlà).", "Pierde dinero o armonía en casa y culpa a alguien cercano; antes debe revisar los hechos.", "Busca calma y sentido espiritual."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Se anuncian paz mental, relaciones favorables, comercio próspero, una venta ventajosa y reconocimiento por una tarea bien ejercida. Òtú permanece en Ifẹ trabajando; Ọ̀rúnmìlà recibe un consejo sobre justicia al gobernar. El relato de la Tierra trata la conservación de sus beneficios. La orientación espiritual favorable se expresa en claridad de propósito, no en sentirse superior a los demás."}, {"titulo": "Ibi y advertencias", "texto": "La cara difícil es gastar la propia energía hasta agotarse, confundir una ambición personal con destino, usar el poder sin justicia o actuar desde la avaricia. La ficha también presenta traiciones y conflictos familiares como posibilidades narrativas, no como hechos demostrados. Otra lectura advierte que un sentido inflado de importancia puede desviar a la persona de su propósito."}, {"titulo": "Enseñanza principal", "texto": "Tener visión exige examinarla y ponerla al servicio de una acción justa. El verso del gobierno de Ọ̀rúnmìlà recuerda que la autoridad atrae personas de muchos lugares y debe ejercerse con equidad. El descanso y la moderación ayudan a sostener los bienes que llegan. La devoción del relato de otra lectura se liga a tranquilidad, no a una licencia para imponer la propia voluntad."}, {"titulo": "Relatos reunidos", "texto": "Òtú viaja a Ifẹ para ejercer la adivinación y permanece allí largo tiempo. Otro Òtú recibe dos tortugas y busca el mejor mercado donde venderlas. Ọ̀rúnmìlà emprende la fundación de un pueblo y, en otro verso, pregunta por el sacrificio para gobernarlo con justicia. Otra lectura narra la vida devota de un viajero religioso y la venta de la Tierra en el mercado. Los relatos se conservan por separado."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El viaje de Òtú menciona báculos y carneras; la venta de las tortugas tiene su indicación propia. Los versos sobre fundación y gobierno de Ọ̀rúnmìlà ofrecen listas distintas. Otra lectura da otra ofrenda para la vida devota dirigida a Ọbàtálá, y una indicación separada para la Tierra. La ficha general menciona a Èṣù, Ògún, Yemọja e Ifá en contextos de comercio y relaciones. No se fusionan las listas ni se prescribe una práctica única del signo."}, {"titulo": "Relaciones espirituales", "texto": "Otra lectura asocia Òtúrá Méjì con Ọbàtálá y Ọ̀rúnmìlà y habla de Orí en relación con el propósito. Ọ̀rúnmìlà es protagonista de los versos sobre pueblo y gobierno; Ọbàtálá recibe una ofrenda en un relato. El texto principal nombra además a Èṣù, Ògún, Yemọja e Ifá en otro consejo. Esas menciones se muestran con su función concreta."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los báculos de caminante y las tortugas tienen un papel decisivo en dos relatos de Òtú. También aparecen esteras, plumas de loro, tela blanca, aceite de palma y cuentas en indicaciones de otros episodios. No hay una planta del signo identificada de manera inequívoca; los objetos deben conservarse ligados a su relato."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus reúne versos sobre el viaje de Òtú, la fundación y el gobierno de Ọ̀rúnmìlà, la venta de las tortugas y los dos otros relatos. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=13;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Méjì presenta la determinación como fuente de avance y como posible obstáculo. Otra lectura dice que crea determinación; cuando la meta es apropiada, ayuda a construir fortuna y buen carácter, pero dirigida sin reflexión se vuelve resistencia al cambio. Los testimonios A y B añaden dos preocupaciones distintas: descendencia y reputación ante las palabras ajenas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se está conformando con algo que ya no le sirve y eso lo lleva a un problema.", "Desea tener hijos o sufre por no lograrlos (relatos de Òdonràdà e Imò omi).", "Recibe burlas o le preocupa el qué dirán (la misma boca que alaba también ofende).", "Tiene una meta importante, pero su firmeza se volvió terquedad.", "Está cansado o presionado y necesita descansar y atender su cabeza (Orí) antes de decidir.", "Su forma de ser le complica la convivencia con otros (relato del cangrejo Akon en el mercado).", "Va a asumir una responsabilidad espiritual o a iniciar a otros."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Los textos anuncian hijos, abundancia, reputación recuperada, buen carácter y continuidad de una labor espiritual. El testimonio A celebra la descendencia de Òdonràdà; el B describe el fin de las burlas. Las personas de Ipere Amuyo reciben un consejo vinculado con la crianza y la conducta de sus hijos. La fortaleza favorable consiste en perseverar sin dejar de corregir el rumbo."}, {"titulo": "Ibi y advertencias", "texto": "La manifestación difícil es la obstinación, el conformismo que posterga una solución, el desgaste bajo presión o dejar que la burla ajena gobierne las decisiones. La historia del cangrejo muestra una conducta que choca con el mercado. La ficha tradicional menciona intrigas y enfermedad como posibilidades de consulta; ninguna constituye prueba de enemigos concretos ni diagnóstico clínico."}, {"titulo": "Enseñanza principal", "texto": "Perseverar exige humildad. La fuerza de Ìrẹtẹ̀ no consiste en repetir siempre la misma acción, sino en sostener el propósito y revisar los medios. El testimonio B recuerda que el juicio social puede cambiar de un día a otro; por eso el valor de una persona no puede depender por completo del elogio o el insulto. Otros pasajes atribuidos al signo prohíben robar alimentos y causar daño a una persona inocente; se conservan como enseñanzas éticas distintas de los relatos familiares."}, {"titulo": "Relatos reunidos", "texto": "Òdonràdà llora por no tener hijos y luego celebra su descendencia en el testimonio A. El testimonio B trata a una persona objeto de burlas y la ambivalencia de la boca humana. Ọ̀rúnmìlà e Ìrẹn aparecen en versos sobre iniciación y protección de quienes reciben el rito. Akon, el cangrejo, tiene dificultades para encajar en el mercado; otro relato histórico lo relaciona con Olúwẹri. Ipere Amuyo e Imò omi protagonizan historias sobre hijos y buen carácter. Cada una conserva su enseñanza particular. En un pasaje ético se nombran alimentos ajenos que no deben robarse; otro prohíbe ofrecer a una persona inocente en sacrificio. Un tercer verso trata el compromiso de la palabra y los acuerdos. Son fragmentos distintos del mismo signo."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los testimonios A y B aconsejan sacrificio, sin dar una lista completa. Los versos de Ọ̀rúnmìlà, Ìrẹn, Akon y Olúwẹri contienen indicaciones propias. Otra lectura da una ofrenda para Ipere Amuyo dirigida a Òṣun e Ifá y otra para Imò omi. El texto principal menciona Orí y prácticas relacionadas con Ọ̀rúnmìlà y Ṣànpọ̀nná en casos particulares. Ninguna lista se universaliza para el signo."}, {"titulo": "Relaciones espirituales", "texto": "Otra lectura asocia Ìrẹtẹ̀ Méjì con Òṣun, que aparece como destinataria en un relato de crianza. Ọ̀rúnmìlà e Ifá ocupan los versos de iniciación; Orí figura en el consejo del texto principal para sostener decisiones. Ṣànpọ̀nná se menciona allí en una situación de enfermedad. Son relaciones de textos distintos, no una secuencia ritual única."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Un verso menciona hojas de tẹ̀tẹ̀ para lavar Orí; otro usa aceite de palma y un mantón en la historia del cangrejo. Aparecen también el maíz preparado como eko y cuentas en los relatos de hijos. Se conserva el contexto de cada elemento."}, {"titulo": "Rezos, versos y cantos", "texto": "Se reúnen los versos sobre iniciación, el cangrejo Akon, los testimonios de Òdonràdà y la boca humana, y el canto de Imò omi sobre el valor de los hijos. También hay fragmentos éticos sobre robo, daño a inocentes y palabra comprometida. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=14;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Méjì reúne abundancia, fertilidad y estabilidad. Otra lectura lo relaciona con el rezo y el agua fresca, y advierte que buscar riqueza sin medida puede desplazar el buen carácter. El texto principal habla de condiciones variables en negocios y relaciones: hay posibilidades de amor y dinero, pero requieren confianza, cuidado y decisiones sostenidas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su negocio o su relación pasa por altibajos y busca estabilidad.", "El dinero le llega y se le va (relatos de Ajé, la riqueza).", "Busca amor, matrimonio o hijos.", "Necesita recuperar la confianza y no dejar que el miedo lo domine.", "Va a viajar o quiere ser reconocido (relato de Òtú camino a Ijebu).", "Desea llegar a viejo con bienestar (relato de Arugbó).", "Hizo una ofrenda a medias y eso le afecta (relato de Èjì-Ọ̀ṣẹ́)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Las posibilidades favorables son estabilidad económica, afecto, descendencia, reconocimiento y larga vida en los relatos que tratan esos bienes. Arugbó llega a la vejez; Òtú es tenido por persona importante; Ajé aparece como riqueza deseada por el mundo. Otra lectura vincula abundancia y fertilidad con el buen carácter y la oración, sin presentar el dinero como la única forma de prosperar."}, {"titulo": "Ibi y advertencias", "texto": "La riqueza puede ser inconstante, como muestra el verso en que Ajé rehúsa el consejo y no se establece en un lugar. Otra advertencia es reducir un compromiso a una parte de lo indicado: Èjì-Ọ̀ṣẹ́ entrega menos elementos de los aconsejados y sus bastones se rompen en el camino. La ficha menciona adversarios, pero eso no identifica enemigos reales ni justifica sospechar de terceros sin hechos."}, {"titulo": "Enseñanza principal", "texto": "La abundancia se sostiene mejor cuando no se vuelve avaricia. Los dos versos de Ajé muestran el deseo universal de riqueza y su inestabilidad. El signo invita a unir aspiración, autoconfianza, buen carácter y atención a la salud, en lugar de perseguir resultados inmediatos o confundir prosperidad con dinero solamente."}, {"titulo": "Relatos reunidos", "texto": "Arugbó, los ancianos, recibe consejo para alcanzar larga vida. Ajé protagoniza dos versos distintos: en uno, todo el mundo la busca; en el otro, no logra asentarse. Èjì-Ọ̀ṣẹ́ viaja a Ifẹ con una ofrenda incompleta. Òtú va a Ijebu y obtiene reconocimiento. Túwase Ihuloko busca que la bondad llegue al mundo. Son historias separadas que iluminan diferentes aspectos de la abundancia."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Arugbó, las dos historias de Ajé, Èjì-Ọ̀ṣẹ́, Òtú y Túwase tienen ofrendas diferentes. Otra lectura especifica una lista para el viaje de Òtú dirigida a Orí y otra para Túwase. La ficha general relaciona a Òṣun con amor y prosperidad, y a Ṣàngó y Ọ̀rúnmìlà con una situación de oposición. Las listas no se combinan en una prescripción única de Ọ̀ṣẹ́ Méjì. El pasaje del anciano enumera una gallina, algodón y dieciséis porciones de ẹfun (cascarilla) en su propia consulta."}, {"titulo": "Relaciones espirituales", "texto": "Òṣun es la asociación expresa de otra lectura y figura en el consejo del texto principal sobre amor y dinero. Orí recibe la ofrenda del relato de Òtú. Ṣàngó y Ọ̀rúnmìlà aparecen en otro consejo relacionado con adversidad; Ifá guía los relatos. Cada mención conserva su función específica."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Otra lectura usa el agua fresca como imagen de abundancia. Los relatos contienen algodón, ẹfún, bastones, tortas de frijol, eko de maíz y aceite de palma. En el relato de Túwase se nombran hojas del bosque y gbódógi. Los objetos se mantienen ligados al verso donde aparecen."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus incluye los versos de Arugbó, las dos historias de Ajé, el viaje de Èjì-Ọ̀ṣẹ́, el de Òtú y el relato de Túwase. Otra lectura relaciona la abundancia con el rezo (àdúrà). Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=15;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òfún Méjì presenta el florecimiento como resultado de paciencia, reciprocidad y generosidad. El texto principal habla de fortuna material, pero los versos insisten también en la sabiduría y en compartir. Otra lectura describe la respuesta a los rezos como imagen de manifestación; esa interpretación espiritual no equivale a una garantía de resultados."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Algo empieza a florecer y necesita sostenerlo con paciencia y compromiso.", "Busca dinero, aunque ya tiene otros bienes: conocimiento, amigos o capacidad de ayudar.", "Va a viajar y quiere que le vaya bien.", "Pregunta por hijos o por el futuro de la familia (relato de Ọlọ́fin y los dieciséis Odù).", "Tiene una deuda u obligación pendiente, quizá heredada (relato de la deuda de las madres de los Odù).", "Siente oposición y busca apoyo (relato de Eléjiórangún).", "Espera respuesta a una petición, una obra o un proyecto (relato de Òrìṣànlá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Los textos hablan de prosperidad, bendiciones, un viaje favorable, descendencia y reconocimiento de la propia obra. Òrìṣànlá recibe abundancia en un relato; Òràngúnméjì atiende Orí con una parte de la ofrenda en otro. La sabiduría de los Odù se presenta como riqueza incluso cuando no hay bienes materiales. La generosidad hacia familiares, personas extrañas y necesitadas forma parte de la caracterización favorable."}, {"titulo": "Ibi y advertencias", "texto": "La cara difícil consiste en dar por asegurado el éxito, descuidar obligaciones, retener recursos sin reciprocidad o buscar efectos destructivos mediante prácticas espirituales. Un verso presenta a los Odù que desoyen una deuda ritual y luego carecen de riqueza material. Las alusiones a problemas respiratorios del texto principal no permiten afirmar que todas las personas del signo los padezcan; cualquier síntoma requiere atención clínica."}, {"titulo": "Enseñanza principal", "texto": "La fortuna se mide también por lo que se comparte y por el conocimiento que permanece. El verso de los quince Odù y Èjìogbè contrapone pobreza material y sabiduría. Òfún Méjì invita a recibir sin olvidar obligaciones y a usar el propio éxito para sostener a otras personas."}, {"titulo": "Relatos reunidos", "texto": "Odù prepara pilares y una cadena al crear el carácter de los seres que llegan al mundo. Ọlọ́fin consulta por el nacimiento de los dieciséis Irúnmalẹ̀. Èjìogbè y los otros quince Odù afrontan una deuda de sus madres. Òràngúnméjì divide los materiales de su ofrenda y atiende Orí. Otra lectura conserva los relatos de Òrìṣànlá buscando abundancia y de Eléjiórangún ante oposición. Cada episodio aporta una enseñanza distinta."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los cuatro versos del texto principal describen ofrendas diferentes para creación, descendencia, obligación heredada y atención a Orí. Otra lectura presenta un àdìmú a Ọbàtálá para el relato de Òrìṣànlá y otra ofrenda para Eléjiórangún relacionada con Òrò. La ficha general menciona Ajé y Olókun en una situación de prosperidad. No se combinan esos contextos en un solo ẹbọ de Òfún Méjì."}, {"titulo": "Relaciones espirituales", "texto": "Otra lectura asocia el signo con Yemọja; el relato de Òrìṣànlá presenta a Ọbàtálá como destinatario de una ofrenda. Òrò aparece en el caso de Eléjiórangún. El texto principal menciona Ajé y Olókun en relación con fortuna económica, mientras Orí ocupa el verso de Òràngúnméjì. Se conserva la función propia de cada nombre."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los versos mencionan cuatro pilares, una cadena, ñame machacado, ekuru, olẹlẹ, palomas y objetos divididos para la atención a Orí. En otra lectura aparecen aceite de palma y otros elementos de ofrenda. No se identificó una planta específica del signo; los alimentos y objetos se muestran unidos a cada relato."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus contiene versos sobre la creación del carácter, los dieciséis Odù, la deuda de sus madres y la ofrenda de Òràngúnméjì. Otra lectura reproduce un rezo de buena fortuna de Òrìṣànlá y un relato de Eléjiórangún. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=16;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀yẹ̀kú plantea cómo concluir bien un camino que se abre. Otra lectura contrapone una terminación productiva con la interrupción prematura por falta de equilibrio. La ficha aconseja usar inteligencia y consejo antes que fuerza; el avance necesita alternar esfuerzo, descanso y atención al presente. Un pasaje cosmológico recuerda además la temporalidad de la vida humana."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Gasta mucha energía en ganancias rápidas que no duran.", "Se le abre una oportunidad, pero trabajar sin descanso o pelear sin necesidad puede cortarla.", "Tiene autoridad o dinero y cree que ya no necesita consejo.", "Le cuesta equilibrar trabajo, descanso y disfrute.", "Tiene una competencia o un obstáculo en un viaje y busca regresar bien (relato del camaleón Alàgemo y Olókun).", "No duerme bien o arrastra un conflicto que pasa de una persona a otra (relato de Olúkotún, Ọlọ́fin y el rey).", "Se pregunta por la muerte y el sentido de estar en la tierra (verso de la tierra como mercado y el cielo como hogar)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "El camino favorable es una conclusión productiva y proporcionada: progresar sin perder la capacidad de vivir el presente. Olúkotún recibe reconocimiento por su relación con Ifá en un relato; Alàgemo prepara su regreso después de medirse con Olókun. La imagen de Ogbè y Ọ̀yẹ̀kú unidos expresa una transformación que puede aprovecharse cuando se escucha consejo y se administra la energía."}, {"titulo": "Ibi y advertencias", "texto": "La cara difícil es abrir un camino y dejarlo inconcluso por exceso de esfuerzo, falta de balance, orgullo o afán de imponerse. El relato de Alàgemo muestra que una competencia puede producir represalias y obstáculos en el retorno. El pasaje de Olúkotún incluye cesiones matrimoniales propias de su mundo narrativo; no debe convertirse en práctica actual ni consejo para disponer de otra persona."}, {"titulo": "Enseñanza principal", "texto": "Saber avanzar incluye saber detenerse. Otra lectura pone juntos trabajo, descanso, juego y retiro; la ficha contrapone inteligencia y confrontación. El verso cosmológico sobre la tierra como mercado amplía la perspectiva: los bienes y conflictos de una etapa no agotan el sentido de la vida."}, {"titulo": "Relatos reunidos", "texto": "Olúkotún atiende a Ifá antes de acudir a Ọlọ́fin; el conflicto por una joven y el insomnio reaparece después ante un rey. Alàgemo compite con Olókun en vestidos y busca un regreso seguro cuando surge oposición. Otro verso atribuido a Ogbè Ọ̀yẹ̀kú habla del acuerdo sobre Ikú y usa la imagen de la tierra como mercado. Son relatos separados, con propósitos diferentes."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de Olúkotún presenta una ofrenda que incluye chivas y cauríes y una cesión humana en la narración histórica, que no se propone como acción actual. Alàgemo recibe indicaciones distintas para la competencia y para el regreso. Otra lectura ofrece aquí principios de balance en iré e ibi, no una lista universal. Un texto de ẹbọ conserva un verso propio sobre Orí; sus materiales no se trasladan a todos los casos."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las decisiones de Olúkotún y Alàgemo. Olókun aparece como contraparte de Alàgemo, no como destinatario universal de una ofrenda. Orí figura en un rezo del signo; Olódùmarè e Ikú aparecen en el pasaje cosmológico. Esas relaciones se muestran según su función en cada texto."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El relato de Alàgemo usa ropas de diversos colores, una estera de rafia y ñame machacado en contextos diferentes. También se nombran palomas, cauríes y cuentas. El verso cosmológico menciona el nudo de un árbol como imagen de resistencia. Ninguno de esos elementos se convierte por sí solo en una planta o una lista única del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conserva el verso del camaleón, el relato de Olúkotún, un rezo de Orí en un texto de ẹbọ, la serie de rezos y suyere titulada «Ogbe Yekun» y el verso cosmológico sobre tierra y cielo. Los repertorios escriben el nombre y el yorùbá de maneras distintas. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=17;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ìwòrì reúne confusión emocional y la posibilidad de concluir bien una situación. La ficha aconseja aprender de experiencias pasadas. Otra lectura describe, en iré, un conflicto que se resuelve al asumir responsabilidades; en ibi, el mismo conflicto puede alimentar arrogancia. Los relatos concretan esa elección en relaciones, viajes, trabajo y planes que conviene proteger."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Duda entre empezar o terminar una relación y debe separar la emoción del momento de lo que ya aprendió.", "Quiere que un proyecto llegue a buen fin sin perder lo ganado (relato de Ogbè visitando a Ìwòrì).", "Va a salir a un lugar nuevo y debe cuidar el camino y elegir bien dónde llegar (relato del cazador y el agricultor).", "Contó sus planes antes de tiempo y alguien cercano se los echó abajo (relato de Èbù Èyìn y Ògún).", "Una amistad se está enfriando por tacañería, enojo o desconfianza.", "Pregunta por un embarazo o por la responsabilidad de criar hijos.", "Se siente desordenado por dentro o teme quedarse sin apoyo (relato de la corneja Alukunrin)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La manifestación favorable es resolver un conflicto y terminar con éxito lo empezado. El verso de Ogbè y Ìwòrì se ocupa de conservar la riqueza recuperada. El cazador y el agricultor se preparan antes de salir; Ògún aprende a proteger sus decisiones. Otra lectura añade la transformación espiritual y la responsabilidad de la paternidad como posibilidades de crecimiento, no como un anuncio universal de embarazo."}, {"titulo": "Ibi y advertencias", "texto": "La confusión puede volverse arrogancia, enojo o repetición de errores. El cuento de Èbù Èyìn muestra cómo contar todos los planes facilita que se frustren; el de Alukunrin presenta la negativa a seguir un consejo. La afirmación antigua de que quienes nacen bajo el signo acabarán con enfermedad mental no se sostiene como pronóstico clínico y no se incorpora a la síntesis."}, {"titulo": "Enseñanza principal", "texto": "Mirar atrás sirve para aprender, no para quedarse inmóvil. Las experiencias pasadas ayudan a escoger una relación, proteger un negocio o planear un viaje. Otra lectura pide asumir la responsabilidad del propio desarrollo; otro testimonio enseña a reservar los planes hasta poder llevarlos a cabo, sin convertir la prudencia en sospecha permanente."}, {"titulo": "Relatos reunidos", "texto": "Ogbè visita a Ìwòrì y atiende una indicación para conservar sus bienes. Alukunrin, la corneja, rechaza una ofrenda vinculada en el relato con su desorden. En otro testimonio, un cazador y un agricultor consultan antes de ir a nuevas tierras. Otra historia presenta a Èbù Èyìn deshaciendo los planes de su hermano Ògún hasta que este cambia la manera de comunicarlos. Son episodios separados."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de la visita de Ogbè enumera chivos, gallos, ropa y una rata de monte en su caso particular. La historia de Alukunrin tiene otra lista de ropas y animales, además de plantas nombradas en una preparación. El cazador, el agricultor y Ògún reciben consejos de sacrificio en otro testimonio, sin que se traslade la lista de otro relato. Otra lectura enuncia iré e ibi como orientación, no como un ẹbọ único."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas y Èṣù figura en el verso sobre la conservación de riqueza. Ògún protagoniza la historia de los planes frustrados; no aparece allí como destinatario general de la ofrenda. Orí y las relaciones familiares se sugieren en el consejo sobre responsabilidad, pero las funciones deben distinguirse según cada texto."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen ropas usadas, una negra y otra blanca, la rata de monte, el perro y la presa del cazador, y la tierra elegida por el agricultor. El verso de Alukunrin menciona masínwín, ọgbó y esùsù. Cada elemento permanece ligado a su episodio."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los dos versos de Ogbè Ìwòrì, el texto del cazador y el agricultor y el relato de Èbù Èyìn. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=18;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ìdí trata una apertura que necesita cuidado para no volverse tropiezo. La ficha habla de presión emocional, a menudo ligada a la intimidad o la pareja, que reduce la capacidad de actuar. Otra lectura contrapone un renacimiento productivo, logrado con trabajo y optimismo, a cambios sin rumbo. Los relatos añaden deuda, amistad, viaje y descendencia como contextos diferentes."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay presión en lo afectivo y, mientras no la atienda, le cuesta sacar adelante un proyecto.", "Va a una salida o expedición y debe medir el obstáculo antes de meterse (relato de Ogbè atrapado en el elefante).", "Quiere salir de una deuda, pero otros lo distraen con encargos (relato de Èṣù pescador).", "Alguien querido que está lejos puede volver con buenas noticias (relato de Baáyannì y Ṣàngó).", "Desea tener hijos (relato de Àjàgbé).", "Trabaja para ganar más y ampliar su círculo.", "Siente celos o interrupciones en su avance."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura anuncia la transformación de una etapa pobre en abundancia mediante trabajo y ánimo sostenidos, con nuevos vínculos de amistad. Baáyannì vuelve con fortuna y comparte con Ṣàngó; Àjàgbé obtiene descendencia en su relato. La historia de Èṣù gira en torno a pagar una deuda y recuperar margen de acción. El bien del signo se muestra en una salida ordenada de la presión, no en cambiar por cambiar."}, {"titulo": "Ibi y advertencias", "texto": "La presión emocional sin atender puede cerrar posibilidades prácticas. El cazador Ogbè precipita su entrada en un hueco sin comprobar qué es; el episodio ilustra cómo un apuro se vuelve ridículo y peligroso. Otra lectura advierte sobre cambios sin dirección e interrupciones por celos. Esas advertencias no prueban que una persona específica esté saboteando al consultante."}, {"titulo": "Enseñanza principal", "texto": "Abrir camino exige observar antes de actuar y cumplir con cuidado lo decidido. El cazador no revisa el refugio que elige; Baáyannì, en cambio, vuelve con recursos y cuida la amistad. En la lectura de otra lectura, la mejora nace de trabajo constante y optimismo, no de huir de un problema íntimo sin resolverlo."}, {"titulo": "Relatos reunidos", "texto": "Ogbè sale de caza, busca abrigo durante una lluvia y acaba atrapado en un elefante. Èṣù trabaja como pescador para pagar una deuda con varias entidades, mientras recibe encargos que complican su plan. Baáyannì viaja y vuelve con fortuna para compartir con Ṣàngó. Àjàgbé, identificado en el relato con la mosca, busca hijos y celebra su numerosa descendencia. Son historias separadas."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La cacería de Ogbè tiene una lista de chivos, gallos y cauríes; el episodio de la deuda de Èṣù presenta otra con cascarones de palma, palomas y cauríes. Los textos de Baáyannì y Àjàgbé aconsejan sacrificio en sus casos propios sin que se transfiera la lista de los anteriores. Otra lectura ofrece aquí descripciones de iré e ibi, no un ẹbọ único de Ogbè Ìdí."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù protagoniza el relato de deuda con Ọ̀rúnmìlà, Òrìṣànlá, Òrìṣà Òkò y Ògún. Ṣàngó es el amigo con quien Baáyannì comparte su fortuna; Òrìṣànlá también aparece en el verso de Àjàgbé. Ifá guía las consultas. Cada entidad tiene un papel concreto dentro de su relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen el bosque de la cacería, la lluvia, el elefante, peces de la pesca de Èṣù y cascarones de nuez de palma. El relato de Baáyannì incluye cauríes y una prenda donde se atan. Ninguna mención permite fijar una planta principal del signo; cada elemento se conserva en su contexto."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus incluye los versos de Ogbè y el elefante, de Èṣù y la deuda, de Baáyannì y de Àjàgbé. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=19;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ìrosùn habla de recuperar equilibrio y llevar a buen término un camino que se abre. Otra lectura relaciona el iré con apoyo ancestral y progreso lento y constante; el ibi surge cuando la persona rechaza ese sostén y se vuelve inestable. Los relatos concretos tratan de protección, fortuna que llega de lejos y deseo de descendencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene varios problemas a la vez y busca recuperar orden y calma.", "Teme una pérdida, una enfermedad o un problema legal (relato de Àbàtí).", "La oportunidad de dinero viene de fuera o exige salir a buscarla (relato de Òdùkèkèèkè en el bosque).", "Pregunta por hijos o por un embarazo (canto de Òsìn Gàgààgà).", "Necesita avanzar poco a poco en lugar de exigir resultados inmediatos.", "Busca el respaldo de sus antepasados para continuar lo que empezó."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable de otra lectura es avanzar con apoyo ancestral y constancia. Àbàtí recibe en un verso una promesa religiosa de protección; Òdùkèkèèkè vuelve con bienes a su casa; Òsìn Gàgààgà celebra hijos. La fortuna puede venir de lejos, pero los relatos insisten en prepararse para recibirla y conservarla."}, {"titulo": "Ibi y advertencias", "texto": "La manifestación difícil es la inestabilidad que surge al apartarse de apoyos valiosos o abandonar un proceso antes de tiempo. El nombre Àbàtí se glosa como incumplimiento o tarea inconclusa y permite leer el relato como advertencia contra el descuido. Las menciones de muerte, enfermedad y pleitos son motivos narrativos; no constituyen pronóstico médico o legal."}, {"titulo": "Enseñanza principal", "texto": "Un camino abierto se aprovecha paso a paso. El apoyo de generaciones anteriores y la conducta coherente pueden sostener lo que una oportunidad inicia. Òdùkèkèèkè no solo encuentra bienes: la historia se ocupa de que pueda llevarlos a casa sin perderlos."}, {"titulo": "Relatos reunidos", "texto": "Àbàtí, hijo de Aramfè, consulta ante varios males y recibe una indicación de protección. Òdùkèkèèkè entra al bosque, recoge fortuna y regresa con ella. Òsìn Gàgààgà aparece en un canto sobre tener hijos."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Àbàtí menciona carnero y hojas o medicina de Ifá. El testimonio relaciona el caso de Òdùkèkèèkè con un sacrificio propio y, en otro comentario, nombra babosas y huevos para una consulta sobre descendencia. El relato de Òsìn Gàgààgà también aconseja una ofrenda sin detallar aquí una lista completa. Se conservan esas diferencias y no se compone un ẹbọ universal."}, {"titulo": "Relaciones espirituales", "texto": "Otra lectura habla del sostén ancestral como eje del signo. Ifá guía las consultas de Àbàtí, Òdùkèkèèkè y Òsìn Gàgààgà; Odù se menciona en una indicación de otro testimonio relacionada con descendencia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El bosque es el lugar de la búsqueda de Òdùkèkèèkè. La ofrenda de Àbàtí nombra hojas o medicina de Ifá sin identificar una especie. El testimonio menciona huevos y babosas en una situación de descendencia."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Àbàtí, el canto de Òdùkèkèèkè sobre traer fortuna al hogar y el de Òsìn Gàgààgà sobre hijos. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=20;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀wọ́nrín habla de elegir bien entre varias posibilidades y de convertir una sorpresa en ocasión de crecimiento. El texto principal se centra en pareja y oportunidades de negocio; otra lectura advierte sobre caos inesperado, especialmente en los desplazamientos. Un relato de otro testimonio añade la necesidad de reconocimiento por el trabajo realizado."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene que escoger entre opciones de pareja o ver si una unión les conviene a los dos (relato de Koko, Apata y Àkùrò).", "Quiere atraer clientes o fortalecer sus relaciones.", "Hace cosas por otros y nadie se lo agradece (relato de Ṣeşeeşe kò lórí yìn).", "Busca buena compañía y cariño (relato de Ọlọ́fin y Ogbè).", "Se acerca un viaje y puede haber un imprevisto en el camino.", "Algo que parecía mala suerte puede abrirle una salida si actúa con flexibilidad."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Se describen una unión compatible, compañía afectuosa, más clientela y reconocimiento por el esfuerzo. Koko elige a Àkùrò, cuya prosperidad se liga a la de ella. Ṣeşeeşe recibe alabanza después de reunir a otros en torno a una comida. Otra lectura interpreta el cambio inesperado como posibilidad de revertir una mala racha, sin prometer que todo imprevisto será favorable."}, {"titulo": "Ibi y advertencias", "texto": "El camino puede bloquearse por caos repentino. Un viaje merece atención práctica y la elección de pareja no debería tomarse por impulso. El resentimiento por falta de reconocimiento puede impedir ver otras maneras de compartir el trabajo. El texto de otra lectura menciona un accidente como posibilidad, no como predicción inevitable."}, {"titulo": "Enseñanza principal", "texto": "Elegir bien implica mirar si las dos partes pueden prosperar juntas. Koko y Àkùrò ofrecen esa imagen. El relato de Ṣeşeeşe añade otra forma de reciprocidad: hacer visible el trabajo y reunir a la comunidad puede transformar la indiferencia en reconocimiento."}, {"titulo": "Relatos reunidos", "texto": "Koko, el tubérculo, considera casarse con Apata, la roca, o Àkùrò, la tierra cultivable, y recibe un consejo para elegir. Ọlọ́fin consulta por la compañía de Ogbè. En otro testimonio, Ṣeşeeşe kò lórí yìn lamenta que sus acciones no sean apreciadas y luego recibe reconocimiento. Son tres relatos separados, además de la orientación breve de otra lectura sobre cambios inesperados."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Koko menciona palomas y telas anudadas; el de Ọlọ́fin, gallos, ñame machacado y sopa. El testimonio describe para Ṣeşeeşe una reunión con comida y un elemento escrito ẹyin, glosado de forma discrepante en el original; también menciona otra ofrenda relacionada con bienes que llegan del exterior. Cada indicación responde a su historia y no se convierte en un ẹbọ universal de Ogbè Ọ̀wọ́nrín."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas de Koko, Ọlọ́fin y Ṣeşeeşe. Ogbè aparece como compañero deseado en el verso de Ọlọ́fin. El testimonio menciona a los babaláwo reunidos por Ṣeşeeşe y las distintas bendiciones que busca. No se deduce de estas historias una lista única de orichas destinatarios."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Koko es un tubérculo en el relato de elección; Àkùrò representa tierra cultivable y Apata una roca. En otros versos aparecen ñame machacado, sopa, un elemento escrito ẹyin, telas y palomas."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de Koko y Ọlọ́fin y el canto de Ṣeşeeşe kò lórí yìn, con su búsqueda de reconocimiento y diversas bendiciones. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=21;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀bàrà reúne trabajo intenso, necesidad de calma y cuidado de la salud. Otra lectura presenta en iré una apertura hacia la transformación personal; en ibi, el rechazo a atender el propio bienestar puede cerrar oportunidades. Los versos añaden variaciones estacionales, amistades que cambian, pareja y descendencia. Ningún motivo se convierte por sí solo en un diagnóstico."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se exige demasiado en el trabajo y necesita descansar o avanzar de forma más sostenible.", "Tiene molestias que vuelven cada temporada (relato de las aves en la sequía).", "Busca paz mental y apoyo en su pareja, y no debe tratarla con mezquindad.", "Una amistad cercana se volvió peligrosa (relato de Àfòn e Ìtí).", "Desea formar familia (relato de Ebè y el melón Bàrà).", "Teme una pérdida importante (relato de Ọ̀rúnmìlà ante la visita de Ikú).", "Quiere conocerse mejor y cambiar hábitos que le hacen daño."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de transformación y descubrimiento personal. El testimonio presenta a Àfòn ayudada por sus hijos frente a Ìtí y a Bàrà formando una familia numerosa con Ebè. La ficha sugiere que reducir la sobrecarga y cuidar los vínculos ayuda a aprovechar el camino abierto. Los relatos religiosos de protección no garantizan un resultado médico."}, {"titulo": "Ibi y advertencias", "texto": "El riesgo es forzarse hasta el agotamiento, ignorar señales de malestar o persistir en una relación que hace daño. La fábula de Àfòn e Ìtí dramatiza la traición entre amigas; no autoriza a sospechar de toda amistad. Los pasajes sobre enfermedades estacionales e Ikú son motivos tradicionales; una molestia física requiere valoración médica, no una inferencia desde el Odù."}, {"titulo": "Enseñanza principal", "texto": "Cuidarse también es parte del trabajo. La historia de las aves contrasta a quienes atienden una advertencia con quienes la ignoran. Ebè aprende que la mezquindad dificulta la vida en pareja. El signo invita a bajar la presión, revisar relaciones y actuar con generosidad antes de que el esfuerzo o el miedo consuman la oportunidad."}, {"titulo": "Relatos reunidos", "texto": "Las aves reciben una indicación ante las enfermedades de la estación seca. Ọ̀rúnmìlà se prepara para la visita de Ikú. En otro testimonio, Àfòn enfrenta a Ìtí con ayuda de sus hijos; Ebè se casa con Bàrà, el melón, y ve crecer su familia. Son cuatro episodios diferentes: cuidado estacional, protección, amistad y pareja."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de las aves menciona nueces de kola y cauríes; el de Ọ̀rúnmìlà, una chiva e ikines. El testimonio aconseja a Àfòn una ofrenda ligada a su conflicto y a Ebè otra para la relación con Bàrà. No se trasladan ingredientes de un episodio al otro ni se propone un ẹbọ único para el signo."}, {"titulo": "Relaciones espirituales", "texto": "Ifá orienta los cuatro relatos. Èṣù habla a Àfòn en la fábula de su amistad con Ìtí; Ọ̀rúnmìlà es protagonista del verso donde aparece Ikú. Orí y la calma mental son temas de la caracterización, pero las funciones de cada entidad permanecen en su contexto narrativo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El melón Bàrà es personaje del relato de Ebè. La estación seca, las nueces de kola, el garrote de Àfòn y los ikines de Ọ̀rúnmìlà pertenecen a historias distintas. Àfòn e Ìtí se conservan como nombres de personajes de otro testimonio."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus conserva el verso de las aves, el de Ọ̀rúnmìlà y las narraciones cantadas de Àfòn con Ìtí y de Ebè con Bàrà. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=22;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀kànràn advierte que actuar a medias puede hacer perder una ganancia ya alcanzada. La ficha describe a una persona apurada; otra lectura contrasta una dirección falsa con una nueva forma de proceder que vuelve más sencillo el trabajo. Los relatos muestran bienes inesperados, descendencia y reconocimiento, pero también el costo de descuidar una parte de la tarea."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se apresuró y dejó algo a medias, y eso pone en riesgo lo que ya tenía.", "Su manera de hacer las cosas ya no funciona; necesita cambiar de método, no solo esforzarse más.", "Busca dinero, pareja o hijos, pero cumplió solo una parte de lo que le pidieron (relato de Ogbè y Otuufe).", "Tiene recursos pero sufre por no tener hijos o por las burlas de otros (relato de Sièjidé).", "Puede lograr algo que nadie esperaba (relato de Lábógundé, que llega a ser Èwí).", "Piensa mudarse o establecerse en otro lugar (relato de Bikibi en el bosque de Ògún)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de un camino nuevo al cambiar el procedimiento. Bikibi encuentra un lugar agradable; Lábógundé alcanza un cargo que otros no preveían; Sièjidé celebra maternidad en su relato. El verso de Ogbè ante Otuufe muestra dinero, compañía e hijos, aunque su ofrenda incompleta limita el desenlace. La oportunidad favorable crece cuando la persona completa bien lo que decide hacer."}, {"titulo": "Ibi y advertencias", "texto": "La prisa, las medias acciones y la resistencia a revisar el método pueden producir pérdida. Ogbè reduce los materiales indicados y luego lamenta la cuarta parte que omitió. Las burlas sufridas por Sièjidé son daño social dentro de una historia, no un criterio para juzgar a alguien que pregunta por fertilidad. Ningún verso garantiza embarazo o un cargo público."}, {"titulo": "Enseñanza principal", "texto": "Completar una tarea es distinto de hacerla con apuro. Otra lectura propone cambiar procedimientos cuando el esfuerzo se vuelve innecesariamente difícil. El cuento de Ogbè muestra el costo de entregar menos de lo acordado; el de Lábógundé recuerda que un resultado inesperado puede surgir después de preparar el camino."}, {"titulo": "Relatos reunidos", "texto": "Ogbè visita a Otuufe y usa tres de cuatro elementos indicados, recibiendo bienes pero lamentando la parte ausente. Bikibi consulta antes de asentarse en el bosque de Ògún. En otro testimonio, Sièjidé busca hijos mientras otros se burlan de ella y después celebra su nacimiento; Lábógundé pasa de la carencia al cargo de Èwí en Àdó. El bloque siguiente de otro testimonio corresponde a Ogbè Ògúndá y queda fuera de esta ficha."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ogbè menciona cuatro objetos escritos ṣẹrin y cauríes; entregó solo una parte. Bikibi recibe una indicación diferente con un perro. Los relatos de Sièjidé y Lábógundé también incluyen sacrificio, sin que se tomen para ellos ingredientes del primer verso. No existe una lista única derivada de estas historias."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas; Ọ̀rúnmìlà escucha a Sièjidé en otro testimonio. Ògún aparece en el nombre del bosque al que va Bikibi, sin que ello lo convierta en destinatario general de un ẹbọ. Orí figura en el canto de Sièjidé como parte de la historia de su cambio de fortuna."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El bosque de Ògún es escenario del viaje de Bikibi. El verso de Ogbè utiliza ṣẹrin, un objeto de identificación incierta en las glosas disponibles. Los cauríes y otros bienes del camino son elementos de esa narración, no una lista botánica del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se reúnen los versos de Ogbè ante Otuufe y de Bikibi, los cantos de Sièjidé por riqueza e hijos y el de Lábógundé por su nombramiento."}]$q$::jsonb where numero=23;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ògúndá, llamado también Ogbèyónú, trata oportunidades que pueden parecer poco valiosas al principio. La ficha habla de éxito material cuando se examina una propuesta antes de rechazarla. Otra lectura añade que un camino abierto exige retirar obstáculos y reconocer el fruto de esfuerzos previos; la falta de generosidad puede convertirlo en conflicto. Otros versos del signo destacan paciencia y relación entre Orí interior y Orí exterior."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le llega una oportunidad o un regalo que por fuera no convence, pero por dentro vale mucho (relato del paquete de hojas de koko).", "Espera la recompensa de un trabajo anterior y no ve que ya se le abrió el camino.", "Busca riqueza y estabilidad familiar (relato de la gente de Egún Majo).", "Se alejó de quien antes lo ayudaba y desde entonces no le va bien (relato de Àyìnnipinpin y Ẹlẹ́gùdumòró).", "Siente que ayudar le sale caro y no valora lo que gana con eso.", "Desea pareja o hijos.", "Se siente mal recibido o menospreciado al intentar una relación (relato de Ọ̀rúnmìlà en Ìwó)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de riqueza que llega por un esfuerzo anterior. Ọràngún acepta el paquete rechazado por Alárá y Ajerò y encuentra valor en su interior. Egún Majo recibe un anuncio de prosperidad. Ẹlẹ́gùdumòró disfruta bienes e hijos al mantener una relación de confianza con Àyìnnipinpin. La oportunidad favorable puede depender de mirar más allá de la primera impresión."}, {"titulo": "Ibi y advertencias", "texto": "Rechazar de inmediato lo que parece modesto puede dejar escapar un bien. Otra lectura advierte que la falta de generosidad abre conflicto. El relato de Ẹlẹ́gùdumòró muestra que abandonar una relación que funcionaba por disputar su costo cambia el resultado. No implica aceptar cualquier oferta sin examinarla: la enseñanza es valorar su contenido, consecuencias y reciprocidad."}, {"titulo": "Enseñanza principal", "texto": "El valor no siempre coincide con el envoltorio. Ọràngún abre el regalo que otros desechan; Ẹlẹ́gùdumòró compara a varios consejeros y aprende qué relación le daba resultado. Ogbèyónú invita a considerar las oportunidades con atención y a cuidar la reciprocidad con quienes colaboran en el camino. Un verso del Orí interior y exterior insiste en la paciencia frente a la cólera; otro relato de Ìwó muestra que el reconocimiento no siempre llega de inmediato."}, {"titulo": "Relatos reunidos", "texto": "Las personas de Egún Majo consultan por prosperidad. Alárá y Ajerò rechazan un regalo envuelto en hojas secas de koko; Ọràngún lo acepta y descubre cuentas valiosas. En otro testimonio, Àyìnnipinpin ayuda a Ẹlẹ́gùdumòró, quien luego se aparta de él, prueba con otros sacerdotes y vuelve a llamarlo. Los episodios se mantienen separados. En una tradición adicional, Ọ̀rúnmìlà llega a Ìwó, enfrenta desdén y acaba ligado a un relato sobre el nombre de la esposa; ese episodio es independiente del regalo y de Àyìnnipinpin."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Egún Majo recibe una lista propia con puercos, cauríes y vino. El relato del regalo tiene otra indicación asociada a aceptar lo enviado. El testimonio nombra kola, comida y bebida en la relación de Ẹlẹ́gùdumòró con Àyìnnipinpin. Esas prácticas pertenecen a contextos distintos y no forman un único ẹbọ de Ogbè Ògúndá."}, {"titulo": "Relaciones espirituales", "texto": "Ifá orienta las consultas de Egún Majo y de los tres receptores del regalo. Àyìnnipinpin aparece como sacerdote de la casa de Ẹlẹ́gùdumòró; el relato trata una relación de ayuda y confianza, no una lista general de orichas. La ficha de otro testimonio menciona a los líderes de la propia tradición como vínculo que conviene cuidar. Orí interior y exterior son protagonistas personificados de otro verso atribuido al signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Las hojas secas de koko envuelven el regalo que otros desprecian. También aparecen cuentas, nuez de kola, comida, vino y otros bienes entregados. Su sentido depende de la historia en que aparecen."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Egún Majo, el de Alárá, Ajerò y Ọràngún, y el canto de Àyìnnipinpin con Ẹlẹ́gùdumòró. Se suman por separado el verso de paciencia de Orí y el relato de Ìwó. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=24;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀sá trata la constancia ante un camino áspero y la necesidad de terminar lo empezado. La ficha advierte sobre la posibilidad de engaño entre amistades; otra lectura contrapone una apertura hacia abundancia con la decepción causada por otros o por la propia falta de juicio. Sus dos relatos principales muestran un viaje próspero y una amistad que se convierte en amenaza."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Lo que está haciendo se puso difícil y piensa dejarlo antes de terminar.", "Va a viajar por trabajo y allá puede encontrar con qué prosperar (relato de Ogbè en Alahusa).", "Un amigo o una propuesta le da desconfianza, o parece demasiado buena (relato de Iki y el carnero Agbo).", "Busca recursos fuera de su entorno y debe evaluar bien el viaje.", "Teme perder por confiar sin revisar los hechos.", "El obstáculo principal puede ser una expectativa propia o una decisión apresurada."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable de otra lectura habla de viajar para encontrar fortuna y abundancia. Ogbè recibe en Alahusa una promesa de progreso y se prepara antes de ir. El texto principal añade que el esfuerzo sostenido puede llevar a concluir una obra difícil. En la historia de Iki, escuchar una advertencia le permite actuar con prudencia frente a una relación de riesgo."}, {"titulo": "Ibi y advertencias", "texto": "El peligro es rendirse antes de acabar o dejarse llevar por una propuesta de un amigo sin considerar sus consecuencias. El carnero intenta servirse de Iki en el relato; esto es una fábula de engaño, no un permiso para acusar a alguien. Otra lectura también llama la atención sobre el autoengaño: atribuir toda dificultad a otros puede ocultar un error propio."}, {"titulo": "Enseñanza principal", "texto": "Persistir y confiar requieren discernimiento. Ogbè avanza hacia Alahusa con preparación; Iki presta atención a una advertencia sobre una amistad. El signo invita a sostener un propósito, pero también a revisar si el camino o la relación elegidos todavía son adecuados."}, {"titulo": "Relatos reunidos", "texto": "Lekeleke consulta para Ogbè antes de su viaje a Alahusa, donde se espera que prospere. En otro verso, Iki es advertido sobre Agbo, el carnero, que intenta presentarlo como ofrenda ante Ọlọ́fin después de ganarse su confianza. Son dos historias separadas: una trata oportunidad de viaje; la otra, engaño y protección."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato del viaje de Ogbè menciona palomas y cauríes; el de Iki, nueces de kola, pulseras de hierro, cauríes y un recipiente de madera con tapa. Son listas de circunstancias distintas. No se combinan en un ẹbọ único del signo ni se aplican automáticamente a toda consulta sobre viajes o amistades."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las dos consultas. Ọlọ́fin y Egúngún aparecen dentro de la historia de Iki; el carnero se acerca al lugar de culto de Egúngún como parte del engaño narrado. Ninguno de ellos se transforma por esa aparición en destinatario universal de una ofrenda de Ogbè Ọ̀sá."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Las nueces de kola, el hierro de las pulseras, el cuenco de madera y las palomas tienen funciones concretas en las ofrendas descritas. Agbo es el carnero del cuento. No se identificó una planta propia del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Lekeleke para el viaje de Ogbè y la narración de Iki con Agbo. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=25;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ìká pide superar celos, desconfianza y fantasías que desvían la atención de los hechos. La ficha propone más sentido común en la vida diaria; otra lectura contrapone contemplación y cautela con arrogancia que aleja amistades. Los relatos tratan de respeto, fama, regreso de una fortuna y una relación que se reencuentra en su propia historia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Imagina ofensas o desconfía sin pruebas; debe revisar los hechos antes de reaccionar.", "Quiere que respeten su trabajo, sus derechos o su lugar.", "Una fortuna o una oportunidad salió de su casa y espera que vuelva.", "Una pareja se separó y alguno piensa en regresar (relato de Ìtipónọlá y Ahoro).", "Desea reconocimiento en su profesión (relato del médico Arinwaka).", "Se siente arrastrado por lo que otros le piden (relato de la corriente Ogbàrá-ojo).", "Necesita parar, aceptar consejo y no perder amistades por orgullo."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable de otra lectura es un tiempo de reflexión que abre otras posibilidades. Arinwaka alcanza reconocimiento en su relato; Ogbàrá-ojo llega a ser respetada. El testimonio habla de una fortuna que vuelve y de derechos reconocidos. La mejora se asocia con prudencia, conducta adecuada y capacidad de corregir una decisión."}, {"titulo": "Ibi y advertencias", "texto": "Los celos y la arrogancia pueden aislar a la persona y dañarle relaciones. Ogbàrá-ojo rechaza un consejo y su curso queda sometido al paso de otros antes de cambiar su situación. En cuestiones de pareja, la historia de Ìtipónọlá no justifica presionar a alguien para que regrese ni anular una separación decidida libremente."}, {"titulo": "Enseñanza principal", "texto": "El respeto se gana mejor con juicio que con sospechas. Otra lectura habla de contemplar y seguir consejo; la ficha pide menos imaginación aplicada a agravios y más atención a la realidad. El relato de Ogbàrá-ojo muestra que una respuesta tardía aún puede mejorar una situación, mientras la historia de Arinwaka vincula oficio y reconocimiento."}, {"titulo": "Relatos reunidos", "texto": "Èṣùmàrè, el arcoíris, adivina para Ogbàrá-ojo, una corriente que termina cambiando su relación con quienes la rodean. Arinwaka, médico de Ọwọni, consulta por su fama. En otro testimonio, Ìtipónọlá se separa de Ahoro y luego vuelve en la narración. Son tres relatos distintos; otro testimonio añade una caracterización sobre fortuna y derechos."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ogbàrá-ojo menciona azadón, machete y chivo; el de Arinwaka, rata de monte, pescado y gallina. El relato de Ìtipónọlá aconseja sacrificio sin que aquí se traslade la lista de otro verso. Las indicaciones se mantienen en sus contextos y no forman un ẹbọ único de Ogbè Ìká."}, {"titulo": "Relaciones espirituales", "texto": "Ifá orienta los tres relatos. Èṣùmàrè aparece como adivino en el verso de Ogbàrá-ojo; Ògún es nombrado en el canto de Ìtipónọlá como parte de una fórmula de linaje. Estas apariciones no hacen de ambos destinatarios de la misma práctica."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El bosque y la corriente de agua son imágenes del relato de Ogbàrá-ojo. El azadón y el machete pertenecen a su indicación; el pescado, a la de Arinwaka. No se identificó una planta específica de este signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Ogbàrá-ojo, el de Arinwaka y el canto de Ìtipónọlá. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=26;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Òtúrúpọ̀n pone en relación competencia, cuidado del bienestar y legado familiar. La ficha habla del riesgo de quedar atrás; otra lectura contrapone una apertura sostenida por buen carácter con planes que se interrumpen cuando se descuida la salud. Los relatos muestran estatus, descendencia, riqueza y un buen nombre que perdura después de una persona."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se compara con otros y teme perder su lugar (relato de la vaca y el caballo).", "Desea hijos o busca guía espiritual (relato de Alaworo-Oriṣà).", "Pregunta a la vez por dinero, pareja e hijos (relato de Sèkèrè).", "Recibió un nombre o una herencia familiar y debe cuidarla sin malgastar.", "Quiere dejar un buen nombre que la gente recuerde (relato del árbol Ìrókò).", "Un problema de salud o un plan frustrado necesita atención práctica.", "Debe escuchar a sus padres o mayores antes de una decisión importante."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "El caballo obtiene un estatus favorable en su relato. Alaworo-Oriṣà busca descendencia; Sèkèrè recibe abundancia; Ìrókò logra un nombre recordado con respeto. Otra lectura relaciona el camino favorable con buen carácter y cuidado de la vida. La bendición de otro testimonio incluye conservar la reputación familiar, no solo sumar dinero."}, {"titulo": "Ibi y advertencias", "texto": "La comparación constante puede volver amarga una oportunidad. La vaca rechaza el consejo en un verso y el caballo pasa a ser más estimado. El testimonio advierte contra desobedecer a los padres o gastar sin prudencia una herencia recibida. Los pasajes sobre enfermedad o larga vida son motivos tradicionales, no diagnósticos ni garantía médica."}, {"titulo": "Enseñanza principal", "texto": "La posición que se recibe y el nombre que se deja requieren cuidado. Ìrókò sigue siendo referencia incluso cuando el árbol ya no está; esa imagen liga reputación con conducta duradera. Sèkèrè muestra abundancia, mientras el consejo de otro testimonio recuerda administrarla para que el legado familiar no se pierda."}, {"titulo": "Relatos reunidos", "texto": "La vaca y el caballo consultan por su estatus relativo. Alaworo-Oriṣà busca hijos y recibe una indicación propia. Sèkèrè, hijo de Àlákòlé, pregunta por riqueza, pareja e hijos y celebra la llegada de bienes. Ìrókò busca un buen nombre que la comunidad siga recordando. El testimonio pasa después a Ogbè Òtúrá, que no se incorpora a esta ficha."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La historia de la vaca y el caballo menciona azadones y cauríes; la de Alaworo-Oriṣà, tela blanca, gallinas y cauríes. Sèkèrè recibe en otro testimonio una indicación de dinero sin una lista completa de otros materiales; Ìrókò recibe otra relacionada con reputación. No se completa lo ausente ni se combinan las ofrendas en un ẹbọ único."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía los cuatro relatos. Èṣù interviene en la historia del caballo y la vaca, favoreciendo el reconocimiento del caballo dentro de la narración. Alaworo-Oriṣà busca una relación con Oriṣà; otro testimonio destaca la continuidad de los ancestros y el respeto a padres. Estas funciones no se fusionan en una sola práctica."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El árbol Ìrókò es la imagen central del relato sobre el buen nombre; se conserva su nombre tradicional sin asignar aquí una especie científica. El azadón, la tela blanca y las cuentas del cuerpo de Sèkèrè aparecen en contextos distintos. El caballo y la vaca son personajes de una fábula sobre estatus."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el canto Jigbinni del caballo, el verso de Alaworo-Oriṣà y los cantos de Sèkèrè y Ìrókò. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=27;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Òtúrá vincula paz con claridad y preparación. Otra lectura contrapone una visión clara del camino con la pérdida que puede nacer de complacerse demasiado. La ficha menciona un conflicto laboral que puede resolverse; otro testimonio recuerda que algunas ganancias maduran tarde y que el trabajo de los primeros años sostiene etapas posteriores."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un conflicto en el trabajo y quiere resolverlo sin perder la calma.", "Desea adquirir bienes o que le lleguen oportunidades a casa (relato de Ọlomo-Agbeti).", "Se impacienta porque el éxito material tarda; puede llegar en una etapa más avanzada de la vida.", "Debe repartir bien su esfuerzo entre la juventud y la madurez (relato del Amanecer y el Crepúsculo).", "Busca paz o dirección espiritual (relato de Ọ̀rúnmìlà al llegar al mundo).", "Está tan cómodo con lo que tiene ahora que puede descuidar el futuro."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable es claridad para hallar paz, resolver una disputa y recibir bienes con el tiempo. Ọlomo-Agbeti espera adquisiciones que llegan a su puerta. Amanecer trabaja y prepara la etapa del Crepúsculo en el relato de otro testimonio. Ọ̀rúnmìlà encarna la constancia de seguir la orientación recibida incluso desde una posición de autoridad."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte contra la complacencia que acaba produciendo pérdida. El cuento de Amanecer y Crepúsculo contrasta preparación y omisión; no exige trabajar sin descanso, sino pensar en el futuro. Las promesas tradicionales de paz o larga vida no son garantías de salud ni resultados económicos."}, {"titulo": "Enseñanza principal", "texto": "La paz necesita decisiones sostenidas. Ọ̀rúnmìlà, aun siendo figura de gran saber en el verso, atiende el consejo de Ifá. El relato del día y la noche enseña que el fruto de una etapa depende en parte de lo que se hizo en la anterior. La claridad ayuda a resolver conflictos sin sacrificar el porvenir."}, {"titulo": "Relatos reunidos", "texto": "Ọ̀rúnmìlà recibe consejo antes de venir al mundo y se presenta como ejemplo de atención constante a Ifá. Ọlomo-Agbeti pregunta por bienes que llegarán a su hogar. En otro testimonio, Amanecer y Crepúsculo reciben la misma indicación y responden de manera diferente. Son tres episodios separados."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ọ̀rúnmìlà menciona chiva, rata de monte y pescado; el de Ọlomo-Agbeti, rata, pescado y dos figuras. Amanecer y Crepúsculo reciben una indicación en su propio relato. El testimonio también habla de reunir y alimentar a niños en una situación particular. Las listas no se fusionan en un ẹbọ universal de Ogbè Òtúrá."}, {"titulo": "Relaciones espirituales", "texto": "Ifá y Ọ̀rúnmìlà ocupan el relato sobre la llegada al mundo. El testimonio menciona Ègbérun en una recomendación particular. Ninguna aparición convierte a todas estas entidades en destinatarias de una misma ofrenda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los relatos nombran azadón y machete en los epítetos de los adivinos, además de pescado, rata de monte y figuras usadas en ofrendas específicas. Amanecer y Crepúsculo son imágenes temporales, no plantas. No se identificó una especie botánica propia del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Ọ̀rúnmìlà, el de Ọlomo-Agbeti y el canto del Amanecer y el Crepúsculo. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=28;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ìrẹtẹ̀ pide determinación con criterio. La ficha habla de prevenir pérdidas en trabajo o pareja y de preparar viajes prometedores; otra lectura añade que hay desplazamientos innecesarios que conviene evitar. Los relatos muestran tanto un viaje imprudente como riqueza obtenida en otra ciudad o mediante el trabajo conjunto de personas distintas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme perder un empleo o una relación y debe ver qué cuidar y qué cambiar.", "Planea un viaje y debe saber si es una oportunidad real o un movimiento sin propósito.", "Personas que no son familia pueden unirse y salir ganando (relato de Erin, Ẹfọn y Eṣinṣin).", "Un negocio en otra ciudad o un trabajo de campo puede traer dinero a casa (verso de Ọ̀rúnmìlà).", "No quiere escuchar una advertencia concreta (relato de Ewọn, Iro e Ìgèdè).", "Se siente estancado y la terquedad no le deja cambiar el plan."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura describe un camino abierto que requiere decisión. Ọ̀rúnmìlà recibe bienes desde la ciudad en un verso. En otro testimonio, Erin, Ẹfọn y Eṣinṣin combinan esfuerzos y obtienen influencia, reconocimiento y ganancias de la granja. La prosperidad se relaciona con colaboración y con escoger el desplazamiento adecuado."}, {"titulo": "Ibi y advertencias", "texto": "El relato de Ewọn, Iro e Ìgèdè muestra las consecuencias de ignorar un aviso de no ir a la granja. Otra lectura añade que la testarudez puede producir pérdidas y que no todo viaje conviene. Las menciones de muerte, enfermedad o captura por ajogun pertenecen a textos religiosos; no se convierten en pronósticos médicos ni de seguridad para quien consulta."}, {"titulo": "Enseñanza principal", "texto": "La determinación necesita una dirección revisada. Los tres colaboradores de otro testimonio avanzan porque comparten esfuerzo; los viajeros del otro verso se precipitan al desoír la advertencia. La diferencia no está en moverse o quedarse, sino en examinar propósito, momento y preparación."}, {"titulo": "Relatos reunidos", "texto": "Ewọn, Iro e Ìgèdè van a la granja pese a una advertencia y Àgbọnnìrègún interviene después en la narración. Ọ̀rúnmìlà consulta por riquezas que llegan desde la ciudad. En otro testimonio, Erin, Ẹfọn y Eṣinṣin colaboran para trabajar la tierra y regresar con bienes. Son episodios independientes que dan respuestas diferentes a la pregunta por un viaje."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La historia de Àgbọnnìrègún presenta una ofrenda propia en la granja; el verso de Ọ̀rúnmìlà menciona rata, pescado y gallina. El testimonio habla de ofrendas de los tres colaboradores sin trasladarles ingredientes de los otros relatos. Otra lectura ofrece orientación en iré e ibi, no una lista universal de Ogbè Ìrẹtẹ̀."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas; Àgbọnnìrègún actúa en el relato de los tres viajeros y Ọ̀rúnmìlà en otro verso. Los ajogun aparecen como amenaza dentro del lenguaje religioso de otro testimonio. No se deduce de esas apariciones una sola entidad destinataria para toda consulta del signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La granja y los caminos son escenarios centrales. En las ofrendas aparecen ñame machacado, palomas, rata y pescado, cada uno en su relato."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus reúne el verso de Ewọn, Iro e Ìgèdè, el de Ọ̀rúnmìlà y el canto de Erin, Ẹfọn y Eṣinṣin. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=29;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀ṣẹ́ reúne buenas noticias, celebración y cambios favorables en los vínculos. Otra lectura relaciona el iré con paz y abundancia y advierte que la avaricia puede cerrarlas. Los relatos muestran matrimonio, atención a Orí y una mejora que llega después de varios intentos sin éxito."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera que mejore su relación de pareja o que llegue una celebración compartida (relato de Oloidẹ y Ami).", "Ha probado de todo sin resultado y se pregunta si algún día prosperará (relato del loro Odídẹré).", "Hizo una compra que lo dejó con dudas, pero puede valer más adelante.", "Necesita atender su cabeza (Orí) y revisar cómo toma decisiones (relato de Irẹṣu-ele).", "Busca dinero o hijos y lleva tiempo sin ver avances.", "Hay motivo para celebrar con otros, sin dejar que el interés económico mande en la relación."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "El signo presenta logros que pueden compartirse. Oloidẹ y Ami celebran con las aves; Irẹṣu-ele atiende Orí; Odídẹré encuentra utilidad en sus plumas y recibe en su relato prosperidad y descendencia. Otra lectura asocia la lectura favorable con Òṣun, paz mental y abundancia. La mejora puede tardar y surgir de algo que al principio parecía decepcionante."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura señala la avaricia como riesgo del camino abierto. En una relación, buscar solo lo que se gana puede erosionar la celebración común. El testimonio presenta la menstruación de Odídẹré como parte de una historia de infertilidad y posterior hijo; ese relato no permite pronosticar embarazo ni interpretar clínicamente el ciclo menstrual de una persona."}, {"titulo": "Enseñanza principal", "texto": "La abundancia cobra sentido cuando se comparte. El festejo de Oloidẹ y Ami convoca a las aves; la mejora de Odídẹré llega después de persistir y atender un consejo. Otra lectura contrapone gratitud y paz con avaricia. El signo invita a reconocer el valor de bienes o vínculos antes de descartarlos."}, {"titulo": "Relatos reunidos", "texto": "Oloidẹ consulta antes de unirse con Ami y luego presenta a su pareja ante las aves en una celebración. Irẹṣu-ele recibe un consejo relacionado con reparar Orí. Odídẹré, el loro, se siente incapaz de prosperar y termina encontrando riqueza y un hijo dentro de su historia. Otro relato de otro testimonio muestra una compra cuya utilidad aparece después. Son episodios separados."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Oloidẹ menciona una chiva; el de Irẹṣu-ele, cesto con cascarones de palma, gallos, ñame asado y cauríes. Odídẹré recibe en otro testimonio una indicación con agua dirigida a Èṣù; sus materiales no se trasladan a los otros relatos. Otra lectura menciona a Òṣun en iré y a Ògún en la advertencia contra avaricia, sin crear una lista única de ẹbọ."}, {"titulo": "Relaciones espirituales", "texto": "Òṣun figura en la orientación favorable de otra lectura, Ògún en su advertencia, y Èṣù en el relato de Odídẹré. Orí ocupa el verso de Irẹṣu-ele; Ifá guía las consultas. Estas funciones se mantienen diferenciadas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los cascarones de nuez de palma y el ñame asado pertenecen al verso de Irẹṣu-ele; el agua y las plumas del loro, al relato de Odídẹré. El vino de palma aparece en la celebración de las aves. No se infiere una especie vegetal propia del signo a partir de esos elementos."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Oloidẹ y Ami, el de Irẹṣu-ele y el canto de Odídẹré. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=30;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ogbè Òfún reúne deseo, relaciones y búsqueda de una vida con seguidores, hogar y recursos. Otra lectura contrapone la satisfacción del destino con una sensación falsa de plenitud. Los relatos incluyen una relación con una persona comprometida, la competencia entre Ikú y Àrùn, y figuras que buscan reunir apoyo o los bienes de la vida. Son escenas narrativas que requieren cuidado al interpretarse. Otros pasajes del signo explican la autoridad del Ọba y el reparto de días rituales entre deidades."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa en una relación que puede causar dolor porque una de las partes ya tiene compromiso (relato de Ogbè y la esposa de Òfún).", "Busca dinero, pareja, hijos o casa (relato de Owó leléwà).", "Quiere reunir seguidores o reconocimiento (relato del Ọba).", "Cree que ya tiene lo que quería, pero quizá descuidó otras responsabilidades.", "Teme la muerte o la enfermedad (relato de Ikú y Àrùn).", "Está a cargo de un grupo y debe ver cómo ejerce y comparte esa autoridad."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura presenta la satisfacción del destino como lectura favorable. En otro testimonio, el Ọba reúne seguidores y Owó leléwà obtiene recursos, pareja, hijos y casa dentro de su propio relato. El verso de Ikú y Àrùn habla de protección por medio de sonido y canto en la tradición. Esos bienes no se suman como promesa universal."}, {"titulo": "Ibi y advertencias", "texto": "La satisfacción aparente puede ocultar carencias o decisiones que lastiman a otros. La ficha advierte sobre promiscuidad y relaciones múltiples como fuente posible de dolor en su contexto; cada vínculo real debe evaluarse por consentimiento, honestidad y consecuencias. Los pasajes de muerte y enfermedad no reemplazan atención médica. Los relatos de entregar personas o imponer servidumbre pertenecen al texto antiguo y no se presentan como prácticas aceptables."}, {"titulo": "Enseñanza principal", "texto": "Desear un bien no basta para justificar cualquier medio. El verso de Ogbè ante una mujer casada y el de Ikú y Àrùn muestran conflictos por posesión de otra persona; conviene leerlos con atención a la autonomía humana. El testimonio pregunta qué bienes hacen habitable la vida y señala dinero, hogar, vínculos e hijos como aspiraciones distintas. Los relatos del Ọba y de los días rituales invitan a examinar autoridad, desacuerdo y distribución de funciones sin convertir la subordinación descrita en una regla social actual."}, {"titulo": "Relatos reunidos", "texto": "Ogbè va tras la esposa de Òfún en un verso. Ikú y Àrùn compiten por Lasunwontan en otro; un collar de caracoles produce el sonido del canto de Àrùn. En otro testimonio, el Ọba busca seguidores y reparte irú, mientras Owó leléwà busca recursos, pareja, hijos y hogar. Son historias independientes y algunas reflejan prácticas sociales del relato que no deben trasladarse al presente. Una versión adicional presenta al Ọba que desciende a la tierra en busca de seguidores. Otra cuenta el reparto de días rituales: Ṣàngó disputa el día de Ọ̀rọ̀, que termina cediéndoselo. Son relatos separados de la relación afectiva y de Ikú con Àrùn."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ogbè menciona gallina, rata, pescado y cauríes; el de Ikú y Àrùn, caracoles unidos en un collar dentro de una narración de protección. El testimonio presenta ofrendas distintas para el Ọba y Owó leléwà. Ningún pasaje ofrece una lista única de ẹbọ para Ogbè Òfún, ni una técnica médica comprobada."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas. Ikú y Àrùn son personajes personificados en un verso; Òrìṣà aparece como padre de Lasunwontan en esa narración. Egúngún se menciona en un consejo de otro testimonio sobre ancestros. Sus papeles no se fusionan en un mismo ritual. Ṣàngó y Ọ̀rọ̀ son protagonistas del relato calendárico, mientras Olódùmarè y Ọ̀rúnmìlà aparecen en su marco."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El testimonio menciona irú, iyọ̀ y epo en un juego verbal del relato del Ọba. También aparecen caracoles, collar, gallina, pescado y rata en historias distintas. No se asigna una especie vegetal definitiva."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Ogbè y la esposa de Òfún, el canto de Àrùn con su collar, y los cantos del Ọba y Owó leléwà. Hay un canto de la disputa entre Ṣàngó y Ọ̀rọ̀, conservado aparte. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=31;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ogbè representa el cierre de una etapa y la apertura de otra. La ficha lo presenta como retorno del movimiento entre Ogbè y Ọ̀yẹ̀kú. Otra lectura asocia el iré con asumir las responsabilidades de una fase nueva; el ibi, con inestabilidad cuando se responde con arrogancia. Sus relatos tratan de mediar en conflictos y conservar una fortuna que está por llegar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su trabajo o su carrera está bloqueado y necesita cambiar de método o de etapa.", "Un pleito entre visitas o gente cercana amenaza la paz de la casa (relato de los dieciséis reyes y Ọ̀rúnmìlà).", "Dejó entrar a alguien en su casa y necesita poner límites (relato del lagarto y el muro de barro).", "Está cerca una mejora de dinero o de amor y teme perderla (relato de Ọ̀rúnmìlà en Àjitòròo Ṣègì).", "Termina una etapa de aprendizaje y le toca asumir responsabilidades de adulto.", "Siente ganas de responder con orgullo a un problema que se puede arreglar con calma."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de cerrar un ciclo de manera que deje un camino abierto. Ọ̀rúnmìlà conserva paz cuando llegan visitantes conflictivos y, en otro testimonio, mantiene bienes que antes podían escaparse. El lagarto busca un lugar cómodo para vivir. La lectura favorable combina mediación, límites claros y cuidado de los recursos recibidos."}, {"titulo": "Ibi y advertencias", "texto": "La arrogancia ante una transición puede prolongar problemas. En la fábula del lagarto y el muro, quien no cuida su espacio queda expuesto a daño; los visitantes de los reyes muestran cómo un conflicto ajeno puede entrar en casa. Otra lectura incluye una alusión tradicional a enfermedad de transmisión sexual, que no autoriza diagnóstico: la prevención y atención médica deben basarse en salud real, no en el signo."}, {"titulo": "Enseñanza principal", "texto": "Concluir una etapa pide asumir la siguiente. Mediar antes de que una pelea se extienda, poner límites en la propia casa y proteger una ganancia cercana son tres formas concretas de esa responsabilidad. El retorno simbolizado por Ọ̀yẹ̀kú y Ogbè no significa volver al mismo punto: el aprendizaje modifica el camino."}, {"titulo": "Relatos reunidos", "texto": "Los dieciséis reyes y Ọ̀rúnmìlà reciben aviso de visitantes que pelearán; Ọ̀rúnmìlà se prepara. Ọmo-nlé, el lagarto, busca vivir con Ọrọ, un muro de barro; cada uno recibe un consejo distinto. En otro testimonio, Ọ̀rúnmìlà pregunta cómo conservar dinero, pareja, hijos y otros bienes cuando llega a Àjitòròo Ṣègì. Los relatos permanecen separados."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La historia de los visitantes enumera babosas, chivas y cauríes. El lagarto recibe una indicación con palomas y el muro otra con gallo. El Ọ̀rúnmìlà de otro testimonio recibe una ofrenda con una paloma vieja y dinero en su caso particular. No se cruzan las listas ni se formula un ẹbọ único de Ọ̀yẹ̀kú Ogbè."}, {"titulo": "Relaciones espirituales", "texto": "Ifá y Ọ̀rúnmìlà orientan las consultas y el relato de la casa. Los dieciséis reyes forman parte de una narración de convivencia; Ọmo-nlé y Ọrọ son personajes de otra. La atención a cada papel evita convertir una fábula en una instrucción ritual general."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El muro de barro, las babosas, el gallo, las palomas y los cauríes son elementos de historias diferentes. El testimonio usa la imagen de riqueza que se adhiere y no se desprende. No se identificó una planta propia del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de los visitantes, del lagarto y el muro y el canto del Ọ̀rúnmìlà de otro testimonio sobre bienes que permanecen. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=32;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìwòrì trata fertilidad y la transición de un ciclo difícil hacia una vida más favorable. Otra lectura presenta en iré la transformación mediante responsabilidad hacia otra persona; en ibi, el conflicto y una posible dificultad reproductiva. Los versos usan palomas y una personificación sexual; otro testimonio añade la búsqueda de una vida placentera por Wáléọlá."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pregunta por un embarazo o por hijos (relato de las palomas Eyẹlé y Adaba).", "Le preocupa un problema sexual o para tener hijos (relato de Oromina).", "Quiere saber si su vida mejorará y si podrá disfrutar lo que espera (relato de Wáléọlá).", "Una etapa terminó en conflicto y necesita aprender a cuidar a quienes dependen de él.", "Busca apoyo mutuo en la pareja sin que el deseo de tener hijos se vuelva motivo de culpa."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La manifestación favorable de otra lectura es cerrar un ciclo y transformarlo asumiendo responsabilidades compartidas. Las palomas alcanzan fecundidad en su fábula; Wáléọlá llega a una vida placentera en otro testimonio. Estas escenas representan esperanza y continuidad, sin garantizar un resultado reproductivo a toda consulta."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura asocia la lectura difícil con conflicto y preocupación por impotencia o infertilidad. Ese lenguaje tradicional no constituye diagnóstico. La presión por tener hijos puede agravar el sufrimiento si se interpreta como culpa o promesa incumplida. Cuando existe una duda real de fertilidad o salud sexual, corresponde atención clínica basada en la situación de la persona."}, {"titulo": "Enseñanza principal", "texto": "Una transición favorable necesita cuidado de otras personas, no solo esperar un beneficio individual. El signo permite hablar de deseo de hijos con respeto y sin certezas infundadas. El relato de Wáléọlá amplía la idea de bien: pregunta por una vida placentera hasta su final, más allá de la descendencia."}, {"titulo": "Relatos reunidos", "texto": "Ọ̀yẹ̀kúbìrì consulta para la paloma Eyẹlé y el palomo Adaba, ambos asociados con fecundidad. Oromina, personificación del pene, va a Ajatiri y recibe una indicación en otro verso. Wáléọlá, hijo de Àsàńléèyere, pregunta por la calidad de su vida y celebra después el desenlace. Son narraciones separadas; el apodo étnico que una fuente da a Wáléọlá se conserva como dato del relato, sin generalizarlo a personas reales."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de las palomas menciona frijoles y cauríes. El de Oromina enumera varios animales y cauríes para su historia particular. El testimonio habla de una ofrenda abundante para Wáléọlá sin trasladarle los ingredientes de los otros versos. No existe una sola lista de ẹbọ para Ọ̀yẹ̀kú Ìwòrì."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas de los tres relatos. Otra lectura se refiere al cuidado de otra persona como parte de la transición favorable; no da en este pasaje una entidad destinataria universal. Las palomas y Oromina son personajes narrativos, no orichas añadidos al signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El verso de las palomas nombra frijoles y cauríes. Los animales del relato de Oromina pertenecen a una lista ritual distinta. La tierra aparece como imagen en el canto de Wáléọlá. No se identifica una planta específica del signo a partir de esas menciones."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de Eyẹlé y Adaba, el de Oromina y el canto de Wáléọlá. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=33;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìdí relaciona una etapa difícil con la posibilidad de reconstruir bienestar material y personal. Otra lectura contrapone el empobrecimiento que afecta la vida con un crecimiento gradual hacia la abundancia. Los versos hablan de viaje, vínculos y protección; otro testimonio añade descanso, reputación y honestidad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pasa por escasez y necesita recuperarse poco a poco.", "Va a viajar por trabajo o por una relación y espera un buen resultado (relato de Ọ̀rúnmìlà en la ciudad).", "Busca éxito en el amor o en el dinero, cuidando que sus decisiones íntimas no le hagan daño.", "Teme una enfermedad o una pérdida grave (relato de Ikú y Àrùn de visita).", "Trabaja muchísimo y anhela descanso y reconocimiento (relato de Ayílórùlé Òjòpò Òrà).", "Necesita actuar con honestidad para sostener lo que mejoró."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de pasar gradualmente de la pobreza a una vida más abundante. El viaje de Ọ̀rúnmìlà termina con felicidad en su relato; Ayílórùlé obtiene bienes, calma y descanso en otro testimonio. La ficha añade la posibilidad de superar obstáculos mediante una conducta honesta. Los bienes llegan como historias particulares, no como garantía general."}, {"titulo": "Ibi y advertencias", "texto": "La cara difícil une escasez, desgaste y decisiones que descuidan la salud. La ficha advierte sobre poner todo el peso en la actividad sexual; eso no sustituye consejos de salud sexual basados en la situación real. Ikú y Àrùn son personajes del verso, no un diagnóstico. El testimonio menciona compra de personas dentro de una narración histórica: no se presenta como conducta aceptable ni recomendación."}, {"titulo": "Enseñanza principal", "texto": "La recuperación puede ser gradual. El texto de otra lectura pide reconstruir recursos sin perder de vista el bienestar; otro testimonio asocia la prosperidad de Ayílórùlé con calma y descanso. El signo invita a valorar la honestidad y la salud junto con cualquier éxito financiero o afectivo."}, {"titulo": "Relatos reunidos", "texto": "Ọ̀rúnmìlà viaja para adivinar en una ciudad y recibe una promesa de felicidad. En otro verso se prepara ante la visita de Ikú y Àrùn. Ayílórùlé Òjòpò Òrà pregunta si su vida será placentera y termina celebrando reconocimiento, riqueza y descanso. Son relatos separados; el detalle de servidumbre del último pertenece a la narración y no se traslada a la práctica actual."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El viaje de Ọ̀rúnmìlà presenta una lista de palomas y cauríes; el verso de Ikú y Àrùn otra de perros negros y cauríes. El testimonio menciona una ofrenda monetaria para Ayílórùlé. No se combinan las listas ni se afirma que una ofrenda garantice resultados de salud o de pareja."}, {"titulo": "Relaciones espirituales", "texto": "Ifá y Ọ̀rúnmìlà guían los dos versos. Ikú y Àrùn son personificaciones de muerte y enfermedad en uno de ellos. El testimonio presenta a Ayílórùlé como consultante y a sus babaláwo como consejeros; no se deduce una sola entidad destinataria para todo el signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Palomas y cauríes pertenecen al relato de viaje; los perros negros a otra ofrenda. El testimonio usa aves del bosque como imagen de la reputación de Ayílórùlé. No hay una planta específica identificada con seguridad."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos del viaje de Ọ̀rúnmìlà, de Ikú y Àrùn, y el canto de Ayílórùlé. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=34;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìrosùn vincula el cierre de un ciclo con acciones prudentes y apoyo colectivo. Otra lectura contrapone la satisfacción del destino con una oportunidad perdida por terminar de forma prematura. Los relatos muestran a Gbẹrẹfu siguiendo consejo, a un grupo que reúne recursos con el tiempo y a Ọlọ́fin que desoye a un adivino joven."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Empieza una etapa nueva y teme desperdiciar la oportunidad por cerrar mal la anterior.", "Quiere mejorar su economía juntando de poco en poco con otros (relato del grupo de Èésú).", "Piensa en formarse o comprometerse en lo espiritual.", "No toma en cuenta el consejo de alguien más joven o de menor rango (relato de Ọlọ́fin).", "Espera prosperar con un conocimiento o práctica tradicional (relato de Gbẹrẹfu y sus ikines).", "Un malentendido en una reunión o con bebida genera un problema (relato de Òyè Ògosùn y Ṣàngó).", "Debe vigilar la codicia y dejar claros los acuerdos con quienes comparte recursos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Gbẹrẹfu obtiene prosperidad en su verso. El grupo de Èésú alcanza tranquilidad económica mediante aportaciones pequeñas y paciencia. Otra lectura habla de completar una etapa de desarrollo espiritual con sentido de propósito. La lectura favorable privilegia constancia, cooperación y disposición a aprender de personas de distinta edad o rango."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte sobre perder una oportunidad al concluir antes de estar preparado. Ọlọ́fin desoye un consejo y la narración termina con una consecuencia mortal atribuida a Ògún; eso no debe leerse como predicción de muerte. En el relato de Ṣàngó, la falta de comunicación sobre una bebida ya terminada produce un malentendido. La codicia también puede deteriorar un fondo común."}, {"titulo": "Enseñanza principal", "texto": "Un buen pensamiento necesita una acción sostenida. El grupo que aporta dinero muestra que una pequeña contribución repetida puede producir bienestar común. El verso de Ọlọ́fin recuerda que la calidad de un consejo no depende solo de la edad de quien lo da; la historia de Ṣàngó señala el valor de aclarar los hechos antes de reaccionar."}, {"titulo": "Relatos reunidos", "texto": "Gbẹrẹfu, hijo mayor de Ọ̀rúnmìlà, consulta por el provecho de sus ikines. Ọlọ́fin ignora a un adivino joven y entra en conflicto con Ògún. En otro testimonio, un grupo forma Èésú mediante contribuciones; otro relato describe el malentendido entre Òyè Ògosùn y Ṣàngó por recipientes de vino vacíos. Son episodios independientes."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Gbẹrẹfu menciona rata de monte, pescado y chiva. El de Ọlọ́fin da otra lista con perro, ñame asado, vino de palma y cauríes. El grupo de Èésú recibe una indicación monetaria y una paloma vieja; el relato de Ṣàngó incluye costumbres de hospitalidad con bebida. No se reúnen esos materiales en un ẹbọ único."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà es padre de Gbẹrẹfu en el verso; Ifá guía las consultas. Ògún interviene en la historia de Ọlọ́fin y Ṣàngó en la de Òyè Ògosùn. Cada entidad queda vinculada a su propio relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ikines, ñame asado, pescado, vino de palma y recipientes vacíos aparecen en pasajes distintos. El fondo de contribuciones de Èésú es una práctica económica narrada en otro testimonio, no una planta ni un objeto ritual único. No se identificó una especie botánica propia del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de Gbẹrẹfu y Ọlọ́fin, el canto del grupo de Èésú y el de Òyè Ògosùn. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=35;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀wọ́nrín trata decisiones tomadas sin pensar y la preparación para cambios inesperados. La ficha vincula esa imprudencia con bloqueos en trabajo, negocios y relaciones. Otra lectura presenta en iré la resolución de disputas familiares antes de que se agraven; los versos cuentan una crisis afectiva y dos viajes que requieren preparación. Un pasaje cosmológico del mismo signo narra el ciclo de la luna y el comienzo del mes."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Actuó con prisa o fue indiscreto, y eso complica un negocio o una relación.", "Hay un pleito familiar que conviene hablar antes de que duela más.", "Hay un secreto o falta de confianza en la pareja (relato de Lawẹ́nibu).", "Se acerca una salida al monte o un viaje lejano por agua (relatos del cazador y de Ọ̀rúnmìlà).", "Un cambio inesperado le obliga a preparar recursos y explicar bien sus planes.", "Vive una angustia fuerte y necesita apoyo de gente cercana a tiempo."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable de otra lectura es prepararse para el cambio y resolver disputas antes de que desordenen a la familia. Lawẹ́nibu encuentra en su historia una vía para hablar sin ser asesinada; el cazador y Ọ̀rúnmìlà se preparan para sus trayectos. El bien del signo se expresa en prudencia, diálogo y protección concreta de la vida."}, {"titulo": "Ibi y advertencias", "texto": "La imprudencia puede cerrar oportunidades o agravar conflictos. La narración de Lawẹ́nibu contiene amenaza de violencia por una relación íntima: ninguna traición justifica agresión. Otra lectura alude a tendencias suicidas en un contexto de problemas familiares, pero el Odù no diagnostica riesgo individual. Ante una amenaza o angustia real se necesita ayuda inmediata de personas y servicios adecuados."}, {"titulo": "Enseñanza principal", "texto": "Pensar antes de actuar incluye cuidar a quienes serán afectados. El signo no propone ocultar indefinidamente un conflicto, sino buscar una forma segura de tratarlo. Los viajes del cazador y Ọ̀rúnmìlà recuerdan que prepararse para un trayecto es distinto de esperar que el peligro desaparezca por sí solo."}, {"titulo": "Relatos reunidos", "texto": "Lawẹ́nibu recibe consejo antes de confesar una infidelidad en una historia de posible violencia. Odẹ, el cazador, sale al bosque de Olikorobojó; Ọ̀rúnmìlà viaja lejos por agua. El segundo verso atribuye a cada viajero indicaciones diferentes. Los relatos se mantienen separados y no convierten la vida íntima de una persona real en objeto de acusación. Otra explicación, separada de los viajes y de Lawẹ́nibu, atribuye a Èṣù y a Ìyámi la alternancia visible de la luna en un relato sobre cómo se cuenta el mes; no es una explicación astronómica."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La historia de Lawẹ́nibu menciona una chiva; la del cazador, gallos y cauríes; la de Ọ̀rúnmìlà, otra lista con aceite de palma y varios animales. Esas indicaciones pertenecen a situaciones distintas. No se presenta ningún ẹbọ como sustituto de seguridad personal, atención médica o apoyo ante riesgo de violencia."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las tres consultas y Ọ̀rúnmìlà es protagonista del viaje lejano. Otra lectura habla de responsabilidades familiares y cambio inesperado, sin dar en estos pasajes una entidad destinataria universal. La función espiritual del relato no elimina la necesidad de acciones prácticas. Èṣù y Ìyámi intervienen en el relato del ciclo lunar, con un papel distinto de las consultas de viaje."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El bosque y el agua son escenarios de los dos viajes. Aceite de palma, gallos, pescado y otros animales aparecen en listas separadas. No se identifica una planta específica del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Lawẹ́nibu y el de los viajes del cazador y Ọ̀rúnmìlà. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=36;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀bàrà trata las consecuencias de decisiones anteriores y la posibilidad de corregir el rumbo. Otra lectura vincula el iré con saldar una deuda con integridad y el ibi con egoísmo. Los relatos conservan enfoques distintos: una tortuga intenta liberarse de una deuda mediante astucia, un caballo desoye una advertencia y Orí busca compañía al venir al mundo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Arrastra una deuda u obligación sin resolver y debe decidir cómo cumplirla (relato de Awun y Esi).", "Quiere evitar las consecuencias de algo que hizo antes.", "Se siente solo y se pregunta si tendrá apoyo (relato de Orí, al que se le unen las partes del cuerpo).", "Cuida de un hijo o de alguien que depende de él y teme un trato injusto (relato del caballo Eṣin).", "Usa la astucia para salir ganando y debe ver si con eso respeta a los demás.", "La impaciencia puede echar a perder un cambio que ya venía (relato del mono de Ìdèrè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura sitúa la transformación favorable en reparar una deuda con integridad. El testimonio cuenta que Orí encuentra compañía y deja de estar solo. La ficha habla de librarse de efectos negativos de decisiones anteriores. Una salida favorable puede incluir reconocer el daño, corregirlo y construir relaciones de apoyo."}, {"titulo": "Ibi y advertencias", "texto": "El egoísmo y la falta de disciplina pueden mantener abierto un conflicto. El relato de la tortuga Awun muestra una maniobra para evitar el pago de una deuda, mientras otra lectura defiende saldarla: la ficha conserva esa diferencia sin presentar el engaño como recomendación. El caballo Eṣin sufre castigo en otra fábula; el maltrato animal narrado no se aprueba como práctica."}, {"titulo": "Enseñanza principal", "texto": "La oportunidad de cambiar no borra lo ocurrido: pide responder por ello. El contraste entre otra lectura y la tortuga vuelve visible una tensión ética del corpus. El relato de Orí ofrece otra salida a la dificultad: buscar apoyo y dejar que cada parte contribuya, en vez de afrontar la vida en soledad. La fábula del mono añade paciencia y discreción al momento de perseguir un cambio."}, {"titulo": "Relatos reunidos", "texto": "Awun trabaja para Esi por una deuda y prepara un paquete con una cuenta de coral y piedras en una historia de astucia. Eṣin, el caballo, rechaza una indicación antes de tener un hijo y después sufre castigo en la narración. Orí pregunta al llegar del cielo si encontrará compañía; ojos, boca, nariz, oídos, brazos y piernas se unen a él. Son tres relatos separados. Una fábula aparte presenta al mono de Ìdèrè, cuya alegría impaciente interrumpe una transformación que esperaba completar; se conserva como relato mítico, no como explicación biológica."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Awun recibe una indicación con cauríes y una cabra; Eṣin otra con garrotes, chivo y cauríes. El testimonio dice que Orí realizó sacrificio para encontrar compañeros, sin trasladarle la lista de los otros versos. No existe un ẹbọ único de Ọ̀yẹ̀kú Ọ̀bàrà derivado de estas historias."}, {"titulo": "Relaciones espirituales", "texto": "Orí es protagonista del relato de otro testimonio y símbolo del apoyo de todo el cuerpo. Ifá guía las consultas de Awun y Eṣin; Èṣù aparece en la fábula del caballo. Esi es el acreedor de la tortuga dentro de ese relato, no una entidad destinataria general. Ọbàtálá interviene en la fábula del mono como modelador, con una función distinta de Orí en el otro verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La cuenta de coral, el paquete de piedras, la casa de Esi y el cuerpo que acompaña a Orí son elementos narrativos. Los garrotes del cuento de Eṣin pertenecen a esa fábula. No se identificó una planta propia del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de Awun y Eṣin y el canto de Orí sobre las partes del cuerpo que lo acompañan. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=37;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀kànràn, llamado Ọ̀yẹ̀kú Pẹlẹkan en otra tradición del corpus, trata la terquedad que puede cerrar una oportunidad. Otra lectura opone nuevas posibilidades al aislamiento innecesario. Los relatos hablan de reputación, riesgos de confiar mal y una vida que mejora al escuchar consejo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["No quiere seguir un consejo razonable y se aleja de quien podría ayudarle.", "Quiere cuidar su prestigio y teme que una mala decisión lo dañe (relato de la estrella Irawọṣaṣa).", "Siente una amenaza en una salida o una fiesta (relato del mono Oyi).", "Una amistad o una relación de pareja necesita cuidado y límites.", "Busca descanso y estabilidad después de una etapa difícil (relato del Akápò de Ọ̀rúnmìlà).", "Si deja la terquedad, un cambio de rumbo puede traerle oportunidades."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de nuevas oportunidades al terminar un ciclo. El testimonio presenta una mejora en la vida del Akápò, con paz y descanso. La ficha tradicional vincula protección y reputación con escuchar consejos. La oportunidad favorable consiste en corregir una decisión antes de que el aislamiento crezca."}, {"titulo": "Ibi y advertencias", "texto": "La porfía y el orgullo pueden llevar a aislamiento o pérdida. Oyi desoye una advertencia en una narración de peligro y la estrella Irawọṣaṣa pierde su brillo al apartarse de su camino. Son fábulas, no pronósticos de muerte, caída o enfermedad. El temor a detractores no justifica acusar a personas reales sin pruebas."}, {"titulo": "Enseñanza principal", "texto": "Escuchar consejo no equivale a renunciar al juicio propio. El signo presenta la terquedad como obstáculo cuando impide revisar hechos y vínculos. La estrella fugaz ofrece una imagen de prestigio pasajero; el relato del Akápò, otra de bienestar recuperado mediante orientación."}, {"titulo": "Relatos reunidos", "texto": "Oyi, el mono, es amenazado por Akibola antes de una fiesta en el campo. Irawọṣaṣa, una estrella al servicio de Olódùmarè, cae de su posición en una fábula sobre fama. En otro testimonio, el Akápò de Ọ̀rúnmìlà atiende una indicación y encuentra paz. Cada historia conserva su propio consejo."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de Oyi menciona lanzas, gallos y cauríes; el de Irawọṣaṣa, chiva y cauríes. El testimonio describe un animal con cuernos en la situación del Akápò. No se combinan estas indicaciones en un ẹbọ único del signo."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas y Ọ̀rúnmìlà interviene en la del Akápò. Olódùmarè aparece en la fábula de la estrella; Orí y el cuidado personal se relacionan con la mejora de otro testimonio. Los papeles narrativos permanecen separados."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El campo del festival, las lanzas, la estrella y el animal cornudo son imágenes o elementos de relatos distintos. Un verso usa Ìrókò en el nombre de un adivino; eso no basta para asignar una planta medicinal al signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de Oyi e Irawọṣaṣa y el canto Awáwa del Akápò. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=38;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ògúndá, llamado Ọ̀yẹ̀kú Egúntán en otro texto, pide evitar que una disputa termine en daño. Otra lectura describe el iré como eliminación de obstáculos por medio de evitar el conflicto. El testimonio centra esa prevención en la palabra: una expresión descuidada puede abrir una grieta en la familia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una relación o un trabajo está en riesgo por tensión y pleitos repetidos.", "Habla sin pensar y otros toman sus palabras como ofensa (relato de Òyè).", "Un desacuerdo familiar empieza a abrir distancia y conviene atenderlo pronto.", "Teme una pérdida grave que todavía se puede prevenir (verso de Ọ̀yẹ̀kú).", "Busca una vida más tranquila después de mucha lucha.", "Debe saber cuándo y cómo decir una verdad, sin callar por miedo."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura plantea que evitar una pelea innecesaria puede despejar el camino hacia la buena fortuna. En otro testimonio, Òyè modera sus expresiones y su vida mejora. En el otro verso, la fecha temida para Ọ̀yẹ̀kú pasa sin el desenlace anunciado. La lectura favorable se concentra en prudencia, reparación de vínculos y continuidad de la vida."}, {"titulo": "Ibi y advertencias", "texto": "Una disputa sostenida puede causar daño serio. El testimonio usa la pared agrietada por donde entra el aire como imagen de lo que permiten las palabras descuidadas dentro de una familia. No se trata de silenciar a alguien ante abuso: el consejo es hablar con claridad y cuidado, y buscar apoyo cuando existe peligro real."}, {"titulo": "Enseñanza principal", "texto": "La palabra puede cerrar o abrir una grieta. El relato de Òyè pide escuchar la propia forma de hablar antes de que cause un daño no deseado. Otra lectura añade que retirarse de una confrontación improductiva es una manera activa de remover obstáculos."}, {"titulo": "Relatos reunidos", "texto": "Ọ̀yẹ̀kú recibe en un verso un anuncio de muerte a cuatro días y la historia termina sin que ocurra. Òyè, hermano de Ojóòmódá, recibe en otro testimonio una advertencia sobre sus expresiones y la convivencia familiar. Son dos relatos distintos unidos por la idea de prevenir un desenlace grave."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ọ̀yẹ̀kú menciona un carnero. El testimonio dice que Òyè realiza sacrificio, pero el pasaje revisado no da una lista de ingredientes."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas de Ọ̀yẹ̀kú y Òyè. Otra lectura no fija aquí una entidad destinataria universal; su lectura distingue iré e ibi por la conducta frente al conflicto. Las figuras de ambos versos se conservan como personajes narrativos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La pared que se agrieta y la brisa que entra son imágenes centrales del canto de Òyè. El carnero pertenece a la ofrenda del otro verso. No se identificó una planta propia del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso del anuncio a Ọ̀yẹ̀kú y el canto de Òyè sobre la pared y la palabra. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=39;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀sá, también llamado Ọ̀yẹ̀kú Gasá, invita a negociar antes de perderlo todo. La ficha aplica esa idea a parejas, familias y socios; el relato del elefante la muestra entre dos pueblos. Otra lectura vincula el cierre de un ciclo con abundancia apoyada en los ancestros y advierte contra la inestabilidad si se desatiende ese vínculo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Dos personas o grupos se pelean algo que podrían repartir (relato del elefante entre Olijede y Onitiyo).", "Una relación de pareja, familiar o de trabajo se volvió conflictiva y necesita negociarse.", "Teme perderlo todo por no ceder a tiempo.", "Busca prosperidad y continuidad familiar honrando a sus ancestros.", "Siente oposición y quiere superarla (relato de Ọ̀rúnmìlà).", "Puede arrepentirse de algo que sigue posponiendo (relato de la gente de Ogere-egbe)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable es un acuerdo que conserva parte del valor para todos. En el verso del elefante, Èṣù divide el marfil y recomienda dejar la pelea. El testimonio presenta a Ọ̀rúnmìlà venciendo una oposición en su historia. Otra lectura habla de abundancia en relación con la memoria ancestral. Los bienes se sostienen mejor cuando hay capacidad de negociar y actuar a tiempo."}, {"titulo": "Ibi y advertencias", "texto": "La disputa prolongada puede destruir lo que se intenta ganar: los dos pueblos esperan y el elefante se pudre. La gente de Ogere-egbe desoye una advertencia orientada a evitar el pesar. Otra lectura menciona inestabilidad mental como imagen tradicional de un ciclo mal cerrado; no es un diagnóstico clínico. La oposición de otro testimonio tampoco prueba que haya enemigos concretos en la vida del consultante."}, {"titulo": "Enseñanza principal", "texto": "Una concesión a tiempo puede evitar una pérdida mayor. El elefante y su marfil vuelven visible el costo de esperar demasiado: al final queda menos por repartir. La mediación de Èṣù representa una salida práctica, mientras otro testimonio recuerda que la firmeza también necesita orientación."}, {"titulo": "Relatos reunidos", "texto": "La gente de Ogere-egbe consulta para evitar lamentos. Olijede y Onitiyo reclaman el mismo elefante hasta que Èṣù reparte el marfil restante. En otro testimonio, Ọ̀rúnmìlà enfrenta una oposición y celebra superarla. Cada relato conserva una escala distinta: decisión comunitaria, disputa entre pueblos y conflicto personal narrado."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Ogere-egbe recibe una lista con vino de palma, palomas y cauríes; Olijede y Onitiyo, otra con chivo y cauríes. El testimonio menciona un chivo viejo para la situación de Ọ̀rúnmìlà. No se combinan esas indicaciones en un ẹbọ universal ni se sustituyen con ellas las negociaciones concretas que puedan ser necesarias."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas. Èṣù interviene como mediador al final del relato del elefante; Ọ̀rúnmìlà protagoniza el canto de otro testimonio. Otra lectura relaciona el iré con antepasados. Son funciones diferentes y no forman una sola secuencia ritual."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El elefante y el marfil son el centro del relato de reparto. Vino de palma, palomas y cauríes aparecen en la consulta de Ogere-egbe. El pájaro del canto de otro testimonio usa sus alas como imagen del conflicto. No se identificó una planta específica del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Ogere-egbe, el del elefante entre dos pueblos y el canto de Ọ̀rúnmìlà. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=40;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìká, llamado Ọ̀yẹ̀kú Bẹká en otro texto, pide atender la vida espiritual sin reducir toda decisión al dinero. Otra lectura contrapone afirmación personal mediante guía ancestral con el daño de la denigración propia. Los relatos muestran envidia entre adivinos, el papel de Orí y la necesidad de interpretar con cuidado."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está tan metido en ganar dinero que descuidó otras responsabilidades o su vida espiritual.", "Se compara con alguien y la envidia daña la relación (relato de Ọ̀yẹ̀kú y Èká).", "Siente que no alcanza lo que esperaba de su destino (relato de Sàniyàn y Orí).", "Necesita consejo de sus mayores o ancestros antes de entrar en un conflicto.", "Una lectura mal interpretada puede traer daño (relato de Owá).", "Teme pérdidas y busca firmeza sin rebajarse ni dañar a otros."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura presenta la guía ancestral como camino hacia la afirmación personal y la prevención de conflictos. En otro testimonio, Sàniyàn atiende a Orí y encuentra un modo de vivir su destino. Èká prospera en su viaje de adivinación; su éxito muestra una posibilidad favorable que no debería volverse objeto de envidia."}, {"titulo": "Ibi y advertencias", "texto": "El resentimiento por la fortuna ajena puede dañar una amistad y conducir a acciones injustas. El relato del balsero dramatiza ese peligro. Otro verso muestra consecuencias graves de una interpretación equivocada en una consulta. Otra lectura habla de denigración y perturbación espiritual; esos términos no son diagnósticos de la persona que consulta."}, {"titulo": "Enseñanza principal", "texto": "Atender a Orí y buscar orientación no equivale a ignorar los asuntos materiales: ayuda a decidir cómo manejarlos. El contraste entre Ọ̀yẹ̀kú y Èká recuerda que la prosperidad de otro no reduce la propia. La responsabilidad del adivino incluye escuchar, interpretar con rigor y no dejarse guiar por la envidia."}, {"titulo": "Relatos reunidos", "texto": "Ọ̀yẹ̀kú y Èká viajan a adivinar; Èká obtiene mejores resultados y aparece una intriga en el cruce del río. Otro pasaje narra una lectura fallida para Owá y la intervención de Èṣù-Ọ̀dàrà. En otro testimonio, Sàniyàn consulta por su destino y la atención a Orí. Son narraciones separadas, con diferentes motivos de advertencia."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El viaje de Ọ̀yẹ̀kú y Èká incluye una lista de gallinas, maíz y cauríes. El testimonio habla de atender a Orí en el caso de Sàniyàn, sin que se traslade a él la lista de los adivinos. La ficha general menciona compartir las ofrendas con Èṣù y otras entidades en el oficio del babaláwo. No se formula un ẹbọ único del signo."}, {"titulo": "Relaciones espirituales", "texto": "Orí ocupa el relato de Sàniyàn; Ọ̀rúnmìlà e Ifá guían esa consulta. Èṣù aparece en el relato de la interpretación fallida y en la caracterización de la práctica adivinatoria. Los ancestros figuran en la lectura de otra lectura como apoyo para una transición."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El río y el balsero son centrales en la fábula de Ọ̀yẹ̀kú y Èká. Maíz, gallinas y cauríes aparecen en la indicación de ese viaje. El buitre de Sàniyàn es una imagen de perspectiva amplia. No se identificó una planta propia del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de Ọ̀yẹ̀kú y Èká, el episodio de Owá y el canto de Sàniyàn sobre Orí. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=41;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Òtúrúpọ̀n, llamado Batutu o Batúrúpòn en otras versiones, reúne perdón, acuerdos claros y paciencia ante el reconocimiento tardío. La ficha menciona posibles problemas legales; otra lectura contrapone la prevención de un daño con la tensión que crece por pactos secretos. Los relatos del tambor Dùndún y de Ọ̀rúnmìlà añaden fama inesperada y protección en lenguaje religioso."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un problema legal o de trámites y necesita actuar con responsabilidad y buena asesoría.", "Debe reparar una falta anterior o pedir perdón.", "Hay un acuerdo de dinero oculto o confuso que conviene aclarar (relato de Aribijo).", "Ha trabajado sin reconocimiento y se impacienta (relato del tambor Dùndún llamado al palacio).", "Se siente amenazado por pérdidas o enfermedad (canto de Ọ̀rúnmìlà ante los ajogun).", "Un pleito largo le está afectando y se puede aliviar hablando y tomando decisiones concretas."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el cierre favorable con perdonar y reducir tensiones. El verso de perdón pide una nueva oportunidad; Aribijo recibe consejo para mantener acuerdos económicos abiertos. Dùndún alcanza reconocimiento tardío y Ọ̀rúnmìlà supera la oposición en el relato de otro testimonio. El bien del signo se vincula con paciencia, transparencia y reparación."}, {"titulo": "Ibi y advertencias", "texto": "Los acuerdos secretos pueden producir conflicto y la tensión puede prolongar un malestar. La ficha antigua habla de eludir castigos, pero una persona debe hacerse cargo de sus actos y de las consecuencias legales reales. Los ajogun representan peligros en un canto religioso; no son diagnóstico ni prueba de enemigos concretos."}, {"titulo": "Enseñanza principal", "texto": "Pedir perdón es más útil cuando va unido a reparar y actuar con claridad. El consejo a Aribijo evita pactos escondidos; el relato de Dùndún muestra que la falta de reconocimiento presente no define el futuro. La paciencia no elimina la responsabilidad, la sostiene mientras llega una solución."}, {"titulo": "Relatos reunidos", "texto": "Un verso pide perdón a Ọ̀rúnmìlà. Aribijo, hijo de Oke-Apa, es advertido contra convenios secretos de dinero. En otro testimonio, el tambor Dùndún pasa de ser ignorado a ser llamado al palacio; otro relato presenta a Ọ̀rúnmìlà llevando una ofrenda a Èṣù mientras canta frente a Ikú, Àrùn y Òfò. Son episodios independientes."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de perdón menciona gallos y cauríes; el de Aribijo, otra lista con chiva, alimentos, bebida y cauríes. Dùndún recibe una indicación con una paloma vieja. El relato de Ọ̀rúnmìlà describe canto y ofrenda a Èṣù ante ajogun, sin que se tome la lista de otro verso. No se formula un ẹbọ único del signo."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà aparece en el verso de perdón y protagoniza el relato de otro testimonio. Èṣù recibe la ofrenda en este último; Ikú, Àrùn y Òfò son figuras de adversidad dentro del canto. Ifá guía las consultas. Sus papeles permanecen separados de la cuestión legal o económica real."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El tambor Dùndún es el centro del relato de reconocimiento. Paloma, vino, kola, rata y pescado se mencionan en ofrendas diferentes."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el rezo de perdón, el verso de Aribijo, el canto de Dùndún y el «Gangatè» de Ọ̀rúnmìlà frente a los ajogun. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=42;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Òtúrá, llamado Batuyẹ en el texto principal, trata el alivio de una censura o culpa y la recuperación de la vida social. Otra lectura contrapone una orientación espiritual que mejora relaciones con el egoísmo que puede llevar a litigios. Los versos conservados aquí se centran en una acusación que Ṣoràngun quiere superar y una unión matrimonial del relato de Oni-alakan-esuru."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Enfrenta una acusación, una crítica o un trámite y busca que se aclare su situación (relato de Ṣoràngun).", "Un pleito le limita su vida social y sus actividades de siempre.", "Las relaciones se tensan por orgullo o egoísmo y necesitan otra forma de hablar.", "Hay un tema de matrimonio o de acuerdos de pareja (relato de Oni-alakan-esuru).", "Busca orientación espiritual para mejorar su conducta y su trato con los demás."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable de otra lectura es terminar una etapa con mayor claridad y mejorar los vínculos. Ṣoràngun busca salir exonerado en su relato; el texto principal describe la posibilidad de retomar actividades y vida social. El otro verso anuncia matrimonio para Oni-alakan-esuru en su situación concreta. La recuperación depende del caso y no se presenta como resultado automático."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura asocia el egoísmo con la posibilidad de litigio. Las disputas pueden crecer si se confunde la búsqueda de justicia con el deseo de imponerse. La historia de Ṣoràngun no permite afirmar que quien consulta sea inocente o culpable: eso exige hechos y, cuando corresponda, asesoramiento legal."}, {"titulo": "Enseñanza principal", "texto": "Resolver una acusación y reparar una relación son tareas diferentes, aunque ambas requieran claridad. El signo invita a examinar los hechos, asumir la propia parte y buscar una salida proporcionada. La guía espiritual del iré no sustituye el cuidado concreto de los acuerdos y vínculos."}, {"titulo": "Relatos reunidos", "texto": "Ṣoràngun recibe una indicación para afrontar un problema grave y recuperar su posición. Oni-alakan-esuru recibe en otro verso el anuncio de dos matrimonios en un día. Los relatos son distintos; el segundo describe una costumbre narrativa que no establece una obligación o recomendación de poligamia."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ṣoràngun menciona gallos, rata de monte, hojas nombradas gbégbé, cauríes y medicina de Ifá. El de Oni-alakan-esuru ofrece una lista diferente de gallinas y cauríes. No se fusionan en un ẹbọ único ni se presenta una ofrenda como garantía de exoneración legal."}, {"titulo": "Relaciones espirituales", "texto": "Ifá orienta ambos versos. Otra lectura habla de buscar guía del Espíritu para mejorar las relaciones, pero no identifica aquí una entidad destinataria universal. Ṣoràngun y Oni-alakan-esuru son consultantes de historias separadas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Una fuente nombra hojas de gbégbé en la ofrenda de Ṣoràngun. Gallos, gallinas, cauríes y rata de monte pertenecen a las dos listas distintas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los pasajes localizados son el verso de Ṣoràngun y el de Oni-alakan-esuru; no se atribuye un canto adicional a este signo sin texto comprobable. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=43;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìrẹtẹ̀ reúne determinación y cuidado de una persona enferma. Otra lectura contrapone la firmeza útil para proteger a la familia con la terquedad que retrasa la atención. El relato localizado se centra en Kuṣeru y un joven con hinchazón; la ficha no contiene base suficiente para convertirlo en una predicción de enfermedad para otra persona."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Alguien de la casa está enfermo y la familia busca apoyo (relato de la familia de Kuṣeru).", "Una persona sigue como si nada aunque hay señales que piden atención.", "La familia necesita organizarse para cuidar sin paralizarse por la preocupación.", "Con determinación y decisiones a tiempo, el cuidado puede salir adelante."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de proteger la salud de una persona y su familia mediante atención sostenida. En la historia de Kuṣeru, los adivinos anuncian recuperación para el joven del relato. Se conserva como esperanza narrativa, sin prometer curación a quien consulte la Estera."}, {"titulo": "Ibi y advertencias", "texto": "La terquedad puede retrasar ayuda necesaria y agravar una situación real. La ficha original dice que el consultante o alguien de su casa estará enfermo; aquí se trata como motivo tradicional, no como pronóstico. Hinchazón de manos, piernas, ojos o nariz requiere evaluación clínica, y una preparación ritual del relato no reemplaza esa atención."}, {"titulo": "Enseñanza principal", "texto": "Cuidar implica responder a los hechos. El signo presenta la determinación como apoyo para acompañar a una persona enferma, mientras advierte contra aferrarse a una sola explicación o tratamiento. La historia de Kuṣeru invita a reunir ayuda y no dejar solo al joven."}, {"titulo": "Relatos reunidos", "texto": "Los adivinos de la familia de Kuṣeru consultan por un joven antes delgado que presenta hinchazón en varias partes del cuerpo. Le dan a la familia un consejo y anuncian su recuperación dentro de ese relato. No se halló otro relato independiente que deba añadirse a esta ficha."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La historia de Kuṣeru menciona palomas, cauríes y una preparación tradicional con materiales vegetales. Se conserva como dato del corpus; no se dan aquí pasos de preparación ni se recomienda ingerirla o aplicarla como tratamiento médico. No hay otra lista verificada para formar un ẹbọ general del signo."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía la consulta de Kuṣeru y los adivinos de la familia intervienen como consejeros. No se añaden orichas a partir de una inferencia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Una fuente nombra ayẹ y asunrun en la preparación del relato. También se mencionan sal y pimientos; su presencia en el texto no implica seguridad o eficacia clínica."}, {"titulo": "Rezos, versos y cantos", "texto": "El corpus revisado contiene el verso de los adivinos de Kuṣeru. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=44;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀ṣẹ́ reúne el fin de una etapa y la posibilidad de que otra forma de vida crezca. Otra lectura contrapone abundancia tras el cierre de un ciclo con codicia que impide aceptarlo. Un verso filosófico pregunta por la muerte en el orden natural; otro testimonio aporta dos relatos más concretos sobre descendencia y el nombre que deja un árbol."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le cuesta aceptar el fin de una relación, un negocio o una etapa familiar.", "Vive un duelo o se pregunta por el sentido de la muerte (relato de los sabios y el agua que fluye).", "Desea hijos o continuidad familiar (relato del sapo Òpòló).", "Quiere establecerse y dejar un nombre respetado (relato del árbol Àràbà).", "El deseo de tener algo no le deja ver un cambio necesario.", "Llegar a un lugar nuevo puede abrirle una posición importante."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de abundancia al completar un ciclo y aceptar la transición. Òpòló celebra prole dentro de su fábula; Àràbà se establece y se vuelve un árbol reconocido. El verso filosófico presenta renovación como parte del orden natural. Ninguno de esos relatos promete embarazo, fama o alivio inmediato a una persona en duelo."}, {"titulo": "Ibi y advertencias", "texto": "La codicia o el apego a una situación terminada puede bloquear decisiones. Otra lectura menciona el posible fallecimiento de un amigo como motivo de su lectura desfavorable; no se toma como pronóstico. Quien atraviesa duelo necesita tiempo y apoyo, no una afirmación automática de que la muerte es beneficiosa."}, {"titulo": "Enseñanza principal", "texto": "Cerrar un ciclo puede dejar espacio a otra forma de continuidad. El sapo representa descendencia; Àràbà, un nombre que permanece en una comunidad. El verso de los sabios ofrece una reflexión sobre renovación, que debe leerse con respeto a la experiencia concreta de perder a alguien o algo importante."}, {"titulo": "Relatos reunidos", "texto": "Un grupo de sabios pregunta a Ifá por qué existe la muerte; la respuesta usa el agua que se estanca y la que fluye como imágenes de renovación. Òpòló consulta por hijos y celebra su prole. Àràbà busca tierra en la floresta, crece y llega a ser reconocido. El bloque que sigue en otro testimonio corresponde a Ọ̀yẹ̀kú Òfún y no se incorpora aquí."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso filosófico sobre la muerte no aporta una lista única de ofrenda para la Estera. Los relatos de Òpòló y Àràbà mencionan sacrificios propios sin que el pasaje consultado dé ingredientes suficientes para completarlos."}, {"titulo": "Relaciones espirituales", "texto": "Ifá y Ọ̀rúnmìlà son consultados por los sabios; Òrìṣànlá aparece en la explicación de ese verso. En otro testimonio, Ifá guía a Òpòló y Àràbà. Las referencias espirituales se mantienen vinculadas a sus relatos respectivos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Àràbà es un árbol protagonista de otro testimonio; la traducción lo llama baobab. El agua estancada y la que fluye son imágenes del verso filosófico. No se atribuye al signo una planta medicinal por la sola presencia de Àràbà."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de los sabios sobre la muerte y los cantos de Òpòló y Àràbà. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=45;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Òfún reúne un obstáculo repentino con la posibilidad de atravesarlo y recuperar estabilidad. Otra lectura contrasta el daño de evitar un proceso de sanación con el alivio al concluirlo. Los versos hablan de una enfermedad súbita, del trabajo del destino y de la relación entre padres e hijos; son situaciones diferentes, no un pronóstico único."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Surgió un obstáculo inesperado en el día a día o en el negocio.", "Tiene síntomas repentinos o teme enfermar (relato de Abaralile-oṣiṣẹ-oṣabą).", "Se siente a merced de cosas que no controla y busca tranquilidad.", "Hay tensiones en la familia por burlas, presunción o falta de respeto de los hijos a los padres (relato de Baálé y sus hijos).", "Quiere saber si su esfuerzo de hoy le traerá bienestar, recursos o hijos (relato de Èèyàn e Ìpín)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura describe la superación de una enfermedad inesperada al completar un proceso de sanación. Abaralile-oṣiṣẹ-oṣabą se recupera en su relato; la versión paralela aclara que su enfermedad no fue grave. El verso del ser humano describe fuerza, mejoría de vida y paz mental; su canto enumera riqueza, pareja e hijos como bienes del destino. Son posibilidades narrativas, no garantías clínicas o materiales."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte que evitar la sanación puede agravar una disfunción. El texto principal habla de una dificultad inesperada en el ambiente cotidiano o de negocios. El testimonio previene contra las burlas y la actitud pomposa de hijos hacia sus padres. Otro verso alude a muerte y maldad en una imagen de peligro; se conserva como relato y no como anuncio literal de una muerte."}, {"titulo": "Enseñanza principal", "texto": "Atender a tiempo un problema y aceptar ayuda favorece la recuperación del equilibrio. El relato del enfermo trata la respuesta ante una dificultad súbita; el del ser humano sitúa la labor y los bienes en relación con Ìpín, el destino. El respeto familiar forma parte de esa estabilidad."}, {"titulo": "Relatos reunidos", "texto": "Abaralile-oṣiṣẹ-oṣabą, antes sano, recibe una advertencia sobre una enfermedad repentina; el relato concluye con su recuperación. Pékótókótó consulta para Èèyàn, el ser humano que sirve a Ìpín en el Cielo; después de ofrecer ñames, se canta la fuerza y los bienes que puede recibir. Un segundo pasaje de otro testimonio se dirige a Baálé, cabeza de familia, y a sus hijos, y contrapone los movimientos del padre con la conducta de los descendientes."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de Abaralile-oṣiṣẹ-oṣabą nombra babosa, pescado, epo y cauríes junto con medicina de Ifá; otra versión habla de manteca de corojo. El testimonio prescribe dieciséis ñames y describe su uso ritual en el verso de Èèyàn. El pasaje de Baálé también pide sacrificio para longevidad, sin precisar aquí una lista completa. Cada indicación pertenece a su propio caso y ninguna reemplaza atención sanitaria."}, {"titulo": "Relaciones espirituales", "texto": "Ifá orienta los tres relatos. Ìpín, el destino, es central en el verso de Èèyàn: su canto asocia el trabajo del destino con recursos, familia y otros bienes. Baálé y sus hijos son personajes humanos del pasaje familiar, no nombres de orichas; no se asigna al signo un oricha exclusivo sin testimonio explícito."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El ñame es el alimento y elemento ritual explícito de otro testimonio. En el relato de enfermedad aparecen babosa, pescado, epo y cauríes. No se identifica una planta medicinal concreta ni se infiere la composición de la “medicina de Ifá”, que el texto no detalla."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de Adurogangan y Ayẹgiridanu trata la enfermedad y recuperación de Abaralile-oṣiṣẹ-oṣabą. El canto “Ìyànňyàn” celebra el trabajo de Ìpín y enumera sus bienes; otro verso menciona a Baálé y sus hijos. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=46;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ogbè reúne el cuidado de los hijos, la convivencia del hogar y la ayuda que llega al escuchar consejo. Otra lectura presenta una disputa que puede resolverse con honestidad o agravarse por arrogancia. Los testimonios añaden fortuna gradual y cooperación; otros relatos tratan pérdidas, deudas y protección frente a tormentas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le preocupa la salud o el bienestar de un hijo y necesita apoyo de la familia (relato del niño enfermo).", "El ambiente en casa está muy serio o tenso y hace falta juego y convivencia.", "Hay una disputa que se arregla hablando con honestidad y escuchando a un amigo.", "Dos personas piensan hacer negocio juntas (relato de Ìwòrì y Ogbè en la casa de la riqueza).", "Busca dónde establecer a su familia o teme quedarse sin refugio (relato de las dos palomas y la tormenta).", "Una deuda ligada a una relación o a un proyecto le está presionando."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de resolver una disputa y abrir camino mediante la honestidad. El texto principal vincula una atmósfera social positiva con bienestar familiar. En otro testimonio, Òrúnmìlà recibe recursos, pareja e hijos gradualmente; Ìwòrì y Ogbè alcanzan riqueza al cooperar. El cuento del hormiguero presenta un asentamiento que da cabida a la descendencia."}, {"titulo": "Ibi y advertencias", "texto": "La arrogancia puede convertir un conflicto en estrés e inestabilidad. Las versiones de las palomas narran la pérdida de crías tras una tormenta; su foco es la vulnerabilidad del refugio y la diferencia entre escuchar y desdeñar consejo. Otro relato atribuye la retirada de una paloma al peso de una deuda matrimonial. En el pasaje del rey de Ara, el orgullo y el trato desigual acompañan una situación de infertilidad; se relata como tradición, sin culpar a nadie por no concebir."}, {"titulo": "Enseñanza principal", "texto": "El bienestar de una familia depende también de su convivencia, del cuidado concreto y de la disposición a escuchar. La historia de Ìwòrì y Ogbè destaca la colaboración; el consejo de un amigo en otro testimonio merece reciprocidad. Frente al conflicto, la honestidad abre una salida más útil que la presunción."}, {"titulo": "Relatos reunidos", "texto": "Un verso reúne al niño enfermo con sus compañeros de juego en una comida compartida. Dos palomas con dificultades para conservar sus crías consultan; la doméstica busca amparo y la del campo pierde su nido en una tormenta. Un testimonio cuenta cómo Òrúnmìlà recibe bienes poco a poco y cómo Ìwòrì y Ogbè emprenden juntos un negocio. Otros relatos explican por qué ciertas plantas resisten al viento, la retirada de una paloma endeudada, la maternidad de Gbọ̀ndìn frente al orgullo de la esposa del rey de Ara, y el asentamiento de una familia figurada como hormiguero. Son episodios separados bajo el mismo signo."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las listas son distintas por relato. Para la comida del niño se nombran ñame machacado, gallina y cauríes. La versión de las palomas cita quimbombó, ñames, ramas, vasija y cauríes; otra versión menciona vasijas, ñames, maíz y una rama de àtòrí. Los relatos de tormenta, deuda, maternidad y asentamiento dan otras ofrendas propias. No se fusionan en un ẹbọ universal, y la atención médica o la seguridad física siguen siendo necesarias cuando corresponda."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas; Òrúnmìlà protagoniza relatos de otros testimonios y aparece en la historia de las palomas. Èṣù interviene en las versiones sobre la tormenta y la maternidad de Gbọ̀ndìn. Estas funciones son específicas de cada relato, sin adjudicar a un solo oricha todos los temas del signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen ñame, quimbombó, maíz y sorgo o un grano identificado con duda en otro testimonio. La vasija protege a las crías en una versión; viento, lluvia y árboles dan forma a la advertencia sobre refugio. Àtòrí, Ariran y Esun son plantas del relato de la tormenta, donde su flexibilidad permite resistir el viento."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de las palomas, del niño y de los seis relatos reunidos en otra recopilación. El testimonio añade los cantos de Òrúnmìlà sobre riqueza gradual y de Ìwòrì con Ogbè sobre colaboración. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=47;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀yẹ̀kú trata conflictos que amenazan la tranquilidad, la familia o la reputación, y la posibilidad de apartarse de ellos. Otra lectura contrapone un final precipitado por la disputa con una transformación que conduce a contemplación y paz. Las historias sobre ancestros, pareja y orgullo muestran que prevenir una crisis requiere prudencia y diálogo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente bloqueado emocionalmente y busca apoyo en sus ancestros.", "Hay una pelea fuerte en la pareja o miedo a una separación.", "En el trabajo puede pasar una vergüenza, un malentendido o perder la confianza de otros (relato del pato y la ropa de Eégún).", "Preocupa la salud de un recién nacido o de un familiar (relato de Ọlọ́fin).", "Hay tensión entre grupos y hace falta un acuerdo para evitar violencia (relato de Alágbàáà).", "Dice una cosa y hace otra, y eso le resta (relato del azadón)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura presenta la transformación del conflicto en paz. En otro testimonio, Alágbàáà convoca un acuerdo para que enmascarados de Eégún y babaláwos no peleen; el relato termina en celebración y una vida más grata. El verso de Ọlọ́fin plantea que el niño, aun después de una enfermedad, puede prosperar. Estas narraciones invitan a cuidar relaciones y atender dificultades reales."}, {"titulo": "Ibi y advertencias", "texto": "Una disputa alimentada por orgullo o golpes puede terminar prematuramente una etapa valiosa. El testimonio prohíbe pelear a puñetazos aun si alguien cree tener razón. El pato que presume de su secreto ritual queda expuesto cuando falla su atuendo; otros relatos de otra recopilación muestran cómo el conflicto de pareja o una intromisión desencadenan consecuencias trágicas. No se leen como amenazas literales ni se justifica la violencia contra nadie."}, {"titulo": "Enseñanza principal", "texto": "La fuerza de este signo está en desactivar una pelea antes de que arrastre a otras personas. El acuerdo entre Eégún y babaláwos ofrece un ejemplo concreto: reconocer límites mutuos y abandonar los golpes. La relación con los ancestros puede servir como marco de reflexión, pero la reconciliación requiere conducta responsable en el presente. La parábola del azadón invita a alinear decisiones y dirección antes de actuar."}, {"titulo": "Relatos reunidos", "texto": "Ìwòrì recibe una advertencia de peligro y responde con la ofrenda prescrita. Ọlọ́fin oye un consejo sobre el futuro de un recién nacido enfermo. El pato que comercia con vestimenta de Eégún pierde el resguardo de su secreto. Alágbàáà media entre enmascarados y babaláwos para poner fin a las peleas. Otra recopilación conserva además la historia de Olukoun, que huye ante su matrimonio, y la de una pareja perseguida tras un encuentro con deidades. Cada episodio se mantiene separado. Una parábola distinta muestra un azadón que mira hacia la casa cuando va al campo y hacia el campo cuando vuelve; el canto critica esa contradicción de propósito."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso nombra ñame cocido y machacado, nuez de kola, pollo, carnero y cauríes; su glosa explica una cazuela ritual. El de Ọlọ́fin menciona carnero, cauríes y medicina de Ifá. El testimonio asocia a Alágbàáà con vino òpì; sus otros relatos no aportan aquí una receta completa. Otra recopilación registra otras ofrendas para Olukoun y para la pareja. Son indicaciones narrativas distintas, sin una fórmula universal ni sustituto de atención sanitaria."}, {"titulo": "Relaciones espirituales", "texto": "Eégún y los ancestros son centrales en los relatos de vestimenta y en el acuerdo ritual; los babaláwos e Ifá intervienen como consultores y mediadores. Èṣù aparece en el desenlace del pato y en la historia de la pareja conservada en otra recopilación. Ọlọ́fin es protagonista de un verso de cuidado infantil. Ninguna de estas menciones autoriza a fundir personajes y funciones."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El ñame, la nuez de kola y el vino òpì aparecen en ofrendas o cantos. La vestimenta de Eégún es un elemento decisivo del cuento del pato. El verso de Ọlọ́fin menciona iroyin o ifon y ewúro en una preparación; no se presentan como tratamiento comprobado. El azadón aparece como herramienta personificada en un pasaje moral, no como un objeto prescrito para un ẹbọ."}, {"titulo": "Rezos, versos y cantos", "texto": "La ficha reúne dos versos sobre peligro y salud infantil, el canto del pato y el canto de reconciliación de Alágbàáà. Otra recopilación aporta los relatos de Olukoun y de la pareja perseguida. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=48;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ìdí relaciona la continuidad de la vida con generaciones, cuidado del hogar y capacidad de transformarse. Un verso atribuye a Ifá la idea de que los descendientes pueden dar nueva vida simbólica a sus antepasados; otro testimonio habla de hijos, alimento y generosidad. Otra lectura contrapone renacimiento y abundancia sobria con pérdida causada por el miedo a perder."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Desea hijos o piensa en la continuidad de su familia (verso de Ọ̀rúnmìlà sobre padres e hijos).", "La casa necesita comida y estabilidad antes de asumir nuevos compromisos (relato de Ìwòrì e Ìdí).", "El miedo a perder sus bienes lo está llevando a decisiones que los gastan.", "Tiene algo valioso que podría compartir con quien lo necesita (relato del búho Òwiwí)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia la transformación con renacimiento y una abundancia nacida de la sobriedad. El verso de Ọ̀rúnmìlà describe parejas de seres ofrecidas como imagen de multiplicación de la tierra. El testimonio anuncia bienestar del hogar y bendición de hijos, a la vez que insiste en tener comida suficiente. Es una lectura de cuidado y continuidad, no de garantía biológica."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura describe la pérdida que puede provocar el miedo a perder. En otro testimonio, el hambre debilita la vida doméstica y sexual; el búho ignora un consejo de compartir su ropa colorida y lamenta el resultado en su canto. La amenaza a la vista pertenece a esa fábula: cualquier pérdida visual real requiere evaluación médica, no una explicación ritual automática."}, {"titulo": "Enseñanza principal", "texto": "La continuidad no se reduce a tener descendencia. Alimentar, compartir, cuidar vínculos y transmitir vida y memoria también sostienen a una familia. La noción de reencarnación es una idea religiosa expresada por el verso; se conserva como tal, sin convertirla en hecho demostrable o en exigencia para quien consulta."}, {"titulo": "Relatos reunidos", "texto": "Ọ̀rúnmìlà expresa que descenderá del cielo a la tierra y llevará la tierra de vuelta al cielo; el verso relaciona la reciprocidad de padres e hijos con la multiplicación de la vida. Ìwòrì consulta antes de mirar Ìdí y oye que necesita el estómago lleno. En otra fábula, Òwiwí, el búho, desoye a Òhúù y no comparte la prenda vistosa indicada; su grito recuerda la advertencia."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ọ̀rúnmìlà menciona animales presentados en pares, macho y hembra: carnero y oveja, chivo y cabra, gallo y gallina, entre otros. El cuento del búho se centra en entregar una ropa grande y de colores a personas pobres; el pasaje de Ìwòrì e Ìdí alude a sacrificio y alimento sin una lista completa aquí. Las indicaciones pertenecen a relatos distintos y no se combinan en una receta general."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà es protagonista del verso sobre cielos, tierra y generaciones. Ifá orienta los relatos de otro testimonio. Los padres y madres son figuras de continuidad familiar; Òwiwí y Òhúù son personajes de una fábula de aves, no orichas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La comida y el estómago lleno son elementos explícitos del relato de Ìwòrì e Ìdí. El vestido grande y multicolor del búho representa un bien que podría compartirse. El verso de la multiplicación enumera animales por parejas, pero no identifica una planta particular del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Ọ̀rúnmìlà sobre padres, madres y descendientes, el canto de Ìwòrì e Ìdí sobre alimento, y el lamento de Òwiwí. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=49;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ìrosùn aconseja paciencia, deliberación por etapas y perseverancia. El texto principal identifica la vacilación como obstáculo; otra lectura habla de dejar culpa y vergüenza por errores pasados para desarrollar el propio potencial. Los versos reúnen decisiones difíciles, deseo de hijos y la prueba sostenida de Òòsàálá."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene una decisión pendiente, le da vueltas a lo que pasó y sigue sin saber qué hacer (relato de Kòmò).", "Pasa de un plan a otro sin llevar ninguno a la práctica.", "Una pareja desea hijos y necesita apoyarse ante la incertidumbre (relatos de Ọ̀rúnmìlà y de Onígòósùn).", "Una etapa difícil le está dejando enojo, pesimismo o vergüenza.", "Se pregunta si podrá sostener una meta larga a pesar de los altibajos (relato de Òòsàálá y sus tres pruebas)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura describe la realización del potencial mediante transformación y liberación de la culpa. A Kòmò se le promete claridad de ideas tras deliberar con tiempo. Onígòósùn alcanza la maternidad en su relato; Òòsàálá persevera en la lluvia y más tarde obtiene riqueza y reconocimiento. Son desenlaces propios de esas narraciones, no garantías de embarazo o dinero."}, {"titulo": "Ibi y advertencias", "texto": "La impaciencia, la vacilación prolongada o el orgullo pueden impedir avanzar. Convertir un fracaso en vergüenza permanente dificulta volver a decidir. El testimonio muestra que la dureza de una etapa no justifica descargar ira sobre otros. Si hay inquietudes de fertilidad o salud, el relato religioso no sustituye evaluación profesional."}, {"titulo": "Enseñanza principal", "texto": "Pensar por días y meses, elegir un paso concreto y sostenerlo es más útil que quedar inmóvil entre dudas. La perseverancia de Òòsàálá incluye ausencia de rencor durante una etapa adversa. La historia de Onígòósùn añade la necesidad de atender la experiencia emocional de quien espera un hijo, sin reducirla a una receta."}, {"titulo": "Relatos reunidos", "texto": "Kòmò medita sobre un problema, duerme y al día siguiente aún duda; recibe el consejo de ordenar su decisión paso a paso. Ọ̀rúnmìlà consulta por la posibilidad de que su esposa tenga un hijo y menciona osùn como signo de esperanza. Onígòósùn, hija de Àpón, llora por no concebir y otro testimonio cuenta su maternidad. Òòsàálá Òṣèèrèmọ̀gbò atraviesa tres aflicciones, conserva la paciencia y acaba siendo recibido en una casa sobre la colina."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de Kòmò enumera cuatro gallos, cauríes y medicina de Ifá; una nota añade una preparación con garras en agua, que se conserva como dato textual y no como recomendación de consumo. El verso de Ọ̀rúnmìlà menciona dos gallinas, osùn y cauríes. El testimonio indica dieciséis piezas de osùn y dinero para Onígòósùn, con un gesto ritual referido al pecho y a Orí. Cada lista corresponde a su historia."}, {"titulo": "Relaciones espirituales", "texto": "Ifá orienta la decisión de Kòmò y la consulta familiar de Ọ̀rúnmìlà. Orí y Èṣù aparecen en el ritual narrado para Onígòósùn. Òòsàálá, identificado en otro testimonio como Òòṣà ńlá, protagoniza el relato de perseverancia. Estas funciones se conservan separadas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Osùn es la madera o colorante rojo nombrado en los relatos de maternidad; la glosa fuente lo llama camwood o “madera roja”. La lluvia, el sol y la colina son elementos del camino de Òòsàálá. La nota sobre garras en agua no establece una planta ni una terapia validada."}, {"titulo": "Rezos, versos y cantos", "texto": "La ficha conserva el verso deliberativo de Kòmò, el de Ọ̀rúnmìlà y su esperanza de hijo, y los cantos de Onígòósùn y Òòsàálá. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=50;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀wọ́nrín reúne preparación ante lo inesperado, búsqueda de lo perdido y cuidado de relaciones que pueden renovarse. Otra lectura contrasta una pérdida imprevista con la previsión antes de viajar. El testimonio añade un tema social: el abandono de una viuda rompe obligaciones de cuidado y desencadena daño en la comunidad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Va a viajar o a trabajar cerca del agua y necesita prepararse y tomar precauciones (relato de Joworo).", "Busca a alguien o algo que se perdió (relato de la comunidad de Otú-Ifẹ̀).", "Puede reencontrarse con una expareja, un familiar o un amigo.", "Perdió a sus padres o tíos y necesita una red de apoyo.", "Una persona viuda o mayor se está quedando sin compañía ni sustento (relato de la viuda de Ẹlérín).", "Se están tomando decisiones de herencia o de mando sin pensar en quienes dependían del anterior."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura valora prepararse para un viaje y para sucesos inesperados. Joworo sale a una travesía ligada al agua y el verso lo imagina a salvo; la comunidad de Otú-Ifẹ̀ encuentra a las personas buscadas. Otro relato presenta nuevas relaciones afectivas. En la historia de la sucesión, quien consulta y atiende el problema logra asumir el cargo; el bienestar colectivo exige también cuidar a la viuda."}, {"titulo": "Ibi y advertencias", "texto": "La falta de previsión puede traer pérdidas. El testimonio relata que los aspirantes a suceder a Ẹlérín descuidan a su viuda; ella, agraviada, pone una cobra en una vasija y otras personas resultan heridas. Es un relato de abandono y represalia que no justifica dañar a nadie. La soledad tras la viudez y la muerte de familiares merece apoyo real; no debe reducirse a una amenaza ritual."}, {"titulo": "Enseñanza principal", "texto": "Prepararse para el viaje y buscar ayuda a tiempo puede evitar daños; sostener vínculos es otra forma de protección. Un reencuentro requiere consentimiento y atención mutua. El relato de la viuda recuerda que una comunidad no puede celebrar un nuevo liderazgo mientras deja desamparada a la familia del anterior."}, {"titulo": "Relatos reunidos", "texto": "Olúgbemiro y Emibajo consultan para Joworo antes de ir hacia el agua. En Otú-Ifẹ̀, una comunidad busca a personas ausentes y celebra hallarlas. Ìwòrìòdérín recibe en un canto la bendición de numerosas parejas. Después de morir Ẹlérín, los aspirantes a su cargo abandonan a la viuda; una cobra oculta hiere a dos, mientras un tercero consulta y obtiene el cargo. Cada trama responde a una situación distinta."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Joworo menciona camarones, una carnera y cauríes. Para Otú-Ifẹ̀ se nombran cuatro palomas y cauríes. Los relatos de Ìwòrìòdérín y de la sucesión también mencionan sacrificio sin detallar aquí una lista única. Ninguna ofrenda sustituye medidas de seguridad en el agua o atención a una mordedura de serpiente."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas de Joworo, Otú-Ifẹ̀ y la familia de Ẹlérín. El testimonio menciona “dobles celestiales” como vínculo devocional en una lectura del signo; no identifica allí un oricha específico. Los adivinos Olúgbemiro y Emibajo y el rey Ẹlérín cumplen papeles narrativos diferentes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El agua es el entorno del viaje de Joworo; los camarones son parte de la ofrenda de ese verso. El canto de Ìwòrìòdérín compara la extensión de sus relaciones con la rafia de las esteras. La vasija y la cobra son elementos del cuento de sucesión, no una instrucción ritual ni una planta asociada al signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de Joworo y de la búsqueda en Otú-Ifẹ̀, el canto de Ìwòrìòdérín y el relato cantado de la sucesión de Ẹlérín. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=51;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀bàrà centra la conducta en hechos concretos: honestidad, paciencia, cuidado de los hijos y atención a quien sufre. Otra lectura presenta crecimiento espiritual al abandonar la mentira y el daño; repetirlos conduce a nuevos problemas. Los relatos de otro testimonio añaden desesperanza y deseo de descendencia, y piden responder con apoyo real. Otra tradición del signo explica el origen de las festividades anuales de los orichas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita dejar las preocupaciones generales y tomar decisiones concretas.", "Hubo engaños o robos que pueden traer consecuencias para otros (relato de Òlé y Òpùrọ̀).", "Quiere criar hijos responsables y cuidar la memoria familiar (relato de Abowaba).", "Siente que el bienestar nunca llega y está perdiendo la esperanza; necesita apoyo de otros a tiempo (relato de Ìwòrì ò bèrè).", "Una comunidad o familia desea hijos y sufre por no tenerlos (relato de Dásà a ò kú mó)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula la transformación honesta con elevación. Abowaba recibe un relato de larga vida, memoria familiar e hijos responsables. En la ciudad de Dásà a ò kú mó, la narración celebra el nacimiento de niños después de un periodo de carencia. Ìwòrì ò bèrè recibe ayuda cuando otras personas advierten su desesperación; lo importante para una lectura actual es que no quede solo ante el peligro."}, {"titulo": "Ibi y advertencias", "texto": "Persistir en robo o mentira repite el daño y puede traer conflictos graves. El verso de Òlé y Òpùrọ̀ les aconseja cesar esas conductas y cuenta que se negaron. La desesperación de Ìwòrì ò bèrè muestra un riesgo serio que no debe romantizarse con el desenlace de su fábula. La infertilidad o la falta de hijos no son defectos morales de una persona."}, {"titulo": "Enseñanza principal", "texto": "Un cambio creíble se demuestra en la conducta: dejar de mentir, reparar daño, cuidar a los hijos y pedir apoyo cuando el sufrimiento desborda. El testimonio muestra a una comunidad que interviene para proteger a Ìwòrì ò bèrè; esa intervención importa más que su posterior nombramiento como rey."}, {"titulo": "Relatos reunidos", "texto": "Òlé y Òpùrọ̀, ladrón y mentiroso, oyen que deben dejar su conducta perjudicial, pero se resisten. Abowaba consulta por la continuidad de su familia y la responsabilidad de sus hijos. Ìwòrì ò bèrè, abatido por la espera y la penuria, está en riesgo de suicidio; personas de otra ciudad lo encuentran y lo detienen, y el relato concluye con su elección como rey. En Dásà a ò kú mó, una comunidad pide hijos y celebra su llegada. Son episodios separados. Un relato distinto presenta a Ọbàtálá, Odùduwà y Ọ̀rúnmìlà al recibir días festivos de Olódùmarè: Ọbàtálá celebra primero, Odùduwà organiza otra fiesta y Ọ̀rúnmìlà anuncia la suya según el cambio estacional. No se confunde con las historias de desesperación o descendencia."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Òlé y Òpùrọ̀ menciona nueces de kola, epo, cauríes y palomas, además de donar dinero y kola. Abowaba recibe otra lista: seis palomas, cauríes y medicina de Ifá. El relato de Dásà a ò kú mó habla de chivas y dinero. El de Ìwòrì ò bèrè menciona ofrenda sin dar aquí una composición completa. Ninguna lista es un ẹbọ general ni reemplaza intervención ante una crisis suicida."}, {"titulo": "Relaciones espirituales", "texto": "Ifá orienta a los personajes de los cuatro relatos y la continuidad de la familia ocupa un lugar destacado. Los babaláwos acompañan la consulta de Dásà a ò kú mó. No se asigna un oricha particular al signo por inferencia; los papeles narrativos se mantienen diferenciados. En la narración del calendario figuran Olódùmarè, Ọbàtálá, Odùduwà, Ọ̀rúnmìlà y Ògún; cada uno cumple una función en esa historia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La nuez de kola y epo son elementos de la ofrenda del primer verso. La imagen de cargar niños en lugar de una joroba expresa el cambio celebrado por Dásà a ò kú mó; no es una descripción médica. El testimonio no permite fijar una planta propia del signo a partir de estos pasajes."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de Òlé y Òpùrọ̀ y de Abowaba, el canto que pide proteger a Ìwòrì ò bèrè y el de la ciudad de Dásà a ò kú mó. El bloque siguiente de otro testimonio pertenece a Ìwòrì Ọ̀kànràn y no se incorpora. El relato del calendario contiene un canto de celebración de Ọbàtálá y otro de Odùduwà. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=52;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀kànràn une discreción en la consulta, sinceridad y planificación paso a paso. Otra lectura considera que resistirse al cambio puede cerrar oportunidades. Un testimonio añade otro eje del mismo signo: salir del aislamiento y construir relaciones en una comunidad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["No le cuenta todo al babaláwo o no se siente en confianza para hablar.", "Quien aconseja puede estar contando cosas privadas o hablando de más (verso de Ọ̀rúnmìlà).", "Tiene un proyecto nuevo que debe evaluar antes de arrancar (relato de Makanju-huwa y la cabra).", "Busca oportunidades, pero se aísla y no acepta consejo (relato de Olórèé Agbọ̀n).", "La familia pregunta por los hijos y cómo acompañarlos juntos (relato de la Mosca del Sol)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de nuevas oportunidades al avanzar de manera gradual. El verso de Makanju-huwa ofrece la imagen de una cabra que examina el terreno antes de acostarse: un paso prudente protege una iniciativa. En otro testimonio, Olórèé Agbọ̀n encuentra posibilidades al relacionarse con otras personas, y la Mosca del Sol obtiene descendencia dentro de su fábula."}, {"titulo": "Ibi y advertencias", "texto": "La falta de sinceridad dificulta una orientación útil; la indiscreción de quien consulta para otros puede provocar litigios o daño reputacional. Rechazar todo consejo por resistencia al cambio puede cerrar caminos. El aislamiento excesivo aparece en otro testimonio como pérdida de vínculos; la prudencia al planear no debe volverse parálisis."}, {"titulo": "Enseñanza principal", "texto": "La confianza exige dos compromisos: hablar con honestidad en un espacio seguro y guardar lo que otra persona confía. Después se puede estudiar un proyecto de forma concreta y actuar por etapas. Olórèé Agbọ̀n recuerda que la vida social también puede ser una fuente de apoyo y oportunidad."}, {"titulo": "Relatos reunidos", "texto": "Ọ̀rúnmìlà oye que un adivino debe evitar hablar descuidadamente de las personas que lo consultan. Makanju-huwa evalúa una empresa futura; la cabra que mira el suelo antes de reposar simboliza su prudencia. Olórèé Agbọ̀n, que vivía apartado bajo el mercado, recibe el consejo de encontrarse con la gente. La Mosca del Sol consulta por descendencia y el relato celebra su prole. Son escenas separadas."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ọ̀rúnmìlà enumera cuatro babosas, una chiva y cauríes. El de Makanju-huwa nombra chiva, gallina, cauríes y medicina de Ifá; su nota describe una bebida ritual con garras en agua que se conserva como dato textual, no como recomendación de consumo. El testimonio menciona ofrendas para Olórèé Agbọ̀n y la Mosca del Sol sin precisar aquí todos los ingredientes."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà aparece como consultante en el relato sobre discreción. Ifá orienta los demás episodios; el babaláwo tiene un papel ético concreto como custodio de la información recibida. Olórèé Agbọ̀n y la Mosca del Sol son personajes de los cantos, no orichas asignados al signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La cabra y el terreno son la imagen de prudencia del segundo verso; babosas, gallina y cauríes figuran en ofrendas diferenciadas. El mercado es el entorno social del relato de Olórèé Agbọ̀n. Los pasajes consultados no permiten identificar una planta propia de este signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso sobre la discreción del adivino, el de la cabra que examina el terreno y los cantos de Olórèé Agbọ̀n y de la Mosca del Sol. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=53;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ògúndá pide actuar a tiempo cuando un conflicto o una decisión difícil amenaza con desorientar. Otra lectura describe cómo el enojo sostenido alimenta nuevos conflictos y cómo una transformación puede despejar obstáculos. Los relatos añaden reconocimiento, prudencia en relaciones y la posibilidad de volver a encontrar el camino con ayuda familiar. Un verso adicional representa a Orí cuando nada de lo que intenta prospera y pide ayuda para recuperar orientación."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Evita decidir en un momento clave y siente que pierde el rumbo.", "Un enojo viejo vuelve y provoca pleitos en lugar de cerrarlos.", "Busca un cargo o reconocimiento (relato de Orí Olóyè).", "Se interesa por alguien que no ha cerrado su relación anterior y no debe guiarse por rumores (relato de Àṣá y Kútelú).", "Tomó una decisión apresurada antes de una reunión o celebración familiar (relato de Ọloba en el bosque).", "Su suerte puede cambiar (relato de Olúlatẹjà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de dejar atrás la pelea y convertir una situación adversa en mejor fortuna. Olúlatẹjà oye que la mala suerte puede cambiar; Orí Olóyè recibe un puesto y paz en su relato. Ọloba, perdido en el bosque, recupera la orientación cuando sus hijos y la comunidad lo buscan y cantan. La acción oportuna puede ser pedir ayuda, no solo actuar solo."}, {"titulo": "Ibi y advertencias", "texto": "La incapacidad para manejar una dificultad, la ira o las prisas pueden profundizar la confusión. Ọloba desoye el consejo y entra al bosque antes de su festival; el relato lo muestra perdido hasta que su familia interviene. El testimonio advierte sobre una nueva relación construida con rumores mientras el vínculo anterior continúa. Evitar acusaciones infundadas es parte de cortar el conflicto."}, {"titulo": "Enseñanza principal", "texto": "Actuar a tiempo requiere revisar los hechos, dejar ir la ira y aceptar apoyo. El retorno de Ọloba depende de una búsqueda colectiva; el reconocimiento de Orí Olóyè se acompaña de tranquilidad. En asuntos de pareja, lo prudente es aclarar la situación anterior antes de tomar decisiones que afecten a varias personas."}, {"titulo": "Relatos reunidos", "texto": "Olúlatẹjà recibe el anuncio de que su fortuna puede cambiar. Ọloba sale a buscar provisiones para una celebración, se pierde en el bosque y vuelve siguiendo el canto de sus hijos y vecinos. Orí Olóyè consulta antes de venir del cielo a la tierra y alcanza un cargo reconocido. Àṣá quiere tomar a Kútelú, esposa de Àwòdì, mientras el canto insiste en que el supuesto divorcio es un rumor. Son relatos independientes. En otro pasaje, Oríawówẹ consulta porque sus acciones no avanzan y entona una petición ritual de lavado de Orí; no es la misma historia que la búsqueda de Ọloba."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Olúlatẹjà menciona paloma, tela blanca y cauríes. El de Ọloba enumera diez ratas, diez pescados y cauríes, y narra que sus hijos realizan la ofrenda. Orí Olóyè también sacrifica en otro testimonio, sin lista completa en el pasaje consultado. Ninguna de estas ofrendas se combina en un rito universal."}, {"titulo": "Relaciones espirituales", "texto": "Ifá orienta a Olúlatẹjà, Ọloba y Orí Olóyè. Èṣù interviene en el episodio del bosque como agente de la pérdida de orientación y de su resolución. Orí Olóyè representa la cabeza destinada al cargo en el relato de otro testimonio; Àṣá, Kútelú y Àwòdì son personajes de la advertencia de pareja. Orí es protagonista del pasaje de Oríawówẹ y se presenta como dimensión del destino en ese marco tradicional."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El bosque es el escenario de la desorientación de Ọloba; ratas y pescados figuran en su lista de ofrenda. La tela blanca y la paloma pertenecen al relato de Olúlatẹjà. La corona es el símbolo del cargo de Orí Olóyè. Los pasajes no identifican una planta botánica propia de este signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Olúlatẹjà sobre el cambio de fortuna, el canto que guía a Ọloba, el de Orí Olóyè y el que desmiente el rumor sobre Kútelú. El bloque siguiente de otro testimonio pertenece a Ìwòrì Òsá. Se conserva por separado la petición ritual de Oríawówẹ. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=54;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀sá gira en torno a reconocer las capacidades propias y responder por los actos. Una ficha contrasta el poder y la sabiduría recibidos con el rechazo a utilizarlos; otro testimonio añade paciencia, evitar peleas y aceptar ayuda de un amigo. Otra lectura relaciona la vía favorable con trabajar la resistencia para llegar a la abundancia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Sabe cómo resolver un problema, pero lo pospone o cree que no puede.", "Huyó de una responsabilidad o de las consecuencias de lo que hizo (relato de la tortuga).", "Sigue pidiendo ayuda para algo que podría empezar a resolver por su cuenta (relato de Olódùmarè).", "Espera mejorar la economía de la casa, quizá con un amigo, pero un pleito amenaza ese apoyo (relato de Ìwòrì en casa de Òsá).", "Se siente atacado por detractores y debe distinguir un conflicto real de una reacción impulsiva (relato de Àwón)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura describe abundancia al atravesar la resistencia y atender la guía de Ifá. En otro testimonio, Ìwòrì visita la casa de Òsá, recibe riqueza y la lleva a su hogar después de evitar peleas. Àwón también obtiene apoyo frente a sus adversarios en un relato distinto. La prosperidad es un desenlace de esos versos, no una promesa automática."}, {"titulo": "Ibi y advertencias", "texto": "La tortuga huye al bosque por su mala conducta y rechaza el consejo recibido; su relato advierte contra evadir responsabilidades. Otra lectura asocia esa evasión con deterioro del equilibrio personal, formulación tradicional que no es diagnóstico clínico. La hostilidad y la malicia pueden cerrar relaciones valiosas antes de que den fruto."}, {"titulo": "Enseñanza principal", "texto": "Pedir orientación y ejercer la propia capacidad son acciones compatibles. En el relato de Olódùmarè, las personas reciben fuerza y sabiduría pero no las usan; el consejo es activar esos recursos. El testimonio muestra cómo la tolerancia permite a Ìwòrì aprovechar una oportunidad sin convertirla en pelea."}, {"titulo": "Relatos reunidos", "texto": "Obahun Ìjapá, la tortuga, se retira al bosque para eludir las consecuencias de su conducta y no acepta la ofrenda indicada. Olódùmarè pregunta a quienes solicitan ayuda por qué no utilizan la fuerza y la sabiduría que ya tienen. Ìwòrì viaja a la casa de Òsá, evita discutir y vuelve con riqueza. En otro canto, Ọláawin y Òòsà apoyan a Àwón frente a sus adversarios. Son relatos independientes."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de la tortuga nombra una paloma, cauríes y medicina de Ifá; el de Olódùmarè cita tela negra, oveja negra, cauríes y medicina de Ifá. El testimonio pide palomas y dinero para la llegada de riqueza, y menciona una ofrenda distinta para Àwón. No se fusionan esas listas ni se presentan como una obra única del signo."}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè protagoniza el verso sobre poder y sabiduría. Ifá guía las consultas; otro testimonio menciona de forma expresa a Oriṣàálá como apoyo de una persona y presenta a Òòsà junto a Ọláawin en otro relato. Cada nombre mantiene su función dentro del pasaje en que aparece."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La tela y la oveja negras pertenecen a la ofrenda del verso de Olódùmarè; palomas y cauríes aparecen en los relatos de la tortuga y del viaje a casa de Òsá. El bosque representa la huida de la tortuga. Los pasajes consultados no identifican una planta específica para este signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de la tortuga, el de Olódùmarè y los cantos “Gbàbilà gbàbilà” y “Àgùtàn ni ò sunwòn sunwòn”. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=55;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ìká contrapone la fidelidad y el buen uso de los recursos con el robo, la violencia y la traición. El texto principal advierte que poner el dinero por encima de las relaciones puede ocultar oportunidades de bienestar. El testimonio presenta la nuez de kola como elemento de convivencia y una fábula sobre un aprendiz amenazado por sus compañeros."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay una relación nueva o actual con futuro, pero solo se está mirando lo material.", "La casa busca negocio, comida y paz (relato de Ajitobi y las nueces de kola).", "Hubo un robo o lo están presionando para entrar en algo ilegal (relato de Kuṣika y su banda).", "Alguien joven o de menor rango se siente amenazado por compañeros con más poder (relato de Àmùrè ò dàgbà).", "Se está poniendo a prueba la lealtad en la pareja, la familia o el grupo."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el aumento de capacidad con la fidelidad. Ajitobi obtiene reconocimiento por mantener el comercio de kola en su casa. Àmùrè ò dàgbà, aprendiz de Ifá, sale con vida del intento de dañarlo y puede cantar su supervivencia. Son desenlaces de relatos separados, no promesas de invulnerabilidad."}, {"titulo": "Ibi y advertencias", "texto": "El verso de Kuṣika advierte que el robo reiterado puede terminar en captura y exige abandonar esa conducta. En otro testimonio, los compañeros de Àmùrè ò dàgbà organizan una agresión por celos y abuso de posición. La búsqueda de ganancias sin lealtad ni respeto amenaza la paz que la ficha presenta como posible."}, {"titulo": "Enseñanza principal", "texto": "La fidelidad no se mide solo por lo que se posee: también se demuestra al respetar a los demás, abandonar el daño y proteger a quien tiene menos poder. La historia de Àmùrè ò dàgbà muestra que una jerarquía religiosa no debe usarse para perseguir al aprendiz. El relato de Kuṣika insiste en desistir de robar."}, {"titulo": "Relatos reunidos", "texto": "Kuṣika y su banda roban de noche; los adivinos les advierten que pueden ser descubiertos y les piden dejar el robo. Ajitobi, esposa de Ìwòrì Àyòká, se vincula a un hogar donde nunca faltan nueces de kola. En una narración más larga, Cobra, Pitón y Babosa ocupan cargos mientras Àmùrè ò dàgbà queda como aprendiz; los mayores traman dañarlo, pero el halcón se lleva su vestimenta y él sobrevive. Los episodios deben leerse por separado."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Kuṣika nombra mercancías robadas, una chiva y cauríes, pero el punto principal del consejo es cesar el delito; no se presenta la ofrenda como forma de eludir responsabilidad legal. Ajitobi ofrenda en su propio relato. Àmùrè ò dàgbà entrega una prenda agbàdà antes del ataque narrado. Las indicaciones pertenecen a casos distintos."}, {"titulo": "Relaciones espirituales", "texto": "Ifá orienta los tres relatos; Èṣù interviene en la historia de Àmùrè ò dàgbà cuando el halcón confunde la prenda con su presa. Los cargos de Cobra, Pitón y Babosa son papeles de la fábula, no orichas del signo. Agbọ̀nnìrègún se menciona como referente de la casa en que aprende Àmùrè ò dàgbà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La nuez de kola es el alimento y bien de comercio explícito en el relato de Ajitobi. El agbàdà, una prenda, es decisivo en la historia del aprendiz. La chiva y los cauríes figuran en el verso de Kuṣika; no se identifica aquí una planta medicinal específica."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de Kuṣika, los cantos de Ajitobi y el canto responsorial de Àmùrè ò dàgbà tras sobrevivir. El testimonio usa Ìwòrì Àyòká como variante del signo. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=56;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Òtúrúpọ̀n reúne el deseo de hijos, la continuidad familiar y la posibilidad de convertir una etapa adversa en bienestar. Otra lectura asocia su lectura favorable con proteger un embarazo; otro testimonio cuenta que las buenas cosas llegan “en bultos” y muestra a un hijo que aprende de la tradición de su familia. Ningún relato garantiza embarazo o salud."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una familia que perdió un hijo teme pasar otra vez por eso.", "Una mujer embarazada o que desea hijos busca apoyo y cuidado.", "La familia quiere continuar un oficio o una enseñanza de sus mayores (relato de Atinúlahùn).", "Teme que un error de dinero convierta una oportunidad en pérdida (relato de la compra de Ọ̀rúnmìlà).", "Una etapa de dolor no le deja ver lo bueno que ya está llegando (relato del baobab)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura describe prevención y cuidado en torno al embarazo. En otro testimonio, Ọlọ́mọ ní ràdiràdi, comparado con un baobab lleno de semillas, ve llegar abundancia y descendencia. Atinúlahùn sigue enseñanzas de Ifá y recibe reconocimiento. Son imágenes de continuidad y prosperidad propias de sus cuentos."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura vincula la desatención de la guía con enfermedad, formulación ritual que no constituye un diagnóstico ni culpabiliza a quien pierde un embarazo. El primer verso recuerda el temor a la muerte de los hijos. Otro relato muestra a Ọ̀rúnmìlà desoyendo una indicación antes de comprar a una mujer esclavizada, que muere poco después; se conserva como narración histórica sin validar la esclavitud ni atribuir una muerte a una omisión ritual."}, {"titulo": "Enseñanza principal", "texto": "Cuidar a la familia implica actuar con atención, sostener los vínculos y buscar ayuda adecuada cuando la salud preocupa. El relato de Atinúlahùn valora aprender de los mayores sin repetir mecánicamente todos sus actos. El del baobab presenta la abundancia como algo que se reconoce y se comparte, no como una promesa individual."}, {"titulo": "Relatos reunidos", "texto": "Un verso trata la pérdida de un hijo de la pareja figurada por Ìwòrì y Òtúrúpọ̀n y su esperanza de otra descendencia. Otro cuenta que Ọ̀rúnmìlà compra a una mujer esclavizada pese a no seguir el consejo recibido; ella muere y la casa entra en duelo. En otro testimonio, Ọlọ́mọ ní ràdiràdi, nombre dado al baobab, representa frutos y bienes abundantes. Atinúlahùn, hijo de Agbọ̀nnìrègún, aprende de Ifá y prospera. Cada pasaje conserva su propio contexto."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso nombra gallina, chiva, pescado ahumado, cauríes y una preparación vegetal tradicional. El segundo cita chiva y cauríes para una situación económica distinta. El testimonio menciona paño y algodón en la ofrenda del relato del baobab. No se funden en un ẹbọ único; la preparación asociada al embarazo no se recomienda como tratamiento."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas; Ọ̀rúnmìlà y Èṣù intervienen en el relato de la compra y el duelo. Agbọ̀nnìrègún aparece como padre de Atinúlahùn en otro testimonio. Esas funciones pertenecen a historias distintas y no asignan un oricha exclusivo a este signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El verso menciona ẹla, glosada como orquídea en una fuente, y semillas de iyèré. El baobab es la imagen de otro testimonio para frutos llenos de semillas. Pescado, paño y algodón aparecen en ofrendas separadas."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los dos versos sobre descendencia y pérdida económica, y los cantos “Ìwòrì tútú ninini” y “Ìwòrì jáárájá”. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=57;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Òtúrá se ocupa de la desarmonía familiar y de cómo valorar la ayuda sin despreciar a quien parece tener menos prestigio. Una ficha habla de dificultades entre padres e hijos; otro testimonio contrapone al sabio orgulloso con quien escucha el consejo. Otra lectura presenta la vía favorable como transformación de la mirada, y la desfavorable como una ilusión que impide apreciar lo bueno."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Un padre o una madre quiere que sus hijos se pongan de acuerdo (relato de la serpiente padre).", "En la familia o el grupo compiten por cargos, reconocimiento o ganancias.", "Desprecia una ayuda porque viene de alguien que considera poco capaz.", "El hijo menor no es valorado igual que los demás (relato de Kèké, Òkótó y Àré).", "Cree que ya sabe resolverlo todo y dejó de escuchar (relato del Sabio y el Necio)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de una percepción más clara y del valor de la iniciación en su lectura favorable. En otro testimonio, Àré, el menor de tres, es quien actúa y sostiene a la familia cuando hace falta. El personaje llamado Necio también obtiene un resultado favorable porque escucha, mientras el Sabio presume de su autosuficiencia."}, {"titulo": "Ibi y advertencias", "texto": "La ficha presenta a una familia que no logra unirse ante una amenaza. Otra lectura advierte sobre una visión ilusoria que lleva a despreciar bondad y belleza y puede volverse autodestructiva. El relato del Sabio muestra cómo el orgullo deja escapar una ganancia. Ninguno de esos desenlaces debe usarse para descalificar a una persona por su educación o capacidad."}, {"titulo": "Enseñanza principal", "texto": "La prudencia familiar no nace solo de jerarquías: escuchar al miembro menos valorado puede ser decisivo. El testimonio enseña a distinguir experiencia de arrogancia. Frente a un problema común, la cooperación entre hijos o compañeros ofrece más que insistir en que uno solo posee todas las respuestas."}, {"titulo": "Relatos reunidos", "texto": "La serpiente padre consulta porque sus descendientes no se unen para protegerse. Kèké, Òkótó y Àré son tres miembros de una familia que buscan prosperar; el menor realiza la ofrenda y termina ayudando al padre. En otro relato, el Sabio se burla de la necesidad de consejo mientras el llamado Necio lo acepta y obtiene ganancias. Son fábulas diferentes dentro del signo."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de las serpientes enumera dieciséis babosas, paloma, cauríes y un elemento descrito como veneno; se registra como texto tradicional, no como preparación o consejo de uso. El testimonio habla de una piel animal para uno de los relatos y de ofrendas distintas para los tres miembros de la familia y para el Sabio y el Necio. No hay una lista única para todos."}, {"titulo": "Relaciones espirituales", "texto": "Ifá orienta las consultas de la serpiente, los tres familiares y los personajes Sabio y Necio. Kèké, Òkótó y Àré son personajes narrativos. La mención favorable de iniciación en otra lectura no asigna por sí sola un oricha exclusivo al signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La piel animal y los objetos de ofrenda pertenecen a relatos distintos. La serpiente es un personaje de la fábula familiar, no una instrucción para manipular animales o venenos. Los pasajes consultados no permiten identificar con seguridad una planta particular."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso de la familia de serpientes y los cantos de Kèké, Òkótó, Àré, el Sabio y el Necio. La versión de otro testimonio aparece bajo Ìwòrì wòtu. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=58;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ìrẹtẹ̀ vincula la iniciación con un cambio de conducta y con la relación entre aprendiz y guía. Un verso afirma que quien se inicia debe también “reiniciarse” en su propia mente. Otra lectura contrapone determinación y transformación personal con testarudez que prolonga el conflicto. El testimonio añade un relato extenso sobre Orí, destino y trato justo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa iniciarse en Ifá o renovar su compromiso con lo que ya aprendió.", "Un babaláwo, aprendiz o consultante debe revisar cómo trata a quienes le ayudan.", "Repite una conducta dañina aunque sabe lo que provoca (verso de los actos que regresan).", "Aspira a un cargo importante y teme perderlo por ingratitud o imprudencia.", "Está enfermo o cuida a alguien enfermo (relato de Ẹ̀rẹ̀).", "Un golpe del destino puede terminar en un cambio de posición (relato de Ṣàṣóré)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de determinación después de transformar una conducta negativa. El primer verso valora hacer el bien y cuidar a personas necesitadas; el segundo da advertencias prácticas sobre riesgos que pueden evitarse. En otro testimonio, Ṣàṣóré termina en una posición de autoridad después de sobrevivir a un agravio, y otro relato celebra la mejoría de Ẹ̀rẹ̀. Son desenlaces narrativos, no resultados garantizados."}, {"titulo": "Ibi y advertencias", "texto": "La testarudez y el daño a otros pueden volverse contra quien los practica. El verso advierte contra robo, decisiones imprudentes y violencia al manejar un cuchillo. El testimonio muestra a un superior que encierra a Ṣàṣóré y lo arroja al río por una oración que interpreta como ofensa; el relato no justifica ese acto. Las afirmaciones de curación de otro testimonio no son pronósticos médicos."}, {"titulo": "Enseñanza principal", "texto": "La iniciación sin cambio interior queda incompleta. Hacer el bien, abandonar el robo, actuar con seguridad y tratar con respeto a aprendices y guías son formas concretas de esa transformación. La historia de Ṣàṣóré recuerda que el poder debe ejercerse sin crueldad, incluso cuando alguien interpreta mal una palabra."}, {"titulo": "Relatos reunidos", "texto": "Un verso dirigido al mundo entero dice que las buenas y malas acciones regresan a quienes las realizan y pide dejar el robo. Otro recita precauciones. En otro testimonio, Ìwòrì pregunta por la enfermedad de Ẹ̀rẹ̀ y celebra su recuperación. Ṣàṣóré ora a Orí; un gobernante lo castiga y lo arroja al río dentro de un ataúd, pero sobrevive, llega a Benín y es elegido rey. El episodio pertenece a una narración de destino, no a una recomendación de soportar maltrato."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso nombra babosas, pescado y cauríes; el segundo, pescado, cauríes y medicina de Ifá. Una nota describe una sopa con hojas de èṣò, cuya identificación y seguridad no están verificadas. El testimonio menciona atención ritual a Orí y ofrendas en los relatos de Ẹ̀rẹ̀ y Ṣàṣóré, sin una lista única que abarque los casos."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es la referencia central de los versos de iniciación y conducta. Orí aparece expresamente en otro testimonio como destino y objeto de atención ritual; Ọ̀rúnmìlà es nombrado en la tradición de los versos. Ṣàṣóré y Ẹ̀rẹ̀ son personajes humanos de relatos distintos, no orichas propios del signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El pescado y los cauríes figuran en ofrendas; la nota de medicina tradicional menciona hojas de èṣò. La cuerda, el agua y el cuchillo son imágenes de seguridad del segundo verso; el río y el ataúd son elementos del relato de Ṣàṣóré."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan el verso ético sobre los actos buenos y malos, la recitación de precauciones “Ìwòrì-tẹjúmọ́…” y los cantos de Ẹ̀rẹ̀ y Ṣàṣóré. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=59;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀ṣẹ́ relaciona esperanza y administración cuidadosa con la posibilidad de salir de la adversidad. Un verso invita a mantener el buen nombre durante la pobreza; otro testimonio muestra a un granjero que pierde dinero al dejar de atender su trabajo. Otros pasajes tratan el deseo de maternidad de mujeres de distintas edades, sin convertirlo en promesa médica."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pasa por problemas de dinero y teme perder el ánimo o la reputación (relato de Owókosi).", "Su negocio pierde ventas porque se distrae o trata mal a una clienta (relato del granjero y la comerciante).", "La familia desea hijos o una mujer madura pregunta si puede embarazarse (relatos de Ojú-oje y Osúnláyà).", "Tiene recursos, pero la avaricia o la mala administración no le deja usarlos bien.", "Quiere proteger a sus hijos y el bienestar de la casa."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura describe la recuperación como punto de partida hacia la abundancia. Owókosi recibe el consejo de no dejarse vencer por la pobreza y de conservar su buen nombre; la amargura de una hoja se contrapone a una dulzura futura. Ojú-oje y Osúnláyà alcanzan maternidad en sus relatos. Son imágenes de esperanza, no garantías de embarazo o riqueza."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte que la avaricia y la mala administración pueden bloquear la mejora. El granjero de otro testimonio deja de atender mercancías y ventas porque mira el cuerpo de una clienta; acaba perdiendo dinero y es objeto de burla. El relato señala falta de concentración y respeto, no culpa de la mujer comerciante."}, {"titulo": "Enseñanza principal", "texto": "La recuperación exige sostener la dignidad y atender las responsabilidades diarias. El verso de Owókosi aconseja preservar el buen nombre aun en la escasez; la fábula del granjero pide concentrarse en el trabajo y tratar a las personas con respeto. La esperanza de maternidad merece apoyo sin convertir un relato religioso en predicción."}, {"titulo": "Relatos reunidos", "texto": "Owókosi atraviesa pobreza y recibe un consejo de perseverancia y cuidado de su reputación. Ojú-oje consulta por la posibilidad de ser madre. En otro testimonio, un granjero pierde ingresos mientras mira a una comerciante en vez de atender su negocio. Osúnláyà, esposa de Agbọ̀nnìrègún, llora por no tener hijos y el canto celebra su descendencia; también formula preguntas sobre edad y menstruación, que se conservan como parte de la narración."}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Owókosi menciona palomas, cauríes y una preparación tradicional con hojas; el de Ojú-oje nombra gallina, chiva, cauríes y medicina de Ifá. El testimonio alude a una vasija llena de nueces de kola y a otra ofrenda para Osúnláyà. Son indicaciones de casos distintos; ninguna preparación se presenta como tratamiento de fertilidad o pobreza."}, {"titulo": "Relaciones espirituales", "texto": "Ifá guía las consultas de Owókosi, Ojú-oje, el granjero y Osúnláyà. Agbọ̀nnìrègún aparece como esposo de Osúnláyà en otro testimonio. El nombre de Ojú-oje como “diosa de la belleza” pertenece al verso específico y no basta para asignar a todo el signo un oricha exclusivo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La hoja amarga ewúro sirve como imagen de una etapa difícil que puede preceder a otra más dulce. Una nota menciona también Oluṣesaju. La nuez de kola y una vasija de barro aparecen en una ofrenda de otro testimonio; no se recomienda la preparación vegetal como tratamiento."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan los versos de Owókosi y Ojú-oje, el canto del granjero y la comerciante y el de Osúnláyà. El testimonio llama al signo Ìwòrì wówó / Ìwòrì wóṣù. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=60;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo se relaciona con la mejora de los negocios y el alivio de preocupaciones económicas. También aparece la posibilidad de fortuna, familia y una vida más placentera; cada promesa pertenece a un pasaje concreto."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme que su negocio o sus ingresos no crezcan, pero puede venir una mejora rápida.", "Va a viajar para trabajar y puede volver con prestigio y recursos (relato de Ọ̀rúnmìlà en la laguna y el mar).", "Busca protección para su cabeza (Orí), prosperidad, pareja e hijos (relato de Ìwòrì lavando la cabeza de Òfún).", "Pregunta si tendrá una vida agradable (relato de la gente de Isàọ̀wóngá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable de otra lectura habla de transformación y de una nueva relación. En los versos se anuncia prestigio, buena fortuna financiera y una vida satisfactoria para quienes consultan y cumplen la indicación de su relato."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable de otra lectura relaciona el conflicto con la disfunción de una relación. El consejo sobre alimentos que aparece en otro testimonio es específico de ese testimonio y no debe imponerse como prohibición general del signo."}, {"titulo": "Enseñanza principal", "texto": "La prosperidad se presenta unida a la consulta y a la atención al consejo recibido. El relato de la comunidad de Isàọ̀wóngá distingue la pregunta por una vida feliz de la acción concreta que sus protagonistas realizaron."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe una predicción de honor y fortuna antes de viajar a la laguna y al mar.", "Ìwòrì lava la cabeza de Òfún; el relato lo asocia con riqueza, cónyuge e hijos.", "La comunidad de Isàọ̀wóngá pregunta si tendrá una vida grata y, tras atender el consejo, celebra su bienestar."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del viaje menciona un carnero blanco, una paloma blanca y 8.000 cauríes. El testimonio da indicaciones distintas para la fortuna y la familia, entre ellas una ofrenda a Ifá. Son contextos separados; no hay un ẹbọ único para todo Ìwòrì Òfún."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà es el protagonista del verso del viaje. Ifá interviene en la consulta; Orí aparece en el relato de protección. Estas funciones no deben fundirse en una sola atribución."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los testimonios mencionan carnero, paloma, cauríes y langostinos. El testimonio nombra el quimbombó en una restricción situada; no se generaliza ni se presenta como consejo médico."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan por separado el verso del viaje, el canto del lavado de la cabeza y el relato de Isàọ̀wóngá. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=61;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìdí Ogbè trata una amenaza presente o cercana y la posibilidad de superarla. Los textos reúnen preocupación por trabajo y dinero, tensiones afectivas, enemigos y la importancia de cuidar la palabra."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme por su empleo, su dinero o una relación que lo desgasta.", "Siente que la muerte o la enfermedad rondan la casa (relato de Ọ̀rúnmìlà frente a Ikú y Àrùn).", "Está rodeado de enemigos y puede salir victorioso (relato de Ṣàngó).", "Alguien puede meterlo en un pleito público; debe cuidar lo que dice."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura describe una amenaza que puede superarse. El relato de Ṣàngó termina en victoria sobre adversarios; el texto principal plantea que el problema puede tratarse y no es necesariamente permanente."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que ignorar una amenaza puede agravarla. Los relatos de Ikú y Àrùn son imágenes de la tradición, no pronósticos clínicos ni diagnóstico individual. El testimonio también previene sobre discusiones y palabras imprudentes."}, {"titulo": "Enseñanza principal", "texto": "La respuesta adecuada depende del peligro concreto: distinguir el temor de un hecho confirmado, hablar con cuidado y atender la indicación propia del relato consultado."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà coloca figuras protectoras en las entradas de su casa; Ikú y Àrùn se retiran.", "Ṣàngó recibe consejo ante enemigos que lo rodean y el relato concluye con su victoria.", "El testimonio narra episodios diferentes sobre Ìgbin y sobre Adédoyin; no se reducen a una sola historia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ọ̀rúnmìlà describe figuras ṣìgìdì, materiales rituales y un chivo; el de Ṣàngó menciona carnero y cauríes. El testimonio ofrece otras indicaciones. Cada lista corresponde a su propio relato y requiere interpretación ritual competente."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà y Ṣàngó protagonizan versos distintos. Ikú y Àrùn aparecen como personificaciones de muerte y enfermedad. El testimonio nombra además a un òrìṣà en la historia de Ìgbin."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen nuez de kola, carnero, chivo, cauríes y una hierba transcrita de forma incierta en el verso de Ọ̀rúnmìlà."}, {"titulo": "Rezos, versos y cantos", "texto": "Hay versos para Ọ̀rúnmìlà y Ṣàngó, además de cantos en otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=62;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo contrapone la búsqueda de prosperidad y descendencia con el deber de atender los riesgos y a los antepasados. Las fuentes ofrecen relatos distintos: algunos hablan de éxito gradual; otros, de la consecuencia de rechazar un consejo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Busca alivio de las presiones diarias y de problemas en el negocio, apoyándose en sus antepasados.", "Desea hijos y protección frente a adversarios (relato de Òyà).", "Se prepara para salir a otra ciudad y pregunta cómo le irá (relato de Okunkunṣù en Ifẹ̀).", "No quiere soltar un bien material y por eso ignora una advertencia (relato de Olorí-Oga y la tela blanca)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "En buena fortuna, la ficha relaciona el éxito económico con la atención a Orí. Otra lectura describe un avance lento hacia el éxito. El relato de Okunkunṣù anuncia prosperidad tras llegar a Ifẹ̀ y atender el consejo recibido."}, {"titulo": "Ibi y advertencias", "texto": "La ficha en mala fortuna habla de evitar un desenlace prematuro. El relato de Olorí-Oga usa la tela blanca y la muerte como advertencia narrativa. No se debe convertir en predicción literal de muerte para toda persona que reciba el signo."}, {"titulo": "Enseñanza principal", "texto": "Los relatos distinguen entre cumplir una parte del consejo y atenderlo por completo: en el episodio de Òyà, la descendencia llega, pero el conflicto con los adversarios persiste. La enseñanza depende de la situación consultada."}, {"titulo": "Relatos reunidos", "puntos": ["Olorí-Oga se niega a ofrecer la tela blanca indicada y el verso presenta las consecuencias.", "Okunkunṣù viaja a Ifẹ̀ y recibe una predicción de éxito.", "El testimonio cuenta que Òyà atiende la petición por hijos pero omite la advertencia sobre adversarios.", "El coco obtiene descendencia en un relato distinto."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los versos mencionan una tela blanca, una carnera y cauríes en el caso de Olorí-Oga; otro cita rata, pescado y gallina para el viaje de Okunkunṣù. El testimonio da otras ofrendas para descendencia y adversarios. Ninguna lista es universal."}, {"titulo": "Relaciones espirituales", "texto": "Orí y los antepasados se vinculan con la caracterización y el WO. Òyà y Òṣun intervienen en un relato de otro testimonio; sus papeles se conservan separados."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los pasajes nombran tela blanca, carnera, cauríes, rata, pescado, gallina, coco y una cesta de pollos. No se infiere de ellos una receta botánica o médica general."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos y el canto de Olorí-Oga se mantienen diferenciados de los relatos yorùbá de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=63;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo insiste en usar la inteligencia y la fuerza de manera responsable, trabajar y elegir bien las compañías. También advierte sobre la posibilidad de perder posición frente a un rival que se ha pasado por alto."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme que lo desplacen en un negocio, una sociedad o una relación, y no sabe bien quién compite con él.", "Tiene una capacidad que no está usando: saber sin aplicar es como no saber.", "Puede estar rodeado de gente con malas mañas que terminen perjudicándolo.", "Teme quedar en un puesto de menor importancia."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con seguir la sabiduría de Ifá. Los versos proponen conservar el lugar alcanzado mediante la atención a un consejo preciso y el empleo efectivo de las facultades personales."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable une la inacción con el conflicto. La caracterización advierte de pérdidas al participar en acuerdos fraudulentos. La presencia de un rival es una posibilidad del WO, no una identificación automática de una persona."}, {"titulo": "Enseñanza principal", "texto": "Saber o poder hacer algo no basta si se abandona esa capacidad. El segundo verso expresa la enseñanza en dos imágenes paralelas y subraya también la importancia de las compañías."}, {"titulo": "Relatos reunidos", "puntos": ["Un consultante pregunta por la posibilidad de quedar relegado a un puesto de menor importancia.", "Otro relato presenta a personas que se apartan de quienes trabajan con sabiduría y señala la consecuencia de esa elección."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita cuatro palomas, 8.000 cauríes y una medicina de Ifá; el segundo, dos gallinas y 4.400 cauríes. Las dos listas corresponden a situaciones distintas y no son un ẹbọ general para el signo."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el marco de los consejos de ambos versos. La ficha no asigna una entidad espiritual exclusiva a Ìdí Ìwòrì."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan palomas, gallinas y cauríes. El primer verso alude a una medicina de Ifá sin describir sus ingredientes; no se puede reconstruir su composición a partir de este pasaje."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos conservan sus enunciados de adivinación. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=64;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Los textos de este signo reúnen dos ejes diferentes: la atención a molestias físicas descritas en la tradición y el reconocimiento público que puede favorecer un oficio o comercio. El testimonio añade un relato de prosperidad material."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene molestias en la cintura, las nalgas, las vías urinarias o la menstruación y conviene revisarlo con un médico (relato de Àgbà-Kuomi).", "Quiere dar a conocer su trabajo, sus productos o su nombre y el reconocimiento no llega (relato de Ọ̀rúnmìlà y el loro).", "Busca prosperar en el comercio, la familia, la casa y el dinero."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla del desarrollo del potencial y del reconocimiento. Un verso narra que el símbolo de Ọ̀rúnmìlà se vuelve visible y conocido; otro testimonio también habla de fortuna comercial."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura menciona la posibilidad de una infección de transmisión sexual. El verso de Àgbà-Kuomi habla de una dolencia en las nalgas. Ningún pasaje permite afirmar que la persona consultante padezca esa condición; ante síntomas corresponde evaluación médica."}, {"titulo": "Enseñanza principal", "texto": "La popularidad y la prosperidad pertenecen a relatos situados. Conviene distinguir la imagen ritual del reconocimiento público de una promesa de éxito comercial garantizado."}, {"titulo": "Relatos reunidos", "puntos": ["Àgbà-Kuomi consulta por una dolencia situada debajo de las nalgas y recibe un consejo ritual.", "Ọ̀rúnmìlà recibe una indicación relacionada con Òṣù y el relato explica su reconocimiento mediante una imagen del loro.", "El testimonio cuenta que Ọ̀rúnmìlà buscaba fortuna en el comercio y atendió el consejo recibido."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de Àgbà-Kuomi menciona nueve babosas y 8.000 cauríes. El de Ọ̀rúnmìlà enumera gallina, aceite de palma, rata, pescado, cauríes y Òṣù. Son indicaciones diferenciadas; el texto no ofrece una preparación médica validada."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el relato del reconocimiento. Òṣù se nombra como objeto ritual en ese verso. No se transforma esa mención en una atribución de otro oricha."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los pasajes nombran babosas, gallina, rata, pescado, aceite de palma, plumas de loro y el bastón Òṣù. No se identificó una planta medicinal específica del signo en estos relatos."}, {"titulo": "Rezos, versos y cantos", "texto": "Hay un verso sobre Àgbà-Kuomi, otro sobre el reconocimiento de Ọ̀rúnmìlà y pasajes de otro testimonio sobre comercio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=65;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo se relaciona con presión en el trabajo y la posibilidad de que un desempeño creativo reciba reconocimiento. Otros relatos tratan la firmeza y la continuidad de la vida mediante las imágenes de la tortuga y la palmera."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene presión en el trabajo y espera que valoren su esfuerzo o su habilidad (relato de la tortuga).", "Quiere mantenerse firme y resistir (relato de la palmera).", "Siente amenazas de adversarios o de pérdida y debe tomar precauciones (relato de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con una valoración inesperada del trabajo creativo. La caracterización anuncia reconocimiento profesional; los relatos de la tortuga y la palmera expresan honor y permanencia en circunstancias distintas."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable de otra lectura advierte sobre depresión intensa. El testimonio usa imágenes de amenazas y muerte. Son textos tradicionales y no diagnostican un trastorno ni anuncian una muerte individual; una crisis emocional requiere apoyo profesional."}, {"titulo": "Enseñanza principal", "texto": "El reconocimiento de la tortuga y la permanencia de la palmera son resultados de relatos separados. La lectura concreta ha de conservar esa diferencia y atender el trabajo real de la persona."}, {"titulo": "Relatos reunidos", "puntos": ["La tortuga consulta para recibir honor donde ejerza su habilidad y el relato concluye con estima pública.", "La palmera consulta para mantenerse firme y el verso termina con su supervivencia.", "Un relato de otro testimonio presenta a Ọ̀rúnmìlà tomando precauciones ante una amenaza personificada."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La tortuga ofrece cuentas de coral, palomas y cauríes. La palmera recibe otra lista: carnera, campana, cauríes y medicina de Ifá. El testimonio contiene una indicación diferente para su relato; no se combinan las tres."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece en las consultas de los versos. Ọ̀rúnmìlà protagoniza el relato de otro testimonio; Ikú figura como personificación en ese episodio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen cuentas de coral, palomas, carnera, campana, cauríes y la palmera. La palmera actúa como personaje de un verso, no como receta botánica para una dolencia."}, {"titulo": "Rezos, versos y cantos", "texto": "Se distinguen los versos de la tortuga y la palmera del relato de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=66;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo aborda obstáculos y malentendidos, en especial entre personas cercanas. Un relato mira la relación entre Èdí y Ọ̀bàrà; otro, las dificultades que rodean a un árbol y a la palma. El testimonio añade una posibilidad distinta: un viaje favorable."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene tensiones con su pareja o con la familia de ella; las evasivas y el desprecio empeoran el pleito (relato de Èdí y Ọ̀bàrà).", "Piensa viajar y duda si en el nuevo lugar le irá bien (relato de Ọ̀rúnmìlà y el viaje a Èňpe).", "Su proyecto está rodeado de obstáculos que debe despejar antes de esperar resultados (relato de la palma y la maleza)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con elevación y disciplina espiritual. El relato de la palma termina con un entorno despejado y provechoso; otro testimonio presenta un viaje que puede traer fortuna."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de una amistad perdida por egoísmo o malentendido. El relato de Èdí y Ọ̀bàrà muestra el daño de ridiculizar a la otra persona. No se garantiza que un compromiso formal resuelva por sí solo una relación difícil."}, {"titulo": "Enseñanza principal", "texto": "Las dificultades materiales y las afectivas requieren respuestas diferentes. La imagen del granjero que limpia alrededor de la palma enseña a retirar obstáculos concretos; la historia de Èdí y Ọ̀bàrà pide atender el trato mutuo."}, {"titulo": "Relatos reunidos", "puntos": ["Un árbol rodeado de maleza y la palma reciben consejos distintos; el granjero despeja el lugar de la palma.", "Èdí y Ọ̀bàrà afrontan desacuerdos y un posible matrimonio en un relato sobre malentendidos.", "Ọ̀rúnmìlà pregunta por un viaje a Èňpe en otro testimonio, donde se narra un resultado favorable."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de la palma enumera herramientas, animales y cauríes; el de Èdí y Ọ̀bàrà da otra lista para evitar la pelea. El viaje de otro testimonio tiene su consejo propio. No se unen esas indicaciones en una sola ofrenda."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù interviene en el relato de la palma. Ọ̀rúnmìlà protagoniza el viaje de otro testimonio. Ọlọ́fin aparece dentro del relato de Èdí y Ọ̀bàrà; las funciones de cada personaje permanecen diferenciadas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La palma es protagonista de un verso; también aparecen paloma, gallo, gallina, chivo, chiva, pescado, rata, herramientas y cauríes. La palma no se convierte por ello en una receta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de la palma y de Èdí y Ọ̀bàrà se conservan separados del canto del viaje. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=67;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo advierte sobre deshonestidad, traición y consecuencias de apropiarse de lo ajeno. A la vez, Otra lectura y otro testimonio ofrecen lecturas favorables sobre nuevas direcciones, paciencia y posibles bienes lejanos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme una traición de alguien en quien confía.", "Está ante una tentación deshonesta o cerca de gente que quiere robar (relato de los ladrones en la granja).", "Un viaje largo puede traer herencia o fortuna, con paciencia y atención (relato de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de nuevas direcciones y de reparar dificultades heredadas. El testimonio menciona la posibilidad de bienes lejanos y pide paciencia; es un testimonio diferente del verso de los ladrones."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable advierte de actuar sin rumbo y de las consecuencias del robo. El verso presenta a dos ladrones apresados tras entrar en un campo; no se debe convertir esa historia en acusación contra la persona consultante."}, {"titulo": "Enseñanza principal", "texto": "La vergüenza que alcanza a quienes roban es la enseñanza expresa del verso. La sospecha de traición requiere comprobar hechos, mientras que la posibilidad de un viaje o herencia debe leerse según el pasaje que se confirme."}, {"titulo": "Relatos reunidos", "puntos": ["Dos ladrones entran en una granja y son apresados; el verso compara su atadura con la de los ñames.", "El testimonio presenta a Ọ̀rúnmìlà viajando hacia un lugar lejano y contiene además un episodio de Òkòtó; no son la misma historia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de los ladrones enumera babosas, cauríes y una medicina de Ifá, pero sus protagonistas rehúsan el consejo. El testimonio menciona otras ofrendas para el viaje. Cada caso permanece asociado a su relato; no se prescribe una lista universal."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece como marco de adivinación. Ọ̀rúnmìlà interviene en un relato de otro testimonio. La ficha no atribuye en exclusiva el signo a un oricha a partir de esas menciones."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El verso menciona ñames, soga, babosas y cauríes. El ñame es parte de la comparación narrativa, no una indicación botánica o alimentaria general."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conserva el verso de los ladrones separado de los relatos de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=68;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìdí Ògúndá vincula la fuerza con el buen juicio y el carácter. Los versos muestran a Ògún buscando equilibrio entre su cabeza y su cuerpo, y preguntan por qué su casa se ha quedado vacía. El testimonio añade trabajo constante y una expectativa de bienestar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene fuerza y energía, pero debe cuidar sus decisiones y cómo trata a los demás (relato de Ògún y su cabeza).", "Una conducta sexual imprudente puede traerle problemas.", "Sale temprano a trabajar y espera que esa constancia le dé frutos (relato del trabajador del campo)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula la lectura favorable con despejar obstáculos y mejorar la convivencia. En un verso, Ògún atiende el consejo para fortalecer su Orí; otro testimonio habla de bendiciones y paz mental ligadas al trabajo."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de conflicto por conducta antisocial. El segundo verso presenta la casa vacía de Ògún como consecuencia de su carácter. La advertencia del WO sobre promiscuidad pertenece a la caracterización de la fuente, no es juicio sobre una persona concreta."}, {"titulo": "Enseñanza principal", "texto": "La fuerza física no reemplaza la sabiduría ni el trato digno. Los versos plantean dos aspectos distintos del equilibrio: cuidar la propia cabeza y mantener relaciones que no alejen a los demás."}, {"titulo": "Relatos reunidos", "puntos": ["Ògún consulta para que su cabeza sea tan fuerte como su cuerpo.", "Otro verso pregunta por la casa desierta de Ògún y señala su carácter.", "El testimonio cuenta la historia de un trabajador que sale temprano al campo; su enseñanza se conserva aparte."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso enumera carnera, paloma, cauríes y medicina de Ifá; el segundo cita chiva, cauríes y otra medicina. El testimonio tiene instrucciones propias. No se funden las ofrendas de carácter, equilibrio y trabajo."}, {"titulo": "Relaciones espirituales", "texto": "Ògún protagoniza ambos versos; Orí es la cabeza a la que se refiere el primero. Ọ̀rúnmìlà aparece como voz introductoria de la adivinación."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran carnera, paloma, chiva y cauríes. El testimonio habla del campo y del trabajo; no se extrae de ello una planta medicinal identificada."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos sobre Ògún y el relato del trabajador conservan contextos independientes. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=69;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata la intranquilidad, el peso de las responsabilidades y la búsqueda de descanso. Sus versos usan la imagen de Ìdí que huye o no logra sentarse; otro testimonio presenta relatos distintos sobre avisos, alimento y oposición."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está agobiado por los asuntos diarios y no encuentra descanso (relato de Ìdí que no puede sentarse).", "Huye de un cargo o una obligación por miedo a lo que traiga (relato de Ìdí escondiéndose).", "Dos personas ignoran avisos y deben atender un pleito con adversarios."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con abundancia y con evitar una situación vergonzosa. El primer verso termina con la posibilidad de descanso tras atender el consejo que recibe su protagonista."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable de otra lectura menciona inestabilidad emocional y planificación de la natalidad; son formulaciones de esa fuente, no diagnósticos ni instrucciones médicas individuales. El segundo verso presenta vergüenza por huir de un cargo."}, {"titulo": "Enseñanza principal", "texto": "El alivio no llega solo por escapar de la responsabilidad. Los versos distinguen entre buscar reposo y ocultarse para no asumir un papel que corresponde a la persona."}, {"titulo": "Relatos reunidos", "puntos": ["Ìdí corre, intenta sentarse y no logra descansar hasta recibir consejo.", "En otro verso, Ìdí se esconde para evitar que la nombren jefa y termina con problemas de vergüenza.", "El testimonio reúne un relato sobre el loro y el maíz húmedo y otro sobre animales enfrentados; se mantienen separados."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del descanso cita paloma y cauríes. El segundo enumera hojas, además de animales y cauríes. El testimonio ofrece otra indicación para dos personas."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el marco de la consulta. Èṣù aparece en uno de los relatos de otro testimonio; su papel se conserva en ese episodio específico."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen paloma, carnera, maíz y una hoja transcrita de forma dudosa como «Owa». La identidad botánica de esta última queda sin resolver y no se propone uso medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan separados los dos versos de Ìdí y las historias de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=70;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo advierte contra dañar a otros y contra aprovecharse de un secreto ajeno. Sus textos reúnen la posibilidad de engaño en negocios, el llamado al perdón y relatos sobre daño, discreción y elección de un lugar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme que alguien cuente un secreto suyo o lo engañe en un negocio (relato de Olókun y Ọlósa).", "Piensa en vengarse, y el daño a otros se regresa (relato de Abatẹnijẹ).", "Tiene enemigos o busca el lugar adecuado para establecerse (relato de la jícara)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con poder personal y perdón. El verso de Olókun y Ọlósa expresa que sus secretos permanecerán protegidos después de atender el consejo de su propio relato."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura previene sobre las consecuencias de intentar dañar a otros. El verso de Abatẹnijẹ anuncia el fin de una etapa de maldad; no permite acusar a la persona consultante de brujería ni atribuir hechos no confirmados."}, {"titulo": "Enseñanza principal", "texto": "La discreción y la reparación del daño son temas diferentes que aparecen en los dos versos. El primero pone en cuestión la intención de perjudicar; el segundo protege la intimidad de Olókun y Ọlósa."}, {"titulo": "Relatos reunidos", "puntos": ["Abatẹnijẹ escucha una advertencia sobre el daño a otros y la necesidad de cambiar de conducta.", "Olókun y Ọlósa reciben consejo para conservar sus secretos.", "El testimonio narra una consulta de la jícara sobre el lugar donde establecerse; queda separada de los otros dos versos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Abatẹnijẹ contiene una indicación abierta atribuida a su adivino, sin lista cerrada que pueda trasladarse a otra consulta. El de Olókun y Ọlósa menciona recipientes de barro, palomas y cauríes. El testimonio presenta materiales distintos para su conflicto."}, {"titulo": "Relaciones espirituales", "texto": "Olókun y Ọlósa son protagonistas del verso de los secretos. Ifá es el marco de adivinación. Sus papeles no se sustituyen entre sí."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran recipientes de barro, palomas, cauríes y una jícara en el relato de otro testimonio. La jícara figura como personaje y objeto, no como preparación médica."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos sobre Abatẹnijẹ y sobre Olókun y Ọlósa se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=71;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "La ficha trata descendencia y molestias físicas descritas por la tradición. También habla de un despertar emocional o espiritual. Los relatos de Olú-Ọgán, Ondugbé y Ṣàngó son distintos y no comparten un mismo consejo ritual. Una narración independiente trata la petición de ayuda a los ancestros y la conducta de un mensajero."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Desea tener hijos y busca apoyo ante dificultades para concebir o dar a luz (relatos de Olú-Ọgán y de Ṣàngó).", "Tiene una molestia en la parte baja del cuerpo que conviene revisar con un médico (relato de Ondugbé).", "Vive una desilusión o está cambiando su forma de ver la situación.", "Necesita ser honesto; un hijo podría enfrentar dificultades.", "Pidió ayuda a su familia y un intermediario no le entregó lo que le dieron (relato de Èṣù Ọ̀dàrà y los ancestros)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con cuidar la salud reproductiva. Un verso presenta la posibilidad de descendencia; otro testimonio cuenta la consulta de Ṣàngó por la ausencia de hijos. Son testimonios situados, no garantías de fertilidad."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura menciona la posibilidad de enfermedad, incluso de transmisión sexual. El verso de Ondugbé trata una dolencia bajo el cuerpo. Ante síntomas, se necesita atención médica; el signo no establece un diagnóstico. El episodio del mensajero trata engaño y confianza, no una indicación de administrar sustancias a otra persona."}, {"titulo": "Enseñanza principal", "texto": "Los textos unen la esperanza de descendencia con la responsabilidad de atender tanto el consejo propio del relato como la salud de la persona. La honestidad de otro testimonio es una enseñanza adicional."}, {"titulo": "Relatos reunidos", "puntos": ["Olú-Ọgán recibe consejo en un verso sobre tener hijos.", "Ondugbé consulta por una dolencia en la parte baja del cuerpo.", "Ṣàngó, en otro testimonio, pregunta por la descendencia y recibe una respuesta propia.", "Ọ̀rúnmìlà envía a Èṣù Ọ̀dàrà a pedir apoyo a los ancestros; el mensajero oculta lo recibido y después queda en evidencia. Se conserva separado de las consultas por descendencia y salud."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Olú-Ọgán nombra semillas de quimbombó, ñames, chivas y cauríes; el de Ondugbé enumera animales y cauríes diferentes. El episodio de Ṣàngó tiene otra indicación. Ninguna lista es un tratamiento médico ni un ẹbọ universal."}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó protagoniza el relato de otro testimonio. Ifá aparece en las consultas de los otros versos; no se atribuye a Ṣàngó el papel de todos sus personajes. En el relato adicional intervienen los ancestros y Èṣù Ọ̀dàrà como mensajero de Ọ̀rúnmìlà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los pasajes nombran quimbombó, ñame, chiva, gallo, perro y cauríes. La semilla y el ñame están en un contexto ritual; no se recomiendan como tratamiento clínico."}, {"titulo": "Rezos, versos y cantos", "texto": "Hay versos distintos para Olú-Ọgán y Ondugbé, además del relato de Ṣàngó. El pasaje de los ancestros tiene un verso introductorio propio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=72;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona el cuidado personal con la unión familiar. Un verso habla de una dolencia en la parte baja del cuerpo; otro, de evitar que la familia de Alárá se disperse. La ficha añade restricciones de alimentación propias de su tradición."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le preocupa su salud, como la presión o el colesterol, y debe revisarse con un médico (relato de Olúyemi).", "La familia se está desuniendo o teme separarse (relato de Alárá).", "Espera una familia numerosa y estabilidad económica."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia la orientación favorable con fortalecer los vínculos familiares. El verso de Alárá termina con prosperidad y unión; otro testimonio también presenta una expectativa favorable para la familia."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable habla de dispersión familiar. La ficha contiene prohibiciones alimentarias situadas en un verso, pero no deben convertirse en dieta general ni sustituir indicación médica."}, {"titulo": "Enseñanza principal", "texto": "La escoba, formada por muchas fibras reunidas, funciona en el verso de Alárá como imagen de la unión de la familia. El consejo sobre alimentación pertenece a otro pasaje y no expresa la misma enseñanza."}, {"titulo": "Relatos reunidos", "puntos": ["Olúyemi recibe una indicación ante una dolencia del bajo vientre y una nota sobre restricciones tradicionales.", "Alárá consulta para que su familia permanezca unida y el relato concluye con prosperidad.", "El testimonio ofrece relatos adicionales sobre sustento y vida familiar; sus instrucciones se mantienen separadas."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Olúyemi enumera paloma, gallina, gallo, pescado, cauríes y medicina de Ifá. El de Alárá cita un manojo de escoba, pichones y cauríes. Son listas de consultas diferentes; no se construye una receta combinada."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el marco de ambas consultas. No se identifica en estos versos un oricha exclusivo del signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan pescado, aves, cauríes y un manojo de escoba. La prohibición de nuez de kola y carne de animales domésticos aparece solo en la nota de un verso; no es recomendación nutricional general."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Olúyemi y Alárá y los pasajes de otro testimonio se conservan por separado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=73;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo presenta el trabajo constante como camino hacia un cargo o reconocimiento. También distingue el miedo a asumir un empleo del esfuerzo necesario para sostenerlo. Un relato habla de un futuro rey; otro usa herramientas como imágenes de perseverancia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le ofrecen un ascenso o un empleo y teme no estar a la altura (relato de Adegbitẹ).", "Quiere tener trabajo y dejar de temerle (relato de Ariṣẹmaṣe).", "Busca liderazgo, una vida larga y quedarse firme en su lugar (relato de la olla de barro)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con determinación y reconocimiento. El verso de Adegbitẹ anuncia una posición elevada; el de Ariṣẹmaṣe insiste en la capacidad de trabajar sin dejarse paralizar por el temor."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de obstinación y pereza como frenos. El WO señala que el miedo puede bloquear una oportunidad; ninguno de estos pasajes garantiza un ascenso a toda persona que reciba el signo."}, {"titulo": "Enseñanza principal", "texto": "Las imágenes del azadón, el machete, el perro y el carnero explican constancia y resistencia ante el trabajo. No bastan el deseo de un cargo o una predicción favorable si se abandona el esfuerzo."}, {"titulo": "Relatos reunidos", "puntos": ["Adegbitẹ Awẹrorogbọla recibe una predicción sobre un cargo futuro.", "Ariṣẹmaṣe consulta para tener trabajo y dejar de temerlo.", "La olla de arcilla de otro testimonio permanece en el lugar que escogió; es otro relato, no una continuación de los versos anteriores."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del cargo cita palomas, plumas de loro y cauríes. El del trabajo enumera carnero, azadón, machete y perro. El testimonio contiene su consejo propio; no se mezclan las listas."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece como marco de la adivinación. Las imágenes de la olla y las herramientas no son nombres de orichas ni atribuciones exclusivas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan palomas, plumas de loro, carnero, azadón, machete y olla de arcilla. Las herramientas representan el trabajo en un verso; no son plantas ni preparaciones médicas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Adegbitẹ y Ariṣẹmaṣe permanecen diferenciados del relato de la olla. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=74;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne el temor a un daño todavía no identificado y la esperanza de abundancia, serenidad y larga vida. El relato de los árboles representa la amenaza de parásitos mediante imágenes tradicionales."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme a un adversario que todavía no identifica (relato de Baálẹ̀-ẹro).", "Puede tener una enfermedad relacionada con la vida sexual y debe revisarse.", "Ve oportunidades que se le desvían y quiere recuperar la calma y el buen juicio.", "Cumplir el consejo completo hace la diferencia (relato de la palma y Pèrègún)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de abundancia y de superar un conflicto. En el relato de los árboles, la palma y Pèrègún quedan protegidos dentro de esa narración; otro testimonio anuncia bienestar en otro contexto."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de una persona peligrosa. El verso representa parásitos como amenaza. Ante síntomas físicos se necesita valoración médica; la narración no garantiza inmunidad."}, {"titulo": "Enseñanza principal", "texto": "Los árboles responden de formas distintas al consejo recibido. El episodio del viajero plantea otro problema: descubrir a un adversario desconocido. Cada relato requiere su propia lectura."}, {"titulo": "Relatos reunidos", "puntos": ["Los 165 árboles consultan ante un extraño; la palma atiende una parte del consejo y Pèrègún lo cumple.", "Baálẹ̀-ẹro consulta para descubrir un adversario desconocido.", "El testimonio presenta una búsqueda de serenidad y longevidad."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de los árboles enumera cuchillos, òrí, aceite de palma y cauríes; el de Baálẹ̀-ẹro menciona gallinas y cauríes. No se mezclan sus listas."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el marco de las consultas. La palma y Pèrègún son personajes vegetales del primer relato, no orichas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen palma, Pèrègún, aceite de palma, gallinas y cauríes."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos se conservan separados de los pasajes de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=75;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo habla de negocios bloqueados, un cambio de rumbo y un viaje inesperado. Un verso usa el peine como imagen para desenredar una dificultad; otro testimonio añade un relato distinto de descendencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita reorganizar un negocio que no prospera.", "Se acerca un viaje que no tenía planeado (relato de Ìdí y Òfún).", "Se siente cercado por un problema (relato de la gente de Ifẹ̀-Ooye).", "Alguien cercano desea tener hijos (relato de la termita)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura menciona buena fortuna durante un viaje inesperado. El verso de Ìdí y Òfún anuncia un resultado favorable; el de la comunidad describe una liberación."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de no anticipar un conflicto. El bloqueo comercial y el deseo de hijos son situaciones separadas; no se suponen simultáneas."}, {"titulo": "Enseñanza principal", "texto": "El peine que desenreda el cabello simboliza una solución apropiada al obstáculo. Cambiar de rumbo requiere también organización y atención al caso real."}, {"titulo": "Relatos reunidos", "puntos": ["Ìdí y Òfún reciben una noticia de viaje.", "La gente de Ifẹ̀-Ooye está sitiada y recibe un consejo en un verso donde aparece Ọ̀rúnmìlà.", "La termita de otro testimonio pregunta por su descendencia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del viaje menciona carnera, paloma y cauríes; el de la comunidad, peine, paloma y cauríes. El episodio de la termita tiene otra indicación. Ninguna lista es universal."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà interviene en el verso de la comunidad. No se infiere una relación ritual con Orí de la sola presencia del peine."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen carnera, paloma, peine, cauríes y correas en contextos distintos. La termita es personaje de otro testimonio, no una terapia de fertilidad."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos y el relato de la termita permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=76;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "La ficha pone en tensión los vínculos espirituales y afectivos con el progreso económico. El WO indica que las emociones ocupan un lugar importante mientras los negocios avanzan despacio."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le dedica mucha atención a sus relaciones y su negocio avanza lento.", "Pregunta por un posible matrimonio (relato de Agbe-Imorimodori y la hija de Ọlọ́fin).", "Tiene riqueza y fama, pero debe cuidarse de quienes quieren perjudicarlo (relato de Odùgbemi).", "Siente que le faltan bendiciones (relato de Iṣin)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con respetar los tabúes personales y familiares. El testimonio narra una búsqueda de prosperidad; su resultado pertenece a ese relato."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de arrogancia al desatender prohibiciones familiares. El verso de Odùgbemi sitúa la fama y la vida en un contexto ritual específico, no en un pronóstico literal de muerte."}, {"titulo": "Enseñanza principal", "texto": "La lentitud económica no cancela el valor de los vínculos. Los relatos piden distinguir tradición familiar, matrimonio y riqueza sin reducirlos a una sola causa."}, {"titulo": "Relatos reunidos", "puntos": ["Agbe-Imorimodori consulta antes de casarse con Biojẹla, hija de Ọlọ́fin.", "Odùgbemi, rico y conocido, recibe una advertencia situada en ceremonias distintas.", "En otro testimonio, Iṣin pregunta por las bendiciones que le faltan."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita ratas, peces, gallina y cauríes. El segundo diferencia una paloma para una ceremonia de nacimiento y una carnera para iniciación; no se intercambian."}, {"titulo": "Relaciones espirituales", "texto": "Ọlọ́fin aparece como padre de Biojẹla. Èlà se nombra en el canto de otro testimonio. Se conservan sus funciones distintas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen peces, ratas, gallina, paloma y carnera. Iṣin aparece como posible planta."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Agbe-Imorimodori y Odùgbemi siguen separados de los cantos de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=77;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo advierte sobre envidia, seducción y decisiones que pueden causar pérdidas. También habla de una mudanza o un cambio laboral favorable y pide paciencia antes de esperar ganancias."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa mudarse o cambiar de actividad (relato de Ọ̀rúnmìlà en casa de Olókun-Ṣande).", "Su éxito puede despertar envidia.", "Una relación puede dañar a un tercero (relato de Amure y la esposa de Ṣàngó).", "No debe apresurarse a juntar dinero; las ganancias llegan con espera."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con buscar abundancia mediante orientación espiritual. El verso de la mudanza a casa de Olókun-Ṣande presenta ventajas materiales."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de pérdidas y problemas legales ante actos ilícitos. El episodio de Amure y la esposa de Ṣàngó no es una acusación aplicable automáticamente a la persona consultante."}, {"titulo": "Enseñanza principal", "texto": "La posibilidad de prosperar puede traer envidia, pero otro testimonio insiste en paciencia. La relación indebida y los honorarios de una mudanza pertenecen a relatos separados."}, {"titulo": "Relatos reunidos", "puntos": ["Amure consulta antes de buscar a la esposa de Ṣàngó.", "Ọ̀rúnmìlà se muda a casa de Olókun-Ṣande, prospera y enfrenta envidia.", "El testimonio desarrolla la espera antes de las ganancias."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Amure cita chivos y cauríes. El de Ọ̀rúnmìlà contiene dos indicaciones sucesivas con palomas, calabaza con iyèròsùn, chivos y cauríes. No se confunden."}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó aparece en el relato de Amure; Ọ̀rúnmìlà y Olókun-Ṣande en el de la mudanza. Cada figura mantiene su función."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan chivos, palomas, calabaza, cauríes y polvo iyèròsùn. El pasaje no identifica una planta medicinal ni autoriza un uso terapéutico."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de la mudanza incluye un canto sobre el polvo iyèròsùn. Se conserva con su historia y no se fusiona con el verso de Amure. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=78;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo contrapone las metas duraderas con la gratificación inmediata. Sus versos reflexionan sobre conducta, conocimiento y la alternancia de abundancia y escasez; otro testimonio pide terminar lo empezado y hablar con verdad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita una meta de largo plazo y no solo una ganancia rápida.", "Pasa por cambios incómodos que le pueden enseñar mucho.", "Pidió algo y le llegó de más; debe aprender a pedir con medida (relato de los granjeros y la lluvia).", "Piensa viajar o dejar algo a medias, y debe cumplir sus compromisos y honrar a los mayores (relato de Ẹ̀mí léńjé)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con usar responsablemente las propias capacidades. Un verso afirma que las personas pueden buscar una buena posición mediante conocimiento y conducta."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte contra expectativas irreales y conflicto. El relato de lluvias incesantes muestra que eliminar toda dificultad puede producir otro problema; no convierte las estaciones en un pronóstico meteorológico."}, {"titulo": "Enseñanza principal", "texto": "El verso de los granjeros enseña que la escasez permite apreciar la prosperidad y que lluvia y sequía tienen lugares distintos. El otro verso pone el conocimiento y la rectificación de faltas en el camino personal."}, {"titulo": "Relatos reunidos", "puntos": ["Personas y espíritus preguntan a Ọ̀rúnmìlà cómo alcanzar una buena posición antes de quedarse en el cielo.", "Los granjeros desean solo lluvia, experimentan una inundación y reconsideran su petición.", "El testimonio narra una consulta de Ẹ̀mí léńjé sobre un viaje y otra sobre honrar a los mayores."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona pescado y ẹ̀kà; el de los granjeros describe una ofrenda inicial y otra posterior, distinta. No se reproduce una lista única para ambos relatos."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza los dos versos. Odùduà y Olódùmarè son nombrados en el primero con funciones diferentes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen pescado, ẹ̀kà, chivas y cultivos de los granjeros. La alternancia entre lluvia y sequía es parte del relato, no una instrucción agrícola universal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos sobre la posición humana y los granjeros se mantienen separados de los cantos de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=79;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne un relato sobre atender heridas y otro sobre el deseo de maternidad. La ficha presenta una posible vocación de cuidado; otro testimonio añade dificultades presentes que requieren anticipación."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Trabaja en el cuidado de la salud o piensa formarse para cuidar a otros (relato de Ìrosùn y las heridas).", "Tiene una herida o dolencia que no debe descuidar.", "Desea tener hijos (relato de la mujer llamada Ìrosùn).", "Viene una etapa difícil y debe prepararse antes de que empeore (relato de Olósùn)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con trabajo constante y renovación. El verso de Ìrosùn anuncia capacidad para sanar heridas en su historia; otro termina con una protagonista que atiende el consejo sobre maternidad."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de no cuidar una herida o enfermedad. Ninguna ficha religiosa demuestra una capacidad clínica ni sustituye atención médica o formación profesional."}, {"titulo": "Enseñanza principal", "texto": "El cuidado exige acción concreta: el verso sobre heridas habla de atenderlas, y el de maternidad pertenece a otra situación. La aptitud para ayudar no justifica improvisar tratamientos."}, {"titulo": "Relatos reunidos", "puntos": ["Ìrosùn consulta sobre sanar heridas y el relato lo relaciona con una vocación sanitaria.", "Una mujer llamada Ìrosùn recibe consejo en su deseo de ser madre.", "Olósùn aparece en otro testimonio ante problemas que parecen anudados."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de heridas menciona vendaje, pescado, cauríes y medicina de Ifá. El de maternidad cita animales y cauríes distintos. El cordón de cuentas rotas pertenece al relato de otro testimonio; no se combinan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá figura como marco de consulta; la ficha no atribuye a un oricha exclusivo la capacidad de sanar."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen vendaje, pescado, murciélagos, un roedor denominado ẹ̀mọ, cauríes y cuentas. No se asume una identificación zoológica segura del término ẹ̀mọ ni se indica tratamiento médico."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos se conservan separados del relato de Olósùn. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=80;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo anuncia prosperidad y, a la vez, advierte que el bienestar puede ir seguido de disputas. Sus versos tratan la paz de una comunidad y la fortuna de otra; otro testimonio añade relaciones y ganancias compartidas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera éxito, pero teme pleitos con la familia o los amigos después.", "Un grupo necesita paz para evitar peleas internas (relato del pueblo de Alẹde Owa).", "Pregunta por un buen año para el dinero y los hijos (relato del pueblo de Ifẹ̀-Ooyẹ).", "Busca pareja (relato de Àpón Àko y Àgàn Ifẹ̀)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con apartar un conflicto y alcanzar abundancia. El verso de Ifẹ̀-Ooyẹ anuncia dinero e hijos dentro de una consulta colectiva."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte del caos si no se previene el conflicto. El verso de Alẹde Owa teme una guerra civil; se trata de una comunidad concreta en el relato, no de un anuncio literal para cada consultante."}, {"titulo": "Enseñanza principal", "texto": "La paz necesita cuidado precisamente cuando las cosas van bien. La abundancia que celebra un verso no elimina la advertencia sobre convivencia que plantea el otro."}, {"titulo": "Relatos reunidos", "puntos": ["El pueblo de Alẹde Owa consulta para conservar paz y evitar guerra interna.", "El pueblo de Ifẹ̀-Ooyẹ consulta por un año favorable para dinero e hijos.", "El testimonio relata las búsquedas de pareja de Àpón Àko y Àgàn Ifẹ̀."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita palomas, carnera, babosas y una cifra de cauríes transmitida con dos variantes. El segundo da otra lista. No se unifican."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el marco de las consultas comunitarias. Los protagonistas de otro testimonio son personas de otro relato, no entidades adjudicadas al signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan palomas, carnera, babosas y cauríes."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos comunitarios y los cantos de Àpón Àko y Àgàn Ifẹ̀ se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=81;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo valora compartir conocimiento y bienes sin perder la prudencia económica. Reúne la enseñanza de Ọ̀rúnmìlà en una ciudad, el comercio de Oyinbo y un relato de otro testimonio sobre recibir incluso un pequeño regalo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene cerca una reunión o una oportunidad de negocio (relato de Oyinbo y sus productos).", "Puede enseñar o ayudar a otros y se pregunta si aceptarán lo que sabe (relato de Ọ̀rúnmìlà en Òtù-Ifẹ̀).", "Tiene recursos, pero puede despreciar algo pequeño o invertir sin pensar (relato de Tètèrègún y la jícara)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de buena fortuna al viajar y compartir saber. Ọ̀rúnmìlà es bien recibido como maestro; el relato de Oyinbo concluye con prosperidad en sus ventas."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte del egoísmo y de invertir sin prudencia. El testimonio señala que rechazar un pequeño presente puede herir a quien lo ofrece."}, {"titulo": "Enseñanza principal", "texto": "La prosperidad de un encuentro no se mide solo por la suma obtenida. Compartir lo que se sabe y respetar aportaciones modestas sostienen la relación que hace posible el intercambio."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà viaja a Òtù-Ifẹ̀ para enseñar a convivir a personas del campo y la ciudad.", "Oyinbo consulta sobre vender sus productos y el relato termina favorablemente.", "Tètèrègún recoge agua de la riqueza de Olókun con una jícara pequeña en otro testimonio."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El viaje de Ọ̀rúnmìlà menciona kola amarga, hojas de ọgbó, plátanos y cauríes. El comercio de Oyinbo enumera sal, gallina, paloma y cauríes. No se fusionan las dos listas."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà enseña en un verso; Olókun aparece en el relato de Tètèrègún. Ambos mantienen funciones diferentes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen kola amarga, hojas llamadas ọgbó, plátanos, sal y jícara. La nota botánica del texto ofrece identificaciones distintas para ọgbó; su especie queda sin resolver."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de enseñanza y comercio se conservan separados del relato de Tètèrègún. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=82;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo llama a defender los propios derechos con firmeza y sin entrar en insultos. Un verso usa al gato como personaje que enfrenta agravios; otro testimonio advierte sobre ceder temporalmente un cargo o responsabilidad importante."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Es tímido, le cuesta imponerse o deja que otros decidan por él.", "Debe saber quién puede perjudicarlo sin acusar por simple sospecha (relato del gato Ologbo).", "Piensa ceder un puesto y luego le puede costar recuperarlo (relato de Òkèrè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con comenzar de nuevo y superar adversarios sin responder con insultos. El gato del verso se propone vencer obstáculos."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte del aislamiento si no se reconoce una hostilidad real. El relato del cargo delegado muestra el riesgo de perder control sobre una función; no se convierte en prohibición universal de delegar."}, {"titulo": "Enseñanza principal", "texto": "Hacer valer los derechos no equivale a pelear por cada agravio. El verso y otra lectura combinan la defensa propia con evitar insultos que agraven la situación."}, {"titulo": "Relatos reunidos", "puntos": ["Ologbo, el gato, consulta para superar obstáculos y agravios.", "Òkèrè recibe una posición temporal en otro testimonio y el relato cuestiona la facilidad de recuperarla."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ologbo cita cuchillos, pimienta de Guinea, cauríes y medicina de Ifá. El relato de Òkèrè tiene otra indicación; no se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece como marco de adivinación. Ologbo es el personaje animal del verso, no un oricha."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran pimienta de Guinea, cuchillos y cauríes. La pimienta aparece en una lista ritual, no como tratamiento médico."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso del gato se conserva separado del relato de Òkèrè. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=83;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo aborda obstáculos, buen carácter y el uso de remedios en un contexto religioso. Un verso habla de ofrendas y de no enviar maldad; otro presenta dos cazadores. El testimonio añade un relato sobre matrimonio y descendencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que sus asuntos no fluyen.", "Al buscar salir de un problema debe evitar la soberbia y el maltrato (relato de los dos cazadores).", "Una unión de pareja puede traer los hijos que desea (relato de Ọ̀rúnmìlà y Olósùn)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con ayudar a quienes tienen menos y quitar obstáculos. En el verso de los cazadores, uno cumple el consejo y el otro lo rechaza; otro testimonio anuncia descendencia dentro de su relato."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de conflicto por arrogancia. El primer verso previene contra hacer daño a través de mensajes atribuidos a Èṣù; no se presenta como técnica para perjudicar a otros."}, {"titulo": "Enseñanza principal", "texto": "La mejora del propio destino se vincula en los textos con carácter y ayuda. Los episodios de ofrendas, cacería y familia ilustran situaciones diferentes."}, {"titulo": "Relatos reunidos", "puntos": ["Un relato explica instrucciones de Ọlọ́run, Ọ̀rúnmìlà y Òrìṣà-nlá sobre sacrificios y conducta.", "Dos cazadores, uno de la tierra y otro del cielo, responden de manera distinta a un consejo.", "Ọ̀rúnmìlà y Olósùn aparecen en otro testimonio en una historia de descendencia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona palomas, jabón negro, osùn y cauríes; el de los cazadores da otra lista de palomas y cauríes. El relato de descendencia tiene su propio consejo. No se combinan."}, {"titulo": "Relaciones espirituales", "texto": "Ọlọ́run, Olódùmarè, Ọ̀rúnmìlà, Èṣù y Òrìṣà-nlá figuran con papeles distintos en el primer verso. Olósùn es personaje de otro testimonio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran jabón negro y osùn. El texto identifica osùn como madera roja, pero no justifica generalizar un uso medicinal ni sustituir atención sanitaria."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de conducta y cacería quedan separados del relato de Olósùn. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=84;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata la superación de obstáculos y el recuerdo de quienes ayudaron antes. El verso de Ọ̀rúnmìlà habla de vencer adversarios; otro testimonio añade una consulta sobre Orí y la elección del carácter."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente oposición a un proyecto y debe confirmar quién y cómo lo frena (relato de Ọ̀rúnmìlà ante los obstáculos).", "Busca protección y guía para una decisión importante (relato de la elección de Orí y carácter).", "No debe olvidar a quienes lo han ayudado."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con abundancia procedente de actos anteriores. El verso termina con Ọ̀rúnmìlà superando obstáculos dentro de su historia."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura menciona inquietud ligada a espíritus elementales. Ese pasaje no diagnostica una condición mental ni prueba que alguien esté conspirando contra la persona consultante."}, {"titulo": "Enseñanza principal", "texto": "El testimonio vincula la elección de Orí y del carácter con recordar el bien recibido. Esa enseñanza complementa, sin sustituir, el relato de superar adversarios."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe una indicación para superar obstáculos y enemigos.", "En otro testimonio, Ọ̀rúnmìlà va a escoger Orí y carácter en lugares diferentes."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso cita un chivo para la situación de Ọ̀rúnmìlà. El testimonio menciona un gran pez en relación con Orí. No se presentan como una sola ofrenda."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza los relatos. Orí es el centro de una consulta de otro testimonio y conserva esa función propia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen chivo y pez grande. Una imagen de hojas en la apertura del verso no basta para asignar una planta o especie al signo."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de la victoria y el relato de Orí se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=85;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne presión en los negocios, búsqueda de salud y reconocimiento, y la advertencia de no actuar sin precaución durante los viajes. Un verso habla de fama; otro emplea la imagen de una flecha que no duerme."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Trabaja mucho y su negocio le deja poco.", "Quiere que conozcan su trabajo sin perder la tranquilidad (relato de Ọ̀rúnmìlà y su nombre).", "Viaja seguido y teme que le quiten lo ganado (relato del viaje a Ìjerò).", "Tiene somnolencia o malestar y conviene revisarse (relato de Osù)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con mayor capacidad personal y fama. El primer verso anuncia reconocimiento amplio para Ọ̀rúnmìlà dentro de su historia."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de mala salud cuando se toman decisiones imprudentes. El segundo verso usa la enfermedad del sueño como amenaza narrativa; ante somnolencia persistente se necesita valoración médica."}, {"titulo": "Enseñanza principal", "texto": "El reconocimiento esperado exige cuidar también la salud y la seguridad de los viajes. La flecha en su funda es una imagen del verso, no una recomendación literal de permanecer siempre alerta."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà consulta sobre salud, paz mental y la difusión de su nombre.", "Osù recibe una advertencia relacionada con somnolencia.", "El testimonio narra un viaje de Ọ̀rúnmìlà a Ìjerò y una disputa por el dinero obtenido."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita pescado, paloma y cauríes; el segundo, flecha en funda, carnera y cauríes. El viaje de otro testimonio tiene otra indicación. No se combinan."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el primer verso y el relato de otro testimonio. Osù es personaje del segundo; no se supone que cumple la misma función que Ọ̀rúnmìlà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran pescado, paloma, carnera, flecha y cauríes. No hay en estos pasajes una planta medicinal identificada."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de reconocimiento y somnolencia permanecen separados del viaje a Ìjerò. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=86;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne una enseñanza sobre carácter y otra sobre el deseo de que los hijos sobrevivan. Son versos distintos: Ṣọ̀pọ̀nná rechaza cambiar su conducta, mientras Abimokú atiende un consejo en un relato de maternidad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme que su mal carácter le arruine el nombre y las relaciones (relato de Ṣọ̀pọ̀nná).", "Una mujer está preocupada por un embarazo o por la salud de sus hijos (relato de Abimokú, que pasa a llamarse Mọ́lá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con cuidar la salud y actuar bien en público. El relato de Abimokú termina con un cambio de nombre que celebra la supervivencia de un niño."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura menciona enfermedad de un niño aún no nacido. El verso de Ṣọ̀pọ̀nná advierte del costo social de un mal carácter. Ninguno sustituye atención prenatal o pediátrica."}, {"titulo": "Enseñanza principal", "texto": "El nombre público depende también del trato a los demás. La esperanza por los hijos es una situación aparte y no debe convertirse en promesa médica."}, {"titulo": "Relatos reunidos", "puntos": ["Ṣọ̀pọ̀nná recibe consejo para mejorar su carácter, pero rehúsa seguirlo.", "Abimokú consulta por hijos que sobrevivan y recibe el nuevo nombre Mọ́lá."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona paloma y cauríes; el segundo, tortuga y cauríes. No se unen sus indicaciones ni se proponen como tratamiento de embarazo."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà aparece en el verso sobre carácter. Ṣọ̀pọ̀nná y Abimokú son protagonistas de historias diferentes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan paloma, tortuga y cauríes. La tortuga sirve además de imagen narrativa de supervivencia; no se convierte en receta médica."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos tienen propósitos diferentes y se conservan por separado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=87;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata una tarea desagradable pero necesaria y el valor de un buen carácter. Un relato presenta a una figura enviada para cumplir una misión cuestionada por otros; otro testimonio habla de riqueza y de guardar los propios secretos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene que cumplir una obligación que no le gusta.", "Lo juzgan por una función cuyo propósito otros todavía no entienden (relato de la misión de Ìrosùn Òtúrá).", "Viene una oportunidad de dinero y le conviene ser discreto con sus planes."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con buen carácter. El testimonio habla de riqueza dentro de su propio relato y de una indicación diferente según el papel religioso de la persona."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de tratar mal una enfermedad; es una advertencia tradicional, no diagnóstico. El relato de la misión muestra las quejas contra quien la cumple, sin afirmar que toda tarea incómoda sea correcta."}, {"titulo": "Enseñanza principal", "texto": "La historia invita a distinguir el disgusto inmediato de la función que una tarea cumple para la convivencia. El buen carácter importa al llevarla a cabo."}, {"titulo": "Relatos reunidos", "puntos": ["Olódùmarè envía a Ìrosùn Òtúrá al mundo para una misión que otros cuestionan; Odùduà explica su función.", "El testimonio cuenta la consulta de Ọ̀rúnmìlà relacionada con bendiciones y discreción."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso menciona jicoteas, hojas llamadas ọgbó y cauríes. El testimonio diferencia indicaciones según sea o no babaláwo; no se mezclan con la lista del verso."}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè y Odùduà figuran con papeles distintos en el relato de la misión. Ọ̀rúnmìlà protagoniza el episodio de otro testimonio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El nombre vegetal ọgbó tiene identificaciones botánicas divergentes en la nota de la fuente, por lo que no se asigna una especie. También se nombra ñame machacado en otro testimonio."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de la misión y el relato de Ọ̀rúnmìlà permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=88;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne iniciación, liderazgo y continuidad de vida en los versos, mientras otro testimonio plantea la descendencia mediante la atención a Ifá y Òṣun. El WO de la ficha pide seguir un camino más espiritual."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere asumir liderazgo o profundizar en su práctica religiosa (relato de Ọ̀rúnmìlà iniciando en muchos lugares).", "Pregunta por una iniciación o por una vida larga.", "Quiere conservar el favor y el apoyo que ya tiene (relato de Ìrosùn e Ìrẹtẹ̀).", "Desea tener hijos (relato de Òpìnní)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con determinación y liderazgo. Un verso anuncia que Ọ̀rúnmìlà iniciará a muchas personas; otro testimonio habla de bendiciones de hijos."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable de otra lectura advierte de obstinación frente a la disciplina espiritual. Los relatos de larga vida no garantizan supervivencia ni sustituyen atención sanitaria."}, {"titulo": "Enseñanza principal", "texto": "El liderazgo religioso que describe un verso va unido a preparación y responsabilidad. El deseo de hijos de otro testimonio conserva un contexto separado."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe una predicción sobre iniciar a personas en muchos lugares.", "Ìrosùn e Ìrẹtẹ̀ consultan juntos para conservar el favor de Ọ̀rúnmìlà.", "Òpìnní ofrece a Ifá y Òṣun en otro testimonio mientras busca descendencia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita gallina, hojas tètẹ y cauríes; el segundo, chiva y cauríes. El relato de Òpìnní menciona gallina, pescado y aceite de palma. Son tres indicaciones distintas."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el primer verso; Ifá y Òṣun reciben atención en el relato de Òpìnní. Sus papeles no se fusionan."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen hojas llamadas tètẹ, gallina, chiva, pescado, aceite de palma y cauríes."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de iniciación y continuidad se conservan separados del canto de Òpìnní. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=89;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo habla de superar obstáculos mediante nuevas vías de trabajo y comercio. Un verso presenta el ejercicio de adivinación de Ọ̀ṣẹ́; otro testimonio añade relatos sobre detractores y descendencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Busca una forma nueva de llevar su negocio o su trabajo (relato de Ọ̀ṣẹ́ y su Òṣù).", "Siente que otros le frenan y debe confirmar qué está pasando antes de culpar a alguien.", "Pregunta por sus hijos (relato de Ológbò)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con abundancia y orientación espiritual. La ficha presenta mejora de negocios al aplicar técnicas nuevas; el verso sitúa la superación de enemigos en el trabajo de adivinación."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura menciona posibles molestias menstruales en la orientación desfavorable. No es un diagnóstico ni una indicación para posponer atención médica. El testimonio previene sobre conflictos con detractores."}, {"titulo": "Enseñanza principal", "texto": "La mejora no se describe como espera pasiva: el WO pide ensayar conocimientos y formas de trabajo diferentes. Los relatos de otro testimonio amplían el tema sin convertirlos en una sola situación."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀ṣẹ́ saluda al pueblo con su Òṣù y el verso explica su trabajo de adivinación.", "El testimonio narra la consulta de Ológbò sobre sus hijos y otros episodios relacionados con oposición."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ọ̀ṣẹ́ cita paloma, rata, pescado y cauríes. Las indicaciones de otro testimonio pertenecen a sus propios relatos y no se agregan a esa lista."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀ṣẹ́ protagoniza el verso; Òṣù es el objeto ritual que suena. El testimonio presenta otros personajes en narraciones independientes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen paloma, rata, pescado y un fruto de palma en una imagen de otro testimonio. No se infiere de esa imagen una especie o un remedio."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso del Òṣù y los relatos de Ológbò se mantienen diferenciados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=90;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne cuidado de la salud y la posibilidad de fortuna, mientras el WO señala el desgaste de dedicar toda la energía a un conflicto familiar o de pareja. Los versos del leopardo y de Ọ̀rúnmìlà tienen fines diferentes."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se esfuerza tanto en una relación que descuida el trabajo o el negocio.", "Tiene un riesgo de salud y no debe creerse invulnerable (relato del leopardo Ẹkùn y Ṣọ̀pọ̀nná).", "Busca recursos y bienestar después de una etapa de desgaste (relato de Ọ̀rúnmìlà y la buena fortuna)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con elevación de la cabeza y buena fortuna. Un verso anuncia prosperidad para Ọ̀rúnmìlà; no elimina la necesidad de atender la situación familiar de quien consulta."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de arrogancia que aumenta la vulnerabilidad. El leopardo del verso presume de fuerza y no cumple por entero un consejo; Ṣọ̀pọ̀nná figura como amenaza en ese relato, no como diagnóstico."}, {"titulo": "Enseñanza principal", "texto": "La confianza excesiva del leopardo ilustra el riesgo de ignorar un problema concreto. El verso de Ọ̀rúnmìlà, en cambio, trata una fortuna que se aproxima."}, {"titulo": "Relatos reunidos", "puntos": ["Ẹkùn, el leopardo, recibe una advertencia sobre Ṣọ̀pọ̀nná y solo cumple parte del consejo.", "Ọ̀rúnmìlà consulta y recibe una predicción de buena fortuna."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato del leopardo menciona aceite de palma, maíz tostado y ẹ̀kọ en recipientes; el de Ọ̀rúnmìlà, paloma y cauríes. No se combinan."}, {"titulo": "Relaciones espirituales", "texto": "Ṣọ̀pọ̀nná aparece como figura amenazante en el primer verso; Ọ̀rúnmìlà es protagonista del segundo. Orí se menciona mediante el lavado de cabeza en este último."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran aceite de palma, maíz tostado, ẹ̀kọ, recipientes, paloma y cauríes. Ningún elemento se presenta como prevención médica comprobada."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del leopardo y de la fortuna se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=91;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata confusión mental y relaciones que dificultan decidir con claridad. Sus versos presentan una limpieza ritual y una persona descrita como amarga; otro testimonio añade el respeto al linaje ancestral."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está confundido por su pareja, sus amigos o sus compañeros.", "Siente un ambiente pesado y quiere recuperar la calma (relato de Ọlọ́fin Ọbẹlejẹ).", "Lo comparan con algo amargo o lo critican (relato de Olú Oge).", "Debe tomar en cuenta a sus ancestros y su carácter al decidir."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con serenarse y despejar la confusión para abrir circunstancias mejores. El primer verso menciona la posibilidad de prosperidad después de atender su propia consulta."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable advierte de accidentes si persiste la confusión. Las imágenes de brujería o vibración negativa no establecen una causa sobrenatural de síntomas psicológicos."}, {"titulo": "Enseñanza principal", "texto": "Antes de actuar, conviene aclarar qué relación o hecho está nublando el juicio. La referencia a los ancestros de otro testimonio es una enseñanza adicional, no una explicación universal de la confusión."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlọ́fin Ọbẹlejẹ despierta con inquietud y recibe un consejo de limpiar su entorno.", "Olú Oge es comparado con hojas amargas en un segundo verso.", "El testimonio relata una consulta sobre respeto a los ancestros y buen carácter."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso describe chivo, hojas y ofrendas posteriores diferentes para prosperidad y relaciones. El segundo menciona gallos, hojas de Jogbó y cauríes. Sus indicaciones no se unen."}, {"titulo": "Relaciones espirituales", "texto": "Orí aparece en las indicaciones concretas del primer verso. Èṣù y otras entidades se conservan solo donde intervienen en los relatos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran las hojas Ọlowonran-nṣanṣan y Jogbó; no se les asigna uso terapéutico."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Ọlọ́fin y Olú Oge se mantienen separados del relato de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=92;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo insiste en la cautela. Un verso narra las consecuencias de una relación clandestina; otro advierte a un viajero agrícola sobre descuidar su seguridad. El testimonio también recomienda prudencia frente a adversarios."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está tomando una decisión apresurada en una relación (relato de Yemowó y Ajanaa-Werepe).", "Va a ir al campo o de viaje y puede pasar por alto un riesgo concreto (relato de Kuterunbe).", "Se siente rodeado de adversarios y debe actuar con prudencia antes de pelear."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con evitar un conflicto grave. La prudencia es el punto común de los versos, aunque sus personajes y riesgos son distintos."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura menciona pérdida e infidelidad. El relato de Yemowó y Ajanaa-Werepe muestra una relación clandestina; no permite acusar de infidelidad a toda persona que reciba el signo."}, {"titulo": "Enseñanza principal", "texto": "Pensar antes de actuar reduce daños que podrían venir de una relación, un viaje o una actividad en el campo. La advertencia ha de leerse con los hechos del caso."}, {"titulo": "Relatos reunidos", "puntos": ["Yemowó y Ajanaa-Werepe reciben consejos separados ante el riesgo de una relación clandestina.", "Kuterunbe viaja al campo para una fiesta anual y recibe una advertencia sobre sus semillas.", "El testimonio presenta un relato de Onígbò Asùnlólá y otro consejo de cautela."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso contiene listas separadas para Yemowó y su amante; el segundo cita semillas, gallos y cauríes."}, {"titulo": "Relaciones espirituales", "texto": "Ọbàtálá y Yemowó aparecen en el relato de pareja. Los personajes del verso agrícola tienen otra función; no se atribuyen todos a un mismo episodio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran semillas del campo, gallos, palomas y babosas. El testimonio menciona ekuru; no se infiere una receta médica o agrícola general."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de la relación y del viaje se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=93;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona trabajo, paciencia y bienestar. Un verso plantea que cultivar la tierra puede aliviar la escasez de alimentos; otro aborda una alteración emocional en un familiar. El testimonio cuenta una prosperidad que llega tras esfuerzo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Trabaja mucho sin ver resultados y necesita paciencia y un plan más claro.", "Se siente cansado, ansioso o deprimido y necesita descanso; si sigue, ayuda profesional (relato de Ojugbebikan y su esposa).", "La comida está cara o escasa y buscan cómo mejorar (relato de la gente de Ìwòrì)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con transformación mediante trabajo y preparación. El verso de los agricultores concluye con la acción de sembrar; otro testimonio habla de riqueza que otros no reconocerían al principio."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de conflicto al no prepararse. El segundo verso contiene una descripción tradicional de trastorno mental; no autoriza diagnosticar a una persona ni reemplazar atención clínica."}, {"titulo": "Enseñanza principal", "texto": "El proverbio del verso sostiene que trabajar la tierra puede reducir la miseria de una comunidad. El consejo de paciencia de otro testimonio complementa esa idea, pero no convierte el esfuerzo en garantía de riqueza."}, {"titulo": "Relatos reunidos", "puntos": ["Los habitantes de Ìwòrì consultan por el alto precio de los alimentos y reciben herramientas para cultivar.", "Ojugbebikan consulta por la condición emocional de su esposa.", "El testimonio narra una búsqueda prolongada de prosperidad."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de los agricultores menciona azadones, machetes, animales y cauríes; el de Ojugbebikan da otra lista. No se fusionan ni se presentan como tratamientos de salud mental."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece como marco de las consultas. Los agricultores y Ojugbebikan pertenecen a relatos independientes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran herramientas agrícolas, alimentos, babosas y cauríes. Ningún pasaje identifica una planta medicinal específica para los síntomas emocionales."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de agricultura y salud emocional se conservan separados de los cantos de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=94;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona honestidad, generosidad y devolución de lo ajeno con la posibilidad de prosperar. La tortuga y los cestos reciben consejos distintos; otro testimonio añade la esperanza de descendencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera que mejore un negocio que va mal.", "Tiene algo que no es suyo o duda si devolverlo (relato de los cestos y bolsos).", "Le cuesta compartir o teme perder su posición (relato de la tortuga).", "Desea hijos y reconocimiento (relato de Àlúkúlàkà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con renacimiento mediante generosidad. El verso de los cestos concluye que devolver a cada dueño lo que le pertenece favorece el bienestar."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte del daño de no devolver algo ajeno. La tortuga del otro verso teme que un asunto se vuelva contra ella; no se da por hecho que la persona consultante haya retenido bienes."}, {"titulo": "Enseñanza principal", "texto": "La confianza se construye al ser generoso y honesto con lo que pertenece a otros. Los versos expresan esa enseñanza de maneras distintas."}, {"titulo": "Relatos reunidos", "puntos": ["La tortuga escucha un consejo sobre generosidad y sobre conservar su posición.", "Cestos y bolsos reciben una indicación para ser apreciados; el relato destaca la devolución de lo ajeno.", "Àlúkúlàkà pregunta por descendencia en otro testimonio."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La tortuga recibe una lista con kola, ñame, sopa, palomas y cauríes; los cestos y bolsos, otra de palomas y cauríes. El episodio de descendencia tiene su propio consejo."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece como marco de consulta. La tortuga es protagonista de un verso y no un oricha."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran nuez de kola, ñame, sopa, palomas y cauríes. Ninguno se extrapola a una receta general del signo."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan por separado los versos de la tortuga, los cestos y bolsos, y el canto de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=95;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo concede importancia a los sueños y al carácter. El verso de Ọlawunmi muestra a una persona que consulta después de un sueño; el WO vincula las dificultades temporales con la relación con sus ancestros."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tuvo un sueño que le dejó inquietud o esperanza y quiere entenderlo (relato de Ọlawunmi y la campana).", "Busca acercarse a su tradición familiar o a sus ancestros.", "Teme que un arranque de mal carácter termine en vergüenza pública."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con atender los sueños y desarrollar buen carácter. En el verso, Ọlawunmi recibe una interpretación favorable y una predicción de honor."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de vergüenza por mal carácter. Un sueño descrito en el verso no crea una regla universal para interpretar todos los sueños de manera idéntica."}, {"titulo": "Enseñanza principal", "texto": "El protagonista no se queda con una impresión inicial: busca consejo, escucha una interpretación y actúa según la consulta. La prudencia en el carácter acompaña ese proceso."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlawunmi sueña con una campana y una sonrisa; al despertar pide adivinación y recibe un consejo.", "La ficha relaciona el contexto del sueño con atención a la energía ancestral, sin atribuir un ancestro específico al relato."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso menciona palomas, gallinas, nueces de kola y cauríes; una paloma se relaciona con la cabeza de Ọlawunmi. No se presenta esa lista como interpretación de cualquier sueño."}, {"titulo": "Relaciones espirituales", "texto": "Ifá interviene en la adivinación. Orí está presente en la atención a la cabeza dentro del verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran palomas, gallinas, kola y cauríes. Son elementos de una indicación ritual situada, no de una preparación médica."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de Ọlawunmi se conserva como testimonio individual. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=96;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo invita a buscar una solución cercana que quizá ha pasado inadvertida. Los versos desarrollan esa idea con Owa y presentan otra situación de oficio y larga vida; otro testimonio menciona bienes familiares conservados."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera un cambio y no ve que lo que necesita ya está cerca (relato de Owa).", "Pregunta por algo de su padre o por un bien antiguo de la familia (relato de Monírèrè).", "Busca un oficio o una forma de ganarse la vida (relato del pescador Dẹ̀dó)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de una bendición inesperada relacionada con esfuerzos anteriores. Owa descubre lo que buscaba cerca de sí; otro testimonio describe un bien familiar que no se habría perdido."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte del egoísmo y de no apreciar una bendición al llegar. El pasaje sobre bienes familiares no demuestra que exista una herencia concreta para toda consulta."}, {"titulo": "Enseñanza principal", "texto": "La ignorancia de lo que se tiene cerca puede impedir una solución. El verso lo dice mediante Owa; otro testimonio ofrece un caso particular de patrimonio paterno."}, {"titulo": "Relatos reunidos", "puntos": ["Owa consulta para encontrar algo cercano que no logra reconocer.", "Dẹ̀dó recibe una indicación relacionada con la pesca y la continuidad de vida.", "Monírèrè figura en un relato de otro testimonio sobre riqueza familiar."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Owa menciona gallina, cauríes y una medicina de Ifá; el de Dẹ̀dó cita hojas, carnera, paloma y cauríes. Sus listas no se combinan."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà y Olódùmarè son nombrados en el discurso del primer verso; sus funciones no se reducen a una sola figura."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan gallina, iguana, carnera, paloma y hojas llamadas pẹpẹrẹkun. La especie de esas hojas no está verificada y no se ofrece un uso médico."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Owa y Dẹ̀dó se mantienen separados del relato familiar de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=97;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo contrasta un día de aflicción con otro de alegría. Dos versos usan la misma pregunta inicial, pero presentan resultados distintos: acusaciones contra la tortuga y celebración para un ave. El testimonio agrega una advertencia familiar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Debe ver con realismo un asunto diario y separar la preocupación de los hechos.", "Teme acusaciones falsas o arrastra penas pasadas (relato de la tortuga).", "Hay motivo de alegría y de reunión (relato del ave Egaṣẹṣẹ).", "Debe respetar las prohibiciones y evitar pleitos graves entre los hijos (relato de los peces e Ìkòrò)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de nuevos comienzos al transformar penas pasadas. El verso del ave expresa alegría en su propia consulta; no borra el riesgo del relato de la tortuga."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable advierte de aislamiento si las penas no se trabajan. La tortuga subestima las acusaciones hasta que aumentan; esa historia no prueba que alguien vaya a ser acusado."}, {"titulo": "Enseñanza principal", "texto": "La misma frase sobre risa y llanto introduce dos situaciones opuestas."}, {"titulo": "Relatos reunidos", "puntos": ["La tortuga recibe una advertencia sobre falsas acusaciones y solo atiende el consejo después de agravarse el problema.", "Egaṣẹṣẹ, el ave del árbol de algodón, consulta en un día de alegría.", "El testimonio narra una consulta de peces e Ìkòrò vinculada con la familia.", "Otra explicación tradicional narra un intercambio de hábitat entre el pez y la rata tras un ataque de Ajogun, con intervención de Èṣù; es una etiología mítica, no biología evolutiva."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de la tortuga nombra efun, osùn, paloma, hojas de algodón y cauríes, con una indicación posterior diferente. El del ave cita paloma, ñame, sopa, vino de palma y cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece como marco de adivinación. La tortuga, el ave y los peces son protagonistas de relatos distintos. El relato mítico del pez y la rata atribuye la transformación a Èṣù y menciona a Ajogun como fuerza adversa."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan hojas de algodón, ñame, vino de palma, osùn y aves. No se atribuye a estos elementos una función médica general."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos de risa y llanto se conservan en versiones separadas y no se reduce su contraste a una sola predicción. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=98;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne conflictos en negocios y hogar con dos resultados distintos: un árbol resiste la oposición que lo rodea y una pareja busca crecer junta. El WO aconseja reconocer una lucha que no se puede ganar y limitar sus pérdidas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está en un pleito costoso y debe ver si le conviene seguir.", "Siente hostilidad a su alrededor y teme perder su lugar (relato del árbol Odán).", "Una pareja quiere salir adelante junta (relato de Ọ̀wọ́nrín y Egúntán)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con quitar obstáculos. El árbol odán resiste a quienes intentan doblegarlo; otra pareja asciende tras atender su consejo."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de conflicto cuando no se reconocen a tiempo los adversarios. El relato del árbol usa un monstruo como figura narrativa y no identifica enemigos reales de la persona consultante."}, {"titulo": "Enseñanza principal", "texto": "No toda disputa requiere pelear hasta el final. El WO introduce la posibilidad de reducir pérdidas, mientras los versos muestran resistencia o cooperación según su contexto."}, {"titulo": "Relatos reunidos", "puntos": ["Odán, un árbol, permanece firme frente a árboles hostiles y un monstruo.", "Ọ̀wọ́nrín y Egúntán, presentados como pareja, consultan para crecer en el mundo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso enumera rata, pescado, aceite de palma, òrí y cauríes; el segundo, paloma, carnera y cauríes. No se unen."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el marco de la consulta. Odán es personaje vegetal; Ọ̀wọ́nrín y Egúntán son protagonistas de otro relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Odán se identifica en la fuente con más de una posibilidad dentro de Ficus. También se mencionan palma, animales y cauríes."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del árbol y de la pareja se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=99;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo pide coraje ante una disputa y cautela al iniciar una relación con alguien en una situación difícil. Un verso es una afirmación de valentía; otro describe una pareja que llega desde un conflicto anterior."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Enfrenta una disputa y quiere mantenerse firme sin actuar por impulso.", "Alguien que acaba de dejar otra relación quiere entrar en su vida (relato de Ọ̀wọ́nrín).", "Debe distinguir entre ayudar por compasión y cargar obligaciones que todavía no conoce."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con abundancia, fortaleza y la posibilidad de recuperarse de una relación antigua. El verso de la valentía pide honor en la lucha."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura menciona una depresión posible tras un conflicto extremo; no es diagnóstico. El segundo verso aconseja precaución con la nueva relación sin juzgar por sí mismo a quien llega."}, {"titulo": "Enseñanza principal", "texto": "El coraje no anula la prudencia. La valentía del primer verso y el cuidado afectivo del segundo deben aplicarse a situaciones distintas."}, {"titulo": "Relatos reunidos", "puntos": ["Un canto nombra a Elégbárá, al trueno y al leopardo como imágenes de firmeza ante la lucha.", "Ọ̀wọ́nrín recibe una advertencia sobre una futura pareja que viene de otra casa."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El segundo verso cita babosa, cauríes y medicina de Ifá para su situación particular. El canto de valentía no incluye esa misma lista."}, {"titulo": "Relaciones espirituales", "texto": "Elégbárá figura en el canto; Ààrá es trueno y Ẹkùn es leopardo. No se convierten las tres referencias en una sola entidad."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen babosa, cauríes y leopardo, este último como imagen del canto. No se extrae una planta ni una preparación médica del pasaje."}, {"titulo": "Rezos, versos y cantos", "texto": "El canto de la lucha y el verso de la relación se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=100;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo valora moderación, cálculo y paciencia. Un verso relaciona el equilibrio cotidiano con abundancia; otros tratan la protección ante adversarios y el temor a un desenlace prematuro."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Debe pensar antes de actuar o de gastar (relato de Afiwon-ṣe-ohun-gbogbo y Oyinbo).", "El bienestar puede llegar poco a poco.", "Siente desprecio de otros o teme por su seguridad (relatos de Ademoorin Ayankale y de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de incremento gradual de capacidad y recursos. El primer verso presenta un personaje que evalúa comida, bebida, ropa y vivienda antes de decidir."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de conducta imprudente y pide paciencia, en especial ante asuntos de salud. El lenguaje de muerte del segundo verso es narrativo y no pronostica un desenlace clínico."}, {"titulo": "Enseñanza principal", "texto": "Calcular lo necesario antes de consumir o construir es la enseñanza del primer verso. La moderación no elimina el valor de atender una amenaza real ni el cuidado de la salud."}, {"titulo": "Relatos reunidos", "puntos": ["Afiwon-ṣe-ohun-gbogbo y Oyinbo consultan sobre mantener equilibrio en sus asuntos.", "Ademoorin Ayankale recibe una advertencia sobre un peligro grave.", "Ọ̀rúnmìlà consulta por el desprecio de otras personas durante sus viajes."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Cada uno de los tres versos trae una lista distinta de materiales."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà interviene en el tercer verso. Ifá es el marco de las otras adivinaciones; no se infiere un oricha exclusivo del signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los pasajes mencionan pimienta de Guinea, nuez de kola, semillas, hojas, animales y cauríes. Las identificaciones botánicas dudosas quedan abiertas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los tres versos se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=101;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne dos esperanzas diferentes: cuidar a los hijos y regresar con fortuna de un viaje. El testimonio añade la posibilidad de una nueva relación y de recibir bienes antes limitados."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme por un embarazo o por la salud de sus hijos (relato de Ekún-o-de-bẹ).", "Va a viajar y quiere volver bien (relato de Ọ̀rúnmìlà).", "Desea pareja y siente que las oportunidades se le han cerrado (relato de Itú)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con protección y abundancia. El verso del viaje anuncia el regreso favorable de Ọ̀rúnmìlà; otro testimonio habla de mejores circunstancias en una consulta distinta."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura menciona enfermedad de un niño aún no nacido. El verso de Ekún-o-de-bẹ trata pérdida de hijos; ante un embarazo o síntomas infantiles se necesita atención médica y no una predicción religiosa como diagnóstico."}, {"titulo": "Enseñanza principal", "texto": "El verso de Ekún-o-de-bẹ insiste en actuar ante un problema y no limitarse al lamento. El viaje de Ọ̀rúnmìlà plantea otra clase de preparación."}, {"titulo": "Relatos reunidos", "puntos": ["Ekún-o-de-bẹ consulta tras pérdidas de hijos.", "Ọ̀rúnmìlà recibe una predicción sobre el retorno de un viaje.", "Itú pregunta por la posibilidad de tener esposa en otro testimonio."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso enumera gallinas, cauríes y medicina de Ifá; el del viaje, palomas y cauríes. El episodio de Itú menciona otros materiales. No se reúnen en una sola indicación."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el verso del viaje. Itú y Ekún-o-de-bẹ pertenecen a relatos independientes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan gallinas, palomas y cauríes. No se infiere de esas listas un tratamiento para prevenir pérdidas gestacionales."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de hijos y viaje se conservan separados del relato de Itú. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=102;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo pide evitar una pelea con alguien mucho más fuerte y recuperar la confianza en una posibilidad favorable. Un verso usa al caracol frente al leopardo; otro presenta una hoja que busca mantenerse viva y verde."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere vengarse o responder a golpes a una ofensa (relato del caracol Igbin y el leopardo).", "Su rival tiene más poder y necesita otra forma de protegerse.", "Perdió la esperanza de que lleguen tiempos mejores (relato de la hoja gbégbé).", "Le faltan los medios para hacer su trabajo (relato de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con ser confiable y superar una oposición fuerte. El verso de gbégbé termina con la hoja verde dentro de su propia narración."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable advierte de decepción cuando se pierde la confianza. El caracol recibe una advertencia de no desafiar al leopardo; no se trata de identificar literalmente un enemigo animal."}, {"titulo": "Enseñanza principal", "texto": "El valor puede consistir en no entrar en una lucha desigual. El relato del caracol propone dejar de buscar revancha directa y atender otra forma de respuesta."}, {"titulo": "Relatos reunidos", "puntos": ["Igbin, el caracol, se dirige a pelear con Ẹkùn, el leopardo, y recibe consejo de prudencia.", "La hoja gbégbé consulta por su continuidad y por recibir algo bueno.", "El testimonio cuenta a Ọ̀rúnmìlà ante la falta de artículos para su práctica."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El caracol recibe una lista de tortuga y cauríes; gbégbé, otra de kola amarga y cauríes. El testimonio menciona papilla de maíz en su contexto. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ọlọ́run es invocado en el relato del caracol; Ọ̀rúnmìlà protagoniza el episodio de otro testimonio. Sus funciones son distintas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La fuente identifica gbégbé con Icacina trichantha. También aparecen kola y maíz."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del caracol y la hoja se conservan separados del relato de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=103;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo invita a revisar ideas, motivos y metas sin quedar atrapado en la desconfianza o el desprecio. Un verso trata un cargo de autoridad; otro, una provocación a alguien más poderoso; otro testimonio aborda la seguridad entre conocidos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Sospecha de otros y debe separar los hechos de sus miedos.", "Va a ocupar un cargo y debe pensar cómo ejercerlo (relato de Ọlọ́fin Iwajo).", "Puede retar o menospreciar a alguien cuya reacción no puede controlar (relato de Afi-niṣ-egan).", "Hay un peligro escondido en una relación de confianza (relato de Oníwèémò y el Gusano)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con determinación y salida de la desesperanza. El verso de Ọlọ́fin Iwajo anuncia una oportunidad de liderazgo."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de obstinación. El segundo verso muestra la consecuencia de menospreciar a otra persona. La alusión a paranoia de la ficha no constituye un diagnóstico clínico."}, {"titulo": "Enseñanza principal", "texto": "Reflexionar sobre el propio comportamiento ayuda a evitar tanto sospechas infundadas como provocaciones imprudentes. Los dos versos plantean riesgos distintos."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlọ́fin Iwajo recibe una predicción sobre un cargo y el deber de cuidar su periodo de gobierno.", "Afi-niṣ-egan desafía a Ìrẹtẹ̀ y recibe una advertencia que no atiende.", "Oníwèémò y el Gusano figuran en un relato de otro testimonio sobre confianza y peligro."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del cargo cita babosas, perro y cauríes; el del desprecio, ñame y babosas. Las indicaciones de otro testimonio son diferentes y no se fusionan."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù interviene en la advertencia del segundo verso. Ọlọ́fin Iwajo protagoniza el primero; los personajes de otro testimonio pertenecen a otra historia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen babosas, ñame, perro y cauríes. Su presencia en las listas rituales no constituye tratamiento psicológico."}, {"titulo": "Rezos, versos y cantos", "texto": "El relato del cargo, el de la provocación y el del amigo ocultamente hostil se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=104;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata acusaciones falsas, capacidad de superar oposición y salida de una etapa de escasez. Los dos versos atienden situaciones diferentes: bienestar en la casa de Ọ̀rúnmìlà y defensa de quien es acusado."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay chismes sobre su vida íntima o teme que lo juzguen injustamente.", "Debe confirmar de qué lo acusan antes de responder (relato de Ọ̀wọ́nrín acusado).", "Siente que termina una etapa de pobreza o tristeza.", "Puede llegar bienestar a su casa (verso de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con abundancia y el fin de acusaciones falsas. El segundo verso afirma la inocencia del protagonista y su posibilidad de vencer adversarios."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte que una pena prolongada puede afectar las decisiones. La existencia de un verso sobre falsa acusación no demuestra que todas las críticas contra una persona sean falsas."}, {"titulo": "Enseñanza principal", "texto": "La reputación debe evaluarse por hechos. El verso de la acusación ofrece una defensa del protagonista, mientras el relato de otro testimonio habla de dejar atrás tiempos difíciles."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe en un verso una predicción de bienestar para su casa.", "Ọ̀wọ́nrín es acusado de acciones que el segundo verso niega.", "El testimonio usa una imagen de lavarse para hablar de dejar atrás la pobreza."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita paloma y cauríes; el segundo, gallo, piedra de rayo y cauríes. El testimonio trae otra indicación. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el primer verso. Ifá aparece en el segundo junto con una piedra de rayo como objeto ritual, sin convertirla en una entidad."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen paloma, gallo, piedra de rayo y cauríes. El lavado de otro testimonio es una imagen del relato y no una indicación sanitaria."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del hogar y de la acusación permanecen separados del canto de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=105;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo pide amplitud de perspectiva y preparación ante cambios inesperados. Un verso imagina viajes por el aire y pérdidas posibles; otro anuncia que muchas personas acudirán a Ọ̀rúnmìlà. El testimonio añade asuntos familiares."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está tan fijado en una sola oportunidad que no ve las demás.", "Teme un cambio muy grande y necesita prepararse sin dramatizar (relato de la gente de Ifẹ̀-Ooyẹ).", "Quiere que su trabajo sea útil y conocido (relato de Ọ̀rúnmìlà y las visitas).", "Está mezclando el trabajo con problemas de familia."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con preparación. El segundo verso describe la casa de Ọ̀rúnmìlà llena de visitantes y una fama creciente."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable advierte de consecuencias por falta de preparación. El viaje por el aire del primer verso es una imagen de un futuro desconocido; no confirma un desastre natural inminente."}, {"titulo": "Enseñanza principal", "texto": "Mantener la mente abierta permite prepararse para varias posibilidades. La popularidad de Ọ̀rúnmìlà en otro verso muestra una oportunidad distinta de la amenaza colectiva."}, {"titulo": "Relatos reunidos", "puntos": ["La comunidad de Ifẹ̀-Ooyẹ escucha una descripción de viajes por el aire y de pérdidas posibles.", "Ọ̀rúnmìlà recibe una predicción de reconocimiento y visitas.", "El testimonio incluye un consejo de separar trabajo y conflictos de familia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso colectivo enumera materiales blancos, algodón y cauríes; el de Ọ̀rúnmìlà cita babosa, hojas de èso y cauríes. El testimonio tiene otra indicación. No se reúnen."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el verso de la fama. Ifá es el marco de la adivinación comunitaria; los papeles son distintos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El texto menciona algodón y hojas llamadas èso, además de animales y cauríes."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos sobre cambio colectivo y fama se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=106;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo vincula el poder de la palabra con la responsabilidad de escuchar un consejo. Un verso anuncia influencia pública para Eko; otro narra el conflicto entre un adivino y un cliente que desconfía de él."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Duda de un camino o de un consejo y esa desconfianza frena sus decisiones.", "Quiere que su palabra tenga peso y usarla para arreglar conflictos (relato de Eko).", "Avisó de un peligro y salió perjudicado por quien no quiso escuchar (relato de Adifala y Oṣin).", "Espera bienestar y descendencia."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con abrir camino mediante lenguaje y resolución de disputas. El verso de Eko anuncia que sus palabras serán oídas."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de arrogancia tras una decepción. El relato de Oṣin y Adifala muestra las consecuencias de rechazar y castigar al mensajero de una advertencia; no se lee como fecha de muerte para alguien actual."}, {"titulo": "Enseñanza principal", "texto": "La influencia verbal requiere escuchar además de hablar. El caso de Eko y el de Oṣin presentan dos caras de esa responsabilidad."}, {"titulo": "Relatos reunidos", "puntos": ["Eko recibe una predicción de prestigio por sus palabras.", "Adifala advierte a Oṣin de un peligro y es apresado por él; el relato continúa con un canto de advertencia.", "El testimonio presenta una lectura favorable de familia y descendencia.", "Una invocación atribuida a Ọ̀bàrà Ogbè pide que la muerte, la enfermedad y la pérdida abandonen una casa mediante el estribillo «Òwìrìwìrì». Es lenguaje ritual, no una promesa de curación."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Eko menciona carnera. El de Oṣin tiene otra lista vinculada a su advertencia. El testimonio añade su propia indicación; no se fusionan."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà figura como referencia del oficio de Adifala. Ọlọ́run y otras figuras que aparecen en los relatos mantienen funciones propias. La invocación adicional nombra a Ifá y personifica fuerzas adversas; no atribuye a una persona actual un diagnóstico."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran carnera, escoba, vasija y otros objetos de la historia de Oṣin. Su presencia narrativa no forma una receta general."}, {"titulo": "Rezos, versos y cantos", "texto": "El canto de Adifala se conserva con el relato de Oṣin y separado del verso de Eko. El estribillo «Òwìrìwìrì» pertenece a una invocación adicional del signo. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=107;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo aborda autoridad y resistencia a ella en el trabajo y el hogar. Los versos incluyen un tamborero que se niega a servir, clientes que rechazan a Ọ̀rúnmìlà y una búsqueda de pareja en otro testimonio."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un socio o compañero que quiere mandarlo todo.", "Duda entre cumplir una obligación o mantener su independencia (relato del tamborero del rey).", "Sus clientes o seguidores no reconocen su autoridad (relato de Ọ̀rúnmìlà).", "Desea encontrar pareja (relato de Ṣèkèrè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con honrar la tradición y concluir una transformación. El relato de Ṣèkèrè en otro testimonio anuncia una posibilidad favorable de pareja."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de pérdidas por no escuchar a los mayores. Los versos sobre servicio expresan una relación histórica de autoridad; no justifican someter a nadie en una relación actual."}, {"titulo": "Enseñanza principal", "texto": "La autoridad se debe evaluar junto con el respeto y los límites. El desacuerdo de un socio no es igual a los relatos tradicionales del tamborero, los clientes o Ṣèkèrè."}, {"titulo": "Relatos reunidos", "puntos": ["Un tamborero del rey declara que dejará de servir.", "Clientes de Ọ̀rúnmìlà rechazan su autoridad en otro verso.", "Ṣèkèrè consulta por la falta de esposa en otro testimonio."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del tamborero cita una gallina para Ifá. El de Ọ̀rúnmìlà menciona ratas, hojas y jabón. La consulta de Ṣèkèrè tiene otra indicación."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el verso sobre clientes. Ifá recibe una ofrenda en el primero; Ṣèkèrè es personaje de otro testimonio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen gallina, ratas, jabón y hojas."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan separados los versos sobre autoridad y el relato de pareja. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=108;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reconoce la importancia del dinero sin ponerlo por encima de sabiduría, salud y buen carácter. El verso principal debate las consecuencias de perseguir riqueza a cualquier precio; otro testimonio añade relatos de familia y vivienda."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está tomando todas sus decisiones solo por el dinero (relato del debate con Ọ̀rúnmìlà).", "Necesita cuidar su equilibrio emocional y su vida espiritual.", "Desea tener hijos o construir su casa."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con dar prioridad al buen carácter. El verso no condena el dinero: explica que puede ayudar, pero no evita por sí solo las dificultades humanas."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de avaricia y conflicto. El verso señala que la riqueza no protege de enfermedades; esa idea no es una predicción clínica."}, {"titulo": "Enseñanza principal", "texto": "La enseñanza explícita es que el carácter y la sabiduría importan más que la acumulación. Puede buscarse comodidad económica sin abandonar el juicio ni el cuidado de otras personas."}, {"titulo": "Relatos reunidos", "puntos": ["Una comunidad discute con Ọ̀rúnmìlà si el dinero es lo más importante de la vida.", "El testimonio ofrece una historia sobre descendencia y otra sobre construir casa; no son continuación del debate anterior."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso principal enumera animales, ñame, ekuru y cauríes para su situación. Los relatos de otro testimonio tienen otras indicaciones; no se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà es la voz que explica el valor relativo del dinero. Ifá se nombra como guía dentro del mismo discurso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen ñame, ekuru, pescado y animales en el verso. No se desprende de ellos una recomendación médica o botánica."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso sobre dinero se conserva separado de los cantos familiares de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=109;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata independencia e integridad ante presiones de una relación o de la comunidad. Un verso advierte sobre forasteros que pueden alterar la vida de familias; otro expresa juicios morales de su fuente sobre intercambiar sexo por dinero."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una exigencia de la pareja está desequilibrando la relación y hay que hablarla.", "Él o su comunidad temen una amenaza de fuera o una separación de familias (relato de Ọlọ́fin y los forasteros).", "Tiene un viaje posible y debe confirmar si es el momento."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con proteger a la familia y la comunidad. El testimonio deja abierta la posibilidad de viajar, con atención al momento."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de egoísmo y de situaciones en que el dinero se mezcla con la intimidad. El juicio del segundo verso pertenece a su contexto histórico; no se usa para estigmatizar ni diagnosticar a nadie."}, {"titulo": "Enseñanza principal", "texto": "Cuidar la integridad exige reconocer presiones, acuerdos y riesgos concretos. Los dos versos tratan escenarios distintos y no convierten una tensión de pareja en amenaza comunitaria."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlọ́fin recibe una advertencia sobre forasteros y familias que podrían ser llevadas a otra ciudad.", "Un grupo de mujeres recibe en otro verso una advertencia moral de su época.", "El testimonio presenta una consulta sobre si conviene emprender un viaje."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ọlọ́fin nombra aceite de palma, palomas y medicina de Ifá. El segundo trae una lista diferente con palomas, babosas y cauríes. El viaje de otro testimonio tiene su propio contexto."}, {"titulo": "Relaciones espirituales", "texto": "Ọlọ́fin protagoniza el primer verso; Èṣù recibe atención en su indicación. Las mujeres del segundo son protagonistas de otra narración."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan aceite de palma, palomas, babosas y cauríes. No se infiere una práctica válida para toda situación de pareja."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos comunitario y moral se mantienen diferenciados del relato del viaje. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=110;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo vincula estudio religioso y crecimiento espiritual con la posibilidad de prosperidad. Un verso trata la formación de un babaláwo; otro presenta una figura vegetal que desea hijos. El testimonio añade un relato propio."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que para avanzar necesita aprender y profundizar en su práctica (relato de Ọ̀bàrà Ìrosùn en la arboleda de Ifá).", "Se pregunta si debe estudiar Ifá o iniciarse.", "Desea tener hijos (relato de la hierba Esùsú)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con estudiar y recibir Ifá. El verso de la arboleda pide que el protagonista aprenda antes de asumir un papel ritual."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de resistencia a la disciplina espiritual. La iniciación no se deriva automáticamente de una síntesis ni se impone a toda persona consultante."}, {"titulo": "Enseñanza principal", "texto": "El verso mira el entorno antes de dar nombre a un hijo: las funciones y nombres se asumen con conocimiento. La formación precede a cualquier reconocimiento."}, {"titulo": "Relatos reunidos", "puntos": ["La gente encuentra a Ọ̀bàrà Ìrosùn en la arboleda de Ifá y recibe un consejo sobre aprendizaje.", "Esùsú, una hierba, consulta por descendencia.", "El testimonio presenta una lectura favorable de bienestar en otro contexto."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita ratas, peces, Òṣù y cauríes; el segundo, chiva y cauríes. El testimonio tiene su propia indicación. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el centro de la formación del primer verso. Òrìṣà-nlá figura en el segundo con una función distinta."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La fuente identifica esùsú con una hierba del género Saccharum; no se usa esa identificación como receta botánica. También aparecen ratas, peces y chiva."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de formación y descendencia se conservan separados del canto de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=111;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona serenidad con la posibilidad de prosperar. Un verso muestra a un antílope que destaca en una reunión y despierta celos; otro anuncia a Ọ̀rúnmìlà el fin de una etapa de pobreza."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita calmarse antes de decidir.", "Teme la envidia después de destacar (relato del antílope Egbin en el baile).", "Busca mejorar su economía o ser reconocido en su trabajo (relatos de Ọ̀rúnmìlà y de Yemeké)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con protección frente a cambios inesperados. El verso de Ọ̀rúnmìlà anuncia un periodo de recursos después de dificultades."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de caos por celos. El episodio del antílope usa veneno y lluvia en una explicación tradicional; no es un hecho médico sobre animales ni prueba de que alguien esté tramando daño."}, {"titulo": "Enseñanza principal", "texto": "El éxito del antílope y los celos de sus compañeros muestran que destacar puede alterar relaciones. La respuesta prudente es mantener la calma y comprobar lo que ocurre."}, {"titulo": "Relatos reunidos", "puntos": ["Egbin, el antílope, brilla en un baile y despierta la hostilidad de otros participantes.", "Ọ̀rúnmìlà consulta cuando vive dificultades económicas.", "Yemeké aparece en otro testimonio en un viaje de práctica religiosa."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del antílope cita gallinas y cauríes; el de Ọ̀rúnmìlà, paloma, sal y cauríes. El relato de Yemeké tiene indicación propia."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el verso de prosperidad. Egbin y el caballo son personajes animales del relato del baile."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran gallinas, paloma, sal y cauríes. El veneno del relato no se convierte en explicación zoológica o tratamiento."}, {"titulo": "Rezos, versos y cantos", "texto": "Los relatos del baile, la prosperidad y Yemeké permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=112;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata disputas con amigos o compañeros y el deseo de ser escuchado. Un verso advierte al ave Iwo de volverse desagradable para otras; otro usa imágenes de impedir hablar, que pertenecen a su contexto ritual."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un pleito en el trabajo o en sus relaciones (relato del ave Iwo).", "Siente que no lo escuchan o teme que lo que diga cause rechazo.", "Quiere callar las críticas, pero no por la fuerza."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con nuevas oportunidades y con el coraje de expresarse. El objetivo de mejorar una relación no se reduce a dominar la voz ajena."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de aislamiento por egoísmo. El ave Iwo rehúsa un consejo para evitar caer mal a las demás aves; el resultado de ese verso no debe generalizarse sin el relato completo."}, {"titulo": "Enseñanza principal", "texto": "El valor de hablar debe acompañarse de respeto. La imagen ritual del segundo verso no se toma como consejo para impedir que otra persona denuncie o exprese un daño."}, {"titulo": "Relatos reunidos", "puntos": ["Iwo, un ave, recibe una advertencia sobre su relación con las demás aves.", "Un segundo texto repite fórmulas sobre alguien que no logra hablar.", "El testimonio presenta otro consejo frente a adversarios."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del ave menciona un alimento, pimienta de Guinea y cauríes. El testimonio nombra hojas y una cabra en otro contexto; no se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece como marco de los relatos. El ave Iwo y Ẹlẹmbẹrun son personajes de versos distintos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran pimienta de Guinea, hojas llamadas odán y animales."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos y el relato de otro testimonio se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=113;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona reputación, chismes y negocios retrasados. Un verso habla de atraer gente a la casa de Ọlọ́fin Iwatuka; otro, de preservar el buen nombre de Olú-Iwo. El testimonio añade descanso y atención a Orí."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Los chismes le están afectando el trabajo o la relación con otros (relato de Olú-Iwo).", "Quiere recuperar su buen nombre después de un conflicto.", "Su casa o su negocio se quedó sin gente y quiere volver a llenarlo (relato de Ọlọ́fin Iwatuka).", "Necesita descanso y atender su cabeza (Orí)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con eliminar obstáculos y protegerse de chismes. El verso de Olú-Iwo termina con una afirmación de que la murmuración no dañará su nombre."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de conflicto por egoísmo y habladurías. El relato no prueba que los comentarios sobre una persona sean falsos; corresponde revisar hechos y reparar lo que proceda."}, {"titulo": "Enseñanza principal", "texto": "La reputación se protege con conducta y con la forma en que se resuelven desacuerdos. La referencia al cambio de nombre del primer verso pertenece solo a esa consulta."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlọ́fin Iwatuka pregunta cómo volver a llenar su casa de visitantes.", "Olú-Iwo recibe una advertencia sobre descrédito y continuidad de vida.", "El testimonio anuncia descanso y atención a Orí en otro episodio."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita paloma y cauríes; el segundo, carnera, tortuga y cauríes. El testimonio ofrece otra indicación. No se unen las listas."}, {"titulo": "Relaciones espirituales", "texto": "Ọlọ́fin Iwatuka y Olú-Iwo son protagonistas de versos separados. Orí figura en la lectura de otro testimonio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los relatos de este signo no nombran una planta o un elemento específico."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del hogar y de la reputación se mantienen separados del canto de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=114;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo advierte sobre clientes que no pagan y sobre errores prácticos cometidos en medio de la inquietud. Un verso trata el cobro de deudas; otro testimonio añade una consulta diferente sobre hijos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Dio mercancía o dinero a crédito y teme no recuperarlo (relato de Ẹta y el deudor).", "La angustia no le deja revisar con calma sus cuentas y acuerdos.", "Desea una familia numerosa (relato de Kànsièrè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con proteger el dinero prestado. El verso de Ẹta anuncia la posibilidad de cobrar una deuda concreta; otro testimonio habla de descendencia en otro contexto."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de pérdidas por conductas deshonestas. No se debe señalar a un cliente específico como estafador sin comprobar sus actos."}, {"titulo": "Enseñanza principal", "texto": "La prevención económica exige atender vencimientos y compromisos reales. La dimensión emocional del WO explica por qué conviene decidir con serenidad."}, {"titulo": "Relatos reunidos", "puntos": ["Ẹta consulta por una persona deudora que podría desaparecer sin pagar.", "Kànsièrè aparece en otro testimonio en un relato de descendencia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de la deuda cita paloma, gallina y cauríes; el relato de hijos tiene su indicación propia."}, {"titulo": "Relaciones espirituales", "texto": "Ifá figura en la consulta de Ẹta. Los personajes del relato de hijos pertenecen a otro episodio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹta se explica en una nota como retoño o rama tierna. También se mencionan paloma y gallina."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso del cobro y el canto de Kànsièrè se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=115;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo habla de conservar influencia y bienes sin caer en excesos. Olubolaji recibe una predicción de reconocimiento; otro verso se ocupa de vencer la oposición. El testimonio insiste en la moderación."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme perder propiedades, posición o apoyo (relato de Olubolaji).", "Pasa por dificultades temporales y busca algo que le ayude a cambiar.", "Se siente rodeado de oposición (verso de Ọ̀rúnmìlà).", "Puede estar exagerando en su búsqueda de bienestar (relato del cazador)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con capacidad personal y protección frente a pérdidas. El verso de Olubolaji anuncia estima de muchas personas."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de ignorar la oposición. El verso de Ọ̀rúnmìlà usa lenguaje de enemigos en una encantación; no identifica adversarios reales sin el caso concreto."}, {"titulo": "Enseñanza principal", "texto": "La moderación de otro testimonio permite sostener los logros. El reconocimiento y la respuesta ante oposición son asuntos distintos que requieren juicio propio."}, {"titulo": "Relatos reunidos", "puntos": ["Olubolaji consulta por conservar bienes e influencia y después canta su alegría.", "Ọ̀rúnmìlà aparece rodeado de oposición en un verso de encantación.", "El testimonio presenta a un cazador y aconseja evitar excesos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Olubolaji enumera paloma, gallina, tortuga y cauríes. El verso de encantación menciona hojas de nombres dudosos."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el segundo verso. Olubolaji es consultante del primero; no se confunden sus papeles."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen paloma, gallina, tortuga y hojas."}, {"titulo": "Rezos, versos y cantos", "texto": "El canto de Olubolaji y la encantación de Ọ̀rúnmìlà se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=116;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne relatos sobre el deseo de tener hijos y el temor a pérdidas gestacionales. El primer verso presenta una pareja sin descendencia; el segundo refleja una sociedad histórica que trataba a una mujer esclavizada como propiedad, perspectiva que no se adopta como consejo actual."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una pareja desea hijos y busca orientación (relato de Aroko y su esposa).", "Hay preocupación por un embarazo o por pérdidas anteriores.", "Una relación de pareja es difícil de llevar."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con proteger la fertilidad. El relato de Aroko termina con esperanza de descendencia; no constituye garantía clínica."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura menciona problemas de salud reproductiva. El verso de Ọlọ́fin describe pérdidas gestacionales en una mujer esclavizada; se conserva como testimonio histórico sin avalar esa explotación."}, {"titulo": "Enseñanza principal", "texto": "El deseo de descendencia debe leerse con respeto a la autonomía de las personas. Las dos historias pertenecen a contextos distintos y ninguna sustituye atención reproductiva profesional."}, {"titulo": "Relatos reunidos", "puntos": ["Aroko consulta por la falta de hijos de su esposa.", "Ọlọ́fin recibe un consejo en un relato histórico de compra de una mujer esclavizada.", "El testimonio incluye otra situación de matrimonio y dificultades de convivencia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita chiva y cauríes; el segundo, tortuga, carnera y cauríes. No se combinan ni se presentan como tratamiento de infertilidad."}, {"titulo": "Relaciones espirituales", "texto": "Ọlọ́fin es personaje del segundo verso. Ifá es el marco de las dos adivinaciones."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen chiva, tortuga, carnera y cauríes. No se deduce de ellos una terapia de embarazo."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Aroko y Ọlọ́fin se conservan separados del relato de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=117;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona respeto en el hogar, cuidado del negocio y protección ante una amenaza inesperada. Un verso refleja la compra de una mujer esclavizada en un contexto histórico; otro usa a gallinas y halcón para narrar protección."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La relación de pareja trae tensión a la casa (relato del rey que no escuchó el consejo).", "Teme que alguien cercano lo perjudique o que el chisme afecte su trabajo (relato de la gallina y el halcón).", "Busca prosperar después de probar varios caminos (relato de Gése)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de transformar la situación y vigilar los rumores del entorno laboral. El testimonio plantea que el progreso puede llegar tras una etapa estancada."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de egoísmo y de una amenaza no reconocida. La historia de la mujer comprada refleja una estructura de esclavitud y no se usa para juzgar o controlar a la pareja actual."}, {"titulo": "Enseñanza principal", "texto": "El respeto y la seguridad en el hogar no se obtienen tratando a otra persona como propiedad. El relato de las gallinas es otra imagen de protegerse ante un peligro."}, {"titulo": "Relatos reunidos", "puntos": ["Un rey recibe consejo antes de comprar a una mujer esclavizada; no atiende la advertencia.", "Una gallina doméstica y sus crías reciben una advertencia sobre un halcón.", "El testimonio presenta a Gése ante una búsqueda de prosperidad."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso contiene babosas, ñame, palomas y cauríes; el de las gallinas da otra indicación. El relato de Gése se mantiene aparte."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece como marco de los versos. El rey y los animales son personajes de episodios independientes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran ñame, babosas, palomas, gallinas y halcón. Los animales del segundo verso son personajes, no una receta general."}, {"titulo": "Rezos, versos y cantos", "texto": "Los tres relatos conservan contextos separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=118;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo presenta buenas perspectivas de trabajo o negocio y la posibilidad de sostener lo conseguido. Los versos hablan de fortuna para Ọ̀rúnmìlà y de evitar que decaiga una comunidad fundada por Akintẹlu."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa en un empleo o negocio nuevo.", "Busca estabilidad después de un avance reciente (relato de Akintẹlu y la villa que fundó).", "Puede venir buena fortuna si evita grandes problemas (versos de Ọ̀rúnmìlà).", "Busca pareja."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con determinación y acercamiento a la fortuna. El verso de Ọ̀rúnmìlà dice que la bendición reservada para él se aproxima."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de obstinación nacida de una decepción. La expectativa laboral del WO es una posibilidad de la lectura, no una oferta garantizada."}, {"titulo": "Enseñanza principal", "texto": "La estabilidad requiere mantener lo construido. El relato de Akintẹlu trata una comunidad que no debe decaer, distinta de la prosperidad personal de Ọ̀rúnmìlà."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe en un verso una predicción de buena fortuna y en otro una indicación para evitar grandes dificultades.", "Akintẹlu consulta por la villa que fundó.", "El testimonio presenta una búsqueda de pareja."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los tres versos ofrecen listas diferentes de paloma, babosas, tela, carnera y cauríes según cada caso. No se combinan con el relato de pareja."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza dos versos; Akintẹlu es fundador en el tercero. Ifá aparece en la referencia a la formación del primer protagonista."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen paloma, babosas, carnera, tela blanca y cauríes. No se infiere de ellos una medicina general."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Ọ̀rúnmìlà y Akintẹlu se conservan separados del canto de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=119;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne una petición de no sufrir innecesariamente y un canto sobre la lluvia. El testimonio añade paz en asuntos de familia y pareja. La imagen de detener la lluvia pertenece al verso, no a una capacidad física demostrada."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Carga un peso familiar o emocional que quiere aliviar.", "Quiere proteger una actividad o algo valioso (relato de Ọ̀rúnmìlà y la prenda bajo la lluvia).", "Hay un asunto de relación o de matrimonio."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con recuperarse de problemas familiares y hallar abundancia. El testimonio describe una posibilidad de paz."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de orgullo falso nacido de baja autoestima. El verso que pide no sufrir recuerda una experiencia de maltrato; no se debe trivializar una situación actual de violencia."}, {"titulo": "Enseñanza principal", "texto": "La súplica del primer verso pide cuidado para quien ha sufrido. El canto de la lluvia cumple otra función y no debe confundirse con una promesa de controlar el clima."}, {"titulo": "Relatos reunidos", "puntos": ["Una voz pregunta por sus padres y pide a Ọ̀bàrà Ọ̀ṣẹ́ evitar sufrimiento innecesario.", "Ọ̀rúnmìlà recibe un canto para que la lluvia no moje una prenda.", "El testimonio cuenta una consulta vinculada con una relación."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El canto de la lluvia no trae la misma lista ritual que el relato de otro testimonio."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el canto de la lluvia. La voz del primer verso se conserva como personaje diferente."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan lluvia, ropa y posibles hojas en el primer verso."}, {"titulo": "Rezos, versos y cantos", "texto": "La súplica familiar y el canto de la lluvia se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=120;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo anuncia posibilidades económicas en trabajo, inversión o comercio. Sus versos contienen un canto sobre abundancia y dos consultas distintas de fortuna; otro testimonio advierte a un babaláwo que preste atención a su entorno."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa empezar un trabajo o una empresa.", "Busca recursos después de muchos problemas (relato de Bara Àgbọnnìrègún).", "Puede llegarle una oportunidad de lejos (relato de Tẹwogbolá).", "Puede estar desatendiendo a la gente que lo rodea."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con resolver dificultades gracias a una abundancia inesperada. El canto repite la imagen de dinero imposible de contar."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de desesperación al sentirse abrumado. La promesa de dinero de un verso no garantiza una inversión concreta ni sustituye un análisis financiero."}, {"titulo": "Enseñanza principal", "texto": "La oportunidad se presenta de formas diferentes: visitantes que buscan a Ọ̀rúnmìlà, un pájaro que trae fortuna a Tẹwogbolá y el canto de abundancia. No son una sola predicción."}, {"titulo": "Relatos reunidos", "puntos": ["Bara Àgbọnnìrègún recibe un canto que celebra dinero.", "Ọ̀rúnmìlà consulta por buenas cosas durante su vida.", "Tẹwogbolá espera una fortuna procedente de tierras lejanas."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El segundo verso cita tela, paloma, gallina y cauríes blancos; el tercero, palomas, gallina y cauríes. El primer canto no se transforma en esa misma lista."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà y Bara Àgbọnnìrègún se relacionan en los textos, mientras Tẹwogbolá es protagonista de otro verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El maíz aparece como imagen de abundancia en el canto. También se nombran paloma, gallina y tela; no se propone una planta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los tres versos se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=121;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo presenta una nueva responsabilidad que puede abrir camino a reconocimiento. Dos versos sobre Olitikun separan la superación de adversarios de su nombramiento como portavoz del rey."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Ve venir un empleo, un ascenso o un aumento, pero todavía no está confirmado.", "Se prepara para un puesto con obligaciones nuevas (relato de Olitikun nombrado Tẹ̀wíṣé).", "Quiere destacar ante sus competidores sin creer que todos son enemigos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con asumir responsabilidades y obtener una oportunidad. El segundo verso termina con Olitikun instalado como portavoz del Ewí."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de arrogancia al rechazar una función nueva. La presencia de rivales en un relato no prueba hostilidad de todos los competidores actuales."}, {"titulo": "Enseñanza principal", "texto": "La promoción lleva consigo una tarea concreta: hablar en nombre de otra autoridad. El éxito del puesto se distingue de la victoria sobre opositores del primer verso."}, {"titulo": "Relatos reunidos", "puntos": ["Olitikun consulta por una oposición y recibe un consejo para superarla.", "En otro verso del mismo personaje se narra su nombramiento como Tẹ̀wíṣé.", "El testimonio presenta a Ológun Ìṣèṣè en una lectura favorable distinta."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona tortas de frijol, chivo y cauríes; el segundo, gallos y cauríes. Sus listas no se fusionan."}, {"titulo": "Relaciones espirituales", "texto": "Olitikun protagoniza ambos versos y el Ewí es el rey al que se vincula su cargo. Ológun Ìṣèṣè pertenece al relato de otro testimonio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran frijol, chivo, gallos y cauríes. No se infiere una preparación médica o botánica."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos de Olitikun y el testimonio de otro testimonio permanecen diferenciados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=122;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo contrasta la estabilidad material con las pérdidas que puede causar un conflicto. Un verso narra una guerra que llega a otra comunidad; el segundo usa imágenes de riqueza y comodidad doméstica."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Toma riesgos sin aprender de lo que les pasó a otros.", "Teme que un pleito se extienda a su familia o a su proyecto (relato de Igbeyin-Odo y la casa de Itori).", "Busca bienestar económico y apoyo de sus antepasados.", "Pregunta por un hermano."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con evitar conflicto. El segundo verso anuncia comodidad dentro de una consulta favorable."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de violencia si un conflicto crece. El relato de la guerra es una historia de comunidades y no prueba una amenaza bélica actual para la persona consultante."}, {"titulo": "Enseñanza principal", "texto": "Aprender de errores ajenos puede evitar pérdidas propias. El primer verso muestra cómo un daño que ocurrió en un lugar alcanza a otro."}, {"titulo": "Relatos reunidos", "puntos": ["Igbeyin-Odo y la casa de Itori reciben consejos antes de que la guerra se extienda.", "Otro verso presenta a Ọ̀kànràn Ọ̀yẹ̀kú hablando de riqueza y comodidad.", "El testimonio narra una consulta por un hermano."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de la guerra cita gallos y cauríes; el de la riqueza, babosas y cauríes. Se mantienen separados."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece como marco de ambas adivinaciones. El WO menciona trabajo con ancestros, sin identificar una entidad exclusiva."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran gallos, babosas, aceite de palma y agua como elementos de los versos. No se deduce una preparación médica."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos y el relato de otro testimonio conservan contextos diferentes. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=123;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo propone hablar de los problemas para encontrar ayuda. Un verso presenta a un lagarto que calla y no recibe apoyo; otro anuncia el regreso de una persona esperada. El testimonio añade un relato sobre colaboración."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se guarda sus preocupaciones por miedo a contarlas (relato del lagarto Alaamu).", "Espera a alguien que puede traer noticias o bienestar (relato de Moyebo).", "Una colaboración está parada por falta de comunicación (relato del Día y la Lluvia)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con identificar el origen de una dificultad y pedir asistencia. El verso de Moyebo termina con la expectativa de su regreso."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de conflicto cuando nadie comunica lo que necesita. El retraso de un viajero en un verso no garantiza la llegada de cualquier persona esperada."}, {"titulo": "Enseñanza principal", "texto": "El silencio del lagarto ilustra cómo una necesidad desconocida no puede recibir apoyo. Expresar el problema con claridad es la enseñanza central."}, {"titulo": "Relatos reunidos", "puntos": ["Alaamu, el lagarto, rehúsa hablar de sus problemas.", "La familia de Moyebo espera su retorno de un viaje.", "El testimonio presenta al Día y la Lluvia en una tarea compartida."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del lagarto cita chivo, gallo, paloma y cauríes; el de Moyebo, gallina, paloma, langosta y cauríes. No se combinan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el marco de las dos consultas. El lagarto, Moyebo, el Día y la Lluvia son personajes de relatos distintos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran palma como árbol del relato, aves, chivo y langosta. El árbol no se convierte en un remedio botánico."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso del lagarto y el de Moyebo se conservan separados del testimonio de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=124;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo abre la posibilidad de retomar una relación o colaboración antigua. El verso principal cuenta cómo Ọ̀rúnmìlà y Ẹhìnmọlá cambian de circunstancias con el tiempo; otro testimonio habla de vida y salud en otro pasaje."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una oportunidad de amor o de trabajo que no se dio puede volver (relato de Ọ̀rúnmìlà y Ẹhìnmọlá).", "Se impacienta porque la otra persona no responde como quisiera.", "Debe ver si la relación respeta lo que quieren los dos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con una nueva dirección y con controlar el enojo. El verso presenta un cambio de opinión de Ẹhìnmọlá después de un periodo de separación."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de actuar sin madurez. El relato de cortejo contiene juicios históricos sobre rechazo y maldición que no justifican presión ni castigo contra quien no desea una relación."}, {"titulo": "Enseñanza principal", "texto": "La paciencia sirve para escuchar, no para esperar que otra persona pierda autonomía. Si una relación se reabre, debe ser por acuerdo libre de ambas partes."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe consejo durante su interés por Ẹhìnmọlá; el relato continúa tras un año.", "El testimonio presenta un testimonio diferente sobre salud y continuidad de vida."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ọ̀rúnmìlà menciona paloma, cauríes y medicina de Ifá. El testimonio ofrece una indicación distinta y no se funde con la historia de pareja."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà y Ẹhìnmọlá son protagonistas del verso; otras deidades aparecen como pretendientes dentro de esa historia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran paloma y cauríes. No se extrae una planta o tratamiento de la historia de cortejo."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de la pareja y el relato de otro testimonio permanecen separados."}]$q$::jsonb where numero=125;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo advierte de palabras o actos irresponsables que bloquean el progreso, pero también plantea la posibilidad de pedir perdón. Un verso habla de gallina y pollitos; otro afirma que disculparse por un daño puede abrir una salida."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene pleitos con su pareja o sus hijos.", "Se arrepiente de algo que dijo o hizo y necesita disculparse.", "Quiere moverse con libertad sin que un problema del pasado le estorbe (relato de la gallina y sus pollitos).", "Hay un conflicto amoroso (relato de Bàtá y Koko)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con perdón y un nuevo rumbo. El segundo verso presenta la disculpa sincera como condición para superar el conflicto."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable advierte de aislamiento por mala conducta. El lenguaje de brujas o hechiceros del verso pertenece a la narración y no prueba una causa sobrenatural en un caso real."}, {"titulo": "Enseñanza principal", "texto": "El verso expresa que un daño intencional no es bueno y que quien se disculpa puede ser perdonado. Reparar el daño exige más que pronunciar una fórmula."}, {"titulo": "Relatos reunidos", "puntos": ["Una gallina y sus pollitos consultan para seguir desplazándose sin impedimentos.", "Un personaje rechazado por otros recibe consejo sobre disculparse.", "El testimonio narra un conflicto afectivo vinculado con Bàtá y Koko."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de la gallina cita Òṣù, rata, pescado y cauríes; el del perdón, palomas, carnera, kola y cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù y Olódùmarè aparecen con papeles distintos en el verso del perdón. Ṣàngó figura en el relato de otro testimonio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan kola, aves, rata y pescado. No se deduce una receta medicinal de estas listas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de movilidad y disculpa se conservan separados del relato de Bàtá. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=126;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata consecuencias de actos injustos y conflictos ante una autoridad. Un verso describe un proceso judicial; otro insiste en que hacer daño a otros acaba por exigir reparación."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Enfrenta un problema legal o de trámites (relato de Ọ̀kànràn y el juicio).", "Siente ganas de desobedecer o menospreciar una obligación.", "Debe reparar lo que dañó antes de que el conflicto crezca (relato del grupo que presumía de hacer daño)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con ayudar a quien tiene menos y comenzar de nuevo. El verso del proceso presenta una posibilidad de reposo para su protagonista."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de caos al no apreciar lo que se tiene. Los versos mencionan juicio y castigo en su contexto religioso, pero no predicen una sentencia ni reemplazan asesoría jurídica."}, {"titulo": "Enseñanza principal", "texto": "El segundo verso sostiene que un daño puede tardar en mostrar sus consecuencias, pero no desaparece por ello. Reparar a otros importa más que confiar en que la falta pase inadvertida."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀kànràn enfrenta un proceso judicial y recibe una advertencia.", "Un grupo presume de hacer daño sin consecuencias; Ọ̀rúnmìlà responde que deberá reparar los perjuicios.", "El testimonio presenta otro relato sobre habitantes y visitantes de una tierra."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita paloma, carnera y cauríes; el segundo, babosas, aceite de palma y cauríes. No se mezclan ni se presentan como solución legal."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà interviene en el segundo verso como voz que advierte sobre reparación. El proceso del primero tiene otro protagonista."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen paloma, carnera, babosas y aceite de palma. Su mención no equivale a consejo jurídico o médico."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos judicial y moral se conservan separados del testimonio de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=127;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne vida larga, protección del hogar y tensiones familiares. Dos episodios del mismo verso distinguen a Ọlaṣoni, que pregunta por su salud, de Ọla-Ogún, que teme un rayo en su casa."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene conflictos con sus hijos o con sus padres (relato de Ọlaṣoni).", "Le preocupa la seguridad de su casa ante una tormenta (relato de Ọla-Ogún y el rayo).", "Espera bienestar en la pareja y con los hijos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con protegerse de acusaciones injustas. El testimonio anuncia bienes y familia en su contexto particular."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de amargura frente a alegaciones falsas. La historia del rayo no es un pronóstico meteorológico: ante tormentas corresponde tomar medidas materiales de seguridad."}, {"titulo": "Enseñanza principal", "texto": "Cuidar el hogar incluye atender las relaciones entre generaciones y los riesgos reales del entorno. Los episodios de salud y de tormenta no deben fundirse."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlaṣoni recibe un consejo sobre vida larga y no lo atiende.", "Ọla-Ogún consulta por el riesgo de que un rayo alcance su casa.", "El testimonio incluye una lectura favorable sobre pareja e hijos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La indicación de Ọlaṣoni nombra carnera y cauríes; la de Ọla-Ogún enumera otros animales, aceite de palma, plátanos y cauríes. Son listas de casos diferentes."}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó se menciona en el episodio del trueno. Ifá es el marco de ambas consultas y no se confunden sus funciones."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran plátanos, aceite de palma, carnera y babosa. Estos elementos del relato no sustituyen protección física contra tormentas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los episodios de Ọlaṣoni y Ọla-Ogún se conservan separados de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=128;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona nuevos comienzos con prudencia. Un relato sitúa a los irúnmọlẹ̀ ante el envío de bienes a la Tierra; otro celebra la fuerza de Ògún, en un lenguaje de combate que pertenece a su época."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa empezar un negocio o una relación nueva (relato de los irúnmọlẹ̀ que traen bienes a la Tierra).", "Quiere quitar obstáculos sin entrar en una pelea innecesaria (relato de Ogún-gbèmi).", "Un niño o joven cuenta experiencias espirituales y hay que escucharlo con cuidado.", "Busca prosperidad y una vida larga."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura habla de abrir camino y atender una experiencia espiritual según la tradición. El testimonio anuncia bienes y continuidad dentro de su relato."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura menciona conflicto y problemas de salud mental si se maneja mal una experiencia. No se diagnostica ni se indica iniciación como sustituto de una evaluación clínica cuando haga falta."}, {"titulo": "Enseñanza principal", "texto": "El relato de fuerza no autoriza violencia. La prudencia del WO pide considerar los efectos de una nueva dirección antes de actuar."}, {"titulo": "Relatos reunidos", "puntos": ["Los irúnmọlẹ̀ reciben una tarea vinculada con llevar bienes a la Tierra.", "Ogún-gbèmi recibe un discurso de combate y resistencia.", "El testimonio presenta una lectura de prosperidad y larga vida."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de los irúnmọlẹ̀ enumera alimentos y animales. El segundo verso tiene otra lista."}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè y los irúnmọlẹ̀ aparecen en el primer relato. Ògún se nombra en el segundo; sus papeles no se fusionan."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran ñame, kola, aves y otros alimentos."}, {"titulo": "Rezos, versos y cantos", "texto": "Los relatos del envío a la Tierra y del combate se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=129;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo enseña a reconocer cuándo retirarse de una lucha. Un verso contrasta pelear con esquivar; otro muestra que herramientas y esfuerzo humano actúan juntos. El WO aplica la prudencia a la relación de pareja."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay un pleito de pareja que necesita una salida en paz.", "Su oponente es más fuerte y debe saber cuándo hacerse a un lado (relato de Akinṣuyi).", "Quiere hacer algo y olvida la colaboración que hay detrás (relato del elefante y las herramientas).", "Debe decidir cómo defenderse (relato del halcón)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con abundancia al saber retirarse ante una oposición abrumadora. El testimonio anuncia que una oportunidad puede conservarse con prudencia."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de aislamiento por falta de claridad. El primer verso dice que quien solo sabe combatir puede ser vencido; no se trata de exigir que alguien permanezca en una relación peligrosa."}, {"titulo": "Enseñanza principal", "texto": "El respeto puede requerir esquivar una pelea, no ganarla. El segundo verso añade que ningún instrumento hace el trabajo por sí solo: hay acción humana detrás."}, {"titulo": "Relatos reunidos", "puntos": ["Akinṣuyi recibe consejo sobre ser respetado y saber evitar ciertas luchas.", "El elefante y los seres humanos figuran en un verso sobre herramientas, fuerza y protección.", "El testimonio presenta al halcón ante una decisión de defensa."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita guinea y cauríes; el del elefante contiene otra indicación. No se combinan con el episodio del halcón."}, {"titulo": "Relaciones espirituales", "texto": "Ọlọ́run es nombrado en el verso de herramientas. Akinṣuyi y el elefante son protagonistas de relatos diferentes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan azadón, hacha, machete, ñame y animales. Las herramientas son imágenes de trabajo y no recetas rituales universales."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Akinṣuyi y del elefante se conservan separados del relato del halcón. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=130;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne valor y honestidad frente a las dificultades. Un verso presenta a la tortuga en una lucha; otro usa una roca para hablar de verdad y permanencia. El testimonio añade la idea de actuar dentro de las propias capacidades."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Debe mantener lo que cree sin perder la honestidad (relato de la roca Àpáta).", "Enfrenta oposición y debe distinguir entre firmeza e imprudencia (relato de la tortuga Ìjapá).", "No debe aceptar una tarea para la que todavía no tiene medios (relato del halcón)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con fortalecer la capacidad personal y aceptar aspectos buenos y difíciles de la vida. La tortuga del primer verso recibe una predicción de respeto."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de mirar un problema desde un solo ángulo. El lenguaje del verso sobre sobrevivir a una pelea es narrativo, no una garantía de invulnerabilidad."}, {"titulo": "Enseñanza principal", "texto": "El valor se sostiene mejor con verdad y juicio. La roca del segundo verso sirve como imagen de estabilidad; no convierte una creencia en hecho físico."}, {"titulo": "Relatos reunidos", "puntos": ["La tortuga consulta por una disputa y recibe el nombre Ìjapá en el relato.", "Àpáta, una roca, figura en un verso sobre honestidad y permanencia.", "El testimonio presenta a un halcón y otra enseñanza sobre no exceder la propia fuerza."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita carnero y cauríes."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà y Edùmarè son nombrados en el discurso del verso de la roca. La tortuga y el halcón pertenecen a otros relatos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan carnero, roca y pastos como imágenes narrativas. No se identifica una planta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de la tortuga y la roca se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=131;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo valora aprender antes de poner a prueba a otra persona. Su relato principal presenta a Ọ̀rúnmìlà identificando lo oculto en una calabaza y a Osányin sufriendo una lesión después de desatender una advertencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["No le cuenta todo al adivino para ponerlo a prueba (relato de Olódùmarè y la calabaza).", "Piensa viajar y debe revisar para qué y cuándo.", "Se arriesga sin escuchar un consejo y, aun así, puede encontrar su oficio (relato de Osányin)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con dejar atrás tristeza y cuidar la salud. El relato termina con Osányin dedicándose a hierbas después de recibir ayuda de Ọ̀rúnmìlà; no prueba eficacia clínica de remedios específicos."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de amargura y enfermedad. La lesión de Osányin es un episodio del relato, no un pronóstico para quien tenga este signo."}, {"titulo": "Enseñanza principal", "texto": "El verso dice que se conoce un camino al recorrerlo y que el estudio permite comprender Ifá. La arrogancia al desafiar o probar a otros puede ocultar información útil."}, {"titulo": "Relatos reunidos", "puntos": ["Olódùmarè oculta algo en una calabaza; Ọ̀rúnmìlà consulta e identifica su contenido.", "Osányin insiste en acompañarlo, se lesiona y después encuentra un oficio como herbolario.", "El testimonio aconseja pensar antes de emprender un viaje."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato principal menciona perro y chiva en una indicación a Olódùmarè. El consejo de viaje de otro testimonio es diferente; no se combinan."}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè plantea la prueba, Ọ̀rúnmìlà consulta y Osányin participa con consecuencias propias. Sus funciones se distinguen."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen calabaza, algodón, animales y hierbas no identificadas individualmente. No se deduce una fórmula terapéutica de la expresión «medicinas de Ifá»."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conserva el relato largo de la calabaza separado del consejo de viaje. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=132;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata disputas familiares por posesiones y la posibilidad de preservar vínculos. Un verso advierte contra responder a cada ofensa con otra; otro muestra a una familia de serpientes que pierde armonía."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pelea con su familia por bienes materiales (relato de Olukoya).", "Una amistad o sociedad se está rompiendo por venganzas de ida y vuelta (relato del líder de las serpientes).", "Debe cuidar lo que dice (relato de Enu, la Boca)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con resolver disputas familiares. El verso de Olukoya propone prevenir que una pelea dañe la relación."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de aislamiento y decepción si la disputa consume a la familia. El verso de serpientes no justifica usar armas o venenos contra nadie."}, {"titulo": "Enseñanza principal", "texto": "La lógica de «me haces, te hago» mantiene abierta la pelea. Buscar una forma de detenerla es la enseñanza expresa del primer verso."}, {"titulo": "Relatos reunidos", "puntos": ["Olukoya consulta por una pelea con su familia.", "El líder de las serpientes recibe una advertencia sobre conservar la unidad y no la atiende.", "El testimonio presenta a Enu, la Boca, en una consulta sobre su función."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Olukoya cita gallinas, aceite de palma y cauríes; el de las serpientes nombra objetos peligrosos, chiva y cauríes. No se combinan ni se transforman en instrucciones para hacer daño."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el marco de los versos. Enu y el líder de las serpientes son personajes de relatos distintos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan gallinas, aceite de palma, chiva y objetos del relato de serpientes. No se infiere un remedio medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Olukoya y las serpientes se conservan separados del relato de Enu. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=133;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo habla de formación y crecimiento espiritual. El verso principal presenta a Eniayewu ante la posibilidad de iniciarse en Ifá; otro testimonio añade un relato de Irù y su aprendizaje."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Busca crecer en lo espiritual y pregunta qué formación necesita (relato de Eniayewu).", "Cree que debe resolverlo todo solo y le cuesta pedir ayuda.", "Una persona joven aprende y sigue consejo (relato de Irù, hijo de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con determinación, humildad y atención a los ancestros. El verso de Eniayewu describe la iniciación como posibilidad dentro de su consulta."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de obstinación cuando se pretende manejar todos los problemas sin ayuda. La ficha no convierte una recomendación de iniciación de un verso en mandato automático para cualquiera."}, {"titulo": "Enseñanza principal", "texto": "Crecer implica reconocer límites y buscar enseñanza. La decisión ritual concreta debe hacerse con guía competente y contexto, no con una síntesis general."}, {"titulo": "Relatos reunidos", "puntos": ["Eniayewu recibe un consejo de iniciación en Ifá.", "Irù, hijo de Ọ̀rúnmìlà, aparece en un relato de otro testimonio sobre inteligencia y aprendizaje."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Eniayewu enumera palomas, rata, pescado y cauríes. El testimonio tiene otra indicación; no se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es centro de la formación del primer verso. Ọ̀rúnmìlà es padre de Irù en el relato de otro testimonio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan palomas, rata, pescado y cauríes. No se presenta una preparación médica o botánica."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de Eniayewu se conserva separado del relato de Irù. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=134;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo aborda angustia y retrasos financieros. Un verso pregunta qué cuenta como tribulación; otro invoca a Edùmarè en medio de la pena. El testimonio presenta a Òṣun en una consulta de bienestar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pasa por contratiempos económicos.", "Siente tristeza o arrepentimiento por una decisión que tomó por miedo a perder.", "Busca apoyo espiritual sin descuidar una enfermedad o necesidad concreta.", "Puede pasar de la pobreza a la alegría (relato de Òṣun)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con superar la tristeza y abrir una oportunidad de abundancia. El testimonio habla de una lectura favorable relacionada con Òṣun."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de avaricia nacida del temor. El primer verso menciona enfermedad crónica como ejemplo de tribulación; no diagnostica a quien consulta."}, {"titulo": "Enseñanza principal", "texto": "Nombrar la aflicción ayuda a diferenciar enfermedad, encierro y carencia. La invocación del segundo verso ofrece consuelo religioso, sin sustituir ayuda práctica o sanitaria."}, {"titulo": "Relatos reunidos", "puntos": ["El hijo de una persona próspera pregunta repetidamente qué es una tribulación.", "Una voz invoca a Edùmarè para recordar la vida y la satisfacción.", "Òṣun aparece en un relato de otro testimonio sobre pobreza y alegría."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita tela, paloma, carnera, gallina y cauríes; el segundo nombra paloma, iguana y cauríes. El testimonio tiene indicación propia."}, {"titulo": "Relaciones espirituales", "texto": "Edùmarè y Ọ̀rúnmìlà figuran en la invocación del segundo verso. Òṣun pertenece al relato de otro testimonio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan aves, carnera, iguana y tela. No se deduce un tratamiento de enfermedad crónica."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de tribulación e invocación se mantienen separados del relato de Òṣun. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=135;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo presenta la salida de una etapa de angustia y la posibilidad de una relación nueva o renovada. Un verso habla del amor buscado por Ọ̀kànràn-Abaṣẹwolu; otro, de alivio para Ọ̀kànràn y Òfún."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere empezar una relación o mejorar la que tiene (relato de Ọ̀kànràn-Abaṣẹwolu).", "Busca salir de una mala racha sin perder la esperanza.", "Teme el desprestigio (relato de Títílolá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con optimismo y un cambio favorable. El segundo verso anuncia a sus protagonistas apoyo frente a un sufrimiento súbito."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable menciona depresión cuando la mala fortuna se prolonga; no es un diagnóstico. El optimismo tampoco sustituye ayuda profesional si existe sufrimiento persistente."}, {"titulo": "Enseñanza principal", "texto": "La esperanza puede acompañarse de acciones concretas. Los relatos de pareja y de alivio son posibilidades distintas y no se atribuyen automáticamente a una misma persona."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀kànràn-Abaṣẹwolu consulta por encontrar una pareja que le corresponda.", "Ọ̀kànràn y Òfún reciben un consejo frente al sufrimiento repentino.", "El testimonio presenta a Títílolá ante el temor al descrédito."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de la pareja cita paloma, gallina y cauríes; el de alivio, carnero y cauríes. No se unen con la indicación de otro testimonio."}, {"titulo": "Relaciones espirituales", "texto": "Orí se invoca mediante la cabeza en el primer verso. Ọ̀kànràn y Òfún son protagonistas del segundo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan paloma, gallina, carnero y un gran árbol de algodón como imagen del verso. No se propone un uso medicinal del árbol."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de pareja y alivio se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=136;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo valora honestidad e integridad frente a la mentira y la envidia. Un verso contrapone verdad y falsedad; otro es una invocación de dinero, pareja e hijos. Su primera narración incluye una generalización despectiva sobre musulmanes que pertenece al texto y no se acepta como hecho. Una oración independiente desarrolla el agradecimiento por los bienes recibidos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Duda de que alguien le esté diciendo la verdad.", "Teme que los rumores o la envidia tapen su esfuerzo (verso de la mentira que corre y la verdad que se queda).", "Pide dinero, pareja e hijos.", "Debe agradecer lo que ya ha recibido."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con despejar obstáculos diciendo la verdad. El segundo verso pide que lleguen recursos y familia dentro de una fórmula de bendición."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de arrogancia y decepciones. El pasaje hostil hacia una comunidad religiosa no debe usarse para juzgar a sus miembros ni para atribuirles una conducta."}, {"titulo": "Enseñanza principal", "texto": "La afirmación central es que una mentira no se sostiene como la verdad. El buen carácter requiere aplicar esa regla también al modo en que se habla de otras personas. La oración de gratitud añade que recibir bienestar implica reconocerlo."}, {"titulo": "Relatos reunidos", "puntos": ["Un verso compara la larga marcha de la mentira con la permanencia de la verdad e incluye una polémica religiosa de su época.", "Otro texto pide dinero, pareja e hijos por medio de una invocación.", "Una fórmula de agradecimiento presenta a los hijos de distintos seres que no expresan gratitud, frente a los humanos que sí lo hacen."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las indicaciones rituales del primer verso quedan en su propio contexto. La invocación del segundo no se convierte en la misma lista de ofrendas."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù interviene en la narración polémica; Edùmarè y Olódùmarè se nombran como referentes de verdad dentro del verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombra ñame y otros alimentos en los textos. Ninguno se presenta como preparación médica."}, {"titulo": "Rezos, versos y cantos", "texto": "El relato de verdad y la invocación de buena fortuna se conservan separados. El yorùbá y el pasaje polémico requieren lectura contextual. También hay una oración de gratitud que aparece en dos lugares del mismo libro; se cuenta como un solo pasaje."}]$q$::jsonb where numero=137;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona buena voluntad con comodidad y prosperidad. Tètèrègún lleva el agua de la riqueza a Olókun; otro personaje consulta para no depender de otros. El WO menciona apoyo ancestral ante dificultades."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita apoyo para salir de un obstáculo.", "Puede ayudar a alguien y recibir a cambio una relación favorable (relato de Tètèrègún llevando agua a Olókun).", "Teme depender del dinero de otros (relato de Ẹnú-ọnà-ilé)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con apartar obstáculos y atender a Olókun en un contexto de abundancia. El relato de Tètèrègún termina con una bendición de bienestar."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de pérdidas si la agresión destruye vínculos familiares o amistades. El agua de la riqueza es imagen del relato, no garantía monetaria literal."}, {"titulo": "Enseñanza principal", "texto": "La generosidad de transportar algo valioso para otro sostiene la reciprocidad del primer verso. El segundo pone el foco en evitar la necesidad permanente."}, {"titulo": "Relatos reunidos", "puntos": ["Tètèrègún lleva agua a Olókun y recibe una bendición de comodidad.", "Ẹnú-ọnà-ilé consulta para no vivir en pobreza o dependencia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Tètèrègún menciona orí, babosas y cauríes; el otro, palomas y cauríes. Sus listas no se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Olókun recibe el agua de Tètèrègún. Los ancestros aparecen en el WO como apoyo, sin una entidad individual identificada."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tètèrègún figura como personaje vegetal. También se nombran agua, babosas y palomas."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de Tètèrègún incluye un canto propio; se conserva separado del segundo relato. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=138;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo presenta un relato de agitación intensa y amenazas con armas, interpretadas por la fuente en lenguaje espiritual. Ọ̀rúnmìlà interviene para atender a Ògún. El WO pide una purificación espiritual dentro de esa tradición."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Él o alguien cercano está muy alterado y puede volverse peligroso (relato de Ògún enojado).", "Siente un ambiente hostil o tiene cerca a una persona que lo amenaza.", "Piensa viajar para buscar mejores oportunidades."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con un viaje que puede abrir otra situación. El relato de Ògún termina con una promesa tradicional de atención, no con una prueba de cura clínica."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de conflictos que se multiplican. Si alguien amenaza con cuchillo o machete, la prioridad es la seguridad y la ayuda de emergencia; el signo no sustituye atención médica o psicológica."}, {"titulo": "Enseñanza principal", "texto": "El verso contrapone fuerza y sabiduría: pide ser tan firme como Ògún y tan prudente como Ifá. No avala acercarse sin protección a una persona armada."}, {"titulo": "Relatos reunidos", "puntos": ["Ògún aparece agitado y amenazando a otros; un grupo consulta a Ọ̀rúnmìlà.", "Ọ̀rúnmìlà da una respuesta ritual y ofrece atención al personaje del relato."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso menciona babosa, chiva, cauríes y medicina de Ifá. No se presenta como tratamiento clínico de agitación o violencia."}, {"titulo": "Relaciones espirituales", "texto": "Ògún es el personaje central; Ọ̀rúnmìlà consulta Ifá. Irókò aparece como árbol en una comparación del verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan Irókò, babosa y chiva. La mención del árbol no identifica una preparación medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "El único verso de la ficha se conserva en su contexto. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=139;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne un viaje favorable en el relato de Ògún y una imagen de goteo o fuga en el de una calabaza. La ficha también menciona molestias intestinales y sangrado durante el embarazo como advertencias de su fuente."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se prepara para un viaje y quiere volver bien (relato de Ògún y su equipaje).", "Tiene una molestia digestiva o una pérdida de líquido que conviene revisar con un médico (relato de la calabaza nueva con fuga).", "Si hay sangrado en un embarazo, debe ir al médico de inmediato."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con viaje seguro. El verso de Ògún anuncia regreso con bienestar después de prepararse."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura menciona malestar de estómago. Un relato afirma que un sacrificio curaría un problema obstétrico; esto no sustituye la atención médica."}, {"titulo": "Enseñanza principal", "texto": "Prepararse para un viaje y reconocer a tiempo un síntoma son acciones distintas. El relato de la calabaza usa una fuga como imagen y no diagnostica una enfermedad."}, {"titulo": "Relatos reunidos", "puntos": ["Ògún prepara su equipaje y recibe una predicción de viaje favorable.", "Kèrègbe titun, una calabaza nueva, recibe una advertencia sobre una fuga en su base."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del viaje cita gallo, aceite de palma, kola y cauríes."}, {"titulo": "Relaciones espirituales", "texto": "Ògún protagoniza el viaje; Ọ̀rúnmìlà anuncia su resultado. La calabaza es personaje de otro verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen kola, aceite de palma, gallo y calabaza. No se infiere de ellos tratamiento intestinal u obstétrico."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del viaje y la calabaza permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=140;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo presenta la posibilidad de dejar atrás una etapa difícil. Un verso repite que termina la maldición y menciona pobreza, pareja, hijos y salud; otro trata la búsqueda de una esposa desaparecida."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere empezar un negocio o una relación después de una etapa difícil.", "Siente que la mala racha puede terminar (relato de Àgùtàn, la carnera).", "Busca a alguien que se alejó (relato de Ọ̀rúnmìlà y la esposa ausente)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con transformar una mala racha en mejores circunstancias. El primer verso enumera varias formas de bienestar en una secuencia de celebración."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable advierte de resistencia a una perspectiva más esperanzadora. El canto sobre sanar no garantiza recuperación médica ni que todos sus beneficios lleguen juntos."}, {"titulo": "Enseñanza principal", "texto": "La repetición del fin de la maldición afirma que un estado doloroso no define para siempre a una persona. La búsqueda de la pareja es un relato aparte."}, {"titulo": "Relatos reunidos", "puntos": ["Àgùtàn, la carnera, recibe un verso sobre el final de una etapa de dificultades.", "Ọ̀rúnmìlà consulta por una esposa ausente en otra historia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso enumera paloma, kola, pimienta de Guinea y cauríes. El segundo cita rata, camarón, babosa y cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ògún es nombrado en la apertura del verso de la búsqueda; Ọ̀rúnmìlà es protagonista de esa consulta."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan kola, pimienta de Guinea, camarón y animales. No constituyen un tratamiento médico por aparecer en el canto."}, {"titulo": "Rezos, versos y cantos", "texto": "El canto sobre el fin de las dificultades y el verso de la búsqueda se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=141;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo aborda envidia surgida tras un logro y la necesidad de tratar un conflicto pendiente. Un verso atribuye hostilidad a quienes no trabajan; otro usa imágenes de combate y victoria."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está evitando una conversación difícil que ya no puede aplazar.", "Siente celos o percibe envidia después de un logro (verso de Ògún sobre trabajo y envidia).", "Debe distinguir una crítica de una amenaza real antes de enfrentarse."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con soltar la envidia y protegerse de cambios inesperados. El esfuerzo reconocido del primer verso es una imagen de logro."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de caos si se conserva el resentimiento. El primer verso desea destrucción a los rivales; no se adopta esa violencia como consejo actual."}, {"titulo": "Enseñanza principal", "texto": "El conflicto puede abordarse con claridad sin convertir a la otra parte en enemigo absoluto. El WO pide enfrentarlo, pero no exige violencia."}, {"titulo": "Relatos reunidos", "puntos": ["Ògún escucha un verso sobre trabajo y envidia de quienes no se esforzaron.", "Un segundo canto invoca honor en una lucha mediante imágenes de leopardo y trueno."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita un cántaro, carnero y cauríes. El segundo presenta un encantamiento y dos preparaciones rituales distintas para una disputa; sus ingredientes son propios de ese verso. No se combinan ni se convierten en instrucciones contra terceros."}, {"titulo": "Relaciones espirituales", "texto": "Ògún protagoniza el primer verso. El leopardo y el trueno son imágenes de fuerza del segundo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen cántaro, carnero y cauríes."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso sobre envidia y el encantamiento de combate se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=142;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo distingue una relación intensa pero frágil de una disputa entre los mismos personajes. Los versos de Ògún y Ọ̀bàrà no se combinan: uno trata matrimonio; el otro, evitar que una lucha termine con una muerte."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le atrae una relación que quizá no tiene bases para durar (relato de Ògún y Ọ̀bàrà).", "Un pleito de pareja se está poniendo agresivo.", "Necesita hablar el conflicto sin querer controlar a la otra persona."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con prepararse y quitar obstáculos. La expectativa favorable no garantiza que una pareja permanezca unida."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable advierte de egoísmo e impreparación. El verso de la lucha menciona muerte; ante violencia real se debe buscar seguridad y ayuda, no tratarlo como escena inevitable."}, {"titulo": "Enseñanza principal", "texto": "La fascinación de Ògún por Ọ̀bàrà no reemplaza el consentimiento ni el trabajo de una relación. En el segundo verso, el cuidado central es impedir un daño grave."}, {"titulo": "Relatos reunidos", "puntos": ["Ògún consulta antes de unirse con Ọ̀bàrà.", "Ògún recibe otra advertencia antes de enfrentarla en una lucha."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de matrimonio menciona gallina, gallinero y cauríes; el de la lucha, hojas secas, cestos, gallinas y cauríes. No se funden."}, {"titulo": "Relaciones espirituales", "texto": "Ògún y Ọ̀bàrà son personajes de ambos versos, pero con circunstancias distintas. Ifá es el marco de la consulta."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran gallinas, hojas secas y cestos. No hay especie vegetal identificada ni remedio."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de matrimonio y confrontación permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=143;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo propone emplear capacidad intelectual, acción y guía espiritual para salir de un trabajo estancado. Egúngún consulta por un negocio incompleto; manos y pies actúan juntos en el segundo verso."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa cambiar de trabajo.", "Su negocio no deja lo que esperaba y debe corregirlo (relato de Egúngún).", "Busca el apoyo de sus ancestros antes de una decisión importante."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con nuevas oportunidades y atención a los ancestros. El verso de Egúngún anuncia el fin de una etapa de sufrimiento."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de perder oportunidades si se permanece inmóvil. La imagen de manos y pies no garantiza éxito laboral sin acciones concretas."}, {"titulo": "Enseñanza principal", "texto": "Manos y pies simbolizan cooperación entre lo que se sabe y lo que se hace. El cambio de trabajo del WO necesita esa combinación."}, {"titulo": "Relatos reunidos", "puntos": ["Egúngún recibe consejo ante un negocio poco rentable.", "Manos y pies son consultantes de otro verso sobre fortuna en la Tierra."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona kola y un látigo ritual; el segundo, carnera. No se combinan las dos listas."}, {"titulo": "Relaciones espirituales", "texto": "Egúngún aparece en el primer verso y en la referencia a ancestros del iré. Las manos y pies son imágenes del segundo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran nueces de kola, carnera y un cesto. No se infiere una planta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Egúngún y manos y pies se mantienen diferenciados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=144;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona dedicación sostenida con recursos y reputación. Un verso imagina a Ifá escogiendo el dinero como pareja; otro habla del carácter de un recién nacido."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Trabaja muy duro y espera ganar más (relato de Ifá que escoge el dinero).", "Debe mantener el rumbo sin descuidar a su gente ni su ánimo.", "Le preocupa cómo se formará el carácter de un niño (relato del recién nacido)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con abundancia y reconocimiento mediante constancia. El verso de Ifá sitúa el dinero como compañero simbólico, no como único valor."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de enojo o tristeza si el conflicto consume la atención. No es diagnóstico de depresión ni garantía de fortuna por trabajar sin descanso."}, {"titulo": "Enseñanza principal", "texto": "El esfuerzo puede rendir frutos, pero el verso compara el valor del dinero con la fuerza de Ifá. El relato del niño recuerda la importancia de la conducta."}, {"titulo": "Relatos reunidos", "puntos": ["Ifá es descrito como solitario y escoge el dinero en una imagen de pareja.", "Un recién nacido recibe una predicción sobre su crecimiento y carácter."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita paloma y cauríes; el del recién nacido, guinea, paloma y cauríes. Son indicaciones separadas."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es protagonista simbólico del primer verso. El recién nacido pertenece a otra consulta."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen paloma, guinea y cauríes. No se identifica una planta o alimento de uso medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=145;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo advierte de acusaciones en el trabajo y del valor de la honestidad para proteger la reputación. Otro verso presenta descanso y recuperación ante dificultades económicas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene una acusación o un pleito con compañeros de trabajo.", "Teme que lo confundan con quien robó (relato de Omotade).", "Está cansado y debe descansar antes de decidir sobre dinero (relato de Alade)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con despejar obstáculos actuando con honestidad. El segundo verso anuncia que el dinero puede llegar tras una pausa."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte que la deshonestidad puede salir a la luz. El primer verso no prueba que la persona acusada sea culpable: pide distinguir hechos y reputación."}, {"titulo": "Enseñanza principal", "texto": "La integridad y el descanso responden a problemas diferentes. Cuidar el nombre no exige tomar decisiones agotado."}, {"titulo": "Relatos reunidos", "puntos": ["Omotade recibe consejo para no ser contado entre ladrones.", "Ọ̀rúnmìlà aparece en un relato donde Alade está rodeado de dificultades y recibe consejo de descansar."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona gallinas, rata, pescado, aceite de palma y cauríes; el segundo, palomas y cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà se nombra en ambos versos con funciones distintas; Omotade y Alade pertenecen a historias diferentes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran aves, rata, pescado y aceite de palma. Ningún elemento equivale a consejo médico para el agotamiento."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de reputación y descanso se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=146;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona buen carácter, paz comunitaria y prosperidad. Un verso habla de dinero e hijos para Ifẹ̀-Ooyẹ; otro usa el dolor del árbol Irókò para narrar reconciliación entre Ògún y Òtúrúpọ̀n."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere que bajen las dificultades y está dispuesto a mejorar su conducta.", "Un grupo tiene oportunidades, pero debe evitar pleitos internos (relato de la gente de Ifẹ̀-Ooyẹ).", "Un desacuerdo se calmaría si alguien cambia su forma de actuar (relato de Ògún, Òtúrúpọ̀n y el Irókò)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con despejar obstáculos y conservar paz. Los dos versos presentan resultados favorables en situaciones diferentes."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable menciona dolor de pecho y enfermedad. El relato del Irókò usa dolor como imagen; ante dolor torácico real corresponde atención médica urgente."}, {"titulo": "Enseñanza principal", "texto": "El segundo verso condiciona el fin del daño a mantener buen carácter. La fortuna comunitaria del primero también requiere convivencia."}, {"titulo": "Relatos reunidos", "puntos": ["La gente de Ifẹ̀-Ooyẹ recibe una predicción de abundancia y un consejo para evitar litigios.", "Ògún y Òtúrúpọ̀n aparecen en un relato con el Irókò y un cambio de conducta."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso enumera palomas, gallinas y cauríes; el segundo, perro, aceite de palma, gallo y cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ògún y Òtúrúpọ̀n son personajes del segundo verso. Ifá aparece en las consultas de ambos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Irókò es el árbol del relato, no una receta médica. También se nombran aceite de palma y animales."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de la comunidad y del Irókò se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=147;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne preocupación por la salud y una invocación sobre Orí frente a la oposición. El primer verso presenta a Ọta-Omi con miedo a enfermar; el segundo usa un lenguaje agresivo contra enemigos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme enfermarse o perder estabilidad; conviene revisar los síntomas con un médico (relato de Ọta-Omi).", "Está bajo mucha presión y culpa a otros de parte de ella.", "Quiere ir hacia algo nuevo sin que el miedo lo paralice."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con transformación y movimiento hacia una oportunidad. El verso de Ọta-Omi concluye con estabilidad dentro del relato."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte que el temor puede agravar una dificultad. La ficha llama hipocondría a la preocupación, pero esta síntesis no establece un diagnóstico; el segundo verso tampoco autoriza daño a terceros."}, {"titulo": "Enseñanza principal", "texto": "El temor a perder salud puede atenderse con evaluación y calma. La invocación a Orí expresa otra dimensión tradicional sin demostrar que un adversario cause una enfermedad."}, {"titulo": "Relatos reunidos", "puntos": ["Ọta-Omi consulta por temor a enfermar y por mantener su lugar.", "Un canto invoca a Orí y usa imágenes de enemigos y plantas que caen."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita babosa, paloma, cauríes y medicina de Ifá. El canto no se transforma en esa misma ofrenda ni en instrucción para perjudicar a otros."}, {"titulo": "Relaciones espirituales", "texto": "Orí es el centro del segundo verso; Ọta-Omi protagoniza el primero. Sus funciones no se mezclan."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan babosa, paloma y una planta llamada egbee en una imagen del canto."}, {"titulo": "Rezos, versos y cantos", "texto": "El relato de salud y el canto de Orí se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=148;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne el papel de Elégbárá como mensajero de ofrendas y un relato sobre verdad y un ritual de Egúngún. El segundo refleja una disputa histórica de poder entre hombres y mujeres; no se adopta como regla para relaciones actuales."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere saber cómo se hace o se entrega una ofrenda (relato de Elégbárá y Ọ̀rúnmìlà).", "Debe actuar con honestidad en una disputa.", "Siente presión o control en una relación y debe mirar la conducta real, no prejuicios."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con determinación y sinceridad. El segundo verso contrapone la agitación de mentir con la calma de decir verdad."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de obstinación después de una decepción. La historia de control ritual por género no justifica dominar ni excluir a nadie."}, {"titulo": "Enseñanza principal", "texto": "La honestidad es la enseñanza expresa del segundo verso. El primero pregunta cómo reconocer la aceptación de una ofrenda y describe la función mensajera de Elégbárá."}, {"titulo": "Relatos reunidos", "puntos": ["Elégbárá conversa con Ọ̀rúnmìlà sobre transportar ofrendas.", "Ògún interviene en un relato sobre verdad y sobre el origen de un ritual de Egúngún."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las indicaciones de Elégbárá y Ògún pertenecen a versos diferentes."}, {"titulo": "Relaciones espirituales", "texto": "Elégbárá aparece como mensajero en el primer verso. Egúngún se relaciona con ancestros en el segundo; Ògún tiene otra función narrativa."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran soga para palma, gallo y objetos del ritual."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos se conservan separados. La traducción histórica sobre género y el yorùbá necesitan lectura contextual."}]$q$::jsonb where numero=149;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo afirma que no se debe castigar a alguien por sus características físicas. El verso de Olówo pide honor y trato justo; el WO describe a una persona que sigue su propio ritmo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente juzgado por su apariencia o su forma de ser.", "Quieren imponerle una regla que no evita ningún daño real.", "Necesita defender su dignidad sin faltar al respeto a los demás (relato de Olówo)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con actuar honradamente y alcanzar abundancia. El verso termina pidiendo reconocimiento y respeto."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de confusión y falta de honor. Ningún pasaje autoriza castigar a alguien por una característica corporal."}, {"titulo": "Enseñanza principal", "texto": "La enseñanza es explícita: honrar a una persona por quien es y por lo que hace, no convertir un rasgo físico en motivo de sanción."}, {"titulo": "Relatos reunidos", "puntos": ["Olówo recibe un consejo para no ser castigado injustamente.", "El verso compara el valor de un árbol con el trato debido a una persona de albinismo, dentro de su lenguaje tradicional."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso menciona paloma, carnera y cauríes en el caso de Olówo. No se convierte en una regla ritual para todos los casos de discriminación."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el marco de la consulta. La mención de un òrìṣà en la comparación del verso no lo establece como entidad exclusiva del signo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran paloma, carnera y un árbol como comparación moral; no se identifica una especie vegetal ni un uso médico."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conserva el verso de Olówo con su mensaje de respeto. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=150;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo aborda propiedad, herencia y el daño de ocultar una disputa. Un verso exige devolver lo ajeno; otro relata cómo un saco de cuentas provoca engaños entre hermanos y tentación de robo para un rey."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay un reparto de herencia o un pleito por bienes.", "Los hijos sienten que no los trataron igual (relato de los dos hermanos y las cuentas).", "Alguien guarda un conflicto en secreto y así no se puede resolver.", "Teme que quien lo hospeda o lo guarda se quede con lo suyo (relato del viajero y el casero)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con sacar el problema a la luz. El viajero del primer verso busca recuperar sus pertenencias."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de daño personal y comunitario cuando se oculta la disputa. La historia no decide la propiedad legal de ningún bien actual; requiere comprobar documentos y acuerdos."}, {"titulo": "Enseñanza principal", "texto": "Devolver lo que pertenece a otros evita que la disputa crezca. El segundo relato muestra cómo apropiaciones sucesivas y mentiras convierten un reparto en peligro."}, {"titulo": "Relatos reunidos", "puntos": ["Un viajero se hospeda con un casero codicioso y teme que le robe sus cosas.", "Dos hermanos esconden cuentas heredadas; uno engaña al otro y el rey piensa quedarse con el saco."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita gallina y cauríes; el segundo, paloma y cauríes en otro contexto. No se mezclan ni sustituyen una solución jurídica."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece en las consultas de ambos versos. Los hermanos, el rey y el viajero pertenecen a escenas distintas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan cuentas, saco y una calabaza usada para ocultarlas. Las notas botánicas del segundo verso ofrecen nombres de plantas, pero no quedan ligadas de modo claro a una preparación de la ficha."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos y la historia explicativa de las cuentas se conservan juntos solo donde pertenecen al mismo relato. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=151;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo invita a detenerse para apreciar lo logrado y no arriesgarlo todo por objetivos pasajeros. Un verso repite que Ọ̀sá apoya a quienes vienen de él; otro muestra ofrendas realizadas sin tiempo de aprovecharlas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está arriesgando algo duradero por una ganancia rápida (relato de Atiba y Atimumu).", "Necesita recuperar el equilibrio y valorar lo que ya logró.", "Hay una oportunidad que depende de seguir el consejo al pie de la letra."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura relaciona el iré con apertura y crecimiento espiritual. El primer verso expresa apoyo mediante una fórmula repetida."}, {"titulo": "Ibi y advertencias", "texto": "La orientación desfavorable advierte de engañarse a sí mismo. Las imágenes de animales que no llegan a consumirse cuestionan la prisa, sin imponer una conclusión única a toda consulta."}, {"titulo": "Enseñanza principal", "texto": "La urgencia no siempre crea progreso. El segundo verso recuerda que adquirir o sacrificar algo sin tiempo para usarlo puede vaciarlo de sentido."}, {"titulo": "Relatos reunidos", "puntos": ["Una fórmula dice que Ọ̀sá apoya a la rata, al pez y a quienes proceden de él.", "Atiba y Atimumu realizan actos que no alcanzan a aprovechar.", "El testimonio contiene otro relato de oportunidad y comunidad."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El segundo verso menciona aceite de palma para Èṣù en su propio altar. El primero no trae esa misma indicación; no se construye un ẹbọ general."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù Òdàrà recibe atención en el segundo verso. Ọ̀sá es el signo nombrado en la fórmula de apoyo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran rata, pez, perro, carnero, chivo y aceite de palma en distintas imágenes. No se extrae una receta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "La fórmula de apoyo y el verso sobre la prisa permanecen separados del relato de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=152;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo contrapone caminos estrechos y anchos con ramas expuestas a una tormenta. La ficha también menciona incertidumbre legal, laboral o comercial, y otro testimonio contiene una lectura favorable."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un trámite o una decisión de trabajo incierta.", "Se siente bloqueado mientras busca una salida (relato de los caminos estrecho y ancho).", "Teme que un cambio repentino sacuda su casa o su trabajo (relato de las ramas y el viento)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura asocia el iré con sostener una disciplina espiritual. El verso de los caminos habla de continuidad; otro testimonio anuncia bienestar en una consulta diferente."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de pérdida ante un giro repentino. El relato de ramas y tornado es una imagen de vulnerabilidad, no una predicción meteorológica específica."}, {"titulo": "Enseñanza principal", "texto": "Un camino puede prolongarse aunque sea estrecho; una rama puede necesitar preparación ante un cambio brusco. Los dos versos expresan tiempos y riesgos distintos."}, {"titulo": "Relatos reunidos", "puntos": ["Onàtóóró y Onàgboorò, caminos estrecho y ancho, reciben un consejo de continuidad.", "Las ramas de los árboles reciben una advertencia sobre viento fuerte.", "El testimonio menciona una lectura favorable y una ofrenda de èkuru."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita paloma, carnera y cauríes; el segundo, tortuga, paloma y cauríes. El èkuru de otro testimonio pertenece a otro relato."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las dos consultas. Los caminos y ramas son personajes figurativos, no orichas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan ramas, árboles, aves y èkuru. No se asigna una especie vegetal al relato del tornado."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de caminos y ramas se mantienen separados del testimonio de otro testimonio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=153;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo anuncia una oportunidad económica y explica en otro relato la posición protegida del buitre. Ajétunmobi recibe noticias de fortuna procedente del mar; Igún evita que otros lo maten al llegar su caso ante Olódùmarè."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera los frutos de un esfuerzo largo (relato de Ajétunmobi).", "Teme que otros quieran quitarle un puesto o un beneficio.", "Necesita protección frente a quien se le opone (relato del buitre Igún)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Otra lectura vincula el iré con riqueza inesperada asociada con trabajo o creatividad. El verso de Ajétunmobi anuncia recursos procedentes del mar y la laguna."}, {"titulo": "Ibi y advertencias", "texto": "Otra lectura advierte de conflicto al desatender una prohibición. El peligro del buitre pertenece a una historia de origen y no prueba una conspiración actual."}, {"titulo": "Enseñanza principal", "texto": "El relato de Igún muestra que su ofrenda llega al cielo por una cadena de mensajeros y decisiones. La fortuna de Ajétunmobi es un relato separado."}, {"titulo": "Relatos reunidos", "puntos": ["Ajétunmobi pregunta por el resultado de sus esfuerzos y recibe una predicción económica.", "Igún, el buitre, es protegido cuando Ọmo lleva sus obi a Olódùmarè y Èṣù interviene.", "El testimonio contiene otra consulta sobre oposición."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Ajétunmobi recibe una lista de carnera, palomas, plátanos y cauríes. Igún ofrece kola, carnera y cauríes. No se mezclan las dos situaciones."}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè decide sobre Igún; Ọmo actúa como mensajero y Èṣù interviene. El buitre es protagonista de esa historia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran plátanos pequeños, kola y animales. El fruto del verso se conserva como alimento narrado, no como remedio general."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de prosperidad y de Igún permanecen diferenciados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=154;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata obstáculos en un camino personal y la posibilidad de abrir una relación o una etapa nueva. Un relato presenta la dificultad de avanzar; otro, la llegada de alguien esperado y una noticia favorable."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que sus esfuerzos no avanzan y el camino se le cierra.", "Llega alguien nuevo y no sabe cómo saldrá esa relación.", "Espera una visita o una noticia que puede cambiar sus planes."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable propone escuchar una opinión inesperada y reconsiderar la dirección que se sigue. Un verso celebra la llegada de la persona aguardada."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de cambios bruscos y decisiones arbitrarias. No se debe convertir una posibilidad de conflicto en un diagnóstico de una relación concreta."}, {"titulo": "Enseñanza principal", "texto": "Abrir el camino también exige escuchar y decidir con cuidado. La llegada de una noticia no resuelve por sí sola los obstáculos del otro relato."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀sá pregunta por un camino que se le presenta cerrado.", "Una comunidad se prepara para recibir a alguien que había esperado."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del camino menciona lámpara de barro, aceite de palma y cauríes. El de la llegada nombra kola, kola amarga, pimienta de Guinea, ginebra, vino de palma y cauríes para su propia celebración. Las listas no se fusionan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá da consejo en las consultas. Los personajes y la comunidad de los versos no se convierten en entidades espirituales adicionales."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran aceite de palma, kola, kola amarga, pimienta de Guinea y vino de palma. Son elementos de escenas distintas; no se propone una preparación medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=155;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne una búsqueda de paz y recursos con la necesidad de avanzar sin agotarse. Alágemo se mueve con cautela; otro verso consulta por riqueza."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay un cambio repentino en su casa o en su trabajo.", "Trabaja con terquedad y necesita descansar.", "Busca seguridad económica sin romper la paz en casa (relatos de Alágemo y de Eeka-Alajé)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La interpretación favorable habla de descansar, disfrutar los resultados y reconocer que el esfuerzo no exige tensión permanente. Un verso atribuye riqueza a Eeka-Alajé."}, {"titulo": "Ibi y advertencias", "texto": "La interpretación desfavorable describe rigidez y trabajo sin pausa. El relato de Alágemo muestra cautela, no una orden de aceptar cualquier situación."}, {"titulo": "Enseñanza principal", "texto": "La prudencia y el descanso pueden acompañar el progreso. Los relatos de paz y riqueza responden a preguntas distintas."}, {"titulo": "Relatos reunidos", "puntos": ["Alágemo avanza con cautela y procura conservar la paz.", "Eeka-Alajé consulta por recursos y recibe una respuesta favorable."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Alágemo menciona aceite de palma, manteca de cacao, pescado y cauríes. El de Eeka-Alajé cita gallinas y cauríes. Cada lista pertenece a su consulta."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las dos consultas. Alágemo y Eeka-Alajé son protagonistas de relatos diferentes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen aceite de palma, manteca de cacao y pescado en un verso; gallinas en otro. No se infiere un tratamiento de salud."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Alágemo y Eeka-Alajé se conservan separados."}]$q$::jsonb where numero=156;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona la reputación con el carácter y las responsabilidades. Una voz rechaza públicamente acusaciones; el perro Aṣolé busca ser aceptado por su conducta."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente avergonzado o acusado y cree que huir lo resolverá.", "Necesita aclarar públicamente que no hizo lo que le achacan.", "Un cambio en una relación le está resultando incómodo.", "Tiene obligaciones de trabajo o de familia que no puede descuidar."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable propone tomar distancia de un problema para poder verlo con humor y buscar protección. El relato de Aṣolé muestra la posibilidad de reconocimiento."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que renunciar a toda responsabilidad o intentar controlarlo todo puede empeorar un conflicto. Las acusaciones del verso no se atribuyen a la persona consultante."}, {"titulo": "Enseñanza principal", "texto": "La respuesta ante una crítica debe apoyarse en la conducta comprobable, no solo en escapar de la vergüenza. El relato de Aṣolé presenta aceptación tras una prueba de carácter."}, {"titulo": "Relatos reunidos", "puntos": ["Una voz pública niega robo, brujería, traición y mentira.", "Aṣolé, el perro, aparece en un relato sobre conducta y aceptación."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona babosa, paloma y cauríes; el segundo, miel, gallina y cauríes. Son dos consultas distintas."}, {"titulo": "Relaciones espirituales", "texto": "Ifá figura como marco de los versos. Aṣolé es un personaje animal del relato, no un oricha."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan miel, babosa, paloma y gallina. Ninguno de esos elementos define un remedio general."}, {"titulo": "Rezos, versos y cantos", "texto": "El canto de respuesta a las acusaciones y el verso de Aṣolé se conservan por separado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=157;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo llama a cuidar el apoyo recibido y las relaciones que sostienen la prosperidad. Akeregbe depende de su esposa e hijos; otro canto pide que alguien regrese pronto."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme perder el apoyo de quienes lo acompañaron (relato de Akeregbe).", "Una amistad se enfría por orgullo o porque solo da una parte.", "Quiere revivir una relación o un proyecto que parecía terminado."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La interpretación favorable aconseja sostener también a quienes antes sostuvieron a la persona. Los relatos muestran que la ayuda de familiares puede ser decisiva."}, {"titulo": "Ibi y advertencias", "texto": "La interpretación desfavorable advierte que la arrogancia puede apartar a las amistades. El miedo de Akeregbe a ser abandonado es parte de su historia y no una predicción obligatoria."}, {"titulo": "Enseñanza principal", "texto": "La prosperidad no vuelve prescindibles a las personas que la hicieron posible. El canto de retorno expresa otro deseo y no debe confundirse con el caso de Akeregbe."}, {"titulo": "Relatos reunidos", "puntos": ["Akeregbe confía en su esposa y sus hijos mientras teme perder apoyo en una etapa de gloria.", "Un canto llama a alguien para que vuelva sin demora."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de Akeregbe menciona paloma, gallina y cauríes; el canto de retorno no aporta la misma lista. No se construye un ẹbọ único."}, {"titulo": "Relaciones espirituales", "texto": "Ifá figura en la consulta de Akeregbe. Su esposa e hijos son personas del relato; el canto de retorno no identifica una nueva entidad."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El relato nombra animales y cauríes. La imagen de llamas que vuelven a encenderse es figurada, no una planta o preparación."}, {"titulo": "Rezos, versos y cantos", "texto": "La historia de Akeregbe y el canto de retorno se muestran como piezas distintas. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=158;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo habla de proteger la tranquilidad sin caer en la idea de que uno es invulnerable. El antílope confía en sus cuernos y rechaza una advertencia; el caracol obtiene paz en una vivienda propia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Responde con enojo a las críticas o los pleitos.", "Se cree capaz de aguantar cualquier ataque y no escucha la advertencia (relato del antílope y sus cuernos).", "Busca un lugar propio donde vivir tranquilo (relato del caracol Igbín)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable asocia abundancia con nuevas oportunidades, honestidad y servicio. El relato del caracol imagina una casa tranquila."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que avaricia y exceso de confianza pueden aislar. El peligro del antílope pertenece a su relato, no autoriza anunciar violencia inevitable."}, {"titulo": "Enseñanza principal", "texto": "La fuerza aparente no sustituye a la prudencia. El caracol muestra otra respuesta: crear un entorno de paz en lugar de desafiar toda amenaza."}, {"titulo": "Relatos reunidos", "puntos": ["El antílope se niega a seguir el consejo porque confía en sus cuernos.", "Igbín, el caracol, atiende el consejo y construye una casa asociada con calma.", "Tèèrè, el barro resbaladizo, aparece en un relato separado sobre hostilidad y falta de malicia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El antílope recibe una lista de carcaj, flechas, arco, gallo y cauríes; el caracol, tortuga y cauríes. La ofrenda de Tèèrè pertenece a otro episodio."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las consultas. Antílope, caracol y Tèèrè son protagonistas narrativos; no se convierten en orichas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran cuernos, barro y elementos de caza; no constituyen una receta para la persona consultante."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del antílope y del caracol y el canto de Tèèrè permanecen diferenciados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=159;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo distingue obtener fortuna de conservarla. Olibara atiende anuncios de dinero e hijos, pero ignora una advertencia de conflicto; otro verso relata la relación entre un agricultor y una hierba."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Disfruta un logro y descuida un peligro que no ha resuelto.", "Recibió varios consejos y está siguiendo solo los que le gustan (relato de Olibara y los tres adivinos).", "Un cambio de humor puede llevarlo a un pleito evitable.", "Una fortuna perdida puede regresar."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de superar obstáculos y conservar lo alcanzado. Otro relato anuncia que beneficios antes perdidos podrían regresar."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable vincula la ira y la tristeza con decisiones que agravan un conflicto. No se interpreta como diagnóstico de salud mental ni como predicción literal de guerra."}, {"titulo": "Enseñanza principal", "texto": "Olibara escucha los consejos que prometen ganancias y desoye el que exige prevención. El relato del agricultor enseña reciprocidad entre quienes dependen uno del otro."}, {"titulo": "Relatos reunidos", "puntos": ["Tres adivinos dan a Olibara consejos distintos sobre dinero, hijos y conflicto; solo atiende los dos primeros.", "El agricultor y Aikújegúnrè, una hierba, expresan una relación de beneficio mutuo.", "Otro relato habla del retorno de una fortuna perdida."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las listas de Olibara cambian con cada anuncio: paloma y carnera; chiva y gallina; carnero ante el conflicto. El agricultor y la hierba reciben otras indicaciones. No se combinan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece en las consultas. Òrúnmìlà interviene en el relato del retorno; Olibara y sus tres adivinos pertenecen a la primera historia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aikújegúnrè se identifica en una nota como hierba del género Commelina. También aparecen aceite de palma y peces en otra historia."}, {"titulo": "Rezos, versos y cantos", "texto": "La historia de Olibara, el canto de la hierba y el relato de retorno quedan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=160;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne el deseo de estabilidad para quien viaja y la protección de la confianza. Un verso consulta por un recién nacido inclinado a recorrer el mundo; otro advierte sobre secretos revelados."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le preocupa el futuro de un hijo o dónde va a vivir (relato de Ọmotitun).", "Viaja mucho y busca un lugar estable.", "Alguien de confianza puede contar sus secretos (relato de Ayékogbejẹ)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La interpretación favorable habla de conducta honesta y de una vida que puede mejorar. En otro relato, unas zapatillas superan el desgaste de un viaje."}, {"titulo": "Ibi y advertencias", "texto": "La interpretación desfavorable advierte sobre divulgar secretos o confiar sin cuidado. Ningún texto demuestra que una persona específica haya traicionado a quien consulta."}, {"titulo": "Enseñanza principal", "texto": "Viajar y asentarse no son opuestos absolutos; la pregunta del primer verso es cómo disponer de un lugar al cual regresar. El segundo pide cuidar lo confiado a otros."}, {"titulo": "Relatos reunidos", "puntos": ["Ọmotitun, un recién nacido, recibe una predicción de viajes y una recomendación para su estabilidad.", "Ayékogbejẹ consulta cuando un confidente revela secretos.", "Sálúbàtà, unas zapatillas, emprende un viaje y perdura pese al uso."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La consulta por el niño menciona caracol, aiká, jabón negro, cauríes y hojas de Ifá; la de los secretos, caracol, aceite de palma, manteca de cacao, paloma y cauríes. No se fusionan las listas ni se presenta la preparación tradicional como tratamiento médico."}, {"titulo": "Relaciones espirituales", "texto": "Ifá escucha una súplica en otro canto del signo. Los personajes del recién nacido, el confidente y las zapatillas cumplen papeles narrativos distintos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Jókó-jẹ figura como hoja en una preparación tradicional. Aiká es un animal nombrado en el primer verso, no una planta."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan separados los versos del niño, los secretos y las zapatillas. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=161;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata el deseo de descendencia y la larga vida en relatos diferentes. Una mujer consulta por tener un hijo; otro verso usa la piel de un animal como imagen de continuidad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Desea tener hijos o le preocupa su fertilidad (relato de Ọ̀sá Atinuṣojo).", "Quiere asegurar su bienestar a largo plazo.", "En la familia hay tensión entre juntar bienes y cuidar a los hijos (relato de Yèyé Owójùwà y Yèyé Omójùwà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La interpretación favorable aconseja apartarse del chisme y la envidia. Un relato contrapone riqueza sin descendencia con una familia numerosa que también alcanza recursos."}, {"titulo": "Ibi y advertencias", "texto": "La interpretación desfavorable relaciona conflictos con enfermedad o infertilidad, pero esos enunciados tradicionales no diagnostican ni explican una condición médica real."}, {"titulo": "Enseñanza principal", "texto": "La historia de dos madres pregunta qué permanece después de una vida: bienes y relaciones aparecen como valores distintos. No obliga a preferir una decisión reproductiva concreta."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀sá Atinuṣojo escucha un consejo relacionado con concebir y decide no seguirlo.", "La piel de un animal recibe un anuncio de duración.", "Yèyé Owójùwà y Yèyé Omójùwà eligen propósitos distintos y sus familias viven consecuencias diferentes."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita chiva, gallina, cauríes y hojas de Ifá; el segundo, paloma, carnero, kola y cauríes. El relato de las dos madres presenta otras ofrendas. No hay una receta única ni un tratamiento de infertilidad."}, {"titulo": "Relaciones espirituales", "texto": "Ògún aparece en el WO de una ficha como destinatario de una indicación ritual. Las dos madres y la piel son protagonistas de relatos diferentes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan kola y hojas de Ifá."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos sobre maternidad, piel y las dos madres se conservan en secciones diferenciadas. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=162;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "La verdad y el buen carácter ocupan el centro del signo. Una serie de preguntas a Ọ̀rúnmìlà relaciona la verdad con Olódùmarè y con la palabra que no se corrompe."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está evitando un problema que ya conoce.", "Quiere investigar un asunto para saber qué lo causó.", "La decepción o el enojo le impiden hablar con franqueza (relato de Ọ̀sá Òtúrá preguntando qué es la verdad)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable asocia sinceridad con comprensión, honor y una dirección más clara. Otro relato anuncia que una investigación puede llegar a la raíz del asunto."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que el enojo excesivo puede terminar en decepción. No basta con repetir una frase sobre la verdad: es preciso comprobar los hechos."}, {"titulo": "Enseñanza principal", "texto": "La honestidad implica enfrentar aquello que se ha evitado y admitir lo que aún no se sabe. Las preguntas del verso funcionan como reflexión sobre el carácter."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀sá Òtúrá pregunta repetidamente a Ọ̀rúnmìlà qué es la verdad.", "En otra consulta, una persona investiga un asunto y espera conocer su causa."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La investigación y el diálogo sobre la verdad no aportan una lista ritual común. Las indicaciones que aparecen en cada versión deben permanecer en su contexto."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà responde las preguntas; Olódùmarè aparece en la explicación de la verdad."}, {"titulo": "Plantas, alimentos y elementos", "texto": "No se identifica una planta o alimento que defina el signo en los pasajes examinados."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de preguntas y el relato de investigación se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=163;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo aborda la falta de apoyo y la posibilidad de encontrar ayuda. Un recién llegado no tiene quién le ayude a levantar su carga; otra historia relaciona generosidad con convivencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su pareja no le da apoyo práctico ni moral.", "Se siente solo con una carga pesada (relato del recién llegado al campo vacío).", "Un pleito en casa le impide aprovechar algo bueno.", "Se pregunta si una fortuna que se fue puede volver."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La interpretación favorable habla de determinación y de mantener el conflicto fuera del hogar. Una consulta del signo anuncia descanso y regalos compartidos."}, {"titulo": "Ibi y advertencias", "texto": "La interpretación desfavorable advierte de terquedad cuando se ignora ayuda o consejo. La escena del recién llegado no exige soportar una carga sin pedir apoyo."}, {"titulo": "Enseñanza principal", "texto": "La confianza espiritual del personaje se expresa mientras busca quién le ayude. El relato sobre comida compartida amplía la idea de sostener vínculos mediante generosidad."}, {"titulo": "Relatos reunidos", "puntos": ["Un recién llegado se dispone a vivir en un campo vacío y necesita ayuda para cargar sus pertenencias.", "Olóyan invita a otros a comer cuando prepara una ofrenda.", "Otro relato pregunta si una fortuna que se alejó puede regresar."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona gallina, cauríes y hojas de Ifá para su propia situación. La comida y otras ofrendas de los relatos restantes no se convierten en un solo ẹbọ."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las consultas; la invocación del primer relato pide ayuda divina. Olóyan es protagonista de otro episodio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombra comida preparada para compartir, además de gallina y cauríes en otra escena. No se infiere una receta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "La invocación del recién llegado, el relato de Olóyan y la consulta sobre fortuna se conservan diferenciados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=164;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo advierte sobre acusar sin pruebas y describe una prosperidad que procede de esfuerzos anteriores. Owa sospecha de alguien inocente; otro relato presenta a dos personajes con resultados distintos tras una consulta."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay un cambio repentino en el trabajo.", "Sospecha de alguien y podría culparlo sin pruebas (relato de Owa y el inocente).", "Varias personas tratan de colaborar para obtener un beneficio (relato de Olúigbó y Olúodàn)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable asocia la abundancia con esfuerzos previos. Un verso anuncia bendiciones para Olúigbó tras atender el consejo de su propia consulta."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable relaciona avaricia y envidia con conflicto. La historia de Owa muestra el daño de llamar ladrón a quien no lo es."}, {"titulo": "Enseñanza principal", "texto": "La sospecha exige comprobación. El progreso de un personaje no justifica degradar a otro ni atribuirle una falta."}, {"titulo": "Relatos reunidos", "puntos": ["Olúigbó y Olúodàn reciben una indicación, pero solo el primero la sigue.", "Owa mira como ladrón a un inocente y recibe un consejo para no acusarlo.", "Otro canto reúne a tres participantes que buscan un beneficio común."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona una chiva; el de Owa, dos palomas, ñame asado y cauríes. Cada indicación pertenece a su episodio."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù se menciona en la advertencia dirigida a Owa. Olúigbó, Olúodàn y Owa son protagonistas humanos o narrativos de otros pasajes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparece ñame asado como elemento del relato de Owa. No se identifica una planta medicinal de uso general."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos sobre Olúigbó y Owa y el canto colectivo se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=165;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo invita a distinguir las prohibiciones personales de los peligros comunes. Un verso enumera todo aquello de lo que la gente huye y concluye que nadie puede vivir evitando cada cosa del mundo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está confundido con sus actividades diarias y eso le nubla el juicio.", "Quiere escapar de un problema que tiene que enfrentar (relato de Ọ̀rúnmìlà sobre por qué huye la gente).", "Debe cuidar a un hijo frente a alguien con más poder.", "Necesita saber qué prohibición le corresponde."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable presenta la firmeza ante un problema como protección de la buena fortuna. El verso propone discernir qué debe evitarse en cada caso."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que evitar indefinidamente un problema puede empeorarlo. La lista de serpiente, elefante, fuego, deuda y bienes ajenos es una serie de ejemplos, no una prohibición individual de todos ellos."}, {"titulo": "Enseñanza principal", "texto": "Una regla solo sirve cuando se sabe a quién y a qué situación se aplica. La evasión indiscriminada no sustituye una decisión responsable."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà enumera diversos motivos por los que la gente huye y explica la necesidad de conocer el èèwọ pertinente.", "Otro relato pide cuidar a un hijo ante una relación de poder.", "Dos personajes reciben un consejo sobre telas nuevas y responden de modo distinto."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de las prohibiciones menciona cauríes en su contexto. El relato de las dos telas contiene otra indicación; no se fusionan ni se prescribe una obra universal."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà explica la enseñanza principal. Los personajes de los relatos sobre hijos y telas no se convierten en orichas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se citan serpiente, elefante, búfalo, fuego, tela y otros elementos como ejemplos narrativos. No se deriva una preparación vegetal."}, {"titulo": "Rezos, versos y cantos", "texto": "La enumeración sobre èèwọ y los cantos de los relatos posteriores se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=166;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata el respeto y la forma de defender los propios derechos. Un verso rechaza la grosería; otro responde a la angustia por no tener hijos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita explicar su postura sin ser grosero.", "Siente que no lo respetan.", "Desea hijos y recursos (relato de Adeiloye).", "Puede llegar un cargo importante; si hay embarazo, le preocupa el parto."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La interpretación favorable une paciencia y apertura de camino. Adeiloye recibe una predicción de hijos y riqueza en su relato."}, {"titulo": "Ibi y advertencias", "texto": "La interpretación desfavorable advierte contra arrogancia y decepción. La inquietud por fertilidad del segundo verso no describe necesariamente a toda persona que reciba el signo."}, {"titulo": "Enseñanza principal", "texto": "El respeto se pide y se practica: la firmeza no requiere humillar a otro. El segundo verso responde a otra pregunta y conserva su propio consejo."}, {"titulo": "Relatos reunidos", "puntos": ["Una voz contrapone grosería e impertinencia y pide ser respetada.", "Adeiloye consulta por falta de descendencia y luego celebra a sus hijos.", "Otra versión anuncia a una persona un cargo elevado y trata por separado el temor de una mujer embarazada sobre su parto; no se traslada esa predicción a toda consulta."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El caso de Adeiloye cita dos carneros y cauríes. La exhortación a hablar con educación no constituye la misma ofrenda."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca la consulta de Adeiloye. El jefe del mercado aparece en una comparación del primer verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ropa seca, fuego y serpiente son imágenes del primer canto. No se extrae una receta vegetal."}, {"titulo": "Rezos, versos y cantos", "texto": "La exhortación sobre el respeto y el canto de Adeiloye quedan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=167;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne una relación que podría terminar, una consulta por descendencia y un relato sobre recuperar el valor. Onimeri-apala busca hijos; la cobra y Aiká responden a quienes los desprecian."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una relación se enfrió o terminó (relato de Onimeri-apala).", "Sufre por no tener hijos.", "Evita los pleitos por miedo y se pregunta cómo defender su dignidad (relato de la cobra y Aiká)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable admite que retirarse de un conflicto puede cerrar un ciclo de forma saludable. El verso de Onimeri-apala narra el regreso de su familia."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte sobre rumores y desprecio propio. Los números y resultados extraordinarios del relato no son pronósticos médicos."}, {"titulo": "Enseñanza principal", "texto": "Retirarse de una pelea puede ser una decisión fuerte; defender la dignidad tampoco exige provocar violencia."}, {"titulo": "Relatos reunidos", "puntos": ["Onimeri-apala consulta por infertilidad y el retorno de sus esposas.", "La cobra y Aiká buscan respeto después de huir de amenazas.", "Olóta Ìkayèkú viaja del cielo a la tierra en un relato diferente; otra lectura del signo habla de encontrar tiempo y espacio para actuar."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de Onimeri-apala enumera gallinas, palomas, caracoles, hormiguero y hojas de varias plantas. Es su indicación tradicional, no un tratamiento de fertilidad general. La cobra y Aiká tienen otra consulta."}, {"titulo": "Relaciones espirituales", "texto": "Ifá interviene como autoridad de consulta. La cobra y Aiká son personajes del relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Oluṣesaju, ṣawerepepe y oriji aparecen como nombres de hojas en una preparación tradicional; sus identidades y seguridad no están verificadas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Onimeri-apala y de la cobra se conservan por separado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=168;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo advierte que hacer daño a otros repercute en quien lo hace. Otro verso se ocupa del riesgo de que una enfermedad afecte a más personas en una casa."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Alguien con rencor está bloqueando una relación o un proyecto (relato de Inükogun).", "Hay un enfermo en la familia y teme por los demás; conviene la atención médica (relato de Ìká).", "Debe separar el pleito moral del asunto de salud.", "Puede venir una mejoría (relato de Oníbàyì dúdú)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona una transformación con cambiar la conducta. Ante una enfermedad real, corresponde buscar atención sanitaria y medidas de prevención comprobadas."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que el poder usado para dañar genera conflicto. El segundo verso es una advertencia tradicional; no identifica patógenos ni sustituye una evaluación médica."}, {"titulo": "Enseñanza principal", "texto": "La imagen de esparcir cenizas enseña que las acciones perjudiciales tienen consecuencias. La prevención de enfermedad es otra situación y debe tratarse con información médica actual."}, {"titulo": "Relatos reunidos", "puntos": ["Inükogun considera hacer daño y recibe una advertencia sobre sus actos.", "Ìká cuida a una persona enferma y pregunta cómo proteger al resto de la casa.", "Oníbàyì dúdú recibe un anuncio de mejoría; otro canto compara cómo la palma conserva sus hojas con otros árboles."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona dos palomas y cauríes; el segundo, chiva, gallina y ginebra. Las ofrendas pertenecen a consultas diferentes y no son medidas de prevención de contagio."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el marco de ambas consultas. Los protagonistas son Inükogun e Ìká, en escenas distintas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Cenizas aparecen como metáfora. No se identifica una planta medicinal ni un remedio contra enfermedades contagiosas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos y sus consejos se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=169;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo enseña respeto hacia personas con experiencia y prudencia en los negocios. Un relato muestra a Àgbà rechazando un consejo; otro critica la conducta de jóvenes que desafían y agreden a mayores."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Discute con alguien de experiencia sin escuchar sus razones (relato de Ködunmi-Àgbà).", "Un negocio parece prometedor, pero hay riesgo de engaño.", "Siente que descuidó sus obligaciones espirituales o personales.", "Está sin dinero y espera que lleguen recursos (relato del herrero Alágbède Ìmòbà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona crecimiento personal con más conocimiento y cuidado en los negocios."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte sobre una decisión comercial sin propósito claro y sobre imprudencia. Los castigos del verso son parte de su lenguaje narrativo, no consecuencias automáticas."}, {"titulo": "Enseñanza principal", "texto": "Respeto no significa obediencia ciega: pide examinar el consejo antes de descartarlo y evitar la agresión."}, {"titulo": "Relatos reunidos", "puntos": ["Ködunmi-Àgbà rechaza la indicación que recibe antes de afrontar dificultades.", "Un verso censura a jóvenes imprudentes que agreden a adivinos, herbolarios o ancianos.", "Alágbède Ìmòbà, un herrero sin dinero, recibe un anuncio de recursos abundantes en otro relato."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El caso de Àgbà menciona huevos, manteca de cacao, piedra de rayo y cauríes. El segundo verso es una advertencia de conducta y no aporta esa misma lista."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las consultas. Los mayores del segundo verso son personas de distintas ocupaciones, no orichas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aparecen huevos, manteca de cacao y piedra de rayo. No se deduce un tratamiento o preparación de aplicación general."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de Àgbà y el de los jóvenes imprudentes permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=170;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo enlaza reconocimiento y larga vida en dos consultas a Ìrosùn, presentado como árbol. La caracterización también menciona rivalidad dentro de una relación, pero los versos conservados tratan otras preguntas. El cuaderno del mismo signo añade dos situaciones distintas: conservar las fortunas de la casa paterna y prevenir un contratiempo al iniciar labores agrícolas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere que lo respeten y lo aprecien (relato de Ìrosùn entre los árboles).", "Teme por su futuro y necesita reconocer lo que vale.", "Hay competencia dentro de la pareja o la familia.", "Quiere que prosperen su casa, su pareja y sus hijos sin perder lo ganado (relato de Ọ̀rúnmìlà y la casa de su padre).", "Va a empezar a trabajar una tierra o un proyecto nuevo y debe revisar los riesgos antes (relato de Àlàó de Ìgbesà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de aprovechar las capacidades propias. En un verso Ìrosùn es elegido como árbol estimado; en otro recibe un anuncio de vida prolongada. En el relato de Ọ̀rúnmìlà, las bendiciones de su casa permanecen y se nombran riqueza, pareja e hijos."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable vincula el miedo al futuro con resistencia a avanzar. Los resultados de los versos no son garantía personal de longevidad. La historia de Àlàó presenta un peligro súbito en el trabajo del campo después de desoír un consejo; no permite anunciar la muerte de una persona concreta."}, {"titulo": "Enseñanza principal", "texto": "Reconocer el propio valor ayuda a decidir sin rivalidad innecesaria. La popularidad y la duración se preguntan en relatos diferentes. Los dos relatos nuevos distinguen cuidar lo recibido de prepararse para riesgos reales antes de emprender una tarea."}, {"titulo": "Relatos reunidos", "puntos": ["Ìrosùn consulta para ser favorito entre los árboles.", "En otra consulta, Ìrosùn pregunta por larga vida.", "Ọ̀rúnmìlà consulta para conservar las bendiciones de la casa de su padre y canta su llegada.", "Àlàó de Ìgbesà va a abrir una tierra de cultivo; una desgracia repentina cierra el relato después de que no atiende el consejo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La primera indicación cita paloma, gallina blanca y cauríes; la segunda, carnera, ewé peperẹku y cauríes. No se mezclan. El relato de Ọ̀rúnmìlà menciona una paloma madura y dinero. El pasaje de Àlàó alude a una ofrenda, pero el fragmento revisado no fija una lista que pueda añadirse aquí."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambas consultas. Ìrosùn es el árbol protagonista, no un oricha adicional. Ọ̀rúnmìlà protagoniza la consulta de la casa paterna; Àlàó, la del trabajo agrícola."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ewé peperẹku aparece como hoja. No se recomienda como medicina. El cocoyam ilustra la llegada de las bendiciones en el canto; la azada, el machete y la jícara pertenecen a la escena del agricultor. Serpiente y escorpión son imágenes del verso, no indicaciones medicinales."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos de Ìrosùn se presentan separados. El canto «Wàràwàrà» pertenece al relato de Ọ̀rúnmìlà; el de Àlàó queda separado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=171;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo invita a corregir una conducta antes de que cause daño y a cuidar una posición alcanzada. Alábámo recibe una advertencia moral; la gente de Ifè-Ooyẹ consulta para no ser desplazada."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se arrepiente de algo que hizo con prisa (relato de Alábámo).", "Teme perder respeto, empleo o su lugar en un grupo.", "Se siente agobiado por rivalidades.", "Le preocupan sus hijos (relato de Aláaka)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable propone dejar atrás el arrepentimiento y concentrarse en hacer el bien. El segundo verso relaciona protección con sostener la posición de una comunidad."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de caos al actuar sin evaluar las consecuencias. Los enemigos del relato no prueban que existan adversarios en toda consulta."}, {"titulo": "Enseñanza principal", "texto": "El arrepentimiento tiene valor si modifica la siguiente acción. Defender una posición también exige no repetir conductas dañinas."}, {"titulo": "Relatos reunidos", "puntos": ["Alábámo escucha un consejo para hacer cosas honestas, pero no lo sigue.", "La gente de Ifè-Ooyẹ atiende una consulta sobre respeto y continuidad.", "Aláaka consulta por sus hijos junto a una colina; otro testimonio habla de escapar de una red y conservar el orden de la vida."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Alábámo recibe una lista de caracoles, cauríes y hojas de Ifá. La comunidad recibe efún, osùn, paloma, carnera y cauríes. Cada lista queda con su verso."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà aparece en el canto de la comunidad. Alábámo pertenece a otro episodio."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Osùn se identifica en el texto como madera roja. Efún y los animales citados son elementos rituales de esa historia."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de Alábámo y el canto de Ifè-Ooyẹ permanecen diferenciados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=172;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata el deseo de ser querido y la atención a los vínculos. Dos aves consultan por aprecio; Lekeleke y su esposa preguntan por descendencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere mejorar una relación de pareja (relato de Aṣa y Awodi).", "La falta de agradecimiento está dañando un vínculo.", "Pregunta por un posible embarazo o por hijos (relato de Lekeleke y su esposa).", "Va a entrar a un grupo donde se comparte y debe cuidar su parte (relato del ñame pilado)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona cambio personal con vínculos amorosos. El segundo verso narra el deseo de tener huevos y su cumplimiento."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que el egoísmo puede hacer perder afecto. Un verso habla de embarazo en clave de aves; no confirma un embarazo humano actual."}, {"titulo": "Enseñanza principal", "texto": "El aprecio no se logra solo con apariencia; atender al otro importa. La consulta por descendencia es independiente del deseo de fama de las dos aves."}, {"titulo": "Relatos reunidos", "puntos": ["Aṣa y Awodi buscan ser queridos y elogiados, pero no siguen la indicación.", "Lekeleke y su esposa consultan por huevos semejantes a los de una paloma.", "Ìyán, el ñame pilado, recibe consejo antes de entrar en una comunidad que comparte comida; no lo sigue y el relato dice que es el primer alimento en acabarse."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Aṣa y Awodi reciben una lista de caracoles, cauríes y hojas de Ifá; Lekeleke y su esposa, efún, carretes de hilo y cauríes. No se fusionan. El relato independiente de Ìyán menciona una indicación sin lista verificable de ingredientes; no se añade a las otras ofrendas."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambas consultas. Los nombres de aves son personajes, no orichas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aṣa y Awodi se describen como tipos de halcón; Lekeleke, como ave blanca. Ìyán es el ñame pilado presentado como personaje y alimento compartido, no una especie nueva."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de las aves se mantienen separados."}]$q$::jsonb where numero=173;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo presenta una oportunidad de cambio ligada a la conducta. Ẹka recibe un aviso sobre el daño que ha causado; Ọwọ́, las manos, consulta por tener solo cosas buenas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una decisión importante depende de actuar con justicia.", "Reconoce una conducta pasada que debe cambiar (relato de Ẹka).", "Quiere controlar todo lo que resulte de sus actos (relato de las manos).", "Tiene una buena idea, pero necesita calma en vez de correr sin rumbo (relato de Ògúngbádé)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de nuevas oportunidades tras cambiar una conducta perjudicial. El relato de Ẹka expresa esa posibilidad."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable relaciona el mal comportamiento con aislamiento. La muerte del relato no debe anunciarse como desenlace literal de una consulta actual."}, {"titulo": "Enseñanza principal", "texto": "Cambiar de ropa en la historia de Ẹka simboliza una reforma más profunda del carácter. El relato de las manos recuerda que la vida incluye resultados buenos y malos."}, {"titulo": "Relatos reunidos", "puntos": ["Ẹka recibe el consejo de abandonar actos dañinos y cambiar su ropa negra por blanca.", "Ọwọ́, las manos, recibe una indicación para atraer solo bienes, pero no la sigue.", "Ògúngbádé escucha que una buena idea requiere serenidad en lugar de correr sin dirección."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El caso de Ẹka menciona carnera y ropa negra; el de las manos, paloma blanca, gallina blanca y cauríes. No se combinan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las consultas. Ẹka y las manos son protagonistas narrativos, no entidades que deban confundirse."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ropa negra y blanca son elementos simbólicos del primer verso. No se identifica una planta o remedio general."}, {"titulo": "Rezos, versos y cantos", "texto": "Las historias de Ẹka y Ọwọ́ se mantienen separadas."}]$q$::jsonb where numero=174;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona el coraje con actuar bien. Adetutu vive dominado por el miedo y un canto pide apoyo a Ògún en medio de una disputa. Otro verso previene contra apropiarse de bienes dejados por una persona fallecida."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme un pleito antes de que pase y debe confirmar si de verdad existe.", "Necesita sostener su postura sin dejarse llevar por la ira (relato de Adetutu).", "Celebra un logro y puede ponerse en riesgo por imprudente (relato de Olónkò-ègì).", "Hay un pleito por cosas de alguien que murió, o alguien las retiene sin derecho (relato de Látalè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de despejar obstáculos mediante valor y decisiones cuidadosas."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que la falta de control del enojo puede agravar el conflicto. El canto sobre litigio no determina la inocencia de una persona actual. El verso de Látalè advierte sobre quedarse con la ropa de un difunto; no establece una consecuencia sobrenatural verificable para un caso actual."}, {"titulo": "Enseñanza principal", "texto": "El valor no consiste en buscar pelea; el verso une el apoyo solicitado con hacer el bien."}, {"titulo": "Relatos reunidos", "puntos": ["Adetutu, hijo de un hombre temeroso, pide apoyo de Ògún y recibe un consejo antes de afrontar su miedo.", "Olónkò-ègì celebra un logro y recibe una advertencia sobre disparar al aire; el riesgo del relato no se presenta como práctica aceptable.", "Látalè declara que conservará la ropa del difunto y el canto le responde que el dueño vendrá por ella; es un tercer relato distinto."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de Adetutu menciona perro, vino de palma, ñame asado y aceite de palma. Esa lista pertenece a su consulta."}, {"titulo": "Relaciones espirituales", "texto": "Ògún es invocado expresamente como apoyo en el canto. Ifá enmarca la adivinación para Adetutu."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se citan ñame, aceite y vino de palma como elementos del relato, no como tratamiento del miedo."}, {"titulo": "Rezos, versos y cantos", "texto": "El canto dirigido a Ògún se conserva unido al relato de Adetutu. El verso de Látalè sobre la ropa del difunto se registra aparte."}]$q$::jsonb where numero=175;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo contrapone conducta deshonesta y descanso ganado mediante una vida ordenada. Un ladrón recibe el consejo de adquirir bienes honestamente; Jókó-jẹ consulta por tranquilidad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está pensando conseguir algo por un medio deshonesto (relato del ladrón).", "Un conflicto emocional está influyendo en sus decisiones.", "Quiere recuperar la paz en un ambiente alterado (relato de Jókó-jẹ).", "Su buena fortuna depende de atender su cabeza (Orí)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La interpretación favorable asocia abundancia con valentía para cambiar un comportamiento anterior. Jókó-jẹ recibe una indicación para vivir con calma."}, {"titulo": "Ibi y advertencias", "texto": "La interpretación desfavorable advierte que el mal carácter puede causar temor e inestabilidad. No se interpreta como diagnóstico de salud mental."}, {"titulo": "Enseñanza principal", "texto": "El primer relato niega que robar sea una forma de valor. La tranquilidad del segundo depende de una consulta distinta."}, {"titulo": "Relatos reunidos", "puntos": ["Un ladrón escucha que debe buscar bienes de forma honesta, pero no sigue el consejo.", "Jókó-jẹ consulta por descanso y sigue una indicación sobre tela azul.", "Un machete personificado toma un mango de madera como pareja; otro relato vincula la fortuna de Oòni con la atención a Orí."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona caracoles, cauríes y hojas de Ifá; el segundo, tela azul, paloma, carnera y cauríes. Son listas separadas."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las dos consultas. Jókó-jẹ es protagonista de un verso, sin asignarle una identidad botánica definitiva."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La tela azul es elemento del segundo relato; el nombre Jókó-jẹ requiere identificación antes de tratarlo como planta."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del ladrón y de Jókó-jẹ se conservan por separado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=176;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo se ocupa de una relación que puede aportar cuidado y de la necesidad de proteger lo valioso. Una terrateniente construye una casa amplia, pero teme que alguien robe aquello que más le importa."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se resiste a una unión que podría convenirle.", "Busca a alguien de confianza que cuide sus bienes (relato de la terrateniente y su casa).", "Pregunta si encontrará pareja (relato de Itú)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable vincula disciplina personal con bienestar y creatividad. El relato de la casa pide valorar quién puede ayudar con una responsabilidad concreta."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable asocia descuido con enfermedad o problemas de fertilidad, pero no explica médicamente esas condiciones ni las predice para toda consulta."}, {"titulo": "Enseñanza principal", "texto": "La autonomía no impide recibir ayuda. La decisión sobre una pareja o cuidador requiere observar carácter y circunstancias reales."}, {"titulo": "Relatos reunidos", "puntos": ["Una terrateniente levanta una casa de dieciséis habitaciones y consulta por alguien que la ayude a protegerla.", "Itú pregunta si encontrará pareja y recibe una respuesta favorable en un relato separado del de la terrateniente."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La consulta de la terrateniente enumera palomas, patos, caracoles y cauríes. Es su indicación tradicional, no una solución universal de seguridad o salud."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece en la consulta. La terrateniente y el posible cuidador son personas del relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La tortuga, la calabaza y el árbol irókò aparecen en imágenes introductorias; no se deduce una receta vegetal."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de la terrateniente conserva sus imágenes tradicionales sin convertirlas en afirmaciones médicas. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=177;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo habla de salir de una etapa difícil y reunir a otros para una mejora común. Un verso presenta a Ọ̀rúnmìlà frente a adversarios; otro pide dinero, pareja, hijos y otros bienes."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera que cambie una mala racha.", "Hay oposición a un proyecto y necesita organizarse (relato de los adversarios de Ọ̀rúnmìlà).", "Quiere mejorar su vida material y familiar.", "Necesita pensar con calma antes de decidir."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona mayor claridad con cooperación. En el primer verso, las acciones de los adversarios no derriban la casa de Ọ̀rúnmìlà."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que resistirse a aprender puede terminar en decepción. Los adversarios del relato no prueban que alguien específico ataque a la persona consultante."}, {"titulo": "Enseñanza principal", "texto": "Superar un obstáculo puede requerir sostener la casa y buscar apoyo colectivo, además de esperar buena fortuna."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe una predicción de que la acción de sus adversarios fracasará.", "Un segundo canto llama a reunir bienes y relaciones favorables.", "Ọ̀rúnmìlà entra a un lugar de deliberación con prudencia y después permanece en casa reflexionando, mientras otros continúan consultándolo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ọ̀rúnmìlà cita seis palomas, cauríes y pimienta de Guinea. El canto de petición no se confunde con esa lista."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el primer verso; Ifá es el marco de la consulta."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La pimienta de Guinea se nombra como elemento de una ofrenda, sin propuesta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos cantos se presentan como piezas distintas. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=178;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo destaca el esfuerzo propio en una oportunidad laboral o comercial. Awofusi recibe una predicción de bienes; Atikarẹṣẹtẹ recibe un consejo específico sobre no asociarse en su negocio."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa abrir un trabajo o negocio propio (relato de Awofusi).", "Una sociedad comercial le da desconfianza (relato de Atikarẹṣẹtẹ).", "Necesita confiar más en su capacidad.", "Su prosperidad está ligada a atender a su padre, vivo o fallecido."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona determinación con el trabajo personal. El verso de Awofusi anuncia bienes en sus manos."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de pérdidas en una inversión colectiva mal evaluada. La indicación de no asociarse pertenece al caso de Atikarẹṣẹtẹ y no invalida toda colaboración."}, {"titulo": "Enseñanza principal", "texto": "La autonomía exige evaluar acuerdos concretos, riesgos y recursos; el consejo de un personaje no es una regla financiera universal."}, {"titulo": "Relatos reunidos", "puntos": ["Awofusi consulta por fortuna y recibe una respuesta favorable.", "Atikarẹṣẹtẹ pregunta por comercio y recibe una advertencia sobre asociarse.", "Una versión relaciona la prosperidad con la atención al padre vivo o fallecido; sus instrucciones rituales son específicas de esa historia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Awofusi recibe paloma, gallina y cauríes; Atikarẹṣẹtẹ, miel, palomas, aiká y cauríes. Son consultas diferentes."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca los dos versos. Los protagonistas se mantienen separados."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La miel representa una vida dulce en el segundo relato. Aiká se nombra como animal; no se infiere receta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Awofusi y Atikarẹṣẹtẹ se conservan por separado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=179;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona la pobreza con el daño que puede causar una conducta maliciosa. Otro verso trata una acusación falsa contra Ọlabosipo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Busca salir de una situación económica difícil (relato de Oṣikàlekà).", "Hay una acusación grave que debe comprobarse antes de repetirla (relato de Ọlabosipo).", "El enojo o las ganas de revancha están influyendo en decisiones de dinero.", "Hay una separación de pareja; volver no debe significar quedarse en una relación que hace daño."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable vincula la mejora con corregir una alegación falsa y actuar con más rectitud."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte sobre avaricia y persistencia en una acusación injusta. El castigo narrado para adversarios no debe trasladarse a personas reales sin evidencia."}, {"titulo": "Enseñanza principal", "texto": "Un daño a la reputación exige pruebas y reparación; responder con otra injusticia prolonga el problema."}, {"titulo": "Relatos reunidos", "puntos": ["Oṣikàlekà consulta por pobreza y se niega a seguir una indicación que incluye desprenderse de sustancias dañinas.", "Ọlabosipo es acusado falsamente y busca superar a sus acusadores.", "Oyèbóádé aparece en un relato de conflicto con Ọ̀rúnmìlà. Otra versión habla de una mujer divorciada; sus mandatos de retorno pertenecen a ese testimonio y no justifican permanecer en una relación dañina."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las ofrendas de ambos versos son diferentes. El primer relato menciona palomas, kola y sustancias dañinas; no se reproduce ni recomienda uso de venenos. El segundo cita cáscaras de palma, palomas, gallo y cauríes."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca los versos. Oṣikàlekà y Ọlabosipo son protagonistas distintos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Kola y cáscaras de nuez de palma aparecen en contextos separados. Ninguno constituye tratamiento de pobreza o conflicto."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos sobre pobreza y falsa acusación se muestran por separado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=180;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo pregunta qué hace la persona para recibir aquello que espera. Una tortuga aguarda un regalo; en otra consulta busca recuperar dinero prestado."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera un ascenso, un regalo o un beneficio sin haber hecho su parte (relato de la tortuga).", "Quiere cobrar una deuda.", "Le cuesta pedir afecto y teme decepcionarse.", "Pregunta si podrá conservar lo que ha recibido (relato de Dèndèré)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de expectativas realistas y de crear condiciones para aprovechar una oportunidad."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que la decepción puede convertirse en amargura. El proverbio del relato no demuestra que toda persona sin recursos sea responsable de su situación."}, {"titulo": "Enseñanza principal", "texto": "Prepararse y pedir con claridad ayuda más que dar por seguro un regalo. El cobro de una deuda requiere acuerdos y pruebas concretas."}, {"titulo": "Relatos reunidos", "puntos": ["La tortuga espera un obsequio pero rechaza la indicación de su consulta.", "La tortuga pregunta en otro verso por deudores que aún no pagan.", "Dèndèré, madre de la luna creciente, pregunta si conservará los bienes recibidos y aparece acompañada de estrellas e hijos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona diez palomas y cauríes; el segundo, una paloma y cauríes. Son casos independientes, no un ẹbọ universal."}, {"titulo": "Relaciones espirituales", "texto": "Ifá aparece en ambos relatos; la tortuga es personaje narrativo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "No se identifica una planta especial en los pasajes resumidos. Los animales y cauríes citados pertenecen a las ofrendas de cada verso."}, {"titulo": "Rezos, versos y cantos", "texto": "El proverbio del regalo y el verso de la deuda se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=181;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo habla de una dificultad que puede involucrar a un hijo y de la importancia de prepararse. Un muchacho de la casa de Ọlófin, conocido por sus acrobacias, desoye una advertencia y su madre interviene cuando surge el problema."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La familia ve riesgos en lo que hace un hijo (relato del joven acróbata).", "Hay tensión en casa y conviene hablar antes de que crezca.", "Una relación lo tiene confundido."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable destaca el cuidado de vínculos físicos y afectivos. La madre del relato actúa para atender el problema del muchacho."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que una sensación de recuperación puede ser engañosa. No se deduce de ella un diagnóstico médico ni un accidente inevitable."}, {"titulo": "Enseñanza principal", "texto": "Prepararse ante un riesgo concreto permite actuar con calma. La historia no convierte todas las acrobacias ni a todos los hijos en peligro."}, {"titulo": "Relatos reunidos", "puntos": ["Un acróbata joven de la casa de Ọlófin escucha una advertencia, no sigue el consejo y luego recibe ayuda de su madre."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del muchacho menciona dos gallos, cauríes y una cuerda. La intervención posterior de la madre pertenece a esta misma historia."}, {"titulo": "Relaciones espirituales", "texto": "Ọlófin identifica el ámbito familiar del relato. Ifá enmarca la consulta."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La cuerda forma parte del verso del acróbata. No se identifica una planta ni un remedio."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conserva el verso del muchacho en su propia secuencia. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=182;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo contrapone dinero y alegría compartida. Un hombre rico que no disfruta de su vida recibe un consejo que incluye jugar àyò con niños e invitar a otros a comer."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Trabaja por dinero y se ha alejado de su familia y sus amigos.", "Tiene recursos, pero se siente solo o con nostalgia (relato del hombre rico sin alegría).", "Necesita tiempo para jugar y convivir."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable destaca disfrutar la vida y los vínculos. El relato presenta un modo de volver a compartir lo que se tiene."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable asocia falta de diversión con malestar, pero no diagnostica ni predice una discapacidad."}, {"titulo": "Enseñanza principal", "texto": "La riqueza no reemplaza la convivencia. El juego y la comida compartida son la enseñanza visible de este verso."}, {"titulo": "Relatos reunidos", "puntos": ["Un hombre rico sin placer consulta y recibe el consejo de compartir comida y jugar àyò con niños."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La lista del verso incluye ñame machacado, sopa, otros alimentos, cauríes y semillas del tablero de àyò para una fiesta situada en ese relato."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca la consulta. El hombre rico y los niños son participantes de la historia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ñame, sopa y semillas de àyò se nombran como alimentos y piezas de juego; no se propone tratamiento de salud."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso del hombre rico y el juego se conserva con su contexto."}]$q$::jsonb where numero=183;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo enseña preparación ante un riesgo concreto. La gente de Otù-Ifẹ̀ intenta sacar agua con un plato de barro que se hunde; otro verso personifica al maíz y habla de proteger a sus hijos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está muy preocupado por un hijo o por un negocio nuevo (relato del maíz).", "Va a empezar algo y debe escoger bien sus herramientas (relato del plato de barro en el río).", "Si es la salud de un niño, conviene llevarlo al médico."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La interpretación favorable se orienta a prevenir daños y cuidar a los hijos. La historia del río muestra el valor de una herramienta apropiada."}, {"titulo": "Ibi y advertencias", "texto": "La interpretación desfavorable habla de conflicto alrededor de una enfermedad, pero el relato no permite pronosticar muerte ni sustituye atención médica."}, {"titulo": "Enseñanza principal", "texto": "Una advertencia útil debe traducirse en una medida práctica: en la historia, usar un recipiente que flote para sacar agua."}, {"titulo": "Relatos reunidos", "puntos": ["Un grupo usa un plato de barro en el río pese a una advertencia; alguien cae al tratar de recuperarlo.", "El maíz consulta para mantener unidos a sus hijos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato del río no se convierte en una lista ritual universal. El verso del maíz menciona paloma, cauríes y una faja en su consulta particular."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambas historias. La gente de Otù-Ifẹ̀ y el maíz personificado pertenecen a relatos distintos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El maíz es protagonista del segundo verso; el plato de barro y el recipiente flotante son elementos del primero."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos relatos permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=184;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo habla de salir del ensimismamiento y de la relación entre vida individual y comunidad. Un verso pregunta por la llamada de Odùduà; otro reflexiona sobre las quejas dirigidas a Èlà."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está retraído y le cuesta convivir con otros.", "Necesita renovarse en lo personal o lo espiritual.", "Siente que malinterpretan sus buenas acciones."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona un nuevo comienzo con asumir un papel en la comunidad."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de resistirse al cambio. Sus referencias a enfermedad o tristeza no son un diagnóstico médico."}, {"titulo": "Enseñanza principal", "texto": "Responder a una llamada comunitaria y revisar las propias quejas puede abrir diálogo. Los versos usan imágenes espirituales, no una obligación idéntica para todas las personas."}, {"titulo": "Relatos reunidos", "puntos": ["Niños y mayores dudan ante una llamada de Odùduà y Ọ̀rúnmìlà habla de la belleza del cielo.", "Un canto critica quejarse continuamente de Èlà y pide que sus buenos actos sean reconocidos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El segundo verso menciona paloma y pescado ahumado para su situación. No se une a la primera narración como una obra única."}, {"titulo": "Relaciones espirituales", "texto": "Odùduà y Ọ̀rúnmìlà intervienen en el primer verso; Èlà es invocado en el segundo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Òdúndún y tẹ̀tẹ̀ aparecen como nombres de hojas en una comparación."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Odùduà y Èlà se conservan separados."}]$q$::jsonb where numero=185;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo atiende la discordia y la comunicación en pareja. Delumo consulta por la convivencia con su esposo; otro verso habla del matrimonio de Òtúrúpọ̀n con Ìrosùn."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La pareja discute seguido (relato de Delumo).", "Quiere recuperar la calma hablando.", "Pregunta por el futuro de un matrimonio y de los hijos (relato de Òtúrúpọ̀n e Ìrosùn)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona el cuidado del vínculo con oportunidades de una vida familiar más satisfactoria. El segundo verso anuncia hijos y nietos a sus protagonistas."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que descuidar la relación puede aumentar el conflicto. No se considera inevitable una reconciliación si existe maltrato."}, {"titulo": "Enseñanza principal", "texto": "La imagen de dos caracoles que no se enfrentan propone bajar la confrontación. El cuidado de la salud y la seguridad de cada persona tiene prioridad en una relación real."}, {"titulo": "Relatos reunidos", "puntos": ["Delumo recibe un consejo para buscar paz en su matrimonio.", "Òtúrúpọ̀n consulta antes de casarse con Ìrosùn y recibe una predicción de descendencia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Delumo recibe dos caracoles y cauríes; el segundo verso nombra kola, gallina y cauríes. Son indicaciones de escenas distintas."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambas consultas. Delumo, Òtúrúpọ̀n e Ìrosùn son personajes de las historias."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Caracoles y nueces de kola se mencionan como elementos rituales, sin proponer remedio general."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Delumo y del matrimonio permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=186;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo anuncia alegría próxima y pide cuidar lo alcanzado. La gente de Ọ̀yọ́ recibe una noticia favorable; Ọlasimbo consulta para conservar el honor ganado."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera un acontecimiento feliz (relato de la gente de Ọ̀yọ́).", "Quiere que un logro de trabajo o social le dure (relato de Ọlasimbo).", "Una conducta en su relación de pareja podría dañar su reputación."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona el fruto del trabajo con protección frente a cambios inesperados. El canto de Ọ̀yọ́ celebra una alegría compartida."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de caos y vergüenza pública en circunstancias concretas. No diagnostica problemas de salud ni confirma una falta de pareja."}, {"titulo": "Enseñanza principal", "texto": "Recibir algo bueno y conservarlo son preguntas distintas; ambas requieren actuar con cuidado."}, {"titulo": "Relatos reunidos", "puntos": ["La comunidad de Ọ̀yọ́ celebra algo bueno que se aproxima.", "Ọlasimbo pide que no se alejen de él el dinero, la familia y el respeto."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La comunidad recibe palomas, aceite de palma y cauríes; Ọlasimbo, carnera y cauríes. Las listas no se unen."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù se nombra en el primer verso como posible perturbador de la alegría; Ifá enmarca ambas consultas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma y otros elementos aparecen en contextos rituales, sin indicar una preparación general."}, {"titulo": "Rezos, versos y cantos", "texto": "Los cantos de Ọ̀yọ́ y Ọlasimbo se conservan por separado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=187;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata vínculos familiares que cambian con el tiempo. Iyàmookẹ se pregunta si su hijo adulto volverá a casa; Tenimaasunwọn consulta por la mujer a quien ama."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Un hijo se está alejando de casa al crecer (relato de Iyàmookẹ).", "Padres e hijos no se ponen de acuerdo sobre una relación nueva.", "La pareja quiere cuidar su vínculo (relato de Tenimaasunwọn y Ajémoorin)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable invita a cuidar la salud y las relaciones de la familia. El verso de Iyàmookẹ ofrece esperanza de reencuentro."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que un problema de salud puede afectar a varios miembros, pero no predice una enfermedad específica ni la muerte de la pareja."}, {"titulo": "Enseñanza principal", "texto": "La cercanía familiar no exige impedir la independencia de un hijo. El segundo verso recuerda expresar aprecio a la pareja."}, {"titulo": "Relatos reunidos", "puntos": ["Iyàmookẹ consulta por el futuro de su hijo.", "Tenimaasunwọn busca conservar la relación con Ajémoorin."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La primera consulta menciona una pareja de pichones de paloma y cauríes; la segunda, carnera, caracol y cauríes. No se fusionan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca los versos. Iyàmookẹ, Tenimaasunwọn y Ajémoorin son sus protagonistas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombran animales rituales; no se identifica una planta o remedio de salud."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos sobre el hijo y la pareja se presentan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=188;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo llama a cuidar los acuerdos y la relación con los hijos. Efunbunmi pregunta por el futuro de su descendencia; Ọ̀rúnmìlà afronta un litigio promovido por adversarios. Una exposición doctrinal posterior menciona el mismo signo al describir la llegada del espíritu al cielo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Debe revisar un acuerdo o un procedimiento comercial.", "Le preocupa cómo se portará un hijo en el futuro (relato de Efunbunmi).", "Tiene un pleito y necesita pruebas y asesoría legal concreta (relato de los dos adversarios contra Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de nuevas oportunidades cuando se toman medidas prudentes de protección. El relato de Ọ̀rúnmìlà termina con una maniobra frente a sus adversarios."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de aislamiento o daño si se ignora un riesgo. El verso de Efunbunmi no determina que un niño vaya a cometer delitos."}, {"titulo": "Enseñanza principal", "texto": "La educación de los hijos y un pleito entre adultos son asuntos distintos; ninguno se resuelve prediciendo culpa."}, {"titulo": "Relatos reunidos", "puntos": ["Efunbunmi recibe un consejo sobre el cuidado de sus hijos.", "Dos adversarios piden a Èṣù un litigio contra Ọ̀rúnmìlà, que responde con dos calabazas.", "Una explicación cosmológica, distinta de los dos relatos de consulta, menciona a Ẹ̀mú como guardián que evalúa el retorno del espíritu al cielo. Es una creencia narrada, no una predicción de muerte para esta consulta."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita paloma y cauríes; el segundo, dos calabazas, dos gallinas y cauríes. Son ofrendas separadas."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el segundo relato; Èṣù interviene en el pleito narrado. Ẹ̀mú figura como portero del cielo en una explicación cosmológica atribuida al signo, separada del litigio de Ọ̀rúnmìlà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Akeregbe designa las calabazas del segundo relato."}, {"titulo": "Rezos, versos y cantos", "texto": "Los relatos de Efunbunmi y Ọ̀rúnmìlà permanecen diferenciados. La referencia a Ẹ̀mú procede de una explicación sobre el cielo. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=189;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne preocupaciones distintas por la infancia: un verso habla de educar a un niño desde pequeño; otro pregunta por la llegada y el bienestar de un hijo. Un tercer verso sitúa la llegada del tambor en la tierra y su función de reunir música y celebración."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La familia pasa por la pérdida de un embarazo o de un bebé y busca orientación.", "Pregunta por fertilidad o por un embarazo (relato de Ọ̀rúnmìlà).", "Los padres quieren formar buenos hábitos en un niño (relato de Òtú y su hijo)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable se orienta a proteger la vida familiar y a prepararse con tiempo. El segundo verso anuncia descendencia a Ọ̀rúnmìlà."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable menciona infertilidad y conflicto, pero los textos tradicionales no diagnostican causas ni pronostican el resultado de un embarazo. Ante una pérdida o preocupación médica corresponde atención profesional."}, {"titulo": "Enseñanza principal", "texto": "La imagen de podar un irókò joven enseña intervenir temprano en la educación; no atribuye una identidad delictiva a un niño real."}, {"titulo": "Relatos reunidos", "puntos": ["Òtú carga a su hijo y escucha una advertencia figurada sobre crianza.", "Ọ̀rúnmìlà consulta por un embarazo y el bienestar del futuro hijo.", "Ọ̀rúnmìlà trae el tambor desde el cielo; el canto nombra a Ògún y Ṣàngó como figuras que buscan un instrumento para bailar. Es un verso distinto de los relatos sobre hijos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso enumera caracol, pescado, plátanos, paloma y cauríes; el segundo, gallina, chiva y cauríes. No son tratamientos de fertilidad."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza la segunda consulta; Òtú la primera. En el canto del tambor aparecen también Ògún y Ṣàngó, con funciones narrativas propias de ese verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El irókò aparece como árbol de la metáfora sobre crianza. Una nota nombra la hoja ẹ̀sọ. El tambor es un elemento cultural del tercer verso, sin relación con las ofrendas de las otras consultas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos sobre crianza y embarazo quedan separados. Se añade el canto «Jógede gbàgede» sobre el tambor. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=190;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata la responsabilidad de cuidar a los niños en circunstancias inquietantes. Konkọn consulta por el desasosiego de una nueva crianza; la gente de Ilara recibe una advertencia sobre un conflicto colectivo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La familia está cansada con la llegada de un hijo (relato de Konkọn).", "Las obligaciones nuevas traen contratiempos pasajeros.", "Hay una amenaza en la comunidad y hace falta un plan realista para proteger a los niños (relato de Ilara)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona calma y bienestar. Los relatos muestran la importancia de prever ayuda en la crianza y seguridad."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable habla de confusión si no se cultiva calma; no diagnostica enfermedad mental ni predice una batalla concreta."}, {"titulo": "Enseñanza principal", "texto": "El cuidado de niños requiere apoyo y medidas prácticas, más allá de una lectura general del signo."}, {"titulo": "Relatos reunidos", "puntos": ["Konkọn escucha un consejo antes de asumir la crianza de un recién nacido.", "Ilara recibe una advertencia sobre madres que llevarían a sus hijos para apartarse de una batalla."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El caso de Konkọn cita mortero, caracol, aceite de palma y cauríes; el de Ilara, plátanos y varias hojas además de otros elementos. Las listas no se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambas consultas. Konkọn y la comunidad de Ilara son protagonistas de relatos distintos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ifen, wọ̀rọ̀ y Jókó-jẹ se nombran como hojas. No se propone preparación médica."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Konkọn y de Ilara se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=191;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne crecimiento familiar y agrícola con una consulta por una dolencia. Otú recibe una predicción de hijos y frutos; Dejugbe pide ayuda por un brazo afectado."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme una enfermedad; conviene revisarse con un médico (relato de Dejugbe).", "La familia pregunta por embarazo o descendencia.", "Un trabajo del campo o de la familia empieza a dar frutos (relato de Otú)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona cuidado de la salud y crecimiento. El relato de Otú anuncia más nacimientos y frutos."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable menciona complicaciones del embarazo, pero no es una evaluación prenatal ni permite diagnosticar una dolencia del brazo."}, {"titulo": "Enseñanza principal", "texto": "Los dos relatos responden a preguntas distintas. Ante una lesión o embarazo con síntomas se necesita atención médica apropiada."}, {"titulo": "Relatos reunidos", "puntos": ["Otú consulta por crecimiento de la casa y la granja.", "Dejugbe consulta por una afección en un brazo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Otú recibe plátanos, kola, kola amarga y tierra; Dejugbe, palomas, gallinas, aceite de palma y cauríes. No se fusionan ni sustituyen atención sanitaria."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las dos consultas; los protagonistas se mantienen separados."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Plátanos, kola y kola amarga aparecen en la historia agrícola; el aceite de palma en la segunda. No se infiere un tratamiento médico."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Otú y Dejugbe se presentan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=192;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata el orden del tiempo y la conveniencia de hacer cada cosa en su momento. Ọ̀rúnmìlà pide a Olódùmarè dominio de la luz diurna y recibe conocimiento de los días y sus usos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita planear mejor lo que hace.", "Busca la aprobación de otros antes de actuar.", "Quiere escoger el momento adecuado para una tarea importante (relato de Ọ̀rúnmìlà y los días)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona claridad y buena fortuna con actuar en el momento apropiado."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte sobre decepción por esperar una validación que no corresponde. La narración de los días no crea por sí sola un calendario aplicable sin conocer la tradición concreta."}, {"titulo": "Enseñanza principal", "texto": "El relato distingue controlar el tiempo de comprenderlo. Planificar es una forma de responder a límites reales."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà pide poder sobre la luz del día; Olódùmarè le ofrece en cambio conocimiento del nombre y conveniencia de los días."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso menciona dieciséis caracoles, dieciséis gallinas y cauríes para la petición de Ọ̀rúnmìlà. No se vuelve una ofrenda general para toda agenda."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el relato y Olódùmarè responde a su petición."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El Sol aparece como medida del día; no se identifica una planta o alimento central."}, {"titulo": "Rezos, versos y cantos", "texto": "El relato del orden de los días se conserva como tradición narrada. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=193;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne dos asuntos de protección: la madre de Adepon consulta por sus hijos y Ọwá de Ìlẹ̀ṣà recibe una advertencia sobre un conflicto. La caracterización insiste en preparar estrategias."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le preocupa la salud de un niño; conviene llevarlo al médico (relato de Iyá Adepon).", "Se prepara para un conflicto real.", "La terquedad le impide atender avisos importantes (relato del Ọwá de Ìlẹ̀ṣà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona determinación con prepararse física, emocional y espiritualmente para un reto."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte del daño de no atender oportunamente una enfermedad infantil. El verso nombra lepra, pero no diagnostica a ningún niño actual; requiere evaluación médica ante síntomas."}, {"titulo": "Enseñanza principal", "texto": "Prepararse cambia según el problema: cuidado sanitario para una enfermedad y planes responsables para un conflicto."}, {"titulo": "Relatos reunidos", "puntos": ["Iyá Adepon recibe un consejo por sus hijos; el texto identifica su nombre con la fruta bomba.", "Ọwá de Ìlẹ̀ṣà recibe una advertencia de guerra y la desoye."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita aves negras y cauríes; el segundo, cabeza de carnero y cauríes. No se mezclan ni sustituyen tratamiento o medidas de seguridad."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las consultas. Iyá Adepon y Ọwá de Ìlẹ̀ṣà son personajes distintos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La fruta bomba se menciona como identificación del personaje Iyá Adepon."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos sobre hijos y conflicto se conservan diferenciados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=194;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo pregunta cómo hacer la vida más agradable y proteger a los niños. Ọ̀rúnmìlà y otras personas reciben una invitación a compartir; un árbol llamado Jẹwẹrẹ consulta al tener un hijo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita descansar y recuperar la alegría (relato de Ọ̀rúnmìlà y la vida más dulce).", "Tiene niños a su cargo que atender con responsabilidad.", "La familia teme que falte lo necesario tras el nacimiento de un hijo (relato del árbol Jẹwẹrẹ)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona bienestar con responsabilidad hacia otros. El primer verso presenta comida compartida y disfrute."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que descuidar necesidades de niños puede producir carencias. No predice pobreza ni enfermedad para toda familia."}, {"titulo": "Enseñanza principal", "texto": "La alegría de los niños exige también que los adultos provean cuidado; los dos versos sitúan placer y responsabilidad juntos."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà y otras personas consultan por una vida más dulce.", "El árbol Jẹwẹrẹ se preocupa por las necesidades de su nuevo hijo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita paloma, ave de Guinea, miel y cauríes; el segundo, palomas, gallinas y cauríes. Son listas de escenas distintas."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà figura en la primera consulta; Jẹwẹrẹ es el árbol personificado del segundo verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La fuente relaciona Jẹwẹrẹ con un árbol que da pimienta; la especie no queda verificada. La miel aparece en el primer relato."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de la vida agradable y del árbol se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=195;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo enlaza buena fortuna con compartir. Un árbol llamado Osan recibe el consejo de dar comida y bebida; otro relato presenta la llegada de una visitante con un niño."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Disfruta de recursos o de tranquilidad.", "Se pregunta cómo ayudar a alguien que lo necesita (relato del árbol Osan).", "Una visita va a traer cambios a la casa (relato de la mujer con el bebé a la espalda)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de cubrir necesidades básicas y de hacer buen uso de la prosperidad. El árbol Osan comparte sin quedar desprovisto en su relato."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que la preocupación excesiva puede impedir disfrutar lo que se tiene. La llegada de una visitante no garantiza fortuna en toda consulta."}, {"titulo": "Enseñanza principal", "texto": "Compartir una parte de lo recibido puede fortalecer vínculos. El consejo presupone que cada quien valore sus recursos y obligaciones reales."}, {"titulo": "Relatos reunidos", "puntos": ["Osan, un árbol personificado, recibe el consejo de compartir alimento y bebida.", "Un terrateniente espera a una mujer que lleva un lactante a la espalda."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de Osan cita sal, camarones, tela blanca y cauríes; el de la visitante, dos palomas y cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca los dos versos. El árbol y la visitante cumplen funciones narrativas distintas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Osan se nombra como árbol. Sal y camarones son alimentos del primer episodio."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Osan y del terrateniente permanecen separados; el encabezado posterior de Òtúrá pertenece al siguiente signo. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=196;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo habla de recuperar confianza después de pérdidas. Un verso presenta al maíz cuando llega al mundo; otro muestra a Olókun-Ṣonde, quien pasa de la espera a una posición de gran importancia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente inseguro después de una pérdida (relato del maíz Agbàdo).", "Hay un embarazo que le preocupa y conviene llevarlo con control médico.", "Espera una oportunidad y siente que su vida está detenida (relato de Olókun-Ṣonde, que llega a reina de las aguas)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La interpretación favorable relaciona claridad del propósito con dejar atrás un problema anterior. Olókun-Ṣonde recibe una predicción de grandeza."}, {"titulo": "Ibi y advertencias", "texto": "La interpretación desfavorable advierte contra arrogancia y conflictos familiares. El relato del maíz no anticipa el resultado de un embarazo humano."}, {"titulo": "Enseñanza principal", "texto": "La espera no define la capacidad de una persona. Olókun-Ṣonde actúa ante su consulta, mientras el maíz rechaza la suya."}, {"titulo": "Relatos reunidos", "puntos": ["Agbàdo, el maíz personificado, consulta al llegar al mundo.", "Olókun-Ṣonde espera un cambio y llega a ser reina de las corrientes de agua."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El maíz recibe una indicación de ropa nueva y chivo; Olókun-Ṣonde, recipientes de agua, carneras y cauríes. Son historias distintas."}, {"titulo": "Relaciones espirituales", "texto": "Olókun-Ṣonde es la protagonista del segundo relato y se asocia con corrientes de agua; Ifá enmarca su consulta."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El maíz es protagonista del primer verso. Los recipientes de agua aparecen en el segundo; no se derivan usos medicinales."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del maíz y de Olókun-Ṣonde se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=197;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo pide examinar una oportunidad atractiva antes de comprometerse. Otú, un barquero, conoce a Oyẹ y recibe una advertencia sobre la relación que desea iniciar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le atrae una relación, una sociedad o un negocio que parece prometedor (relato de Otú y Oyẹ).", "La atracción del momento no le deja ver las consecuencias.", "Busca algo que dure sin apresurarse."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable menciona la posibilidad de matrimonio o cierre de una etapa. La decisión depende de conocer a la otra persona y el contexto."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que el egoísmo puede hacer perder una relación. El peligro extremo del relato del barquero no convierte a una persona atractiva en amenaza real."}, {"titulo": "Enseñanza principal", "texto": "El deseo es un motivo para conocer mejor, no para decidir sin información. El verso pide evaluar antes de actuar."}, {"titulo": "Relatos reunidos", "puntos": ["Otú transporta pasajeros en su bote y se interesa por Oyẹ; recibe un consejo sobre las consecuencias de cortejarla."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El caso del barquero menciona aceite de palma y cauríes en su propia consulta. No se prescribe para cualquier vínculo afectivo."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù aparece como fuerza que podría influir en la acción de Otú dentro del relato. Oyẹ y Otú son personajes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El bote y el aceite de palma pertenecen a la historia; no se identifica una planta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de Otú y Oyẹ se conserva en su contexto. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=198;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo aconseja no decidir por impaciencia. Un verso anuncia fortuna en casa y en la granja; otro compara apresurarse con sorber sopa caliente y quemarse."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene una oferta y lo presionan para aceptarla ya (relato de Akinsuyi y la sopa demasiado caliente).", "Un proyecto empieza a dar resultados (relato de los bienes en casa y en la granja).", "Busca colaborar o servir a otros mientras llega algo mejor."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona cambio y servicio con una buena oportunidad. Los versos de Ọ̀rúnmìlà y Akinsuyi anuncian beneficios en sus situaciones."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que la impaciencia puede producir conflicto. Ningún relato garantiza que siempre llegue una segunda oferta superior."}, {"titulo": "Enseñanza principal", "texto": "Esperar lo suficiente para evaluar riesgos evita quemarse con la primera opción, como en la imagen de la sopa caliente."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe un anuncio de bienes en casa y la granja.", "Akinsuyi escucha la comparación con una sopa demasiado caliente."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso menciona carnera, paloma y cauríes; el segundo, chiva, gallina, pescado, rata y cauríes. Cada lista se conserva con su relato."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza la primera consulta; Akinsuyi la segunda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La sopa caliente es imagen de la prisa. Los animales citados son elementos de ofrendas distintas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Ọ̀rúnmìlà y Akinsuyi se separan. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=199;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona una sucesión familiar con el equilibrio de poder en la pareja. Orí-Awo recibe un anuncio sobre la corona de su padre; Adi teme la mirada de su esposa."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Puede tocarle asumir una responsabilidad de la familia o el lugar de su padre (relato de Orí-Awo).", "En una relación hay control o miedo (relato de Adi e Iyalẹta).", "Debe revisar lo que espera de una herencia y de su independencia."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de continuidad familiar. En el verso de Orí-Awo, la corona representa un cargo heredado."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de conflictos de pareja por dominio o miedo. La escena de Adi no justifica controlar ni someter a nadie."}, {"titulo": "Enseñanza principal", "texto": "Una responsabilidad heredada y una relación afectiva requieren acuerdos claros, no obediencia por temor."}, {"titulo": "Relatos reunidos", "puntos": ["Orí-Awo recibe la predicción de ocupar la posición de su padre.", "Adi va a casarse con Iyalẹta y se describe su temor ante ella."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Orí-Awo recibe una indicación de carnera. Adi recibe otra de tres gallos y cauríes; las ofrendas no se fusionan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambas consultas. Orí-Awo, Adi e Iyalẹta son protagonistas distintos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La solidificación del aceite de palma al amanecer aparece como explicación de la imagen de Adi, no como preparación medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de sucesión y matrimonio se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=200;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo contrapone apropiarse de lo ajeno con la paz que puede seguir a una conducta honesta. Onikoyi toma una propiedad que no le pertenece; Olú-Iwo recibe un anuncio de descanso para él y su esposa."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una sociedad está en riesgo por bienes en disputa.", "Está pensando usar algo que no es suyo y conviene devolverlo antes de que crezca el problema (relato de Onikoyi).", "La pareja busca tranquilidad después de un pleito (relato de Olú-Iwo y su esposa)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable vincula honestidad con desarrollo de capacidades y paz. El segundo verso anuncia descanso a Olú-Iwo."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que apropiarse de bienes ajenos puede desencadenar un pleito. El caso de Onikoyi requiere devolución y comprobación de propiedad."}, {"titulo": "Enseñanza principal", "texto": "La paz no se obtiene reteniendo lo que no corresponde. Resolver la disputa material ayuda a cuidar una relación."}, {"titulo": "Relatos reunidos", "puntos": ["Onikoyi es advertido de devolver bienes ajenos antes de que el asunto crezca.", "Olú-Iwo y su esposa reciben un anuncio de tranquilidad."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Onikoyi recibe una lista de caracoles y cauríes; Olú-Iwo, paloma y cauríes. Las listas no sustituyen resolver la disputa real."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambas consultas. Onikoyi y Olú-Iwo pertenecen a relatos separados."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Los elementos rituales mencionados no forman un remedio botánico."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Onikoyi y Olú-Iwo se mantienen diferenciados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=201;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reflexiona sobre la muerte y la continuidad de los vínculos, al tiempo que pide atender a los hijos presentes. Un verso habla de viajeros entre tierra y cielo que volverán a encontrarse."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está pasando por un duelo (reflexión sobre el viaje entre la tierra y el cielo).", "Le da miedo decidir y está aplazando un cambio.", "Ha tenido poco tiempo para sus hijos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona valentía con afrontar un cambio inesperado. El verso ofrece una imagen espiritual de continuidad para quienes lamentan una pérdida."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que el miedo a equivocarse puede generar caos. La idea de reencuentro espiritual es una creencia del verso, no un hecho comprobable para toda persona."}, {"titulo": "Enseñanza principal", "texto": "Reconocer la finitud puede ayudar a dedicar tiempo y cuidado a quienes están aquí. En duelo real, cada persona necesita su propio ritmo y apoyo."}, {"titulo": "Relatos reunidos", "puntos": ["Los seres humanos lamentan la muerte y escuchan una reflexión sobre el viaje entre la tierra y el cielo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El pasaje de duelo debe conservar su propio contexto; no se deduce de él un ẹbọ único ni una práctica obligatoria."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca la reflexión sobre vida y muerte. La imagen de viajeros une plano físico y espiritual en el relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Las termitas aparecen como imagen de separación y reunión. No se propone una planta o medicina."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso del reencuentro se conserva como formulación espiritual. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=202;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo pide respetar los límites que correspondan a la consulta y evitar acusaciones sin pruebas. Ọlobẹde Ipetu recibe un consejo antes de salir al campo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le cuestionan sus opiniones.", "Corre un rumor o una acusación que hay que verificar.", "Debe aclarar qué tiene prohibido antes de actuar (relato de Ọlobẹde Ipetu, que rechaza la indicación)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona cambio interior con apartarse del chisme y examinar los hechos."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que repetir rumores puede aumentar egoísmo y daño. El breve verso del campo no basta para reconstruir una prohibición universal."}, {"titulo": "Enseñanza principal", "texto": "Un tabú tradicional solo se aplica cuando se conoce su contexto; en asuntos cotidianos, es mejor comprobar antes de acusar."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlobẹde Ipetu escucha una indicación sobre un chivo y su cuchillo antes de ir a la granja, pero la rechaza."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso menciona chivo y cuchillo del campo. No se añade una lista ni un resultado no conservado en el pasaje examinado."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca la consulta de Ọlobẹde Ipetu, protagonista del relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El cuchillo es herramienta del campo en el verso; no se identifica una planta o remedio."}, {"titulo": "Rezos, versos y cantos", "texto": "Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=203;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata conflictos causados por palabras y procedimientos. Alafura escucha comparaciones sobre discusiones innecesarias; otro verso narra un matrimonio complicado por un compromiso previo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Habla sin pensar y puede abrir un pleito.", "Hay un compromiso anterior que debe aclararse antes de un matrimonio o un trato (relato de Òtú y la hija de Ọlófin).", "Un litigio se puede evitar con hechos y diálogo (relato de Alafura)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de proteger una oportunidad mediante prudencia. El segundo relato ofrece una salida, pero depende de su situación concreta."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que discusiones evitables pueden terminar en aislamiento o pleito. La primera historia no prohíbe defender un derecho legítimo."}, {"titulo": "Enseñanza principal", "texto": "Reducir las provocaciones y conocer los compromisos existentes ayuda a evitar conflictos innecesarios."}, {"titulo": "Relatos reunidos", "puntos": ["Alafura escucha que el ladrido del perro y el bramido del carnero no deberían convertirse en disputas.", "Òtú quiere casarse con Ọ̀kànràn, hija de Ọlófin, pese a un compromiso previo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El segundo verso menciona caracoles, paloma y cauríes. No se transforma en solución automática para un conflicto legal o matrimonial."}, {"titulo": "Relaciones espirituales", "texto": "Ọlófin es padre de Ọ̀kànràn en el segundo relato; Ifá enmarca ambas consultas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Leopardo, halcón, perro y carnero son comparaciones narrativas. No se propone preparación medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Alafura y del matrimonio quedan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=204;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo habla de enfrentar el efecto de ofensas y de conductas pasadas. Un canto pide que el camino se ordene y que las maldiciones no alcancen a quien habla."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente agobiado por insultos o enemistades.", "Algo que hizo antes le quitó apoyo de la gente.", "Busca renovarse espiritualmente y cambiar conductas concretas."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona la eliminación de obstáculos con revisar la propia conducta y recibir ayuda."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que no corregir un daño anterior puede prolongar el conflicto. El canto no demuestra que una maldición específica exista."}, {"titulo": "Enseñanza principal", "texto": "La limpieza de cabeza del relato es una práctica tradicional situada; reparar una relación o cambiar hábitos exige acciones observables."}, {"titulo": "Relatos reunidos", "puntos": ["Una voz dice que le han deseado mal, pero que no han logrado dañarla, y pide a Òtúrá Ògúndá enderezar su camino."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El pasaje menciona una limpieza de cabeza en su contexto. No se prescribe aquí una preparación ni se la presenta como tratamiento médico."}, {"titulo": "Relaciones espirituales", "texto": "El canto invoca al signo y a la protección espiritual; no atribuye sin prueba una entidad nueva."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La cabeza y el camino son imágenes centrales del canto."}, {"titulo": "Rezos, versos y cantos", "texto": "Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=205;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo contrapone calma ante una dificultad y despreocupación imprudente en los negocios. Olókun consulta por bienestar; un pato que vende mercancías se ríe de la posibilidad de compradores que no paguen."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está irritable y eso provoca discusiones (relato de Olókun y la frescura del cuerpo).", "Alguien le compra a crédito y no le paga (relato del pato comerciante Pepeye).", "Necesita responder con calma a un problema."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona serenidad con capacidad de anticipar riesgos. Olókun recibe un consejo sobre frescura y bienestar."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que el enojo o la burla ante un riesgo pueden llevar a pérdidas. El verso del pato no identifica a deudores reales."}, {"titulo": "Enseñanza principal", "texto": "Mantener la calma no es ignorar el riesgo: conviene registrar acuerdos y pagos de forma clara."}, {"titulo": "Relatos reunidos", "puntos": ["Olókun consulta para mantener la frescura de su cuerpo.", "Pepeye, el pato comerciante, rechaza una advertencia sobre ventas sin pago."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las listas rituales son distintas: Olókun recibe aceites, animales y otros elementos; el pato, paloma y cauríes. Ninguna reemplaza controles comerciales o atención médica."}, {"titulo": "Relaciones espirituales", "texto": "Olókun es protagonista de la primera consulta; el pato personificado, de la segunda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma y otros aceites se citan en el primer relato; no se propone uso terapéutico."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Olókun y del pato se muestran por separado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=206;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òtúrá Ìká reúne una petición de protección y dos consultas distintas: Adeyibo teme un robo o una imputación, mientras Ilé-sanmi espera salir de la pobreza. El canto inicial pide disipar acciones adversas; no identifica por sí solo un agresor real."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente amenazado o envidiado y busca limpieza o protección.", "Teme que lo relacionen con un robo, sufrir uno o enfrentar falsos testimonios (relato de Adeyibo).", "Ha pasado pobreza o adversidades y espera un cambio en su economía (relato de Ilé-sanmi)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona protección con crecimiento y abundancia. En el tercer verso, Ọ̀rúnmìlà explica que Òtúrá “cuenta dinero”; Ilé-sanmi escucha que llega un año próspero y cumple su ofrenda."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable menciona comportamiento impropio y la posibilidad de una acusación de robo. Adeyibo oye la indicación pero la rechaza; la narración no relata después un fallo judicial. El canto sobre brujería no demuestra una agresión sobrenatural concreta."}, {"titulo": "Enseñanza principal", "texto": "Una sensación de amenaza requiere separar hechos, sospechas y deseos de protección. Los tres textos ofrecen contextos diferentes: una súplica, una advertencia de robo y un anuncio de prosperidad."}, {"titulo": "Relatos reunidos", "puntos": ["El canto llama a la muerte y la enfermedad por nombres propios, compara la libertad del elefante y el búfalo, y pide disipar acciones adversas.", "Adeyibo recibe una advertencia sobre robo o falsos testimonios y rechaza la ofrenda.", "Ilé-sanmi consulta cuando está rodeado de adversidades; Ọ̀rúnmìlà anuncia dinero y el personaje cumple la indicación."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Para Adeyibo se citan cuatro caracoles babosa, una paloma, 16.000 cauríes y una preparación de Ifá no descrita. Para Ilé-sanmi, cuatro palomas y 3.200 cauríes. El canto de protección no aporta una lista única."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà interviene en el verso de Ilé-sanmi. Ifá enmarca las consultas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Elefante y búfalo funcionan como comparaciones de libertad en el canto. Los caracoles babosa y palomas pertenecen a la lista de Adeyibo; no se infiere un remedio vegetal."}, {"titulo": "Rezos, versos y cantos", "texto": "Súplica de protección, relato de Adeyibo y consulta de Ilé-sanmi permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=207;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo habla de cumplir lo que se ha decidido y respetar una prohibición ritual situada. Ọbàtálá recibe indicaciones antes de ocupar un lugar en el mundo; Olubolade consulta por su futura familia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Carga burlas o malos tratos.", "Cumplió solo una parte de una promesa o de lo que le indicaron (relato de Ọbàtálá).", "Pregunta por pareja e hijos (relato de Olubolade)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona bienestar con atender el consejo completo que corresponde al relato de Ọbàtálá."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que desatender una prohibición puede causar problemas. La restricción del vino de palma en el verso pertenece a Ọbàtálá y no se impone a todos los consultantes."}, {"titulo": "Enseñanza principal", "texto": "Cumplir a medias puede no resolver el asunto planteado. El relato de Olubolade responde a otra preocupación familiar."}, {"titulo": "Relatos reunidos", "puntos": ["Ọbàtálá recibe tela blanca, una prohibición sobre vino de palma y otras indicaciones, pero cumple solo una parte.", "Olubolade pregunta por pareja y descendencia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La consulta de Ọbàtálá menciona tela blanca, caracol y cauríes; la de Olubolade, aves distintas y cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ọbàtálá es protagonista del primer relato; Ifá enmarca ambos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Vino de palma y tela blanca son elementos del episodio de Ọbàtálá. No se extrae un tratamiento de salud."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Ọbàtálá y Olubolade se muestran por separado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=208;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo pone la moderación en el centro de la vida personal y colectiva. Un verso pregunta quién sabe moderarse; otro trata la prevención de conflictos durante el gobierno de Ewi en Ado."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Gasta o actúa sin medida (relato de Ọ̀rúnmìlà y la moderación).", "Hay malentendidos en un grupo que pueden crecer (relato de Ewi, rey nuevo de Ado).", "Quiere reafirmar su práctica espiritual."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona determinación con entenderse a sí mismo y actuar con mesura. El relato de Ewi imagina un gobierno sin guerra."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de terquedad cuando se desatienden asuntos espirituales. Un complot del verso no autoriza a sospechar de personas actuales sin pruebas."}, {"titulo": "Enseñanza principal", "texto": "La respuesta del canto define moderación con ejemplos concretos: trabajar, evitar derroches y no robar."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà responde repetidamente a la pregunta sobre quién conoce la moderación.", "Ewi, rey nuevo de Ado, consulta para evitar guerra y malentendidos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ewi cita aves de Guinea y palomas blancas. No se atribuye esa lista al diálogo sobre moderación."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà responde en el primer canto; Ewi es el gobernante del segundo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Las aves de la ofrenda pertenecen al relato de Ewi; no se identifica una planta central."}, {"titulo": "Rezos, versos y cantos", "texto": "El diálogo y el verso de Ewi se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=209;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo aborda la protección frente a un conflicto y la superación de contratiempos. Otú consulta antes de una batalla; la comunidad de Ọ̀yọ́ atiende otra dificultad; Eyó aparece en un tercer episodio."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Un pleito amenaza su casa o su trabajo (relato de Otú antes de combatir).", "Quiere conservar algo que logró.", "Un grupo tiene problemas repetidos y necesita organizarse (relato de la gente de Ọ̀yọ́ y el jabón)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona cuidado y perseverancia con continuidad de la buena fortuna. El verso de Ọ̀yọ́ cuenta que cesan sus contratiempos."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte sobre pérdida por descuidar un riesgo. Las batallas de los versos son escenas históricas o narrativas, no anuncios de guerra en una consulta actual."}, {"titulo": "Enseñanza principal", "texto": "La respuesta debe ajustarse al problema: Otú, Ọ̀yọ́ y Eyó afrontan circunstancias distintas."}, {"titulo": "Relatos reunidos", "puntos": ["Otú consulta antes de combatir en Ajaṣe.", "La gente de Ọ̀yọ́ usa jabón en un relato sobre apartar dificultades.", "Eyó recibe otra advertencia ante un sitio."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Cada relato tiene su propia lista: chivos para Otú; esuru, jabón y animales para Ọ̀yọ́; chivos para Eyó. No se fusionan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las consultas. Ọ̀yọ́ y Eyó son comunidades, no entidades espirituales."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Esuru se nombra como elemento del segundo relato."}, {"titulo": "Rezos, versos y cantos", "texto": "Los tres versos se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=210;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo une una buena oportunidad con el deber de no aceptar consejo dañino. Olújimi espera una fortuna; Ọlófin escucha una advertencia sobre una opinión capaz de desordenar su ciudad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se acerca una propuesta favorable (relato de Olújimi).", "Una infidelidad podría dañar la relación.", "Alguien le aconseja algo que perjudicaría a otros (relato de Ọlófin Iwatuka)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona fidelidad y fortuna. El primer verso anuncia un bien que puede llegar a manos de Olújimi."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte sobre el daño de una falta de fidelidad o de adoptar un consejo malvado. No identifica a una persona actual como infiel."}, {"titulo": "Enseñanza principal", "texto": "Aceptar un beneficio no exige abandonar el juicio moral: el segundo relato pide examinar el efecto de una decisión sobre toda la comunidad."}, {"titulo": "Relatos reunidos", "puntos": ["Olújimi espera una entrega de buena fortuna y escucha una advertencia sobre adulterio.", "Ọlófin Iwatuka recibe una recomendación para no aceptar una opinión que desorganizaría la ciudad."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Olújimi recibe tela blanca, semillas, palomas blancas y cauríes; Ọlófin, chiva, gallinas, aceite de palma, cauríes y hojas. Son consultas distintas."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambos versos. La diosa del dinero se menciona en el anuncio a Olújimi; Ọlófin gobierna la ciudad del otro relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ifere se nombra como semilla y kolejo como hoja. No se propone uso médico."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=211;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne prosperidad, descendencia y reciprocidad en dos consultas. Olókun recibe un anuncio de riqueza e hijos; Akisa ofrece miel a su Ifá y recibe miel después."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Busca mejorar su economía o su relación (relato de Olókun).", "Desea hijos o una relación más intensa.", "Necesita seguir siendo humilde mientras le llegan bienes."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona apertura con la atención a Olókun. Su verso anuncia recursos y familia."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que la arrogancia puede acompañar un logro. No se deriva de ahí un diagnóstico de enfermedad."}, {"titulo": "Enseñanza principal", "texto": "El relato de Akisa subraya la reciprocidad: lo que entrega y lo que recibe pertenecen a la misma escena."}, {"titulo": "Relatos reunidos", "puntos": ["Olókun consulta y luego obtiene recursos e hijos.", "Akisa ofrece miel, aadun y kola a Ifá en una consulta distinta.", "Una versión pregunta si las aguas de Olókun se extenderán por la tierra y presenta esa expansión como imagen de grandeza."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Olókun recibe una indicación de carnera y cauríes; Akisa, miel, aadun y kola. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Olókun es protagonista de la primera consulta e Ifá recibe la ofrenda de Akisa en la segunda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Miel, aadun y kola se nombran como alimentos rituales; no se presentan como remedio."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Olókun y Akisa se conservan diferenciados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=212;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo llama a revisar una conducta centrada solo en uno mismo y a cuidar a la familia. Orifusi busca protegerse junto con su esposa e hijos cuando su fama aumenta."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["El egoísmo está dañando un negocio o la relación familiar.", "Teme perder a los suyos al hacerse conocido (relato de Orifusi).", "Necesita revisar si está actuando con honestidad.", "Va a viajar y pregunta si volverá con bienes pese a los adversarios."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable vincula perseverancia y práctica espiritual con continuidad familiar."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte contra mentira y robo. La muerte mencionada en el relato expresa el temor de Orifusi; no es un pronóstico literal para quien recibe el signo."}, {"titulo": "Enseñanza principal", "texto": "La prosperidad que descuida a la familia puede dejar de ser un bien compartido. El relato plantea la protección de todos, no solo de quien consulta."}, {"titulo": "Relatos reunidos", "puntos": ["Orifusi busca una manera de cuidar a su familia cuando su nombre se hace conocido; varios adivinos participan en la consulta.", "Ọ̀rúnmìlà viaja a una localidad lejana y pregunta si regresará con bienes pese a encontrar adversarios."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las indicaciones del relato pertenecen a la situación de Orifusi. La síntesis no construye una ofrenda universal de un pasaje abreviado."}, {"titulo": "Relaciones espirituales", "texto": "Ifá es el marco de la consulta. Orifusi, su esposa, hijos y adivinos son participantes distintos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se nombra una mata de palma entre los lugares o nombres de adivinos; no se convierte en una receta."}, {"titulo": "Rezos, versos y cantos", "texto": "El relato largo de Orifusi se mantiene en su signo. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=213;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata el riesgo de intrigas y la paciencia para responder a ellas. Ọlófin recibe una advertencia de guerra; otro canto describe la iniciación de Ìwòrì por Ìrẹtẹ̀."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Nota tensiones o maniobras dentro de un grupo (relato de Ọlófin Iwatuka y la guerra).", "La frustración lo empuja a actuar con enojo.", "Busca respeto y aprendizaje en su práctica espiritual.", "Siente que le falta fortuna y quiere entender por qué."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona determinación con preparación y guía. El canto de iniciación habla de autoridad y reconocimiento en su contexto."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de un conflicto que puede afectar seriamente la vida. No confirma una conspiración actual sin hechos."}, {"titulo": "Enseñanza principal", "texto": "Prepararse y escuchar antes de reaccionar conserva más opciones que una respuesta impulsiva."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlófin Iwatuka escucha una advertencia sobre guerra y no sigue el consejo.", "Un canto repite que Ìrẹtẹ̀ está iniciando a Ìwòrì y anuncia respeto.", "Ọ̀rúnmìlà, afligido por falta de fortuna, pide una consulta más detallada; otro episodio trata una celebración rodeada de peligros."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La lista de huevos, carnero, chivo, gallo y cauríes pertenece a Ọlófin. El canto de iniciación no recibe esa misma lista."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca el primer relato; Òrìṣà aparece en las palabras del segundo canto."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Àgbe y Àlùkò son aves en las imágenes del canto. No se infiere un uso botánico."}, {"titulo": "Rezos, versos y cantos", "texto": "El relato de Ọlófin y el canto de iniciación se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=214;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo aborda la resistencia al cambio y la ayuda que puede llegar de otros. Ọlọ no quiere levantarse de donde está sentada; después de atender el consejo, se anuncia que alguien la transportará."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Sigue en una situación que ya no le conviene (relato de Ọlọ, que no quiere levantarse).", "Una relación necesita replantearse.", "Necesita aceptar ayuda para avanzar.", "Su casa lo descuida y aun así sigue con su deber."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona un nuevo comienzo con recibir ayuda de otras personas."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de dificultades en una relación si la rigidez impide hablar. El relato de Ọlọ no diagnostica incapacidad física."}, {"titulo": "Enseñanza principal", "texto": "La autonomía y la ayuda no se excluyen: cambiar de lugar puede requerir apoyo."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlọ se resiste a levantarse, atiende una consulta y recibe la promesa de ser llevada por alguien.", "Ọ̀rúnmìlà continúa atendiendo a Ifá cuando su casa lo descuida; otro relato presenta a Olúòhòròbí, identificado con una abeja, aprendiendo generosidad."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso cita dos palomas, cauríes y hojas de gbégbé para Ọlọ. No se vuelve una indicación universal."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca los relatos; Ọlọ, Ọ̀rúnmìlà y Olúòhòròbí aparecen en escenas distintas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Gbégbé aparece como nombre de hoja. No se recomienda su uso."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de Ọlọ se conserva en su secuencia. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=215;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ìrosùn trata la presión causada por dificultades imprevistas y la importancia de prepararse con formación y criterio. Ọlófin recibe un aviso para evitar un problema aún no ocurrido; otras lecturas relacionan determinación con llegar a ser una autoridad bien entrenada."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente presionado seguido y no sabe bien de dónde viene la presión.", "Un obstáculo inesperado podría afectar un plan (relato de Ọlófin).", "Busca prepararse para asumir una responsabilidad o una autoridad (relato de Ọ̀rúnmìlà y su aprendiz)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable vincula determinación y aprendizaje con la satisfacción del potencial. La referencia a convertirse en autoridad exige entrenamiento, no solo deseo de ocupar un puesto."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que la testarudez puede crear resistencia al cambio y agravar una dificultad inesperada. El aviso no permite anunciar un desastre concreto ni atribuirle una causa oculta."}, {"titulo": "Enseñanza principal", "texto": "Prepararse para lo inesperado significa aprender, revisar opciones y actuar con flexibilidad. El pasaje de Ọlófin advierte sin afirmar que el problema ya haya sucedido."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlófin recibe una indicación ritual para que no llegue un problema imprevisto. La traducción repite el consejo dos veces y termina sin narrar un desenlace.", "En otros cantos vinculados con el signo, Ọ̀rúnmìlà aparece enseñando a un aprendiz y se mencionan entidades que viajan del cielo a la Tierra; esos pasajes se mantienen separados del caso de Ọlófin."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Para la situación de Ọlófin se enumeran paloma blanca, gallina blanca y 2.400 cauríes. No se extiende esta lista a los otros cantos ni a toda persona que se sienta presionada."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca la consulta de Ọlófin; Ọ̀rúnmìlà pertenece al canto de aprendizaje. Las entidades del viaje no se atribuyen automáticamente a la escena de Ọlófin."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aves blancas y cauríes son elementos de la ofrenda descrita. No se identifica una planta ni una preparación medicinal en el pasaje de Ọlófin."}, {"titulo": "Rezos, versos y cantos", "texto": "La expresión sobre el problema imprevisto se conserva sin completar el desenlace. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=216;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne reputación, protección y duración. Ọ̀rúnmìlà recibe una predicción sobre conspiradores; Temitayo consulta por una vida larga."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme perder un puesto o su buen nombre.", "Un rumor le da miedo de que lo calumnien (relato de Ọ̀rúnmìlà frente a los conspiradores).", "Quiere que un logro dure y busca una vida larga (relato de Temitayo).", "Hay pretendientes y una decisión de matrimonio en la familia (relato de Lépolátà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona determinación con protección frente a cambios. El segundo verso presenta el nombre de Temitayo unido a superación."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que el miedo a calumnias puede causar confusión. El primer verso no prueba que haya conspiradores en una consulta actual."}, {"titulo": "Enseñanza principal", "texto": "La reputación se cuida con hechos y constancia, no solamente respondiendo a rumores."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe un anuncio de honor frente a quienes conspiran.", "Temitayo consulta por longevidad y buena fortuna.", "Un relato de matrimonio presenta a Ọ̀rúnmìlà y otros pretendientes de Lépolátà; sus detalles no se convierten en reglas actuales sobre con quién debe casarse una hija."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ọ̀rúnmìlà cita carnera, ave de Guinea y cauríes; el de Temitayo, carnera, paloma, peperẹku y cauríes. Son listas distintas."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà y Temitayo protagonizan consultas separadas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Peperẹku se nombra como hierba sin especie identificada; no se recomienda como tratamiento."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de honor y longevidad permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=217;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo plantea conservar los propios principios en medio de oposición. Ọ̀rúnmìlà Alade aparece rodeado de adversarios y otro canto nombra hojas de Ifá y bendiciones."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme una estafa o un engaño.", "Lo presionan para abandonar un ideal.", "Quiere salir de sus problemas sin traicionar sus valores (relato de Ọ̀rúnmìlà Alade).", "Pasa por un cambio y otros creen que ya desapareció (relato del halcón que muda sus plumas)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable vincula firmeza interna con transformación. El verso de Ọ̀rúnmìlà anuncia superar a quienes se le oponen."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de egoísmo al abandonar principios por conveniencia. Una oposición del relato no identifica enemigos reales."}, {"titulo": "Enseñanza principal", "texto": "Sostener un ideal exige también revisar las reglas y comprobar la confianza que se deposita en otros."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà Alade consulta al verse rodeado de adversarios.", "Un segundo canto invoca bendiciones sobre una medicina de hojas, sin convertirlas en una fórmula general.", "Un halcón muda sus plumas y otros creen que desapareció; otro canto pregunta por la dulzura de la vida de Ọ̀rúnmìlà."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato de Ọ̀rúnmìlà cita chivo y cauríes. El canto de hojas pertenece a otra pieza y no autoriza una preparación médica."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el primer verso. Ifá enmarca las consultas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tẹ̀tẹ̀ se menciona en una comparación de rapidez."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de Ọ̀rúnmìlà y el canto de hojas se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=218;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo llama a distinguir competencia profesional de confianza personal. En un relato, Ọ̀rúnmìlà recibe una advertencia sobre una reunión en casa de Ọlófin. Otro relato extenso se ocupa de dar nombres propios y de renovar lo que se ha gastado: distingue a cada ser dentro de su comunidad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente amenazado por compañeros de trabajo (relato de los adivinos que planean envenenar a Ọ̀rúnmìlà).", "No sabe en quién confiar dentro de su oficio.", "Una invitación o un encuentro pide prudencia.", "Un grupo está preocupado por el bienestar de quien lo dirige."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona determinación con nuevas oportunidades al protegerse de intrigas."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de aislamiento por no distinguir aliados y rivales. El envenenamiento del relato no prueba una conspiración actual."}, {"titulo": "Enseñanza principal", "texto": "Ser prudente exige comprobar hechos y cuidar límites, sin acusar indiscriminadamente a los colegas. El relato de los nombres enseña que identificar a cada cual permite atribuir responsabilidades y cuidar la continuidad de la comunidad."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà escucha que unos adivinos planean envenenarlo en casa de Ọlófin y recibe una indicación de ayunar ese día.", "Otro relato habla del matrimonio de Àgbongbòn y Lánrete y de sus hijos; permanece separado de la intriga entre colegas.", "Ọ̀rúnmìlà visita sucesivamente a las ratas, los peces, las aves y otros seres; les asigna nombres individuales y canta el intercambio de objetos viejos por nuevos cuando sus dirigentes están en dificultades."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El relato menciona aceite de palma y cauríes. El ayuno es una indicación situada; no se recomienda a personas con necesidades de salud sin orientación adecuada. En ese relato se mencionan una estera, ropa, azada y machete, cada uno en versión usada y nueva. Es una escena ritual propia del cuento, no una lista general del signo."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà y Ọlófin pertenecen a la escena; los adivinos son participantes del relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma se cita como elemento ritual, no como antídoto. La estera, la ropa y las herramientas usadas y nuevas son símbolos de renovación; no se describen plantas medicinales en ese episodio."}, {"titulo": "Rezos, versos y cantos", "texto": "El relato se conserva en su signo sin atribuirlo a otro encuentro. El canto repetido «Paarò paarò» acompaña la escena de intercambio. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=219;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne alivio mediante iniciación en un relato vegetal y prosperidad después de dificultades en otro. Pèrègún consulta por comodidad; Ọ̀rúnmìlà pregunta por el fin de una etapa pobre."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Busca crecer espiritualmente (relato de Pèrègún).", "Un problema que lleva mucho tiempo exige disciplina.", "El trabajo no da frutos y espera una mejora (relato de Ọ̀rúnmìlà).", "Piensa buscar fortuna fuera de su lugar de origen."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable vincula determinación y práctica sostenida con despejar obstáculos. El segundo verso anuncia un año de recursos a Ọ̀rúnmìlà."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de pérdida de respeto si se rechaza una disciplina asumida. No impone iniciación a toda persona."}, {"titulo": "Enseñanza principal", "texto": "El alivio de Pèrègún y la fortuna de Ọ̀rúnmìlà pertenecen a historias distintas; ambas destacan continuidad de acción."}, {"titulo": "Relatos reunidos", "puntos": ["Pèrègún, planta personificada, recibe una indicación de iniciación.", "Ọ̀rúnmìlà consulta en medio de dificultades económicas.", "Una comunidad consulta por riqueza fuera de su lugar de origen; esa historia no obliga a toda persona a emigrar."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Pèrègún recibe plátanos, manteca de cacao y cauríes; Ọ̀rúnmìlà, paloma, gallina, camarones y cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las consultas; Ọ̀rúnmìlà es protagonista del segundo verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pèrègún y tẹ̀tẹ̀ se nombran como plantas. Plátanos aparecen en la primera ofrenda."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=220;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo presenta la preparación como una forma de cuidado. Un verso trata una guerra entre gente de tierra y cielo; otro anuncia victoria a Adurojà-Abayako."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay competencia en el amor o en la comunidad.", "Un pleito puede crecer si no planea cómo responder (relato de Adurojà-Abayako).", "Teme parecer cobarde por tomar precauciones.", "Se siente atrapado y busca una salida (relato de las ranas en la zanja).", "Desea hijos (relato de Osúnláyà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable vincula planear con protección y abundancia. El segundo verso anuncia superar oposición."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que rehusar prepararse puede empeorar un conflicto. Las guerras del canto son narrativas, no anuncios literales."}, {"titulo": "Enseñanza principal", "texto": "Prevenir un motín no es cobardía, dice el verso; actuar con anticipación puede evitar daño."}, {"titulo": "Relatos reunidos", "puntos": ["Los habitantes de tierra y cielo reciben consejos en medio de una guerra.", "Adurojà-Abayako recibe una indicación frente a adversarios.", "Unas ranas atrapadas en una zanja buscan salida en otra narración. En el relato siguiente del mismo signo, Osúnláyà consulta por descendencia y celebra el nacimiento de hijos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer relato incluye calabazas con miel y otros elementos de su disputa; el segundo, carnero, gallo y cauríes. No se fusionan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las consultas. Tierra y cielo aparecen como colectivos narrativos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Abejas y hormigas funcionan como imágenes de dejar huellas al marcharse; la miel figura en una ofrenda específica."}, {"titulo": "Rezos, versos y cantos", "texto": "Los cantos de los dos conflictos permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=221;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona destreza con mayor responsabilidad. Ọ̀rúnmìlà recibe numerosas consultas; el rey de Benín pregunta por su capacidad de gobernar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Compite por un cargo o un ascenso.", "Su buena fama le está trayendo más trabajo (relato de Ọ̀rúnmìlà y las consultas de muchos lugares).", "Necesita mandar con habilidad y moderación (relato del rey de Benín).", "Alguien puede aprovecharse de lo que él cosechó (relato de la tortuga)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable anuncia reconocimiento por el trabajo y la posibilidad de un puesto mayor."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que un liderazgo deficiente puede malgastar una oportunidad. El anuncio del rey no garantiza una promoción actual."}, {"titulo": "Enseñanza principal", "texto": "La fama exige capacidad para atender las tareas que atrae. Los dos versos prueban habilidades en ámbitos diferentes."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe consultas desde muchos lugares.", "El rey de Benín recibe un anuncio sobre gobernar con destreza.", "Un canto pregunta por hijos para la okra y la berenjena; otro presenta una tortuga que aprovecha una cosecha ajena."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El caso de Ọ̀rúnmìlà cita palomas y cauríes; el del rey, una soga para trepar palmas y cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza el primer verso; el rey de Benín, el segundo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La soga de palma se nombra como herramienta del relato del rey, no como planta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del adivino y del rey se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=222;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne una consulta por descendencia y otra sobre autoridad. Adán, el murciélago, y Oode desean hijos; Ọbàtálá aparece en una escena distinta."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere que tomen en serio sus ideas.", "Pregunta por hijos (relato de Adán y Oode).", "Necesita un trato justo con una autoridad (relato de Ọbàtálá).", "Quiere dejar su propia huella (relato del grillo)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona determinación y justicia con bienestar. El primer verso anuncia descendencia a sus protagonistas."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte del daño de tratar injustamente a otros. El relato de animales no confirma infertilidad humana."}, {"titulo": "Enseñanza principal", "texto": "La autoridad gana legitimidad cuando escucha con justicia; la pregunta por hijos conserva su propio contexto."}, {"titulo": "Relatos reunidos", "puntos": ["Adán y Oode consultan para tener hijos.", "Ọbàtálá es presentado en un relato sobre honor y trato recibido.", "Un grillo intenta dejar una marca propia y atiende solo una parte del consejo; otros versos del conjunto vuelven a la pregunta por hijos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita gallinas, cabras y cauríes. La escena de Ọbàtálá no debe absorber esa lista."}, {"titulo": "Relaciones espirituales", "texto": "Ọbàtálá aparece en el segundo verso; Adán y Oode son personajes del primero."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pitón, boa, elefante y mariwo figuran en imágenes del segundo verso; no se infiere una receta botánica."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de descendencia y autoridad permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=223;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo mira una amenaza de muerte o enfermedad mediante un canto tradicional que invoca protección. El texto recuerda a personas fallecidas y presenta a Ọ̀rúnmìlà ante ese temor."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le preocupa un problema de salud repentino; conviene atención médica.", "Una pérdida reciente le da miedo (canto de Ọlamba y Eji-Ogogo).", "Quiere entender una dificultad sin negarla.", "Hay un asunto familiar que pide perdón, sin aguantar maltratos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable asocia determinación con protección espiritual y comprensión."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de sufrir más por resistirse a entender lo que ocurre. El canto no sustituye diagnóstico, atención urgente ni tratamiento médico."}, {"titulo": "Enseñanza principal", "texto": "Ante síntomas nuevos, la primera respuesta debe ser atención adecuada; el relato espiritual puede acompañar sin reemplazarla."}, {"titulo": "Relatos reunidos", "puntos": ["Un canto recuerda a Ọlamba y Eji-Ogogo y sitúa a Ọ̀rúnmìlà frente a la pregunta por la muerte.", "Una historia sobre dos esposas y el perdón pertenece a una situación familiar específica; no impone tolerar maltrato."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los relatos de este signo no detallan una ofrenda específica."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà protagoniza la consulta. Los fallecidos son nombres recordados en el canto."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El viento mueve hojas de coco en una imagen del verso; no se deriva un remedio vegetal."}, {"titulo": "Rezos, versos y cantos", "texto": "Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=224;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne protección espiritual, autonomía y conflictos de autoridad. Un canto emplea imágenes de púas; otro reflexiona sobre dos poderes que no deben aplastarse."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme un pleito con una autoridad.", "Quiere actuar por su cuenta.", "Se siente rodeado de hostilidad o de rumores."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona firmeza y protección con una mejora de recursos."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que abandonar la propia responsabilidad puede debilitar la posición. Las referencias a hechicería pertenecen al lenguaje del canto, no confirman un ataque real."}, {"titulo": "Enseñanza principal", "texto": "Un conflicto entre poderes exige límites y proporción; el verso sobre dos cosas colosales lo expresa como imagen."}, {"titulo": "Relatos reunidos", "puntos": ["Un canto nombra las púas de ogàn y de Èṣù en una advertencia.", "Otro atribuye a Olódùmarè la regla de que dos grandes cosas no caigan una sobre otra."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los pasajes examinados no se combinan en una obra general. Cualquier lista completa debe verificarse en su verso de origen."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù figura en el primer canto y Olódùmarè en el segundo, con funciones distintas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ogàn se menciona como planta espinosa."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos cantos permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=225;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo vincula éxito profesional y generosidad. Ọ̀rúnmìlà recibe muchos consultantes; Animo-Ọla escucha que la comida compartida puede evitar carencias."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["El trabajo o el negocio empieza a mejorar.", "Su buena fama atrae a más gente que le pide ayuda (relato de Ọ̀rúnmìlà y los clientes).", "Debe decidir cuánto compartir sin descuidar sus obligaciones (relato de Animo-Ọla).", "Tiene que atender a su madre (relato de Òténgélè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona determinación y generosidad con abundancia. El primer verso anuncia más consultas para Ọ̀rúnmìlà."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que negarse a compartir puede empobrecer los vínculos. No garantiza riqueza por hacer una ofrenda."}, {"titulo": "Enseñanza principal", "texto": "Dar alimento y servicio según la propia capacidad convierte el éxito en un bien compartido."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe clientes e iniciados de muchos lugares.", "Animo-Ọla ofrece una comida abundante.", "Òténgélè recibe un consejo de atención a su madre; otro relato habla de sueños inquietantes, que no prueban un ataque ni explican por sí solos dolores físicos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita paloma, gallina y cauríes; el segundo, ñame machacado, sopa, kola y cauríes. Son listas distintas."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà es protagonista de la primera consulta; Animo-Ọla de la segunda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ñame, sopa y kola son alimentos de la segunda historia, no medicinas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos se conservan por separado; los encabezados posteriores de Ọ̀ṣẹ́ pertenecen a la siguiente sección. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=226;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata una mejora después de dificultades y advierte sobre relaciones donde el trabajo no se retribuye. Un relato muestra a Igaliyerẹ excluido de comida y bebida; otro presenta un cargamento pagado con mal. Una tercera versión sitúa el consejo en la ceremonia de nombramiento de un niño y la alegría compartida por su familia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["No le han pagado un trabajo (relato de Ọlojà-ẹrú en el mercado).", "Una sociedad aprovecha su esfuerzo sin darle lo justo.", "Necesita cobrar una deuda sin caer en la avaricia.", "La familia prepara una celebración o un nombramiento y pide bendiciones para un hijo (relato de Olórùbu Ẹ̀gúsí)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona apertura con cobrar lo debido y recuperar recursos. El verso del nombramiento celebra a los hijos y la reunión comunitaria."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que la búsqueda de abundancia puede degenerar en avaricia. Las represalias del relato son narrativas, no instrucciones para actuar."}, {"titulo": "Enseñanza principal", "texto": "La reciprocidad evita que una cooperación se vuelva abuso. Conviene documentar lo entregado y lo acordado."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlojà-ẹrú lleva bienes al mercado y recibe una mala respuesta.", "Olórùbu Ẹ̀gúsí consulta por el hijo y cumple una indicación antes de celebrar su nombramiento."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Una chiva se menciona en el primer relato; chivo y cauríes en el segundo. No se combinan. En el verso de Olórùbu Ẹ̀gúsí se menciona una ofrenda y comida compartida; es otra situación y no se suma a las dos listas anteriores."}, {"titulo": "Relaciones espirituales", "texto": "Igaliyerẹ se identifica con Èṣù en el primer relato; Ọ̀rúnmìlà también aparece en ese verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Alimento y bebida son elementos de reciprocidad en la historia. No se identifica un remedio vegetal. La comida ceremonial del nombramiento se describe en ese tercer relato."}, {"titulo": "Rezos, versos y cantos", "texto": "Los relatos de Igaliyerẹ y del comerciante permanecen separados. También se conserva como pasaje aparte el canto de Olórùbu Ẹ̀gúsí sobre los hijos. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=227;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo vincula la prosperidad con el trato cotidiano y la reputación. Un verso presenta a Ọ̀ṣẹ́ buscando reconocimiento para sostenerse con su actividad y no depender de limosnas; otra lectura menciona la decisión de iniciar una disciplina espiritual."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su vida diaria va bien, pero quiere estabilidad económica y que su trabajo se conozca.", "Busca clientes o reconocimiento (relato de Ọ̀ṣẹ́ y los vendedores de aceite).", "Piensa empezar una disciplina espiritual y debe sostenerla en vez de aplazarla."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "Una lectura favorable relaciona la abundancia con la culminación de una etapa. El verso anuncia popularidad y mejora del sustento para Ọ̀ṣẹ́ después de escuchar el consejo ritual; es un desenlace del relato, no una promesa general."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable relaciona la avaricia con la pérdida y advierte sobre no iniciar la disciplina que la persona desea. El reconocimiento por sí solo no asegura ingresos ni evita dificultades."}, {"titulo": "Enseñanza principal", "texto": "La reputación tiene valor cuando permite servir y sostener un trabajo. El relato asocia la popularidad con los recipientes de venta que acercan al comerciante a la comunidad."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀ṣẹ́ consulta para ser apreciado y evitar la indigencia. Recibe una indicación de sacrificio, la cumple y el verso cierra afirmando que fue escuchado.", "El comentario de la fuente explica la popularidad mediante dos grandes recipientes empleados por vendedores de aceite de palma y manteca; otra versión traduce de modo distinto el segundo contenido."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso enumera dos recipientes de venta, 3.200 cauríes y una preparación tradicional de Ifá. Las versiones discrepan en cómo traducen el contenido del segundo recipiente; se conserva esa diferencia y no se convierte la preparación en tratamiento médico."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca la consulta; Ọ̀ṣẹ́ es el signo personificado."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan aceite de palma, manteca, raíz de iroyin y fruto de aridan en la preparación tradicional. No se indica uso medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso comienza con Ajiṣegiri y Anikansekosunwòn. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=228;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ìwòrì distingue entre alcanzar poder y conservar el hogar. Un verso anuncia grandeza y capacidad de vencer dificultades; otro advierte que una casa puede deshacerse por las palabras de quien la construyó. La caracterización relaciona el exceso de trabajo con el deterioro de vínculos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Trabaja tanto que descuida a su familia y a sus amigos.", "Un ascenso o más influencia le trae problemas nuevos.", "Las palabras duras, el orgullo o las discusiones pueden dividir su casa (relato de quien construyó su casa y la destruyó con la boca).", "Le conviene escuchar el consejo de los mayores."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de abundancia y transformación vinculadas con seguir la guía de los ancestros. En el primer verso se anuncia que Ọ̀ṣẹ́ Ìwòrì será grande y tendrá capacidad de afrontar dificultades; el personaje cumple la ofrenda."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable relaciona avaricia y conflicto con desoír consejo. En el segundo verso, el dueño de la casa rechaza la ofrenda destinada a evitar su dispersión; el texto no desarrolla aquí un desenlace posterior."}, {"titulo": "Enseñanza principal", "texto": "El éxito público pierde valor si la propia manera de hablar deshace la convivencia. La imagen de una casa construida y destruida “con la boca” centra la responsabilidad en la conducta diaria."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀ṣẹ́ e Ìwòrì reciben una predicción de grandeza y de control sobre dificultades; Apá e irókò aparecen como figuras de fuerza.", "Olúfijàbi Abinútan-fi-ogbungbun-tú-ilé-ka recibe la advertencia de que su hogar puede dispersarse. La frase inicial dice que alguien construyó su casa y la destruyó con su boca."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso enumera carnero, 200 piedras, 2.200 cauríes y una preparación de Ifá no descrita. El segundo cita caracol babosa, orí, epo, plátanos maduros pequeños, 16.000 cauríes y otra preparación condicionada que no se explica en el fragmento. No se fusionan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambas consultas. Apá e irókò figuran en comparaciones de fuerza del primer verso; no se trasladan al relato de la casa."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Irókò se menciona en el primer verso; plátanos, orí y epo en el segundo."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de poder y del hogar se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=229;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ìdí trata los límites frente a una persona que ha causado daño. El verso de Ṣaanu-otẹ usa imágenes duras sobre capturar a un ladrón para advertir que la compasión sin protección puede permitir nuevos perjuicios; otra lectura pide una compasión proporcionada."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un problema que se repite o teme que vuelva un daño que ya conoce.", "Duda entre perdonar o poner consecuencias claras (relato de Ṣaanu-otẹ, demasiado indulgente con el fraude).", "Necesita prepararse para un conflicto sin actuar con violencia."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de renacimiento mediante una compasión en medida apropiada. El verso añade que incluso el amor y la misericordia no deben convertirse en exceso que deje indefensa a la persona."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable relaciona avaricia y resistencia con falta de preparación para el conflicto. El canto describe castigos físicos históricos; no autoriza agresión ni justicia por mano propia."}, {"titulo": "Enseñanza principal", "texto": "Poner límites y exigir responsabilidad no elimina la compasión. La imagen del saco que conserva su carga presenta la idea de contener y no dejar escapar lo que debe atenderse."}, {"titulo": "Relatos reunidos", "puntos": ["Ṣaanu-otẹ recibe un consejo por su excesiva indulgencia frente al fraude o la deshonestidad. El verso plantea que un daño no resuelto puede repetirse.", "La traducción inserta una larga nota histórica dentro del canto; se separa de la enseñanza para no tomarla como instrucción ritual vigente."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso enumera cuatro sacos grandes de carga, 3.200 cauríes y una medicina de Ifá no descrita en el fragmento. El saco sirve además como imagen narrativa de contención; no se completa una receta ausente."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca la consulta de Ṣaanu-otẹ. Ọlórun aparece en la reflexión sobre amor y exceso; el ladrón es figura del argumento."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Se mencionan sacos de carga como objeto ritual y metáfora. No se identifica una planta ni un alimento central en el pasaje."}, {"titulo": "Rezos, versos y cantos", "texto": "Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=230;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ìrosùn reúne dos situaciones distintas: una ciudad entristecida por el conflicto y la búsqueda de una vida más agradable, y un relato de aves sobre descendencia. La lectura favorable habla de buena fortuna inesperada; la desfavorable advierte sobre una actitud que prolonga la resistencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pasa por confusiones repetidas y siente que le quitan la tranquilidad.", "Su familia o su comunidad está en conflicto y triste (relato de Ọ̀ṣẹ́ y la ciudad triste).", "Pregunta por descendencia (relato del gallo y la gallina)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de abundancia y satisfacción del potencial, incluida buena fortuna inesperada. En el segundo verso, las aves reciben un anuncio de continuidad de sus crías después de escuchar la indicación ritual."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable asocia avaricia o actitud negativa con resistencia. En el primer verso, Ọ̀ṣẹ́ rechaza la ofrenda que le aconsejan; la fuente no añade en ese pasaje un desenlace que permita afirmar que por ello enferma o pierde bienes."}, {"titulo": "Enseñanza principal", "texto": "El signo distingue entre reconocer una situación que causa aflicción y atender la indicación correspondiente. El relato de la ciudad y el de las aves no se funden en una sola predicción."}, {"titulo": "Relatos reunidos", "puntos": ["“La guerra no es agradable; la ciudad está triste”: Ọ̀ṣẹ́ consulta para que la vida sea placentera, recibe una lista ritual y la rechaza.", "Obiyẹnmẹyẹnmẹ consulta por el gallo y la gallina. Se anuncia que continuarán teniendo crías; escuchan el consejo y cumplen la ofrenda."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Para Ọ̀ṣẹ́ se citan una campana, nueces de kola, un recipiente de ñame machacado, sopa, 2.000 cauríes y hojas de Ifá. Para las aves se indican una chiva y 20.000 cauríes. Son dos listas de versos distintos y no se combinan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambas consultas; las aves son personajes del segundo relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Kola, ñame, sopa y hojas de Ifá aparecen en el primer episodio. El segundo no identifica una planta; ninguno convierte esos alimentos en tratamiento de tristeza."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=231;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata inquietud laboral y la obligación de atender una tarea con cuidado. Pokolaka va a reparar a Ogiri, el muro personificado, y recibe una advertencia de seguridad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está agotado por su trabajo.", "Un trabajo de reparación tiene riesgos (relato de Pokolaka y el muro que podía caerle encima).", "Debe cumplir una obligación antes de que un cambio lo sorprenda."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona protección con completar una responsabilidad. El relato invita a evaluar el estado del muro antes de intervenir."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que egoísmo o descuido puede generar caos. La dolencia de un muro es imagen narrativa, no diagnóstico humano."}, {"titulo": "Enseñanza principal", "texto": "Cuidar a otro incluye proteger a quien realiza el trabajo: la seguridad práctica importa."}, {"titulo": "Relatos reunidos", "puntos": ["Pokolaka se dirige a reparar a Ogiri y escucha que el muro podría derrumbarse sobre él."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso conservado cita tres gallos y cauríes."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca la consulta; Pokolaka es protagonista y Ogiri, muro personificado."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El muro es elemento central del relato. No se identifica una planta o medicina."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conserva el único verso con contenido; no se atribuye un segundo relato inexistente. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=232;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne la preparación del futuro de un hijo y una decisión sobre viaje. Un recién nacido recibe un consejo para su familia; otro viajero es advertido de una estancia poco favorable."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La familia quiere darle mejores condiciones a un niño (relato de los padres del recién nacido).", "Piensa irse a vivir o trabajar fuera de su lugar de origen (relato del señor de tierras y su viaje).", "El desorden diario le pide detenerse y revisar el plan."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona una transformación con actuar a tiempo por el bienestar del menor."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte del costo de ignorar una indicación concreta. El consejo de cancelar el viaje pertenece al viajero del segundo relato."}, {"titulo": "Enseñanza principal", "texto": "Proteger el futuro de un hijo y posponer un viaje son decisiones distintas; ambas requieren información actual."}, {"titulo": "Relatos reunidos", "puntos": ["Los padres de un recién nacido reciben un consejo sobre trabajo y recursos.", "Un señor de tierras pregunta por su viaje a una ciudad extranjera."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita pescado aro y cauríes; el segundo, gallinas y cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las dos consultas; padres y viajero pertenecen a escenas separadas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pescado y gallinas son elementos de ofrendas distintas, no una receta común."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del niño y del viaje se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=233;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ọ̀kànràn relaciona el equilibrio personal con la compañía y el apoyo. Un personaje desdichado consulta para no caminar solo; otro verso anuncia éxito frente a oposición. La caracterización también vincula estabilidad de negocios y vida personal con tranquilidad emocional."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente solo mientras enfrenta problemas que se repiten (relato de la persona que busca quién camine a su lado).", "Sus negocios no son estables y le falta apoyo, paz o una relación de confianza.", "Busca una disciplina espiritual constante para ordenar sus decisiones.", "Puede salir adelante frente a quienes se le oponen (relato de Ṣaṣamura)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de nuevas oportunidades y de adoptar una disciplina espiritual para transformar una mala etapa. El segundo verso narra que Ọ̀ṣẹ́ Ọ̀kànràn escucha el consejo y prevalece frente a sus adversarios."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable vincula avaricia con aislamiento y advierte que provocar a otras personas puede empeorar una situación ya difícil. En el primer verso, la persona oye la indicación para encontrar compañía, pero no la cumple; no se describe un desenlace adicional."}, {"titulo": "Enseñanza principal", "texto": "La compañía adecuada ayuda a atravesar dificultades, pero requiere también criterio y constancia. El dicho inicial recuerda que nadie desea la tribulación y que caminarla solo puede agravarla."}, {"titulo": "Relatos reunidos", "puntos": ["Una persona desdichada consulta para que alguien camine a su lado. Recibe una indicación ritual y la rechaza.", "Ṣaṣamura consulta para Ọ̀ṣẹ́ Ọ̀kànràn; se anuncia éxito sobre la oposición, y el personaje cumple su ofrenda."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso indica dos gallinas, dos gorros o pañuelos para la cabeza, 200 cauríes y una medicina de Ifá no descrita. El segundo enumera tortuga, efún, madera roja de Angola, 24.000 cauríes y otra medicina no descrita. Las listas son distintas."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambas consultas. Los adversarios del segundo relato son figuras de esa escena."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La madera roja de Angola se nombra en la segunda ofrenda. Las prendas de cabeza pertenecen al primer episodio."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de compañía y el de oposición se conservan separados, junto con sus desenlaces diferentes. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=234;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo anuncia el final de una etapa de privación en versos sobre Toto. Otro canto enumera bienes vinculados con Olókun y Ọlósà. Otra tradición del mismo signo trata el dolor por la pérdida repetida de hijos y la esperanza de que un niño sobreviva; es un relato diferente de los cantos sobre dinero."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera que terminen sus problemas de dinero (relato de Toto).", "Necesita cambiar pronto una actividad que ya no funciona.", "La angustia por el dinero le impide pedir orientación.", "La familia teme por la vida de un hijo después de pérdidas anteriores; conviene acompañamiento médico (relato de Ôlömú Jùwàlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de obstáculos que ceden. Toto recibe un anuncio de prosperidad en su relato."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que la avaricia puede crear conflictos. “Para siempre” es lenguaje del canto, no una garantía económica. La historia de los hijos que mueren pertenece al lenguaje y la cosmología del relato; no sirve para diagnosticar a un niño ni para sustituir atención médica."}, {"titulo": "Enseñanza principal", "texto": "La mejora requiere aprovechar la oportunidad con prudencia y compartir las responsabilidades que trae."}, {"titulo": "Relatos reunidos", "puntos": ["Toto escucha que sus tribulaciones pueden terminar.", "Otro canto nombra aves, aguas y bienes en los dominios de Olókun y Ọlósà.", "Ôlömú Jùwàlà consulta por sus hijos; otro relato desarrolla la historia del rey Oníki, un cazador que oye una conversación en el bosque y el niño Mölùmö, cuya familia busca protegerlo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Toto cita paloma, carnera, gallina y cauríes; el canto acuático no recibe automáticamente esa lista."}, {"titulo": "Relaciones espirituales", "texto": "Olókun y Ọlósà aparecen como poderes de las aguas en el segundo canto; Toto es protagonista del primero. Ògún aparece como destinatario de una indicación dentro de la historia de Oníki, con una función distinta de Olókun y Ọlósà en los cantos de prosperidad."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Àgbe, àlùkò y odídẹ̀rẹ̀ son aves de la imagen; no se infiere una receta vegetal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos cantos de prosperidad se mantienen diferenciados. El relato de Mölùmö conserva un intercambio cantado. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=235;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ọ̀sá favorece conciliación, debate y acuerdo para resolver disputas. Elégbárá consulta por un problema judicial; en otro verso, la tortuga busca conservar respeto y evitar que una pelea termine mal. Los episodios no equivalen a un pronóstico legal individual."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está en una disputa, a veces con una autoridad o una institución (relato de Elégbárá y el asunto judicial).", "Hay una forma de arreglo que conviene revisar con claridad.", "Las groserías o las reacciones impulsivas pueden empeorar la negociación (relato de la tortuga Olobakun Ìjapá).", "Necesita valor para defenderse y criterio para saber cuándo retirarse."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable asocia abundancia con protección de lo logrado, salud y coraje ante el conflicto. Ambos protagonistas del material escuchan las indicaciones en sus relatos; la tortuga busca además respeto en todas partes."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable relaciona avaricia y palabras groseras con inestabilidad. El riesgo extremo del verso judicial es parte de la escena tradicional y no predice muerte ni un resultado legal actual."}, {"titulo": "Enseñanza principal", "texto": "El dicho sobre “combatir y esquivar” propone discernir cuándo actuar y cuándo evitar una pelea. Negociar no exige renunciar a derechos, pero sí expresarlos de modo que pueda alcanzarse un acuerdo claro."}, {"titulo": "Relatos reunidos", "puntos": ["Elégbárá recibe un consejo ritual por un asunto judicial; la nuez de kola de tres lóbulos se vuelve imagen de protección en el cierre del verso.", "Olobakun Ìjapá, la tortuga, consulta para que un litigio no lo destruya y para conservar respeto. El final se detiene en las palabras que no deben molestar a otros."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Para Elégbárá se citan tela, nuez de kola de tres lóbulos, aceite de palma, 6.600 cauríes y una preparación no explicada. Para la tortuga: kola amarga, sal, semillas de àyò, gallo y 3.200 cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Elégbárá protagoniza el primer verso; la tortuga el segundo. Ifá enmarca ambas consultas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Kola de tres lóbulos y aceite de palma están en el primer verso; kola amarga, sal y semillas de àyò en el segundo. No son soluciones legales ni médicas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del litigio y de la tortuga permanecen separados. La fuente misma anota que una expresión del segundo no estaba clara para el traductor. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=236;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Ìká une dos asuntos que no deben confundirse: proteger la reputación frente a una asociación perjudicial y superar oposición. Deyunlenu recibe un consejo para no ser contado entre quienes dañan a otros; Ọ̀rúnmìlà protagoniza un verso de victoria."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Un trato o una sociedad anterior podría traerle un reclamo legal.", "Teme que lo que hicieron sus socios lo comprometa aunque él no participó (relato de Deyunlenu Abowoṣerin).", "Quiere responder a una acusación falsa con buen carácter, hechos y acuerdos claros.", "Puede prevalecer frente a quienes se le oponen (relato de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable vincula buen carácter con mayor capacidad personal y prevención de falsas acusaciones. El segundo verso narra que Ọ̀rúnmìlà escucha la indicación y vence la oposición de su relato."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que una asociación indebida puede abrumar a la persona o hacerla parecer partícipe de un daño. En el primer verso, Deyunlenu escucha el consejo pero no cumple la ofrenda; el texto no presenta un desenlace posterior."}, {"titulo": "Enseñanza principal", "texto": "La reputación se cuida antes del conflicto: escoger asociaciones, evitar actos dañinos y conservar claridad sobre lo acordado. La victoria de otro relato no elimina esa responsabilidad."}, {"titulo": "Relatos reunidos", "puntos": ["Deyunlenu Abowoṣerin oye que no debe ser contado entre quienes obran mal cuando estos enfrenten consecuencias; rechaza la ofrenda indicada.", "Ọ̀rúnmìlà recibe la predicción de prevalecer frente a adversarios, realiza su propia ofrenda y el verso cierra con la victoria."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Para Deyunlenu se enumeran ocho huevos de gallina, el palillo de mascar que ya usaba y 16.000 cauríes. Para Ọ̀rúnmìlà se citan carnero, piedra de rayo y 22.000 cauríes. No se combinan ni se aplican automáticamente."}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà aparece en el segundo relato; Deyunlenu en el primero."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Huevos y un palillo de mascar aparecen en el primer relato; la piedra de rayo en el segundo. El palillo no permite identificar con seguridad una planta o especie."}, {"titulo": "Rezos, versos y cantos", "texto": "Se conservan separados el verso de Deyunlenu y el de Ọ̀rúnmìlà. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=237;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo pone en primer plano una relación que podría dar hijos pero también causar sufrimiento económico y emocional. Otro verso habla de los hijos de Olú-ńlá ante adversarios."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Sigue en una relación que le hace daño.", "El deseo de tener hijos pesa en una decisión de pareja (relato de la mujer advertida antes de casarse).", "La familia se pregunta cómo educar y proteger a los niños (relato de Olú-ńlá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona responsabilidad y cuidado de los hijos con bienestar. El primer verso anuncia fortaleza para los hijos de Olú-ńlá."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que una relación que da frutos no por ello es segura o beneficiosa. Ante maltrato real conviene buscar apoyo concreto."}, {"titulo": "Enseñanza principal", "texto": "La futura descendencia no obliga a permanecer en una relación dañina; el bienestar de adultos y niños merece atención por separado."}, {"titulo": "Relatos reunidos", "puntos": ["Olú-ńlá consulta por sus hijos frente a adversarios.", "Una mujer recibe una advertencia sobre casarse con un hombre que podría empobrecerla."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Olú-ńlá recibe garrote, carnero, gallo y cauríes; la mujer, caracoles, ropa jaspeada, aceite y cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambos versos. Olú-ńlá y la mujer son protagonistas de escenas distintas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El aceite de palma figura en la segunda ofrenda; no se propone como remedio para una relación."}, {"titulo": "Rezos, versos y cantos", "texto": "Los relatos de los hijos y del matrimonio se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=238;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo contiene cantos sobre Èṣù-Òdàrà, Ifá y la llegada de bienes. Un verso relaciona nombres de Ifá, Odù, Èṣù y Ajé; otro atribuye al signo la capacidad de dar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere que una oportunidad llegue a buen término.", "Está replanteando cómo usa el dinero y el reconocimiento.", "Una decepción podría llevarlo a actuar contra sus propios intereses."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona abundancia con comprender el papel de Èṣù en los relatos y con generosidad."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que la decepción puede dañar decisiones materiales. Los nombres del canto no son una fórmula para garantizar riqueza."}, {"titulo": "Enseñanza principal", "texto": "El segundo verso expresa que dar también crea prestigio; el primero conserva una genealogía espiritual distinta."}, {"titulo": "Relatos reunidos", "puntos": ["Un canto nombra Akakanika para Ifá, Alakakanika para los Odù y Alapaṣapa para Èṣù-Òdàrà.", "Otro canto enumera bienes y recuerda dones a Alárá y Ajero."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Los fragmentos examinados no autorizan un ẹbọ universal; cada indicación debe verificarse en su verso completo."}, {"titulo": "Relaciones espirituales", "texto": "Ifá, los Odù, Èṣù-Òdàrà y Ajé cumplen papeles diferentes en el primer canto."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Un ave que entra en una casa es imagen del primer verso."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos cantos se mantienen separados."}]$q$::jsonb where numero=239;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo relaciona dinero, influencia y responsabilidad con el modo de actuar. Un canto cuenta un linaje que llega a Ajé; otro habla del gallo y la aceptación de sus palabras."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Empieza un proyecto o una relación nueva.", "Le llegan recursos inesperados y debe decidir cómo compartirlos.", "Quiere que su gente escuche lo que propone (relato del gallo y sus compañeros)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona determinación y generosidad con oportunidades materiales."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que la avaricia puede hacer perder lo recibido. El viaje de Ajé en el canto es narrativo, no garantía de una ganancia."}, {"titulo": "Enseñanza principal", "texto": "Recibir dinero y ejercer influencia son obligaciones distintas; la confianza se sostiene con conducta."}, {"titulo": "Relatos reunidos", "puntos": ["Un canto traza una secuencia de nacimientos hasta Ajé y viajes de los seres humanos.", "Un gallo recibe un consejo para que sus compañeros acepten lo que anuncia."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso del gallo cita paloma y cauríes. El canto del linaje tiene otro contexto; no se construye una obra única."}, {"titulo": "Relaciones espirituales", "texto": "Ajé aparece en el primer canto; Ọ̀ṣẹ́ Ìrẹtẹ̀ y el gallo, en piezas diferentes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Una cuerda para trepar palma es imagen del segundo verso; no se infiere receta botánica."}, {"titulo": "Rezos, versos y cantos", "texto": "El canto de Ajé y la fábula del gallo se conservan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=240;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reflexiona sobre sabiduría ante problemas difíciles. Un verso nombra a Olókun, Ọlósà y Akódá al hablar del saber de Ifá; otro presenta a niños rechazados por el portero del cielo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que un problema es más grande que su preparación.", "La familia está preocupada por la salud de un bebé; conviene llevarlo al médico (relato de los niños que llegan al mundo).", "Busca aprender antes de tomar una decisión."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona preparación y sabiduría con la posibilidad de resolver problemas."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de quedar abrumado por un reto extremo. El relato de bebés que mueren es una explicación espiritual tradicional, no causa médica de mortalidad infantil."}, {"titulo": "Enseñanza principal", "texto": "La sabiduría incluye reconocer cuándo se necesita ayuda especializada. Ante un bebé enfermo debe buscarse atención pediátrica."}, {"titulo": "Relatos reunidos", "puntos": ["Un canto sitúa enseñanzas de Ifá junto a Olókun, Ọlósà y Akódá.", "Un relato presenta a niños que llegan al mundo y son interrogados por Ọ̀rúnmìlà."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las indicaciones de los dos relatos deben mantenerse en su propio contexto; no se ofrece una receta universal para bebés."}, {"titulo": "Relaciones espirituales", "texto": "Olókun, Ọlósà, Akódá y Ọ̀rúnmìlà cumplen funciones diferenciadas en los pasajes."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Océano y laguna son imágenes del primer canto. No se identifica una planta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos sobre sabiduría y niños quedan separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=241;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo trata confrontación y la necesidad de salir de ella sin daño. Òfún y Ogbè aparecen en un enfrentamiento; la tortuga consulta antes de ir a un mercado peligroso. En otra versión, Míèéyè y su esposa reciben una oportunidad de prosperidad que termina en un conflicto de reconocimiento."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está en una disputa legal o con una autoridad (relato de Òfún y Ogbè).", "Su adversario parece más fuerte.", "Debe evaluar un viaje o un negocio con riesgos (relato de la tortuga y el mercado).", "Le llega dinero gracias al trabajo de la casa en conjunto, pero alguien siente que no le reconocen su parte (relato de Míèéyè y su esposa)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona protección y crecimiento espiritual con una salida segura. El relato de Míèéyè ofrece una salida de la pobreza mediante una oportunidad inesperada."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que exagerar el propio destino puede llevar a una pelea mal preparada. Los golpes y monstruos pertenecen a relatos, no a una predicción actual. La disputa posterior entre los esposos ilustra el riesgo de negar la participación del otro."}, {"titulo": "Enseñanza principal", "texto": "La prudencia busca preservar la vida y reconocer el riesgo antes de confrontar o viajar. El relato de Míèéyè añade la importancia de reconocer la contribución de quien ayudó a sostener una oportunidad."}, {"titulo": "Relatos reunidos", "puntos": ["Òfún recibe una indicación durante un conflicto con Ogbè.", "La tortuga se prepara para acudir al mercado con seres descritos como monstruosos.", "Míèéyè y su esposa venden aves a los enviados de Olókun; al enriquecerse, él no comparte lo obtenido y surge un conflicto. Es una narración distinta de los versos de Òfún y la tortuga."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El primer verso cita carnero; el segundo, gallos, cauríes y camarones. Son listas diferentes."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambas consultas; Òfún y Ogbè son signos personificados en el primer relato. En el relato adicional intervienen Orí, Èṣù y Olókun; sus papeles no se trasladan a las otras dos consultas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pèrègún se nombra en una fórmula del primer verso. El relato de Míèéyè menciona aves como parte de la trama, sin sustentar un uso médico actual."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de la confrontación y del mercado permanecen separados. Un tercer verso corresponde a Míèéyè y su esposa. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=242;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo vincula calma, respeto y relaciones favorables con la generosidad. El relato de Isimibakalẹ presenta una casa abierta a quien tiene hambre o sed, junto con el consejo de conservar recursos y espacio para seguir ayudando."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera una etapa de calma después de las dificultades.", "Quiere cuidar el trato con su pareja, su familia o sus visitas.", "Le gusta dar de comer y de beber, y se pregunta cómo hacerlo sin agotarse (relato de Isimibakalẹ).", "Necesita alternar la atención a otros con momentos de descanso o viaje."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable asocia la bondad y la generosidad con buenas relaciones y fortuna. El verso describe un desenlace favorable para Isimibakalẹ tras atender el consejo recibido, sin prometer longevidad individual a toda persona."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que la falta de consideración puede traer pérdidas. El propio relato también exige medir la ayuda: ofrecer sin límites hasta agotarse dejaría a la persona sin medios para continuar."}, {"titulo": "Enseñanza principal", "texto": "Los adivinos comparan el trato entre personas con la miel, que no es amarga. La enseñanza une hospitalidad y buen carácter con límites prácticos para que la ayuda perdure."}, {"titulo": "Relatos reunidos", "puntos": ["Isimibakalẹ recibe a quien tiene hambre o sed y le ofrece comer o beber.", "Los adivinos le aconsejan mantener la bondad con los pobres y tomar distancia de vez en cuando mediante el campo o un viaje. Escucha el consejo y cumple la ofrenda."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso particular enumera cuatro piezas de tela, 80.000 cauríes y miel. Es la lista de este relato, no un ẹbọ general para todo Òfún Ọ̀yẹ̀kú."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca la consulta; anfitrión y visitantes son personas del relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Comida, bebida y miel aparecen en la hospitalidad y la ofrenda. La miel sirve además como imagen de un trato que no se vuelva amargo; no se presenta como tratamiento."}, {"titulo": "Rezos, versos y cantos", "texto": "El verso de Isimibakalẹ incluye una comparación con la miel."}]$q$::jsonb where numero=243;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òfún Ìwòrì relaciona el uso del dinero con satisfacción y cuidado de otros. Ajé, personificación de la riqueza, se vuelve objeto de búsqueda; en otro verso, un escarabajo rico siente vergüenza por no tener hijos y recibe una vía narrativa para cuidar crías."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Un pleito por dinero le afecta el ánimo o una relación.", "Quiere que reconozcan sus recursos o teme que lo busquen solo por ellos (relato de Ọlakanmi y Ajé).", "Tiene bienes, pero siente que le falta familia o alguien a quien cuidar (relato del escarabajo sin hijos)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de transformación y capacidad de generar respeto. Ajé escucha la indicación y, cuando entra al río, las personas van tras ella; el escarabajo también escucha el consejo y forma una familia en el relato."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte de conflicto cuando se dejan de apreciar las bendiciones recibidas. La escena del escarabajo es una fábula etiológica y no diagnostica infertilidad humana."}, {"titulo": "Enseñanza principal", "texto": "El dinero no resuelve por sí solo la necesidad de cuidado y pertenencia. El segundo verso inicia con la idea de aceptar hijos de otras personas, que en la fábula se traslada a crías de insectos."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlakanmi consulta para Ajé. Tras cumplir su ofrenda, ella entra voluntariamente al río y la gente la busca allí.", "Un escarabajo pudiente lamenta no tener hijos. Èṣù lo encuentra camino a la granja y le dice que lleve insectos jóvenes a casa; Odùduà interviene en la explicación de cómo llega a ser padre."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Para Ajé se citan frijoles blancos, sal, miel y 2.000 cauríes. Para el escarabajo, diez ratas, diez pescados, diez palomas y 2.000 cauríes. Son indicaciones de relatos distintos."}, {"titulo": "Relaciones espirituales", "texto": "Ajé personifica la riqueza. Èṣù aconseja al escarabajo y Odùduà figura en la transformación de las crías dentro de esa fábula."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Frijoles, sal y miel pertenecen a la consulta de Ajé; el río aparece en su desenlace. La arena y los insectos jóvenes son elementos de la fábula del escarabajo, no un procedimiento biológico."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos se mantienen separados. El relato no se traduce en consejo médico. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=244;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òfún Ìdí advierte que concentrarse en acumular puede cerrar el bienestar de la casa y enfriar las relaciones. En un verso, Olorí-Ogá escucha que quien impide la fortuna dentro tampoco la obtendrá fuera; el signo invita a reconocer la bondad ajena."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le dedica casi todo su tiempo al negocio y descuida a su pareja, su familia o sus amistades.", "Retiene recursos o decisiones dentro de casa por miedo a que falten (relato de Olorí-Ogá).", "Puede estar juzgando a los demás solo por lo que producen."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de renacimiento y de la necesidad de ver la bondad de otros. En el verso, la buena fortuna se pide para la casa de Olorí-Ogá; no se presenta como un beneficio individual desligado de los demás."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable vincula avaricia con resistencia y pérdida. La caracterización también nombra codicia, gula y egoísmo; son advertencias del material, no diagnósticos de la persona consultante."}, {"titulo": "Enseñanza principal", "texto": "La fortuna retenida dentro de casa deja de circular. El relato propone medir el éxito por su capacidad de sostener relaciones y bienestar compartido, además de los negocios."}, {"titulo": "Relatos reunidos", "puntos": ["Olorí-Ogá recibe la advertencia de que cerrar la buena fortuna de su casa impedirá que llegue bienestar desde fuera.", "La expresión inicial del verso personifica a Òfún como una fuerza que puede obstruir la fortuna; esa imagen requiere leerse dentro del canto, no como amenaza literal general."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Para la situación de Olorí-Ogá se enumeran paloma, carnera, muchas nueces de kola y 20.000 cauríes. La lista pertenece a ese pasaje y no constituye una ofrenda universal para problemas de pareja o negocios."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca la consulta de Olorí-Ogá."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Kola aparece en la lista ritual. El verso no describe una preparación medicinal ni identifica una planta para tratar una enfermedad."}, {"titulo": "Rezos, versos y cantos", "texto": "El pasaje comienza con “Òfún di’remo” y conserva un fragmento traducido incompleto."}]$q$::jsonb where numero=245;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne la esperanza de una vida más placentera y una reflexión sobre honor y finitud. Ewa-olú consulta por alegría; otro verso habla de bendiciones ofrecidas sin alarde."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere aliviar una pena (relato de Ewa-olú).", "Empieza una relación íntima.", "Busca sentido ante una pérdida o un cambio."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona claridad personal con una vida satisfactoria. Ewa-olú recibe un anuncio de dulzura."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte del costo de desoír un consejo espiritual. La muerte del segundo canto pertenece a su visión tradicional, no a una predicción individual."}, {"titulo": "Enseñanza principal", "texto": "La generosidad discreta del segundo verso y la alegría de Ewa-olú muestran formas diferentes de bienestar."}, {"titulo": "Relatos reunidos", "puntos": ["Ewa-olú escucha que su vida será dulce.", "Otro canto habla de dones numerosos, honor y cielo.", "En un verso independiente, Iná —el fuego— aparece personificado en una narración de sanación tradicional; no describe un tratamiento clínico."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La consulta de Ewa-olú cita miel y cauríes; no se traslada al segundo canto."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambos pasajes. El cielo aparece como lugar de honor en el segundo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La miel es elemento del primer verso, sin propuesta terapéutica. Un verso distinto menciona a Iná (fuego) en sentido narrativo y ritual, sin indicar que se use para tratar una enfermedad."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Ewa-olú y del honor se mantienen separados. Hay otro verso atribuido expresamente a Òfún Ìrosùn sobre Iná. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=246;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òfún Ọ̀wọ́nrín relaciona el buen carácter con acciones cuyo valor no depende de recibir agradecimiento. Odùduà habla de beneficiar al mundo; Ọlakanmi recibe un anuncio de bendiciones y una advertencia sobre sus bienes. Los relatos presentan situaciones distintas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Ayuda o trabaja por otros y siente que no lo valoran (relato de Odùduà y los bienes desperdiciados).", "Quiere seguir haciendo el bien sin esperar que le reconozcan cada favor.", "Le preocupa perder bienes o que otros desperdicien lo que compartió (relato de Ọlakanmi)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable vincula protección con cambios inesperados. En el primer verso, el bien desaprovechado vuelve a Odùduà; en el segundo, Ọlakanmi oye que Edùmarè puede traerle cosas buenas."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que despreciar las bendiciones recibidas puede crear desorden. Ayudar sin criterio también puede dejar recursos expuestos; cada pasaje describe un caso propio."}, {"titulo": "Enseñanza principal", "texto": "Odùduà afirma que hacer el bien es un rasgo del carácter aunque parte de la gente no dé las gracias. El verso añade una comparación con padres y madres que buscan dar cosas buenas a sus hijos."}, {"titulo": "Relatos reunidos", "puntos": ["Odùduà pregunta por las cosas buenas que entrega al mundo cuando otros las desperdician; recibe una indicación para que no se pierdan definitivamente.", "Ọlakanmi escucha que Edùmarè le dará bienes y recibe un consejo para proteger sus propiedades de adversarios."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La lista de Odùduà incluye paloma, un animal acuático, 16.000 cauríes y hojas de Ifá. La de Ọlakanmi enumera tres cuchillos, tres gallos y 6.000 cauríes. No se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Odùduà protagoniza el primer pasaje; Edùmarè se menciona como dador de bendiciones en el segundo. Ifá enmarca ambas consultas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "El primer verso menciona un animal acuático y hojas de Ifá, pero no identifica una especie vegetal segura. El segundo no nombra plantas."}, {"titulo": "Rezos, versos y cantos", "texto": "Las palabras de Odùduà y la consulta de Ọlakanmi permanecen como versos separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=247;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo advierte que la confianza y los bienes requieren límites. Olú-Ọta busca apoyo frente a adversarios; otros versos describen personas que podrían aprovecharse de quien da."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["El negocio va bien, pero alguien le pide acceso a sus bienes o su dinero.", "Teme un engaño en una relación (relato del hombre advertido sobre una mujer interesada).", "Debe comprobar intenciones y acuerdos antes de entregar recursos (relato de Olú-Ọta)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona crecimiento comercial con una red de apoyo confiable."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que decepción o egoísmo pueden terminar en apropiación indebida. Los relatos no prueban que una pareja o solicitante actual quiera robar."}, {"titulo": "Enseñanza principal", "texto": "La generosidad no obliga a entregar bienes sin información ni condiciones claras."}, {"titulo": "Relatos reunidos", "puntos": ["Olú-Ọta busca aliados y seguridad.", "Un hombre recibe una advertencia sobre una mujer que podría quitarle dinero.", "Otro hombre escucha una advertencia sobre una petición interesada."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Olú-Ọta recibe palomas y cauríes; los otros relatos mencionan chivo, aceite, kola y hojas. Cada indicación pertenece a su escena."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù se nombra en el tercer relato como influencia que puede tentar a ceder; Ifá enmarca las consultas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma y kola son elementos rituales de dos versos, no una protección financiera por sí mismos."}, {"titulo": "Rezos, versos y cantos", "texto": "Los tres relatos se mantienen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=248;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òfún Ọ̀kànràn critica el abuso de fuerza, jerarquía e influencia. Un verso presenta a Olódùmarè preocupado por el daño que poderosos, gobernantes y ricos causan a personas vulnerables cuando se dispone a enviar gente a la Tierra."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Alguien con autoridad se está dejando llevar por el orgullo.", "Se siente perjudicado por quienes tienen más poder o dinero (relato del sufrimiento causado por reyes y ricos).", "Un puesto nuevo exige escuchar a quienes sufrirán sus decisiones.", "Puede venir un cambio físico, emocional o espiritual, y hay que confirmar cuál."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable habla de oportunidades nuevas para mantenerse limpio en lo físico, emocional y espiritual. El verso presenta a Olódùmarè buscando defender a quienes carecen de medios para responder al abuso."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable asocia disfunción con aislamiento y con una posible reacción social ante el abuso de poder. No se adjudica culpa a una persona concreta sin hechos de la consulta."}, {"titulo": "Enseñanza principal", "texto": "La fuerza debe medirse por cómo trata a quienes menos pueden defenderse. El relato cuestiona la idea de que rango o riqueza justifiquen causar sufrimiento."}, {"titulo": "Relatos reunidos", "puntos": ["Antes de enviar gente a la Tierra, Olódùmarè escucha una descripción del sufrimiento provocado por reyes, jefes, gobernantes y ricos.", "Se mencionan personas inocentes y desfavorecidas que no tienen medios para hacer responder a quienes les causaron daño; el relato enmarca la intervención como defensa frente al abuso."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "La lista particular de Olódùmarè incluye tortuga, cuchillo, flecha, arco, pimienta y 18.000 cauríes. El pasaje dice que escuchó y cumplió la indicación. Es una lista narrativa, no un modelo general de acción contra autoridades."}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè protagoniza el verso como figura que observa y responde al sufrimiento; reyes y gobernantes son colectivos del relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "La pimienta aparece como elemento de la ofrenda. El texto no especifica una especie botánica ni propone uso medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "El relato se conserva con su crítica del abuso y su lista ritual separadas. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=249;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òfún Ògúndá advierte sobre decisiones tomadas desde una posición de poder sin atender las consecuencias para otros. En el relato, Onibara desoye una advertencia sobre su matrimonio y después usa los recursos de su reino para sostener una demanda privada."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa en una relación que podría cambiar sus decisiones y afectar a otros.", "Un cargo o un éxito lo hace sentir por encima de las consecuencias (relato del rey Onibara).", "Va a colaborar con alguien que no conoce bien y conviene evaluarlo con cuidado."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona superar obstáculos con elegir con cuidado las relaciones y las personas con quienes se trabaja. El pasaje invita a escuchar advertencias razonables antes de comprometer recursos compartidos."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable asocia un vínculo dañino con conflicto. La historia muestra que el rey deja de respetar los bienes de sus súbditos y encubre sus actos; el oficio atribuido a la mujer no justifica descalificar a personas reales."}, {"titulo": "Enseñanza principal", "texto": "La autoridad no excusa tomar lo ajeno ni ocultar daños. El centro de la historia es la responsabilidad de Onibara por sus propias decisiones, aunque la narración culpe también a la mujer."}, {"titulo": "Relatos reunidos", "puntos": ["Onibara rechaza la indicación inicial y las advertencias de la gente porque cree que su condición de rey lo protege.", "Para atender una demanda de carne, toma aves y ganado de sus súbditos; el relato lo muestra transformado en leopardo para continuar. Tras ser descubierto, llega un desenlace violento que se conserva como parte de la narración, no como norma de conducta."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "En la consulta inicial se indican un carnero y 2.200 cauríes. Onibara no cumple esa ofrenda. La posterior “medicina” de transformación es elemento fantástico del relato; no se explica como técnica real."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca la consulta; Onibara es protagonista de la historia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aves, ovejas y chivas aparecen como bienes tomados a otras personas; la carne es una demanda dentro del relato. No se identifica una planta ni un tratamiento verificable."}, {"titulo": "Rezos, versos y cantos", "texto": "El relato cierra con un proverbio sobre cubrir el rostro del leopardo. Se conserva como explicación etiológica tradicional y no como afirmación zoológica. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=250;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo presenta la restauración de una comunidad en crisis. Varios versos describen Ifẹ̀ como una calabaza rota y buscan una forma de reparar el orden mediante carácter, sabiduría y acción compartida. Otro relato, independiente de los versos sobre Ifẹ̀, utiliza un jardín junto al agua para hablar de estabilidad durante estaciones difíciles."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su vida parece en orden por fuera, pero tiene problemas sin resolver.", "Su familia o su comunidad está desorganizada (relato de los ancianos de Ifẹ̀).", "Quiere reparar daños del pasado.", "Busca mantener el bienestar que ya logró aunque cambien las condiciones (relato del jardín junto al agua)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona una mejora material con cambio de conducta y reparación. La historia del jardín representa la continuidad de recursos a través de épocas favorables y difíciles; el beneficio se extiende a quienes lo acompañan."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que no revisar el propio carácter puede agravar una crisis. Las imágenes de desastre no anuncian un evento inevitable."}, {"titulo": "Enseñanza principal", "texto": "La reparación de Ifẹ̀ no depende de una persona aislada: los versos convocan saberes y responsabilidades diferentes."}, {"titulo": "Relatos reunidos", "puntos": ["Los ancianos de Ifẹ̀ preguntan quién puede restaurar su dominio.", "Se llama a sacerdotes y sabios cuando la destrucción parece avanzar.", "Otro pasaje busca una hoja llamada Alaṣuwalu como imagen de reforma del carácter.", "Un jardín junto al agua recibe consejo para atravesar tanto la lluvia como la estación seca; tras atenderlo, el relato lo presenta sin agotarse en ninguna de las dos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Las indicaciones tradicionales de los cuatro versos no se reducen a una sola ofrenda. Se menciona Alaṣuwalu. Ese relato menciona cuatro caracoles, cuatro palomas, aceite de palma y dinero; pertenece solo a su situación y no se suma a las listas de los otros cuatro versos."}, {"titulo": "Relaciones espirituales", "texto": "Ifá y varios especialistas aparecen en la búsqueda; las figuras del cielo cumplen otros papeles en los versos posteriores."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Alaṣuwalu se nombra como hoja. La calabaza rota es imagen de la comunidad. El agua y el jardín son imágenes de la narración adicional; no identifican una planta medicinal."}, {"titulo": "Rezos, versos y cantos", "texto": "Los cuatro versos largos permanecen diferenciados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=251;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo anuncia mejoría en el trabajo y una responsabilidad mayor. Ọ̀rúnmìlà consulta en medio de pobreza; Dekasi pregunta por el cargo dejado por su padre."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera una oportunidad de dinero después de las dificultades (relato de Ọ̀rúnmìlà).", "Un ascenso le trae obligaciones nuevas.", "Hay un asunto de sucesión en la familia (relato de Dekasi y el título de su padre)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona el incremento de recursos con asumir responsabilidades y compartir."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que desatender obligaciones nuevas puede hacer perder una oportunidad. El cargo de Dekasi no implica un derecho hereditario actual."}, {"titulo": "Enseñanza principal", "texto": "El progreso exige preparación para administrar recursos o una posición, no solo esperar su llegada."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà recibe una predicción de dinero tras dificultades.", "Dekasi consulta por ocupar el título que dejó su padre.", "Otro verso breve usa la relación entre Òfún e Ìká y la llegada de la noche como imagen de reconocer el momento apropiado; se conserva separado de las consultas por dinero y cargo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Ọ̀rúnmìlà recibe paloma, kola, aceite de palma y cauríes; Dekasi, palomas y cauríes. Las indicaciones no se mezclan."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù se menciona en una nota de la ofrenda de Ọ̀rúnmìlà. Dekasi es protagonista de otro verso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Kola y aceite de palma son elementos rituales; no se propone una medicina."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del dinero y del cargo se conservan separados. Un tercer pasaje, sobre Òfún, Ìká y la noche, aparece bajo este signo. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=252;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo reúne deseo de hijos y una advertencia sobre violencia de pareja. Ọbàtálá recibe un anuncio de descendencia; una mujer recibe una advertencia grave sobre el hombre con quien quiere casarse."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Desea tener hijos (relato de Ọbàtálá).", "Una relación puede incluir agresiones aunque parezca ofrecer familia (relato de la mujer que consulta antes de casarse).", "Debe separar el deseo de tener hijos de su seguridad con la pareja."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona práctica y aprendizaje con bienestar familiar. Ọbàtálá recibe una predicción de muchos hijos."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte del posible daño físico en una relación. Una ofrenda del relato no garantiza que cese la violencia; ante agresión real corresponde buscar seguridad y apoyo."}, {"titulo": "Enseñanza principal", "texto": "Tener hijos no vuelve aceptable sufrir maltrato. La seguridad de la mujer del segundo relato debe evaluarse por sus hechos, no por una promesa."}, {"titulo": "Relatos reunidos", "puntos": ["Ọbàtálá pregunta por hijos y por la enseñanza de Ọ̀rúnmìlà.", "Una mujer consulta antes de casarse con un hombre descrito como agresor."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "El verso de Ọbàtálá cita miel, sal y aves; el de la mujer, aiká, caracoles, palomas y cauríes. No se presentan como tratamiento ni solución de violencia."}, {"titulo": "Relaciones espirituales", "texto": "Ọbàtálá y Ọ̀rúnmìlà participan en el primer relato; la mujer y el pretendiente en el segundo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Miel y sal aparecen en un verso; aiká es animal del otro. No se deduce receta médica."}, {"titulo": "Rezos, versos y cantos", "texto": "Los dos versos permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=253;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òfún Òtúrá reúne dos imágenes de continuidad. Èṣù-Òdàrà se casa con epo, el aceite de palma personificado, y busca que la unión perdure; Olówu consulta para que su vida en la granja no lo deje aislado. La caracterización del signo trata la estabilidad de pareja."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa casarse o vivir con su pareja y busca estabilidad (relato de Èṣù-Òdàrà y el aceite de palma).", "Teme que la relación se enfríe o termine.", "Un trabajo aislado le quita contacto con la gente (relato de Olówu y su granja)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable asocia alegría con la capacidad de sostener vínculos. En los versos, ambos protagonistas escuchan el consejo y cumplen sus ofrendas; la imagen de unión pertenece a la historia de Èṣù-Òdàrà."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que amargura y decepción personal pueden afectar la convivencia. El matrimonio figurado con el aceite no garantiza permanencia a ninguna pareja real."}, {"titulo": "Enseñanza principal", "texto": "Pedir continuidad es distinto de darla por asegurada. El primer relato representa el deseo de unión; el segundo recuerda que el bienestar también requiere no quedar solo."}, {"titulo": "Relatos reunidos", "puntos": ["Èṣù-Òdàrà consulta cuando va a casarse con epo, el aceite de palma. El verso usa comida y unión corporal como imágenes de permanencia.", "Olówu recibe el anuncio de una vida favorable, junto con el consejo de evitar que esa vida se reduzca a estar solo en la granja."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Para Èṣù-Òdàrà se enumeran tres gallos y 6.000 cauríes. Para Olówu, tres carneros, tres azadones, tres machetes y 6.000 cauríes. Las listas pertenecen a escenas distintas."}, {"titulo": "Relaciones espirituales", "texto": "Èṣù-Òdàrà protagoniza el primer verso; Olówu el segundo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma, sal y olẹlẹ aparecen en la apertura alimentaria del primer verso. Azadones y machetes pertenecen al segundo; no se infiere una medicina o receta."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos del matrimonio figurado y de la granja se conservan separados."}]$q$::jsonb where numero=254;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "Òfún Ìrẹtẹ̀ vincula respeto con disciplina propia y protección. Olúṣẹso se reeduca y continúa haciendo el bien; Omi, el agua personificada, recibe un consejo distinto para no ser boicoteada. La caracterización habla de salir de una situación insegura."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere salir de un ambiente o un hábito que lo tiene estancado y recuperar la seguridad en sí mismo.", "Busca que lo respeten por lo que hace y no solo por su puesto (relato de Olúṣẹso).", "Teme que otros bloqueen sus acuerdos o proyectos (relato de Omi)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable asocia determinación con crecimiento y reflexión diaria. En el primer verso, Olúṣẹso sigue una conducta apreciada y recibe respeto después de atender el consejo."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que terquedad y estancamiento pueden impedir avanzar. El segundo verso usa una amenaza contra quienes se oponen al agua como lenguaje narrativo; no constituye una instrucción de represalia."}, {"titulo": "Enseñanza principal", "texto": "La confianza se construye con aprendizaje continuo y actos útiles. Los dos relatos muestran respuestas distintas: Olúṣẹso trabaja en su conducta y Omi busca protección frente al boicot."}, {"titulo": "Relatos reunidos", "puntos": ["Olúṣẹso dice que fue entrenado y volvió a entrenarse. Recibe el consejo de seguir haciendo lo que beneficia a otros y cumple su ofrenda para ser respetado.", "Omi consulta para impedir conspiraciones o boicots. Cumple una ofrenda propia; el cierre del verso defiende la fuerza del agua mediante una imagen amenazante."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Olúṣẹso recibe cuatro palomas, 20.000 cauríes y una preparación de Ifá cuyo uso tradicional incluye hojas para lavar cabeza e Ifá. Omi recibe sal, aceite de palma, paloma, tortuga, tela jaspeada y 3.200 cauríes. Las listas se mantienen separadas."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca las consultas; Omi es el agua personificada en la segunda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Agua, sal y aceite de palma aparecen en el segundo verso. El primero nombra àgbonyin y agbayunkun en una preparación tradicional; no se recomiendan como tratamiento."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Olúṣẹso y Omi permanecen separados. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=255;
update estera_sintesis set secciones=$q$[{"titulo": "Idea central", "texto": "El signo examina pérdida, agravio y respuesta al daño. Enimani recibe una advertencia sobre conservar sus bienes; otro verso afirma que Òfún no ofendió a nadie antes de ser atacado. Un tercer verso relaciona el malestar que expresa un consultante con una preocupación económica, sin convertir esa escena en una explicación general de la enfermedad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme perder algo que acaba de conseguir (relato de Enimani).", "Se siente agraviado por acusaciones o conspiraciones.", "Debe decidir cómo responder sin hacer más daño.", "Tiene un malestar que no sabe explicar y además problemas de dinero; conviene revisarse con un médico."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "texto": "La lectura favorable relaciona abundancia con conservar recursos y desprenderse de lo que ya no se usa."}, {"titulo": "Ibi y advertencias", "texto": "La lectura desfavorable advierte que avaricia u ofensas injustas pueden agravar el conflicto. La venganza del relato no autoriza dañar a nadie."}, {"titulo": "Enseñanza principal", "texto": "Proteger lo propio y buscar reparación por vías legítimas es distinto de vengarse. El tercer verso recuerda que una preocupación material puede sentirse en el cuerpo, aunque un relato ritual no sustituye la evaluación de síntomas."}, {"titulo": "Relatos reunidos", "puntos": ["Enimani, habitante de una ciudad de hechiceros, desoye un consejo sobre bienes efímeros.", "Òfún se presenta como alguien que no ofendió y pide respuesta frente a quienes conspiraron.", "Un consultante pregunta por un malestar desconocido; la respuesta poética señala la falta de dinero como su preocupación más grave.", "Una encantación distinta pide protección frente a lo que el cantor identifica como mal en su casa y su comunidad; no es el desenlace de Enimani ni del consultante con malestar."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "texto": "Enimani recibe tortuga, caracol y cauríes; Òfún, tortuga, cuchillo, cáscaras de palma y cauríes. No se fusionan ni se recomienda la preparación bajo la almohada como tratamiento."}, {"titulo": "Relaciones espirituales", "texto": "Ifá enmarca ambos relatos; Òfún es personaje del segundo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Cáscaras de nuez de palma se citan en el segundo verso sin aplicación general. Otra encantación menciona varias hojas."}, {"titulo": "Rezos, versos y cantos", "texto": "Los versos de Enimani y Òfún quedan separados. El verso del consultante con malestar se conserva aparte. Antes de recitar estos versos, confirma la pronunciación yorùbá con tu awo o padrino."}]$q$::jsonb where numero=256;
commit;
select md5(string_agg(numero||':'||md5(secciones::text),',' order by numero)) from estera_sintesis;
